/* 托福 48 个 List 的例句：SAT 词表里已有例句的词直接复用（RICH 按单词字符串取值，天然共享），
   这里只补 SAT 里没有的 3445 个词。由本轮批量生成，写入方式同 rich.js：合并进同一个 SAT_RICH。 */
Object.assign(window.SAT_RICH,{
"essence":{"e":"The essence of good leadership lies not in giving orders but in listening carefully to those you serve.","t":"优秀领导力的**本质**不在于发号施令，而在于认真倾听你所服务的人。"},
"pastel":{"e":"She painted the nursery walls in soft pastel shades of pink and mint to soothe the newborn.","t":"她把婴儿房的墙壁漆成柔和的粉色和薄荷绿**淡彩色**，好让新生儿感到安心。"},
"recover":{"e":"It took the injured hiker nearly six weeks to recover enough strength to walk down the mountain unaided.","t":"那位受伤的徒步者花了将近六周才**恢复**足够的体力，能够自己走下山。"},
"substitute":{"e":"Because the goalkeeper twisted his ankle, the coach sent in a substitute just minutes before the whistle blew.","t":"由于守门员扭伤了脚踝，教练在哨声吹响前几分钟派上了一名**替补队员**。"},
"renaissance":{"e":"The neighborhood's abandoned factories sparked an artistic renaissance once painters and musicians began renting the empty spaces.","t":"一旦画家和音乐家开始租用那些空置的厂房，这个社区废弃的工厂便引发了一场艺术**复兴**。"},
"sweat":{"e":"Cold sweat trickled down his back as the interviewer paused, scanning his résumé for the missing years.","t":"面试官停顿下来，扫视他简历上缺失的那几年时，冷**汗**顺着他的后背流下。"},
"conform":{"e":"New employees are expected to conform to the office dress code within their first week on the job.","t":"新员工被要求在入职第一周内就**遵守**公司的着装规定。"},
"husk":{"e":"Farmers strip the tough outer husk from each ear of corn before the kernels go to market.","t":"农民在玉米粒上市之前，先剥去每根玉米棒外面坚韧的**外皮**。"},
"tide":{"e":"In this shallow bay, the water tides twice daily, rising over the mudflats and then slowly retreating.","t":"在这个浅海湾，海水每天**涨落**两次，先漫过泥滩，然后又缓缓退去。"},
"decade":{"e":"The company spent a full decade developing the vaccine before it finally received government approval last spring.","t":"这家公司花了整整一个**十年**研发疫苗，才在去年春天终于获得政府批准。"},
"pluralism":{"e":"Religious pluralism allows dozens of different faiths to coexist peacefully within a single, remarkably tolerant city.","t":"宗教**多元化**使数十种不同信仰得以在这样一座异常包容的城市里和平共存。"},
"vagrant":{"e":"The old vagrant slept beneath the bridge each night, wrapped in blankets he had gathered from donation bins.","t":"那个年迈的**流浪汉**每晚都睡在桥下，裹着他从捐赠箱里收集来的毯子。"},
"incline":{"e":"Years of quiet observation began to incline the detective toward suspecting the quiet, unassuming neighbor next door.","t":"多年默默的观察渐渐使这位侦探**倾向于**怀疑隔壁那位不起眼的邻居。"},
"grievous":{"e":"Ignoring the engineer's warnings about the bridge's cracked supports proved a grievous error that cost several lives.","t":"无视工程师关于大桥支撑结构出现裂缝的警告，最终酿成了一个夺去数条人命的**严重**错误。"},
"saucy":{"e":"The waitress gave a saucy reply to the customer's rude remark, leaving the whole table laughing out loud.","t":"那位女服务员对顾客粗鲁的话给了一句**俏皮无礼**的回应，逗得整桌人哈哈大笑。"},
"disproportionate":{"e":"Critics argued that the mayor's budget allocated a disproportionate share of funding to downtown projects, neglecting outer neighborhoods.","t":"批评者指出，市长的预算把**不成比例**的大笔资金分配给了市中心项目，却忽视了外围社区。"},
"nosy":{"e":"Her nosy neighbor kept peeking through the fence, eager to learn who had moved into the empty house.","t":"她那**爱管闲事**的邻居不断从篱笆缝里张望，急切地想知道谁搬进了那栋空房子。"},
"stumble":{"e":"Halfway through his wedding toast, the nervous best man began to stumble over even the simplest words.","t":"婚礼祝酒词讲到一半，紧张的伴郎连最简单的词都开始**结结巴巴**说不利索。"},
"renown":{"e":"The surgeon earned international renown after pioneering a technique that dramatically reduced complications in heart transplants.","t":"这位外科医生因开创了一项大幅降低心脏移植并发症的技术而赢得了国际**声望**。"},
"scroll":{"e":"Archaeologists carefully unrolled the ancient scroll, hoping its faded ink still held readable fragments of forgotten history.","t":"考古学家小心翼翼地展开那卷古老的**卷轴**，希望褪色的墨迹仍留有可辨认的历史片段。"},
"colonization":{"e":"European colonization of the region introduced new crops but also devastated indigenous communities through disease and displacement.","t":"欧洲对该地区的**殖民**引入了新作物，但也通过疾病和迫迁重创了当地原住民社区。"},
"subculture":{"e":"Skateboarding grew from a fringe subculture in California into a mainstream sport celebrated in the Olympic Games.","t":"滑板运动从加州一种边缘**亚文化**发展成了在奥运会上备受推崇的主流运动。"},
"forum":{"e":"The town hall served as an open forum where residents could question officials directly about the new zoning law.","t":"市政厅成了一个公开的**论坛**，居民可以在这里直接就新的分区法向官员提问。"},
"participant":{"e":"Every participant in the clinical trial had to sign a consent form outlining the possible side effects.","t":"临床试验的每位**参与者**都必须签署一份说明可能副作用的知情同意书。"},
"strain":{"e":"The constant strain of caring for her ailing father alone eventually forced her to hire outside help.","t":"独自照顾病重父亲带来的持续**压力**，最终迫使她雇了外人来帮忙。"},
"vary":{"e":"Prices at the farmers market vary considerably depending on the season and how far the produce traveled.","t":"农贸市场的价格会因季节和农产品运输距离的不同而大幅**变化**。"},
"sensitive":{"e":"The new microphone is so sensitive that it picks up a whisper from clear across the auditorium.","t":"这款新话筒**灵敏**得连整个礼堂另一头的低语都能收录到。"},
"exposition":{"e":"Manufacturers from around the world unveiled their latest inventions at the grand exposition held in Paris.","t":"来自世界各地的制造商在巴黎举办的这场盛大**博览会**上展示了他们最新的发明。"},
"sphere":{"e":"Climate policy no longer belongs solely to the political sphere; it now shapes decisions across every industry.","t":"气候政策已不再仅仅属于政治**领域**，如今它影响着各行各业的决策。"},
"giant":{"e":"A giant sequoia can live for thousands of years, towering far above every other tree in the forest.","t":"一棵**巨大的**红杉能存活数千年，高高耸立，远远超过森林里的其他树木。"},
"melt":{"e":"As the spring sun grew stronger, the last patches of snow on the roof began to melt away.","t":"随着春日阳光渐强，屋顶上最后几片积雪也开始**融化**消失。"},
"solicit":{"e":"The charity sent volunteers door to door to solicit donations for families displaced by the recent flooding.","t":"这家慈善机构派志愿者挨家挨户**征求**捐款，帮助近期洪灾中流离失所的家庭。"},
"leisure":{"e":"After retiring from decades of factory work, he finally had the leisure to travel and paint landscapes.","t":"从工厂退休、辛劳数十年后，他终于有了**闲暇**时间去旅行和画风景画。"},
"unravel":{"e":"It took investigators nearly a year to unravel the elaborate scheme behind the company's disappearing funds.","t":"调查人员花了将近一年时间才**理清**这家公司资金失踪背后的复杂骗局。"},
"nail":{"e":"She bent the nail sideways while trying to hang the heavy mirror above the fireplace mantel.","t":"她想把那面沉重的镜子挂在壁炉架上方时，把**钉子**弄弯了。"},
"attain":{"e":"Few climbers ever attain the summit of that peak, given its brutal winds and unpredictable avalanches.","t":"由于那座山峰风势凶猛、雪崩难以预测，很少有登山者能真正**登上**峰顶。"},
"stylized":{"e":"The animated film used a stylized art style with sharp angles instead of realistic, rounded human figures.","t":"这部动画电影采用了**程式化**的美术风格，人物是棱角分明的形象，而非写实圆润的造型。"},
"nominee":{"e":"As the youngest nominee for best director, she nervously watched the envelope open from the front row.","t":"作为最佳导演奖最年轻的**提名者**，她坐在前排紧张地看着信封被打开。"},
"panic":{"e":"When the fire alarm blared unexpectedly during the exam, several students began to panic and rushed outside.","t":"考试期间火警警报突然响起时，几名学生开始**惊慌失措**，冲出了教室。"},
"lure":{"e":"The scent of fresh bread was enough to lure hungry travelers into the tiny roadside bakery each morning.","t":"每天清晨，新鲜面包的香气就足以把饥肠辘辘的旅人**吸引**进这家路边小面包店。"},
"solution":{"e":"After weeks of failed experiments, the team finally found a solution that reduced the machine's error rate to nearly zero.","t":"经过数周失败的实验，团队终于找到了一个能将机器错误率降到几乎为零的**解决办法**。"},
"revere":{"e":"Villagers still revere the old healer, crediting her herbal remedies with saving countless lives during the drought.","t":"村民们依然**敬重**这位老药师，认为她的草药疗法在干旱期间挽救了无数人的生命。"},
"flash":{"e":"In a sudden flash of insight, the young engineer realized the bridge's design flaw had been there from the start.","t":"在突然**闪现**的灵感中，这位年轻工程师意识到桥梁的设计缺陷从一开始就存在。"},
"secrete":{"e":"Certain glands secrete hormones directly into the bloodstream, allowing the body to regulate growth and metabolism efficiently.","t":"某些腺体直接向血液中**分泌**激素，使身体能够有效调节生长和新陈代谢。"},
"issue":{"e":"Housing affordability became the central issue of the campaign, dominating every debate between the two candidates.","t":"住房负担能力成为竞选的核心**问题**，主导了两位候选人之间的每一场辩论。"},
"aria":{"e":"The soprano's final aria brought the entire opera house to tears before the curtain slowly descended.","t":"女高音的最后一首**咏叹调**让整个歌剧院的观众落泪，随后帷幕缓缓落下。"},
"facilitate":{"e":"The new software was designed to facilitate communication between distant research teams working on the same climate project.","t":"这款新软件旨在**促进**从事同一气候项目的远程研究团队之间的交流。"},
"electricity":{"e":"Before the dam was built, most villages in the valley had no electricity and relied entirely on candlelight after sunset.","t":"大坝建成之前，山谷里的大多数村庄都没有**电**，日落后完全依靠烛光照明。"},
"progressive":{"e":"Doctors warned that the disease follows a progressive course, gradually weakening the muscles over several years.","t":"医生警告说，这种疾病的发展是**渐进的**，会在数年内逐渐使肌肉变得虚弱。"},
"reef":{"e":"The captain steered sharply away from the submerged reef just before the hull would have scraped against the coral.","t":"船长在船体即将擦到珊瑚之前，猛地转向以避开那处水下的**暗礁**。"},
"president":{"e":"The president signed the trade agreement only after months of tense negotiations with foreign ministers from both countries.","t":"**总统**在与两国外长经过数月紧张谈判之后，才签署了这项贸易协定。"},
"feeble":{"e":"After the long illness, his feeble legs could barely support his weight as he shuffled across the room.","t":"经过长期患病，他**虚弱**的双腿几乎无法支撑他的体重，只能挪着步子穿过房间。"},
"influx":{"e":"The sudden influx of tourists overwhelmed the small coastal town's restaurants, hotels, and narrow parking streets.","t":"游客的突然**涌入**让这个沿海小镇的餐馆、酒店和狭窄的停车道路都不堪重负。"},
"receptacle":{"e":"Workers placed the radioactive waste in a sealed receptacle designed to contain leaks for at least a century.","t":"工人们将放射性废物放入一个密封的**容器**中，该容器设计能防止泄漏至少一个世纪。"},
"accent":{"e":"Her thick regional accent made it difficult for newcomers to understand her, though locals never had any trouble.","t":"她浓重的地方**口音**让初来乍到的人很难听懂，尽管当地人从来没有任何困难。"},
"kernel":{"e":"Stripped of its rhetorical flourishes, the argument's kernel was simply that taxation without representation was unjust.","t":"剥去华丽的辞藻，这个论点的**核心**其实很简单：无代表权的征税是不公正的。"},
"secure":{"e":"The climbers tested each rope twice, refusing to trust their weight to anything that did not feel completely secure.","t":"登山者把每根绳子都测试了两遍，绝不把自己的体重交给任何感觉不完全**稳固**的东西。"},
"electron":{"e":"When an electron drops to a lower shell, the atom releases the excess energy as a photon of light.","t":"当一个**电子**跃迁到较低的电子层时，原子会以光子的形式释放出多余的能量。"},
"segment":{"e":"The final segment of the documentary focused entirely on the fishermen who still hand-build their boats each winter.","t":"这部纪录片的最后一**部分**完全聚焦于那些至今仍在每年冬天手工造船的渔民。"},
"nourish":{"e":"Rich volcanic soil nourishes the vineyards along the slope, giving the grapes their distinctive mineral flavor.","t":"富含火山灰的土壤**滋养**着山坡上的葡萄园，赋予葡萄独特的矿物风味。"},
"engulf":{"e":"Flames quickly engulfed the wooden warehouse, forcing firefighters to focus on protecting the buildings nearby instead.","t":"大火迅速**吞没**了那座木质仓库，迫使消防员转而集中精力保护附近的建筑。"},
"bedrock":{"e":"Mutual trust formed the bedrock of their partnership, allowing the two founders to weather every financial crisis together.","t":"相互信任构成了他们合作关系的**基础**，让两位创始人能共同挺过每一次财务危机。"},
"due":{"e":"The final loan payment is due at the end of the month, and any delay will trigger a significant penalty.","t":"最后一期贷款将于月底**到期**，任何延误都会引发一笔可观的罚款。"},
"expel":{"e":"The university voted to expel the student after discovering he had fabricated data in three separate research papers.","t":"校方在发现该学生在三篇不同的研究论文中捏造数据后，投票决定将其**开除**。"},
"verbal":{"e":"Their verbal agreement was never written down, which made the dispute nearly impossible to resolve in court.","t":"他们的**口头**协议从未落于纸面，这使得这场纠纷几乎不可能在法庭上得到解决。"},
"deadline":{"e":"The editor pushed back the submission deadline by a week after several reporters requested more time for fact-checking.","t":"几名记者要求更多时间核实事实后，编辑将提交**截止时间**推迟了一周。"},
"identity":{"e":"Investigators spent months trying to confirm the identity of the man found unconscious near the abandoned factory.","t":"调查人员花了数月时间试图确认那名在废弃工厂附近昏迷的男子的**身份**。"},
"patriarch":{"e":"As the family patriarch, he alone decided which grandchildren would inherit shares of the ancestral farmland.","t":"作为**家族族长**，他独自决定哪些孙辈将继承祖传农田的份额。"},
"interior":{"e":"The cathedral's plain stone exterior gave no hint of the elaborate gold mosaics covering its interior walls.","t":"大教堂朴素的石质外观完全看不出其**内部**墙壁上覆盖着精美的金色马赛克。"},
"constitution":{"e":"The drafters spent an entire summer debating how the new constitution should divide power between the states and the federal government.","t":"起草者们花了整个夏天争论新**宪法**应如何在各州与联邦政府之间划分权力。"},
"freeze":{"e":"Overnight temperatures dropped so sharply that the pond began to freeze along its shallow, reedy edges.","t":"夜间气温骤降，池塘浅而多芦苇的边缘开始**结冰**。"},
"sinuous":{"e":"The river follows a sinuous path through the mountains, doubling back on itself again and again before reaching the sea.","t":"这条河流**蜿蜒**穿过群山，一次又一次地自我折返，最终才汇入大海。"},
"alarm":{"e":"A piercing alarm echoed through the factory the moment sensors detected smoke near the chemical storage tanks.","t":"传感器一探测到化学品储罐附近有烟雾，刺耳的**警报**立刻响彻整个工厂。"},
"machinery":{"e":"Rusting machinery from the abandoned textile mill still lines the riverbank, a relic of the town's industrial past.","t":"废弃纺织厂里生锈的**机器**至今仍排列在河岸边，是这个小镇工业历史的遗迹。"},
"expect":{"e":"Meteorologists expect the storm to weaken considerably before it makes landfall along the southern coastline tomorrow.","t":"气象学家**预计**这场风暴在明天登陆南部海岸线之前会大幅减弱。"},
"instinctual":{"e":"Her instinctual response to the loud noise was to grab her daughter's hand and duck behind the counter.","t":"面对巨响，她**本能的**反应是抓住女儿的手，躲到柜台后面。"},
"uncanny":{"e":"The twins possess an uncanny ability to finish each other's sentences, even after years spent living apart.","t":"这对双胞胎即使分开生活多年，仍拥有一种**异乎寻常**的能力，能接上对方未说完的话。"},
"arrest":{"e":"Police made the arrest at dawn, surrounding the farmhouse before the suspect had any chance to flee.","t":"警方在黎明时分实施了**逮捕**，在嫌疑人有机会逃跑之前就包围了那座农舍。"},
"sprinkle":{"e":"She would sprinkle cinnamon over the oatmeal every morning, a small ritual her grandmother had taught her decades ago.","t":"她每天早晨都会在燕麦粥上**撒**一层肉桂粉，这是几十年前祖母教她的一个小仪式。"},
"orthodox":{"e":"The committee rejected his theory simply because it strayed too far from orthodox economic thinking of the time.","t":"委员会否决了他的理论，仅仅因为它偏离了当时**正统的**经济学思想太远。"},
"preliterate":{"e":"Anthropologists studying preliterate societies rely on carefully memorized oral traditions passed down through many generations of storytellers.","t":"研究**文字出现之前**社会的人类学家，依赖世代讲述者精心记忆并口耳相传的口述传统。"},
"hustle":{"e":"After years of city hustle, she craved nothing more than the quiet, unhurried rhythm of farm life.","t":"经历多年城市的**忙碌**之后，她最渴望的莫过于农场生活那种安静、不慌不忙的节奏。"},
"fake":{"e":"The appraiser quickly identified the painting as a fake, pointing out brushstrokes that no eighteenth-century artist would have made.","t":"鉴定师很快认定这幅画是**假货**，并指出那些笔触绝不可能出自十八世纪画家之手。"},
"engrave":{"e":"The jeweler offered to engrave their wedding date on the inside of the ring at no extra charge.","t":"珠宝商提出免费在戒指内侧**镌刻**上他们的结婚日期。"},
"homage":{"e":"The young director's first film pays homage to the black-and-white detective movies he watched obsessively as a child.","t":"这位年轻导演的第一部电影向他童年时痴迷观看的黑白侦探片致以**敬意**。"},
"infatuate":{"e":"The young intern quickly became infatuated with the charismatic senator, ignoring every warning her colleagues offered.","t":"这位年轻实习生很快就对那位极具魅力的参议员**着了迷**，无视同事们给出的所有警告。"},
"discriminate":{"e":"Sommeliers train for years to discriminate between wines that taste nearly identical to an untrained palate.","t":"侍酒师需要多年训练才能**分辨**那些对未经训练的味蕾来说几乎一样的葡萄酒。"},
"associate":{"e":"Most consumers associate the brand's red packaging with reliability, even when cheaper alternatives perform just as well.","t":"大多数消费者会把这个品牌的红色包装与可靠性**联系**在一起，即便更便宜的替代品表现同样出色。"},
"spare":{"e":"The overworked surgeon could rarely spare even ten minutes between back-to-back operations to eat a proper meal.","t":"这位过度劳累的外科医生在连台手术之间很少能**挤出**哪怕十分钟去好好吃一顿饭。"},
"database":{"e":"The librarian showed students how to search the university's database for peer-reviewed articles on climate migration.","t":"图书管理员向学生们展示了如何在学校的**数据库**中检索关于气候移民的同行评审文章。"},
"level":{"e":"Pollution in the river reached a dangerous level last summer, forcing officials to close every public beach downstream.","t":"去年夏天，河流的污染达到了危险的**水平**，迫使官员关闭了下游所有的公共海滩。"},
"oppose":{"e":"Several senior engineers publicly opposed the merger, arguing it would gut the company's research division within a year.","t":"几位资深工程师公开**反对**这次合并，认为这会在一年内掏空公司的研发部门。"},
"lead":{"e":"Ignoring the warning signs on the trail can lead hikers straight into a section prone to sudden rockslides.","t":"忽视步道上的警示标志可能会**导致**徒步者径直走入容易发生突发落石的路段。"},
"rustproof":{"e":"Boat builders coat every exposed bolt with a rustproof finish before the vessel ever touches salt water.","t":"造船工人在船只接触咸水之前，会给每一颗外露的螺栓涂上**不锈**涂层。"},
"sunlit":{"e":"They spread the picnic blanket in a sunlit clearing surrounded by tall pines and the smell of fresh moss.","t":"他们把野餐垫铺在一片**阳光照射的**空地上，四周环绕着高大的松树和新鲜苔藓的气味。"},
"profession":{"e":"Nursing remains a demanding profession that requires years of training and an extraordinary tolerance for exhaustion.","t":"护理仍然是一项要求苛刻的**职业**，需要多年培训以及超乎寻常的抗疲劳能力。"},
"hay":{"e":"Farmers raced to bale the last of the hay before the afternoon thunderstorm could soak the entire field.","t":"农民们赶在午后雷雨把整片田地淋湿之前，抓紧把最后一批**干草**打成捆。"},
"vegetarian":{"e":"Since becoming a vegetarian, she has discovered dozens of protein-rich dishes she never bothered to cook before.","t":"自从成为**素食者**以来，她发现了几十种以前从未费心做过的富含蛋白质的菜肴。"},
"column":{"e":"Her weekly column on local politics attracted a devoted following long before the newspaper's website existed.","t":"早在报社网站出现之前，她那每周一期关于地方政治的**专栏**就已经拥有一批忠实读者。"},
"microbe":{"e":"A single microbe discovered in the hot spring turned out to produce an enzyme useful for industrial cleaning.","t":"在温泉中发现的一种**微生物**竟然能产生一种对工业清洁有用的酶。"},
"homestead":{"e":"Three generations of the same family have worked this homestead since their ancestors first cleared the land.","t":"同一个家族的三代人一直耕种着这座**宅院农庄**，自从他们的祖先最初开垦这片土地以来。"},
"canyon":{"e":"Rafters spend two exhausting days navigating the canyon's roughest rapids before the river finally widens and calms.","t":"漂流者要花两天筋疲力尽的时间穿越**峡谷**中最湍急的激流，之后河面才终于变宽变平静。"},
"portraiture":{"e":"The exhibit traces the evolution of Renaissance portraiture, from stiff formal poses to strikingly lifelike expressions.","t":"这场展览追溯了文艺复兴时期**肖像画**艺术的演变，从僵硬的正式姿势到极为逼真的表情。"},
"alloy":{"e":"Engineers chose a lightweight titanium alloy for the aircraft's frame because it resists both corrosion and fatigue.","t":"工程师为飞机机身选择了一种轻质钛**合金**，因为它既耐腐蚀又抗疲劳。"},
"microscopic":{"e":"Under magnification, the fabric revealed microscopic fibers woven so tightly that no water could pass through.","t":"放大后可以看到，这块布料织有极其**微小的**纤维，紧密到连水都无法渗透。"},
"verse":{"e":"He memorized every verse of the ancient epic long before he understood what most of the words meant.","t":"早在他弄懂大多数词语的含义之前，他就已经背下了这部古老史诗的每一**诗节**。"},
"credential":{"e":"Without the proper credential, she could not legally practice medicine no matter how much experience she had gained abroad.","t":"没有合适的**资格证书**，无论她在国外积累了多少经验，都无法合法行医。"},
"towering":{"e":"A towering redwood blocked most of the afternoon sun from ever reaching the cabin's small garden.","t":"一棵**高耸**的红杉挡住了大部分午后阳光，使其始终无法照到小屋的小花园。"},
"igneous":{"e":"Geologists identified the black boulders scattered across the field as igneous rock formed by ancient volcanic eruptions.","t":"地质学家鉴定出散落在田野上的黑色巨石是由古代火山喷发形成的**火成**岩。"},
"rescue":{"e":"Coast guard crews launched a daring rescue after the fishing boat capsized miles from the nearest harbor.","t":"渔船在离最近港口数英里处翻覆后，海岸警卫队展开了一场大胆的**营救**行动。"},
"acquire":{"e":"The startup managed to acquire three smaller competitors within a single year, tripling its market share almost overnight.","t":"这家初创公司在一年之内**收购**了三家较小的竞争对手，几乎在一夜之间使其市场份额增长了两倍。"},
"geometry":{"e":"Ancient Egyptian surveyors used basic geometry to redraw field boundaries after the Nile's annual floods erased them.","t":"古埃及测量员运用基础**几何学**知识，在尼罗河每年洪水抹去田界之后重新划定边界。"},
"inner":{"e":"Despite her calm public smile, an inner turmoil had kept her awake for most of the week.","t":"尽管她在公众面前始终保持微笑，一场**内心**的动荡却让她整周几乎彻夜难眠。"},
"combine":{"e":"The recipe combines dark chocolate and sea salt in a way that surprises almost everyone who tries it.","t":"这道食谱将黑巧克力与海盐**结合**在一起，令几乎所有尝过的人都感到惊喜。"},
"shrivel":{"e":"Without regular watering, the tomato seedlings began to shrivel within just a few days of the heat wave.","t":"由于缺乏定期浇水，番茄幼苗在热浪来袭仅仅几天后就开始**枯萎**。"},
"infancy":{"e":"Commercial space travel is still in its infancy, with only a handful of companies capable of reaching orbit.","t":"商业太空旅行仍处于**初期**阶段，只有少数几家公司有能力进入轨道。"},
"syrup":{"e":"She drizzled maple syrup over the pancakes until the plate was practically swimming in golden sweetness.","t":"她把枫糖**糖浆**淋在薄煎饼上，直到盘子里几乎浸满了金黄色的甜蜜。"},
"hemp":{"e":"Sailors once twisted hemp fibers into thick ropes strong enough to anchor entire ships during violent storms.","t":"水手们曾经把**大麻**纤维拧成粗绳，坚固到足以在猛烈的风暴中固定整艘船。"},
"mammoth":{"e":"Rebuilding the flooded subway system turned out to be a mammoth undertaking that took nearly a decade to finish.","t":"重建被淹没的地铁系统被证明是一项**巨大的**工程，花了近十年才完成。"},
"weed":{"e":"A particularly invasive weed had taken over half the vegetable garden by midsummer, choking the young pepper plants.","t":"到仲夏时节，一种极具侵略性的**杂草**已经占据了半个菜园，快把幼小的辣椒苗憋死了。"},
"trend":{"e":"Retailers across the industry have noticed a growing trend toward reusable packaging among environmentally conscious younger shoppers.","t":"整个行业的零售商都注意到，转向可重复使用包装正成为一种**趋势**，在具有环保意识的年轻消费者中尤为明显。"},
"motivate":{"e":"A modest bonus structure was enough to motivate the sales team to exceed their quarterly targets by a wide margin.","t":"一个不算丰厚的奖金机制就足以**激励**销售团队大幅超额完成季度目标。"},
"dilate":{"e":"In near-total darkness, the hiker's pupils dilate rapidly to let in every available scrap of light.","t":"在近乎完全的黑暗中，徒步者的瞳孔会迅速**扩张**，以摄入每一丝可用的光线。"},
"peak":{"e":"Power prices spike sharply during peak hours, when nearly every household runs its air conditioner at once.","t":"电价在**高峰**时段会急剧飙升，那时几乎家家户户都同时开着空调。"},
"homing":{"e":"Researchers attached tiny transmitters to the homing pigeons to study exactly how they navigate back across hundreds of miles.","t":"研究人员在这些具有**归巢**本能的鸽子身上装上了微型发射器，以研究它们究竟如何飞越数百英里返回。"},
"flagellum":{"e":"The bacterium propels itself through water by rotating a single flagellum like a tiny, tireless propeller.","t":"这种细菌通过旋转一根**鞭毛**在水中推动自己前进，就像一个微小而不知疲倦的螺旋桨。"},
"tournament":{"e":"Sixty-four teams from across the region compete in the annual tournament, though only one can claim the championship trophy.","t":"来自全区的六十四支队伍参加这项年度**锦标赛**，但只有一支能赢得冠军奖杯。"},
"advocate":{"e":"Public health officials continue to advocate stricter regulations on sugary drinks marketed directly to young children.","t":"公共卫生官员持续**提倡**对直接面向幼儿营销的含糖饮料实施更严格的监管。"},
"crush":{"e":"The hydraulic press can crush an entire car into a flat metal cube within less than a minute.","t":"这台液压机能在不到一分钟内把一整辆汽车**压碎**成一个扁平的金属立方体。"},
"ingredient":{"e":"The head chef refused to reveal which secret ingredient gave the sauce its unmistakable smoky sweetness.","t":"这位主厨拒绝透露到底是哪种秘密**原料**让这款酱汁拥有了那股独特的烟熏甜味。"},
"terminal":{"e":"Passengers arriving on international flights must walk nearly a mile to reach the connecting terminal for domestic departures.","t":"搭乘国际航班抵达的旅客必须步行将近一英里，才能到达用于国内航班转机的**航站楼**。"},
"rub":{"e":"She would rub the tarnished brass vigorously for several minutes before any of its original shine returned.","t":"她要用力**摩擦**这件失去光泽的黄铜好几分钟，原本的光泽才会重新显现。"},
"mighty":{"e":"A single mighty gust tore the tent's pegs right out of the sandy ground and sent it tumbling downhill.","t":"一阵**强劲**的狂风把帐篷的桩钉直接从沙地里拔了出来，把帐篷卷着滚下了山坡。"},
"accident":{"e":"The factory installed new safety guards after a worker lost two fingers in a preventable accident last spring.","t":"去年春天一名工人在一起本可避免的**事故**中失去了两根手指后，工厂安装了新的安全护栏。"},
"shield":{"e":"Thick lead panels act as a shield against the radiation leaking from the reactor's damaged core.","t":"厚重的铅板充当**防护屏障**，抵挡从反应堆受损堆芯泄漏出的辐射。"},
"nightmare":{"e":"Coordinating the wedding around three different flight schedules turned into an absolute nightmare for the exhausted planner.","t":"围绕三种不同的航班时间安排婚礼，对这位筋疲力尽的策划人来说简直成了一场**噩梦**。"},
"accord":{"e":"The two rival factions finally signed a peace accord after nearly a decade of intermittent, bloody fighting.","t":"经过近十年断断续续的血腥冲突，两个敌对派别终于签署了一项和平**协议**。"},
"inflammation":{"e":"Chronic inflammation in the joints gradually made it painful for her to climb even a single flight of stairs.","t":"关节部位的慢性**炎症**逐渐使她连爬一段楼梯都感到疼痛。"},
"versus":{"e":"The championship match pits the defending league leaders versus a scrappy underdog team few thought could advance this far.","t":"这场冠军赛让卫冕的联赛领头羊**对阵**一支谁都没想到能闯到这一步的顽强弱旅。"},
"innocent":{"e":"New DNA evidence eventually proved the man innocent, decades after he had already served most of his sentence.","t":"新的DNA证据最终证明了这名男子是**清白的**，而那时他已经服完了大部分刑期，数十年过去了。"},
"classic":{"e":"Forgetting your umbrella on the one day it actually rains is a classic example of everyday bad luck.","t":"偏偏在下雨那天忘带雨伞，正是日常倒霉事的一个**典型**例子。"},
"muggy":{"e":"The muggy August afternoon left everyone on the porch too drained to do anything but fan themselves slowly.","t":"八月**闷热**的午后让门廊上的每个人都疲惫不堪，只能有气无力地给自己扇风。"},
"skyscraper":{"e":"Construction crews topped off the city's tallest skyscraper just weeks before the annual real estate conference began.","t":"建筑工人为这座城市最高的**摩天大楼**举行封顶仪式，仅比年度房地产大会开幕早了几周。"},
"compliment":{"e":"Please give my compliments to the chef; the tasting menu tonight was easily the finest meal we've had all year.","t":"请代我向主厨**问候**一声；今晚的品鉴菜单绝对是我们这一年吃过的最棒的一餐。"},
"genius":{"e":"Everyone in the lab quietly acknowledged that the reclusive researcher was simply a genius decades ahead of his peers.","t":"实验室里的每个人都默默承认，这位深居简出的研究者根本就是一位领先同行数十年的**天才**。"},
"fauna":{"e":"The nature reserve protects fauna ranging from tiny freshwater fish to elusive mountain leopards rarely seen by hikers.","t":"这片自然保护区保护着丰富的**动物群**，从微小的淡水鱼到徒步者罕见一遇的山地豹都涵盖在内。"},
"healthful":{"e":"Nutritionists insist that a healthful diet built on vegetables, lean protein, and whole grains prevents many chronic diseases.","t":"营养师坚持认为，以蔬菜、瘦肉蛋白和全谷物为基础的**有益健康**饮食能预防许多慢性疾病。"},
"pest":{"e":"My little cousin turned into an absolute pest during the road trip, kicking my seat and demanding snacks every five minutes.","t":"我表弟在这次自驾游中简直成了个**讨厌鬼**，不停踢我的座椅，每隔五分钟就要零食。"},
"predecessor":{"e":"The new principal spent her first month studying the policies her predecessor had established before deciding what to change.","t":"新校长花了第一个月研究**前任**制定的政策，然后才决定要做哪些改变。"},
"scrub":{"e":"Engineers had to scrub the launch after sensors detected a fuel leak just minutes before the scheduled liftoff.","t":"工程师们不得不**取消**这次发射，因为传感器在预定升空前几分钟检测到了燃料泄漏。"},
"check":{"e":"After the long dinner with old friends, the waiter quietly placed the check at the center of the table.","t":"和老朋友吃过这顿漫长的晚餐后，服务员悄悄把**账单**放在了桌子中央。"},
"dive":{"e":"Without hesitating at the edge of the pool, she took a graceful dive that barely made a splash.","t":"她在泳池边毫不犹豫，优雅地来了一个**跳水**，几乎没有溅起水花。"},
"rough":{"e":"Losing both her job and her apartment in the same month made this the roughest year of her life.","t":"同一个月里既丢了工作又丢了住处，这成了她人生中最**艰难**的一年。"},
"stain":{"e":"Red wine spilled across the antique tablecloth, leaving a deep stain that no amount of washing could remove.","t":"红酒洒在了那块古董桌布上，留下一块怎么洗都去不掉的**污渍**。"},
"multiple":{"e":"The detective suspected multiple accomplices were involved, since no single person could have planned such an elaborate heist.","t":"侦探怀疑有**多个**同伙参与其中，因为单凭一人不可能策划出如此精密的抢劫案。"},
"visual":{"e":"Because the lecture relied so heavily on visual aids, students who sat in the back struggled to follow the diagrams.","t":"由于这堂课极度依赖**视觉**辅助材料，坐在后排的学生很难看清那些图表。"},
"stubborn":{"e":"No matter how many facts we presented, our stubborn neighbor refused to admit that his fence violated the property line.","t":"无论我们摆出多少事实，那位**固执**的邻居都拒绝承认自家围栏越了界。"},
"connote":{"e":"To many older readers, the word 'frugal' still connotes a quiet dignity rather than simple cheapness or stinginess.","t":"对许多年长的读者来说，“节俭”一词至今仍**暗示**着一种沉静的尊严，而非单纯的小气。"},
"secede":{"e":"Several southern states threatened to secede from the union rather than accept the new federal trade policy.","t":"几个南方州威胁要**退出**联邦，也不愿接受新的联邦贸易政策。"},
"disquiet":{"e":"Rumors of looming layoffs began to disquiet even the most confident employees on the sales floor.","t":"裁员将至的传闻开始让销售部里最自信的员工也感到**不安**。"},
"bode":{"e":"Dark clouds gathering rapidly over the harbor did not bode well for the fishing boats still out at sea.","t":"港口上空迅速聚集的乌云，对仍在海上的渔船来说**预示着**凶多吉少。"},
"folkway":{"e":"Anthropologists studying the remote village recorded folkways passed down orally for generations, from wedding customs to harvest rituals.","t":"研究这个偏远村庄的人类学家记录下了世代口耳相传的**社会风俗**，从婚礼习俗到丰收仪式无所不包。"},
"overrun":{"e":"Within a single summer, invasive vines had overrun the abandoned garden, choking every rose bush beneath their tangled leaves.","t":"短短一个夏天，入侵的藤蔓就在这座废弃花园里**肆意蔓延**，把每一丛玫瑰都缠得密不透风。"},
"amenable":{"e":"Unlike his older brother, the youngest son proved remarkably amenable to suggestions and rarely argued with his coaches.","t":"与哥哥不同，这个小儿子出人意料地十分**顺从**，很少和教练争辩。"},
"interrelate":{"e":"Economists argue that inflation, employment, and consumer confidence interrelate so closely that changing one inevitably shifts the other two.","t":"经济学家指出，通货膨胀、就业和消费者信心**相互关联**得如此紧密，改变其中一项必然会影响另外两项。"},
"nude":{"e":"The art students spent the entire afternoon sketching a nude model posed beneath the studio's tall north-facing window.","t":"美术系学生们花了一整个下午，为摆在画室高高朝北窗户下的一位**裸体**模特写生。"},
"insulin":{"e":"Because her body no longer produces enough insulin, she must test her blood sugar and inject herself before every meal.","t":"由于她体内**胰岛素**分泌不足，她每餐前都必须测血糖并自行注射。"},
"explore":{"e":"Rather than settle for the guidebook route, the backpackers decided to explore the narrow alleys behind the old market themselves.","t":"背包客们没有满足于导游手册上的路线，而是决定自己去**探索**老市场后面那些狭窄的小巷。"},
"cart":{"e":"The farmer loaded his wooden cart with fresh vegetables and pulled it slowly toward the crowded morning market.","t":"农夫把新鲜蔬菜装上他的木制**手推车**，缓缓地朝拥挤的早市走去。"},
"mercy":{"e":"The judge showed unexpected mercy toward the young offender, suspending his sentence in exchange for community service.","t":"法官对这名年轻罪犯出人意料地展现了**仁慈**，将他的刑期缓期执行，换取社区服务。"},
"barrel":{"e":"Workers rolled the heavy oak barrel down the ramp and into the cellar, where the wine would age for years.","t":"工人们把沉重的橡木**大桶**沿斜坡滚进地窖，葡萄酒将在那里陈酿多年。"},
"transition":{"e":"Moving from high school to college marks a difficult transition that many students underestimate until classes actually begin.","t":"从高中升入大学是一次艰难的**过渡**，许多学生直到真正开课才意识到它的难度。"},
"lyric":{"e":"The young poet abandoned political themes entirely, choosing instead to write lyric verses about longing, memory, and fleeting beauty.","t":"这位年轻诗人彻底放弃了政治题材，转而写起了关于渴望、记忆与转瞬即逝之美的**抒情**诗篇。"},
"questionnaire":{"e":"Before beginning therapy, every new patient must complete a lengthy questionnaire detailing their medical history and current symptoms.","t":"开始治疗之前，每位新患者都必须填写一份详细的**调查问卷**，说明病史和当前症状。"},
"minority":{"e":"Only a small minority of shareholders opposed the merger, so the board proceeded with the acquisition as planned.","t":"只有**少数**股东反对这次合并，因此董事会按计划推进了收购。"},
"entitle":{"e":"Full-time employees are entitled to twenty paid vacation days each year, regardless of their department or seniority.","t":"全职员工每年都**有权享有**二十天带薪假期，无论所在部门或工龄长短。"},
"consistent":{"e":"The witness's testimony remained remarkably consistent under three separate rounds of cross-examination, which only strengthened the prosecution's case.","t":"这名证人的证词在三轮独立的交叉质询中始终**前后一致**，这反而让公诉方的案子更有说服力。"},
"quotation":{"e":"Before hiring the contractor, we compared quotations from four different companies to find the most reasonable price.","t":"在雇用承包商之前，我们比较了四家不同公司的**报价**，以找到最合理的价格。"},
"so-called":{"e":"The so-called miracle cure turned out to be nothing more than sugar pills marketed by a dishonest salesman.","t":"这种**所谓的**神奇特效药，结果不过是一个不诚实推销员兜售的糖丸。"},
"rectangle":{"e":"The architect insisted that the courtyard be a perfect rectangle, exactly twice as long as it was wide.","t":"建筑师坚持要求庭院必须是一个规整的**长方形**，长度恰好是宽度的两倍。"},
"telescope":{"e":"Through her father's old telescope, the child could finally make out the faint rings encircling distant Saturn.","t":"透过父亲那台旧**望远镜**，孩子终于看清了遥远土星周围那圈淡淡的光环。"},
"lightning":{"e":"A sudden bolt of lightning split the old oak tree in the backyard clean down the middle.","t":"一道突如其来的**闪电**将后院那棵老橡树从中间劈成了两半。"},
"utensil":{"e":"Every drawer in her tiny kitchen was crammed with some specialized utensil she had bought but never actually used.","t":"她那间小厨房的每个抽屉里都塞满了买来却从没真正用过的各种专用**厨具**。"},
"kennel":{"e":"While the family vacationed in Europe, their anxious retriever stayed at a well-reviewed kennel just outside town.","t":"一家人在欧洲度假期间，他们那只焦虑不安的金毛猎犬就寄养在镇外一家口碑很好的**寄养犬舍**。"},
"liquid":{"e":"At room temperature, mercury remains liquid, unlike most other metals, which stay solid unless heated to extreme temperatures.","t":"在室温下，水银依然保持**液态**，而大多数其他金属除非加热到极高温度否则都是固态。"},
"remark":{"e":"During the tour, the guide casually remarked that the cathedral had taken nearly two centuries to complete.","t":"参观途中，导游随口**提到**这座大教堂花了将近两个世纪才建成。"},
"hide":{"e":"Despite her calm expression, she could barely hide the disappointment she felt after losing the championship match.","t":"尽管表情平静，她还是很难**掩藏**输掉冠军赛后心中的失望。"},
"spoil":{"e":"Grandparents often spoil their grandchildren with sweets and gifts that the parents would never normally allow.","t":"祖父母常常用父母平时绝不会允许的糖果和礼物把孙辈**宠坏**。"},
"internship":{"e":"She credits the summer internship at a small design studio with teaching her more than four years of college.","t":"她说，在一家小型设计工作室的暑期**实习**教给她的东西，比四年大学学到的还多。"},
"polish":{"e":"The editor spent an entire week polishing the manuscript's final chapter until every sentence read smoothly.","t":"编辑花了整整一周时间**润色**手稿的最后一章，直到每句话都读起来通顺流畅。"},
"starch":{"e":"Rice and potatoes are both rich in starch, which the body breaks down into glucose for quick energy.","t":"米饭和土豆都富含**淀粉**，人体会将其分解为葡萄糖以迅速供能。"},
"gigantic":{"e":"A gigantic crane lowered the prefabricated bridge section into place while traffic below waited patiently for hours.","t":"一台**巨大**的起重机把预制桥段缓缓吊装到位，下方的车流耐心等待了好几个小时。"},
"accumulate":{"e":"Over three decades of careful saving, the retired teacher managed to accumulate a surprisingly large investment portfolio.","t":"经过三十年的谨慎储蓄，这位退休教师竟**积累**起了一笔相当可观的投资组合。"},
"diagonal":{"e":"To reinforce the bookshelf, the carpenter added a diagonal brace running from the top corner to the bottom leg.","t":"为了加固书架，木匠加装了一根从顶角斜到底脚的**对角线**支撑条。"},
"absenteeism":{"e":"The factory's productivity dropped sharply last winter, largely because chronic absenteeism left several assembly lines understaffed for weeks.","t":"去年冬天工厂的生产率大幅下降，很大程度上是因为长期**旷工**让好几条装配线人手不足长达数周。"},
"bacon":{"e":"The smell of bacon sizzling in the pan pulled every sleepy family member down to the kitchen.","t":"平底锅里**培根**煎得滋滋作响的香味，把每个睡眼惺忪的家人都吸引到了厨房。"},
"silversmith":{"e":"The old silversmith spent hours hammering one small teapot until its surface gleamed without a single flaw.","t":"这位老**银匠**花了好几个小时敲打一把小茶壶，直到壶面光洁得毫无瑕疵。"},
"cell":{"e":"Under the microscope, the students watched one living cell slowly divide into two identical daughter cells.","t":"在显微镜下，学生们看着一个活**细胞**缓缓分裂成两个一模一样的子细胞。"},
"stake":{"e":"As a longtime resident and business owner, she has a genuine stake in how the new zoning law turns out.","t":"作为一名长期居民兼企业主，她在新的分区法规最终如何落地这件事上有着切身的**利害关系**。"},
"pesticide":{"e":"Organic farmers refuse to spray pesticide on their crops, relying instead on natural predators to control insect populations.","t":"有机农场主拒绝在作物上喷洒**农药**，转而依靠天敌来控制虫害数量。"},
"conflict":{"e":"Her research findings conflict with the earlier study, forcing the committee to reexamine every assumption before publishing the report.","t":"她的研究结果与早先的那项研究**相冲突**，迫使委员会在发表报告前重新审视每一个假设。"},
"eternal":{"e":"The old monk believed that true wisdom, unlike wealth or fame, remains eternal and untouched by the passage of centuries.","t":"老僧人相信，真正的智慧不同于财富或名声，是**永恒不朽**的，不受岁月流逝的侵蚀。"},
"sting":{"e":"A wasp managed to sting the toddler's ankle while she played barefoot in the garden, and she screamed in pain.","t":"一只黄蜂在小女孩赤脚在花园里玩耍时**蜇**了她的脚踝，疼得她尖叫起来。"},
"respond":{"e":"When the fire alarm rang, the entire staff had to respond immediately, evacuating the building within ninety seconds without exception.","t":"火警响起时，全体员工必须立即**做出反应**，在九十秒内毫无例外地撤离大楼。"},
"sunset":{"e":"Fishermen along the coast always return before sunset, since navigating the rocky shoals in darkness would be far too dangerous.","t":"沿海的渔民总是在**日落**之前返航，因为在黑暗中穿越多礁石的浅滩实在太危险了。"},
"fungus":{"e":"A strange fungus spread across the greenhouse floor overnight, coating the damp soil with a fine layer of grayish threads.","t":"一种奇怪的**真菌**一夜之间蔓延到温室的地面上，给潮湿的土壤覆上一层灰白色的细丝。"},
"elasticity":{"e":"The engineer tested the rubber band's elasticity by stretching it repeatedly, noting how quickly it snapped back to its original length.","t":"工程师反复拉伸橡皮筋来测试它的**弹性**，观察它恢复到原长的速度有多快。"},
"moisture":{"e":"The greenhouse sensors constantly measure soil moisture, alerting the gardener whenever the roots risk drying out during the hottest afternoons.","t":"温室传感器持续监测土壤**湿度**，一旦根系在最炎热的下午有干枯的风险就会提醒园丁。"},
"gravity":{"e":"The judge's grave expression made clear she understood the gravity of the crime before announcing an unusually harsh sentence.","t":"法官凝重的表情表明，她在宣布异常严厉的判决之前，完全明白这起罪行的**严重性**。"},
"stout":{"e":"The old bridge rested on stout wooden beams that had withstood a century of floods without a single crack appearing.","t":"那座古桥架在**结实**的木梁上，历经一个世纪的洪水却没有出现一道裂缝。"},
"assent":{"e":"The board members nodded in assent, and the merger proceeded without a single dissenting vote raised during the entire meeting.","t":"董事会成员们点头**表示同意**，整场会议没有一票反对，并购便顺利推进了。"},
"conceit":{"e":"His conceit grew so extreme that he refused to credit any colleague, insisting the entire discovery belonged to him alone.","t":"他的**自负**发展到了极端的地步，拒绝认可任何同事的功劳，坚称整个发现都归他一人所有。"},
"husbandry":{"e":"Generations of careful husbandry allowed the family farm to breed cattle that consistently produced more milk than any neighboring herd.","t":"几代人精心的**畜牧经营**使这家农场培育出的牛群产奶量始终高于邻近的任何牛群。"},
"abysmal":{"e":"The restaurant's service was so abysmal that three separate tables walked out before their appetizers ever reached the kitchen pass.","t":"这家餐厅的服务**糟糕透顶**，以至于开胃菜还没做好，就有三桌客人直接走人了。"},
"swoop":{"e":"In one swift swoop, the hawk snatched the rabbit from the meadow before the startled farmer could even raise his gun.","t":"那只鹰**猛地一扑**，眨眼间就从草地上叼走了兔子，吓呆的农夫甚至来不及举枪。"},
"punch":{"e":"Furious at the referee's call, the boxer's coach nearly climbed into the ring to punch the man himself.","t":"拳击手的教练对裁判的判罚怒不可遏，差点爬上拳台亲自去**揍**那名裁判。"},
"mingle":{"e":"At the reception, executives and interns were encouraged to mingle freely, breaking down the usual barriers of rank and department.","t":"在招待会上，高管和实习生被鼓励自由**交往**，打破了平日职级和部门之间的隔阂。"},
"interim":{"e":"During the interim between the CEO's resignation and the new hire's arrival, the company operated under a cautious, temporary leadership team.","t":"在首席执行官辞职与新任者到岗之间的这段**过渡期**里，公司由一个谨慎的临时领导团队运营。"},
"laudable":{"e":"Her decision to donate her entire bonus to the shelter was laudable, even if a few cynical coworkers questioned her motives.","t":"她把整笔奖金都捐给收容所的决定**值得称赞**，尽管几个爱挑剔的同事质疑她的动机。"},
"incur":{"e":"Missing the filing deadline will cause the company to incur a substantial penalty, regardless of how reasonable the delay actually was.","t":"错过申报截止日期将使公司**招致**一笔不小的罚款，无论这次延误实际上有多么合理。"},
"siege":{"e":"The medieval city withstood a brutal siege for nearly a year before the invading army finally abandoned its exhausted campaign.","t":"这座中世纪城市顶住了长达近一年的残酷**围困**，最终侵略军才放弃了这场令人筋疲力尽的战役。"},
"lunge":{"e":"The guard dog suddenly lunged at the mail carrier, snapping its chain taut just inches from her startled face.","t":"看门狗突然朝邮递员**猛扑**过去，链子绷得笔直，离她惊恐的脸只有几英寸。"},
"basement":{"e":"After the pipe burst, three inches of water flooded the basement, ruining the boxes of old photographs stored down there.","t":"水管爆裂后，三英寸深的水淹没了**地下室**，毁掉了存放在那里的一箱箱旧照片。"},
"speckle":{"e":"Sunlight filtering through the maple leaves speckled the forest path with countless small, shifting circles of gold.","t":"阳光透过枫叶洒下，在林间小路上**点缀**出无数个不断晃动的金色小圆点。"},
"beaver":{"e":"All weekend the interns beavered away at the quarterly report, determined to finish before their manager arrived Monday morning.","t":"整个周末实习生们都在**埋头苦干**地赶写季度报告，决心在周一经理到来之前完成。"},
"pollutant":{"e":"Factories along the river release a pollutant that has been linked to the sharp decline in the local fish population.","t":"沿河的工厂排放的一种**污染物**已被证实与当地鱼类数量的骤减有关。"},
"sardonic":{"e":"He greeted the announcement with a sardonic smile, as if everyone in the room already knew the promise would be broken.","t":"他用一个**讥讽**的微笑回应了这项宣布，仿佛在场的每个人都早已知道这个承诺会落空。"},
"practical":{"e":"Rather than dreaming up elaborate theories, the mechanic offered a practical solution that fixed the engine within the hour.","t":"那位机械师没有空想复杂的理论，而是提出了一个**实用**的解决办法，一小时内就把引擎修好了。"},
"circular":{"e":"Reviewers dismissed the essay's central claim, noting that its reasoning was entirely circular and therefore proved nothing new.","t":"评审们否定了这篇论文的核心论点，指出其推理完全是**循环论证**，并未证明任何新东西。"},
"disappoint":{"e":"The sequel disappointed longtime fans, who felt the studio had sacrificed the story's heart for flashy, forgettable special effects.","t":"这部续集让老影迷们**大失所望**，他们觉得制片厂为了炫目却过目即忘的特效牺牲了故事的灵魂。"},
"soft":{"e":"Grandmother spoke in such a soft, soothing voice that even the crying infant settled down within a few minutes.","t":"祖母说话的声音如此**轻柔**、抚慰人心，连哭闹的婴儿都在几分钟内安静了下来。"},
"talent":{"e":"The scout immediately recognized the boy's talent for the violin, a gift so rare that he offered a scholarship on the spot.","t":"星探立刻发现了这个男孩拉小提琴的**天赋**，如此难得的才华让他当场提供了一份奖学金。"},
"incessantly":{"e":"The baby cried incessantly throughout the overnight flight, leaving every exhausted passenger desperate for the plane to finally land.","t":"婴儿在整个夜间航班上**不停地**哭闹，弄得每一位疲惫的乘客都巴不得飞机赶紧落地。"},
"stadium":{"e":"Nearly eighty thousand fans packed the stadium that night, their combined roar shaking the stands when the home team scored.","t":"那晚将近八万名球迷挤满了**体育场**，主队得分时他们的欢呼声震动了整个看台。"},
"budget":{"e":"The city council slashed the parks budget by half, forcing several community pools to close for the entire summer season.","t":"市议会将公园**预算**削减了一半，导致好几个社区游泳池在整个夏季都被迫关闭。"},
"intelligence":{"e":"The agency's satellites gathered intelligence on the troop movements for weeks before analysts finally briefed the anxious generals.","t":"该机构的卫星连续数周收集有关部队调动的**情报**，分析人员这才向焦虑的将军们做了汇报。"},
"ultimatum":{"e":"The union delivered an ultimatum to management: raise wages by Friday, or every factory worker would walk off the job.","t":"工会向管理层下达了**最后通牒**：周五前必须加薪，否则所有工厂工人都会罢工离岗。"},
"decrease":{"e":"Economists attributed the sudden decrease in unemployment to the factory's decision to reopen three assembly lines after years of closure.","t":"经济学家将失业率的骤然**下降**归因于那家工厂在停工多年后重新开启三条装配线的决定。"},
"milieu":{"e":"Raised in a working-class milieu, the novelist drew constantly on childhood memories of cramped apartments and overworked, exhausted parents.","t":"这位小说家成长于工薪阶层的**社会环境**中，不断从挤逼的公寓和操劳疲惫的父母这些童年记忆中取材。"},
"satiric":{"e":"The cartoonist's satiric drawings mocked corrupt politicians so sharply that several officials threatened to sue the struggling newspaper.","t":"这位漫画家**讽刺**意味浓厚的画作辛辣地嘲弄了腐败政客，以至于几名官员扬言要起诉这家举步维艰的报社。"},
"alchemist":{"e":"Centuries ago, a hopeful alchemist spent his entire fortune trying to transform ordinary lead into gleaming, valuable gold.","t":"几个世纪前，一位满怀希望的**炼金术士**耗尽了全部家产，试图把普通的铅变成闪亮珍贵的黄金。"},
"untamed":{"e":"Beyond the fence line stretched miles of untamed wilderness, where no rancher had ever managed to graze cattle successfully.","t":"篱笆那头是绵延数英里**未经驯服**的荒野，从来没有牧场主能在那里成功放牧牛群。"},
"stream":{"e":"Sunlight streamed through the cracked shutters each morning, waking the children long before their tired parents wanted them awake.","t":"每天早晨，阳光透过破损的百叶窗**涌**进屋内，比疲惫的父母希望的时间更早地把孩子们吵醒。"},
"clipper":{"e":"The clipper cut across the Atlantic in record time, its towering sails catching every gust the storm season offered.","t":"这艘**快速帆船**以创纪录的速度横渡大西洋，高耸的船帆兜住了风暴季节送来的每一阵狂风。"},
"equivalent":{"e":"In many recipes, applesauce serves as a reasonable equivalent for butter, cutting the fat without sacrificing much of the flavor.","t":"在很多食谱里，苹果酱可以当作黄油的合理**替代品**，既减少了脂肪又不太牺牲风味。"},
"diffusion":{"e":"Historians carefully traced the diffusion of printing technology from China westward along centuries of bustling, interconnected trade routes.","t":"历史学家追溯了印刷技术**传播**的路径，它沿着几个世纪繁忙交织的商路由中国向西传开。"},
"fray":{"e":"Years of constant friction against the pulley had caused the climbing rope to fray dangerously near its midpoint.","t":"多年来与滑轮不断摩擦，使这条登山绳在中段附近**磨损**得十分危险。"},
"revolution":{"e":"The invention of the steam engine sparked an industrial revolution that permanently transformed how ordinary people lived and worked.","t":"蒸汽机的发明引发了一场工业**革命**，从根本上永久改变了普通人的生活和工作方式。"},
"inhabit":{"e":"Long before settlers arrived, indigenous tribes had inhabited these forested valleys for thousands of undisturbed, self-sufficient years.","t":"早在殖民者到来之前，原住民部落就已经在这片森林山谷中**栖居**了数千年，自给自足，未受打扰。"},
"tissue":{"e":"Doctors removed a small sample of tissue from the tumor and sent it immediately to the lab for testing.","t":"医生从肿瘤上取下一小块**组织**样本，立即送去实验室化验。"},
"mushroom":{"e":"After the overnight rain, dozens of pale mushroom caps had pushed up through the damp soil beneath the old oak.","t":"一夜春雨过后，几十朵浅色的**蘑菇**顶破老橡树下潮湿的泥土冒了出来。"},
"listless":{"e":"The heat left the entire office listless by midafternoon, everyone staring blankly at their screens instead of working.","t":"高温让整间办公室到了下午都**无精打采**，人人都呆呆地盯着屏幕而不是工作。"},
"stretch":{"e":"The final stretch of the marathon climbed steadily uphill, breaking the spirit of even the most determined runners.","t":"马拉松最后**一段路程**一路爬坡，让即便最坚定的跑者也意志崩溃。"},
"recharge":{"e":"After months of overwork, she took a quiet week at the lake simply to recharge before the next big project.","t":"经过几个月的过度劳累，她在湖边安静地待了一周，只为在下一个大项目开始前**恢复精力**。"},
"groom":{"e":"Every morning before dawn, the stable hand would groom the racehorse's coat until it gleamed under the barn lights.","t":"每天黎明之前，马夫都会给赛马**梳理**毛发，直到它在马厩灯光下闪闪发亮。"},
"dim":{"e":"Only a dim light flickered at the end of the tunnel, barely enough for the miners to find their way out.","t":"隧道尽头只有一盏**昏暗**的灯在闪烁，勉强够矿工们找到出路。"},
"appreciate":{"e":"Only after moving abroad did she truly appreciate the quiet, unhurried rhythm of life in her small hometown.","t":"直到搬到国外之后，她才真正**体会到**家乡那种宁静、不慌不忙的生活节奏的可贵。"},
"neuron":{"e":"A single neuron can connect to thousands of others, forming the dense networks responsible for memory and thought.","t":"一个**神经元**可以与成千上万个其他神经元相连，形成负责记忆和思维的密集网络。"},
"glare":{"e":"The glare off the fresh snow was so intense that every skier on the slope needed dark goggles.","t":"新雪反射出的**刺眼强光**十分强烈，滑雪道上的每个人都需要戴深色护目镜。"},
"marsh":{"e":"Herons waded silently through the shallow marsh, hunting for small fish hidden among the reeds and mud.","t":"苍鹭悄无声息地涉水穿过浅浅的**沼泽**，捕猎藏在芦苇和泥浆中的小鱼。"},
"foul":{"e":"A foul smell drifted from the abandoned refrigerator, warning the movers long before they dared to open its door.","t":"一股**难闻**的气味从废弃的冰箱里飘出来，搬运工老远就闻到了，迟迟不敢打开箱门。"},
"eclipse":{"e":"The rookie's stunning debut season completely eclipsed the veteran's achievements, leaving him bitter and largely forgotten by fans.","t":"那位新秀惊艳的首个赛季完全**使老将的成就相形见绌**，让后者既苦涩又几乎被球迷遗忘。"},
"incentive":{"e":"To boost sluggish sales, the manager offered every employee a cash incentive for exceeding their monthly quota.","t":"为了提振低迷的销售业绩，经理向每位超额完成月度指标的员工提供现金**奖励**。"},
"command":{"e":"The general who had commanded the entire northern fleet retired quietly, refusing every request for a farewell ceremony.","t":"那位曾**统率**整个北方舰队的将军悄然退役，拒绝了每一个举办告别仪式的请求。"},
"puncture":{"e":"A sharp nail punctured the delivery van's rear tire, stranding the driver on the highway shoulder for nearly two hours.","t":"一颗尖锐的钉子**刺穿**了送货车的后轮胎，让司机在高速公路应急车道上滞留了近两个小时。"},
"picky":{"e":"Their toddler was so picky about food that dinner often consisted of nothing but plain buttered noodles.","t":"他们的小孩对食物**十分挑剔**，晚餐常常只能吃光溜溜拌了黄油的面条。"},
"raven":{"e":"Her raven hair caught the stage lights, gleaming so darkly that the audience in the back row noticed immediately.","t":"她**乌黑发亮**的头发在舞台灯光下闪耀，连坐在后排的观众都立刻注意到了。"},
"durable":{"e":"The company markets its boots as remarkably durable, guaranteeing they will survive a decade of daily construction-site abuse.","t":"该公司将其靴子宣传为异常**耐用**，保证能经受十年建筑工地日常磨损的考验。"},
"approve":{"e":"The city council finally approved the new bridge project after three years of heated debate and repeated budget revisions.","t":"经过三年激烈的争论和反复的预算修改，市议会终于**批准**了这座新桥的建设项目。"},
"jot":{"e":"She quickly jotted the phone number on her palm, having no paper handy before the caller hung up.","t":"她赶紧把电话号码**匆匆记**在手心上，因为打电话的人挂断前她手边没有纸。"},
"athlete":{"e":"Every athlete on the Olympic team followed a strict diet designed to maximize both endurance and explosive short-term power.","t":"奥运代表队的每一位**运动员**都遵循着一套严格的饮食方案，旨在同时提升耐力和短时爆发力。"},
"ideology":{"e":"The two nations remained bitter rivals for decades, largely because their governing ideology differed so fundamentally on individual freedom.","t":"这两个国家几十年来始终是死对头，很大程度上是因为它们的执政**意识形态**在个人自由问题上根本不同。"},
"spur":{"e":"The looming deadline acted as a spur, pushing the entire design team to finish two full weeks early.","t":"迫在眉睫的截止日期成了一种**激励**，推动整个设计团队提前整整两周完成了工作。"},
"vice":{"e":"Gambling became his one true vice, quietly draining the savings he had spent twenty years building up.","t":"赌博成了他唯一真正的**恶习**，悄悄耗尽了他花二十年积攒下来的积蓄。"},
"oyster":{"e":"The chef shucked each oyster tableside, drizzling it with lemon before serving it raw on a bed of ice.","t":"大厨在餐桌旁当场剥开每一只**牡蛎**，淋上柠檬汁后就摆在冰床上生吃上桌。"},
"deposit":{"e":"Over millions of years, the retreating glacier deposited thick layers of gravel and sand across the entire valley floor.","t":"数百万年间，逐渐后退的冰川在整个山谷底部**堆积**下厚厚的砾石和沙层。"},
"reunion":{"e":"After forty years apart, the two brothers wept openly at their reunion outside the small airport terminal.","t":"分别四十年后，兄弟俩在小机场航站楼外**重逢**，毫不掩饰地放声大哭。"},
"lay":{"e":"Each spring the hens would lay dozens of eggs, far more than the small household could ever consume.","t":"每年春天，母鸡们都会**下**几十个蛋，远远超过这个小家庭能吃掉的数量。"},
"occupy":{"e":"Renovations occupied nearly the entire ground floor for months, forcing every department to work from cramped temporary offices.","t":"装修**占用**了几乎整个一楼长达数月，迫使各个部门都挤在临时办公室里办公。"},
"storage":{"e":"The museum keeps thousands of unlabeled artifacts in storage, far more than could ever be displayed in its small galleries.","t":"这家博物馆的**库房**里存放着成千上万件未标注的文物，远比它狭小展厅所能展示的多得多。"},
"proactive":{"e":"Rather than waiting for complaints, the new manager took a proactive approach, fixing potential problems before customers ever noticed.","t":"新经理没有坐等投诉上门，而是采取了**积极主动**的做法，在顾客发觉之前就解决潜在问题。"},
"fantasy":{"e":"Locked in a fantasy of overnight success, he ignored every practical warning his mentors offered about the risky venture.","t":"他沉溺于一夜成名的**幻想**之中，对导师们就这项冒险事业提出的每一个实际警告都置若罔闻。"},
"posit":{"e":"The theory posits that memory loss stems from disrupted protein synthesis rather than the simple death of neurons.","t":"该理论**假定**记忆丧失源于蛋白质合成受到干扰，而不是单纯的神经元死亡。"},
"psychology":{"e":"She switched her major to psychology after discovering how deeply childhood experiences shape adult behavior and decision-making.","t":"在发现童年经历对成年后行为和决策影响如此深远之后，她把专业改成了**心理学**。"},
"weird":{"e":"A weird humming noise came from the basement every night at exactly three, and no one could ever locate its source.","t":"每晚正好三点，地下室都会传出一种**怪异**的嗡嗡声，可谁都找不到声音的来源。"},
"diverge":{"e":"The two economists' predictions began to diverge sharply once inflation data for the following quarter was finally released.","t":"一旦下一季度的通胀数据公布，这两位经济学家的预测就开始急剧**分歧**。"},
"infuriate":{"e":"The referee's blatantly unfair call infuriated the entire stadium, prompting fans to hurl bottles onto the field.","t":"裁判明显不公的判罚**激怒**了整个体育场，愤怒的球迷们朝球场里扔起了瓶子。"},
"spear":{"e":"The fisherman waded into the shallow river and speared a large trout before it could dart beneath the rocks.","t":"渔夫涉水走进浅浅的河中，趁一条大鳟鱼还没窜到石头底下就把它**刺**了个正着。"},
"conquer":{"e":"It took years of therapy for him to finally conquer the crippling fear that had kept him from flying.","t":"他花了好几年做治疗，才终于**克服**了那种让他无法乘飞机的严重恐惧。"},
"thrust":{"e":"Without warning, the crowd thrust a microphone toward the shy scientist, demanding an immediate comment on the scandal.","t":"毫无预警地，人群把一支话筒**猛地伸**向那位腼腆的科学家，要求他立刻就丑闻发表评论。"},
"casualty":{"e":"The battle produced heavy casualties on both sides, forcing the generals to reconsider their entire strategy overnight.","t":"这场战役双方都造成了惨重的**伤亡**，迫使将军们连夜重新考虑整个作战策略。"},
"superb":{"e":"Critics praised the orchestra's superb performance, calling it the finest rendition of the symphony in nearly a decade.","t":"评论家们盛赞这支管弦乐队**精湛绝伦**的演出，称其为近十年来对这部交响曲最出色的演绎。"},
"bestow":{"e":"The university chose to bestow an honorary degree upon the retired firefighter for his decades of selfless community service.","t":"大学决定将一个荣誉学位**授予**这位退休消防员，以表彰他数十年无私的社区服务。"},
"adventitious":{"e":"Their discovery of the ancient coin was entirely adventitious, made only because a stray dog began digging in the field.","t":"他们发现那枚古币完全是**偶然**的，起因不过是一只野狗在田里刨土。"},
"cranial":{"e":"The surgeon studied the patient's cranial scans carefully, mapping the tumor's exact position before scheduling the delicate operation.","t":"外科医生仔细研究了患者的**颅骨**扫描图，标出肿瘤的确切位置后才安排这台精细手术。"},
"lineage":{"e":"The old count traced his lineage back to a knight who had fought alongside the king seven centuries earlier.","t":"这位老伯爵将自己的**世系**一直追溯到七个世纪前曾与国王并肩作战的一位骑士。"},
"balk":{"e":"Negotiations proceeded smoothly until they hit an unexpected balk over which country would host the following year's summit.","t":"谈判本来进展顺利，却在由哪国主办来年峰会的问题上遇到了一个意想不到的**障碍**。"},
"intervening":{"e":"In the intervening years between the two world wars, the fragile economy never fully recovered from its earlier collapse.","t":"在两次世界大战**之间**的那些年里，这个脆弱的经济体从未真正从早先的崩溃中恢复过来。"},
"corrosion":{"e":"Engineers discovered severe corrosion inside the old pipeline, explaining why pressure had been dropping steadily for months.","t":"工程师们在老旧输油管道内部发现了严重的**腐蚀**，这解释了压力为何几个月来持续下降。"},
"mental":{"e":"After the accident, she needed extensive mental support to cope with the trauma that lingered for years afterward.","t":"事故过后，她需要大量的**心理**支持来应对此后多年挥之不去的创伤。"},
"plump":{"e":"The bakery's plump dinner rolls, golden and soft, disappeared from the display case within the first hour of opening.","t":"面包店里那些**圆滚滚**、金黄松软的餐包，开门第一个小时就从展示柜里销售一空。"},
"readily":{"e":"The stain readily washed out once she applied a bit of vinegar before running the shirt through the machine.","t":"只要先抹一点醋，那块污渍在放进洗衣机之前就能**轻易**洗掉。"},
"pave":{"e":"Her groundbreaking research on vaccines paved the way for treatments that would save millions of lives decades later.","t":"她在疫苗方面的开创性研究**铺平了道路**，为几十年后拯救数百万生命的疗法奠定了基础。"},
"contamination":{"e":"Inspectors shut down the plant immediately after detecting bacterial contamination in three separate batches of packaged spinach.","t":"检查人员在三批包装菠菜中检测到细菌**污染**后，立即关闭了这家工厂。"},
"shrink":{"e":"The wool sweater shrank two full sizes after she accidentally washed it in hot water instead of cold.","t":"那件羊毛衫**缩水**了整整两个尺码，因为她不小心用热水而不是冷水洗了它。"},
"laser":{"e":"Surgeons now use a precise laser instead of a scalpel to correct certain vision problems in under fifteen minutes.","t":"外科医生现在会用精准的**激光**代替手术刀，在十五分钟内矫正某些视力问题。"},
"identify":{"e":"Detectives managed to identify the suspect within hours, thanks to a single clear fingerprint left on the windowsill.","t":"多亏窗台上留下的一枚清晰指纹，侦探们几个小时内就**确认**了嫌疑人的身份。"},
"cue":{"e":"The actor missed his cue entirely, leaving the rest of the cast standing awkwardly in silence for several seconds.","t":"那位演员完全错过了他的**提示**，让其余演员尴尬地在台上沉默站了好几秒钟。"},
"medal":{"e":"She proudly displayed her Olympic medal on the mantel, right beside photographs from her very first swim meet.","t":"她自豪地把奥运**奖牌**摆在壁炉架上，紧挨着她第一次参加游泳比赛时的照片。"},
"inscribe":{"e":"The jeweler inscribed their wedding date inside the ring, a tiny detail only the couple would ever notice.","t":"珠宝匠把他们的结婚日期**刻**在戒指内侧，这个小细节只有这对夫妇自己会注意到。"},
"flake":{"e":"Decades of sun exposure caused the old barn's red paint to flake off in large, brittle curls.","t":"数十年的日晒使这座老谷仓的红漆**成片剥落**，卷曲得又大又脆。"},
"concert":{"e":"The three rival companies acted in concert to lobby against the new environmental regulation, pooling their considerable resources.","t":"三家竞争公司**联合一致**地游说反对这项新环保法规，汇集了各自可观的资源。"},
"supreme":{"e":"The court's supreme authority over constitutional matters meant that no other branch could override its final ruling.","t":"法院在宪法事务上拥有**至高无上**的权威，意味着其他任何部门都无法推翻它的终审判决。"},
"lease":{"e":"Before signing the lease, the young couple carefully checked every clause about pets, repairs, and early termination fees.","t":"在签**租约**之前，这对年轻夫妇仔细核对了关于宠物、维修和提前解约费用的每一条条款。"},
"downward":{"e":"The stock's value spiraled downward for six consecutive weeks, wiping out nearly every gain investors had made that year.","t":"该股票的价值连续六周**一路下跌**，抹去了投资者当年几乎所有的收益。"},
"detergent":{"e":"She measured out exactly one capful of detergent, having learned that using more left a stubborn residue on the dishes.","t":"她量出正好一瓶盖**洗涤剂**，因为她早就发现放多了会在碗碟上留下顽固的残留物。"},
"parking":{"e":"Downtown parking became so scarce during the festival that visitors circled the same three blocks for nearly an hour.","t":"节日期间市中心的**停车位**变得如此紧张，游客们绕着同样三个街区转了将近一个小时。"},
"imprint":{"e":"The image of her grandmother's kitchen remained imprinted on her memory long after the old house had been sold.","t":"即使老房子早已卖掉，祖母厨房的画面依然深深**铭刻**在她的记忆里。"},
"degree":{"e":"Only to a limited degree did the new policy actually reduce traffic congestion during the crowded morning commute.","t":"这项新政策实际上只在有限的**程度**上缓解了拥挤早高峰的交通堵塞。"},
"bulk":{"e":"The bulk of the company's revenue comes from a single loyal client who has ordered from them for decades.","t":"这家公司**大部分**的营收都来自一位忠实的客户，这位客户几十年来一直向他们下单。"},
"mast":{"e":"Sailors scrambled up the mast to untangle the rigging before the sudden squall could tear the sail apart.","t":"水手们爬上**桅杆**解开缠住的索具，赶在突如其来的狂风把船帆撕破之前。"},
"inanimate":{"e":"Young children often talk to inanimate objects like dolls and stuffed animals as though they could truly listen.","t":"小孩子经常对着玩偶和毛绒玩具这类**无生命**的物体说话，仿佛它们真能听懂似的。"},
"exhale":{"e":"The yoga instructor told the class to exhale slowly through pursed lips as they eased out of the stretch.","t":"瑜伽教练让学员们在放松伸展动作时，撅起嘴唇缓缓**呼气**。"},
"comply":{"e":"Restaurants that refuse to comply with the new health code will face fines or even temporary closure.","t":"拒绝**遵守**新卫生条例的餐厅将面临罚款，甚至可能被临时关闭。"},
"plantation":{"e":"Before the war, the sprawling plantation depended almost entirely on the labor of hundreds of enslaved workers.","t":"战前，这座广袤的**种植园**几乎完全依赖数百名被奴役劳工的劳动。"},
"request":{"e":"The passenger politely requested a window seat, but the flight was already fully booked by the time she called.","t":"这位乘客礼貌地**要求**要一个靠窗的座位，可她打电话时航班早已订满。"},
"penetrate":{"e":"That night, the bitter mountain wind managed to penetrate even the thickest winter coat, chilling the hikers to the bone.","t":"那晚，凛冽的山风**穿透**了最厚实的冬衣，把徒步者冻得透心凉。"},
"reserve":{"e":"The government designated the entire river delta a protected reserve, banning all hunting and commercial development within its borders.","t":"政府将整个河流三角洲划为受保护的**自然保护区**，禁止在其范围内进行任何狩猎和商业开发。"},
"overload":{"e":"Plugging in three space heaters at once overloaded the circuit, tripping the breaker and plunging the apartment into darkness.","t":"同时插上三台电暖器**使电路超负荷**，跳闸后整间公寓陷入一片漆黑。"},
"region":{"e":"Farmers in this arid region rely entirely on an ancient irrigation system to keep their crops alive each summer.","t":"这片干旱**地区**的农民完全依靠一套古老的灌溉系统来维持庄稼在夏季存活。"},
"absurd":{"e":"It seemed absurd that the committee would reject the proposal after spending three years and millions of dollars developing it.","t":"委员会花了三年时间和几百万美元来开发这项提案，最后却将其否决，这看起来十分**荒唐**。"},
"leftover":{"e":"Instead of throwing anything away, she transformed last night's leftovers into a surprisingly delicious fried rice for lunch.","t":"她没有把任何东西扔掉，而是把昨晚的**剩菜**变成了一份意外美味的炒饭当午餐。"},
"conservationist":{"e":"As a lifelong conservationist, she spent decades lobbying to protect the wetlands from being drained for new housing developments.","t":"作为一名终身**环保主义者**，她花费数十年游说，防止湿地被排干用于新的住宅开发。"},
"suspect":{"e":"Detectives began to suspect the quiet neighbor only after noticing fresh dirt piled beside his newly planted rose bushes.","t":"侦探们注意到那个安静的邻居新种的玫瑰丛旁堆着新土之后，才开始**怀疑**他。"},
"adhesive":{"e":"The label refused to stay put until she switched to a stronger adhesive designed specifically for outdoor use.","t":"那张标签一直贴不牢，直到她换用一种专为户外设计的更强力**胶合剂**。"},
"gravitational":{"e":"The moon's gravitational pull on Earth's oceans is the primary force responsible for the daily rise and fall of tides.","t":"月球对地球海洋的**引力**牵引是造成潮汐每日涨落的主要力量。"},
"hydrogen":{"e":"Engineers are racing to build vehicles powered entirely by hydrogen, which emits only water vapor when burned as fuel.","t":"工程师们正争分夺秒地研发完全由**氢**驱动的车辆，这种燃料燃烧时只排放水蒸气。"},
"celebrate":{"e":"The whole village gathered in the square to celebrate the bridge's completion after nearly a decade of delays.","t":"全村人聚集在广场上，**庆祝**这座历经近十年延误终于建成的桥梁。"},
"obsess":{"e":"For weeks after the diagnosis, she obsessed over every symptom, convinced each new ache signaled something far worse.","t":"确诊后的几周里，她**满脑子都想着**每一个症状，坚信每一次新的疼痛都预示着更糟的情况。"},
"atomic":{"e":"The scientists who developed the atomic bomb later grappled publicly with the moral weight of their own invention.","t":"研发**原子**弹的科学家们后来公开地面对自己这项发明所带来的道德重负。"},
"senior":{"e":"After fifteen years with the firm, she was finally promoted to a senior position overseeing the entire marketing division.","t":"在公司工作十五年后，她终于晋升为**高级**职位，负责监管整个市场部门。"},
"finalize":{"e":"Lawyers on both sides worked through the night to finalize the contract before the merger deadline the next morning.","t":"双方律师通宵工作，赶在次日早晨并购截止期限之前**最终敲定**了合同。"},
"utter":{"e":"Stunned by the verdict, the defendant could not utter a single word as officers led her from the courtroom.","t":"被判决惊呆了的被告，在警官带她离开法庭时竟一个字都**说不出**来。"},
"outrageously":{"e":"The landlord raised the rent so outrageously that half the tenants signed a petition within a single week.","t":"房东把租金涨得**离谱至极**，以至于一半的租户在短短一周内就联名签署了请愿书。"},
"mammal":{"e":"Despite living entirely underwater, the whale is a mammal and must surface regularly to breathe air.","t":"尽管鲸鱼完全生活在水中，它仍是一种**哺乳动物**，必须定期浮出水面呼吸空气。"},
"bare":{"e":"By December, the orchard's branches stood completely bare, every last apple long since picked or fallen.","t":"到了十二月，果园里的树枝已经完全**光秃秃**的，苹果早就被摘光或掉光了。"},
"sticky":{"e":"The children's hands were still sticky with syrup long after they had finished their pancakes at breakfast.","t":"早餐吃完煎饼很久之后，孩子们的手上还**黏糊糊**地沾着糖浆。"},
"personnel":{"e":"The airline had to reroute several flights after a shortage of qualified personnel left two control towers understaffed.","t":"由于合格**人员**短缺导致两座塔台人手不足，这家航空公司不得不为几个航班改道。"},
"particle":{"e":"The detector is sensitive enough to register a single subatomic particle passing through the massive underground chamber.","t":"这台探测器灵敏到足以记录下一个亚原子**粒子**穿过这个巨大地下腔室的痕迹。"},
"notify":{"e":"Hospital staff are required to notify the health department immediately whenever a patient tests positive for the rare disease.","t":"医院工作人员一旦发现患者对这种罕见疾病检测呈阳性，必须立即**通报**卫生部门。"},
"survey":{"e":"The survey revealed that nearly seventy percent of residents opposed building a highway through the middle of the park.","t":"这项**调查**显示，近百分之七十的居民反对在公园中央修建一条高速公路。"},
"abortive":{"e":"The rebels launched an abortive uprising that collapsed within days, long before it could gather any wider public support.","t":"叛军发动了一场**未能成功**的起义，短短几天内就土崩瓦解，根本来不及获得更广泛的民众支持。"},
"catholic":{"e":"Her catholic taste in music ranged from baroque chamber pieces to underground punk records from the eighties.","t":"她**包罗万象**的音乐品味，从巴洛克室内乐一直延伸到八十年代的地下朋克唱片。"},
"stable":{"e":"Doctors kept the patient in intensive care until his vital signs remained stable for a full twenty-four hours.","t":"医生让病人一直待在重症监护室，直到他的生命体征**稳定**保持了整整二十四小时。"},
"retrospective":{"e":"The gallery organized a retrospective of the painter's entire career, spanning six decades of dramatically shifting styles.","t":"画廊为这位画家举办了一场**回顾展**，涵盖了他风格剧烈变化的六十年创作生涯。"},
"overt":{"e":"Rather than staging an overt rebellion, the employees expressed their discontent through quiet, deliberate slowdowns in productivity.","t":"员工们没有发动**公开**的反抗，而是通过悄悄地故意放慢工作效率来表达不满。"},
"contributory":{"e":"Investigators concluded that poor lighting had been a contributory factor in the accident, though not its sole cause.","t":"调查人员断定照明不良是这起事故的一个**促成**因素，尽管并非唯一原因。"},
"puff":{"e":"By the time he reached the fourth floor, he was puffing so hard that he had to sit down.","t":"等他爬到四楼时，已经**气喘吁吁**，不得不坐下来喘口气。"},
"instill":{"e":"Good coaches instill discipline in young athletes long before they ever compete in a single official match.","t":"优秀的教练早在年轻运动员参加第一场正式比赛之前，就已经**逐渐培养**起他们的纪律性。"},
"depress":{"e":"A flood of cheap imports depressed local wheat prices so severely that many small farmers went bankrupt that year.","t":"大量廉价进口产品严重**压低**了当地小麦价格，导致许多小农户当年就破产了。"},
"avenge":{"e":"The young prince vowed to avenge his father's murder, even if it meant waging war against his own uncle.","t":"年轻的王子发誓要为父亲的谋杀**报仇**，哪怕这意味着要对自己的叔叔发动战争。"},
"gush":{"e":"The moment the drill broke through, oil gushed upward with such force that it coated the entire rig.","t":"钻头一钻透地层，石油便猛烈地向上**喷涌**而出，喷得整个钻井平台都是。"},
"predispose":{"e":"A family history of heart disease can predispose someone to similar cardiovascular problems later in life.","t":"有心脏病家族病史的人，日后**更容易患上**类似的心血管疾病。"},
"languish":{"e":"Without adequate funding, the small science museum languished for years, its exhibits growing dustier and more outdated each season.","t":"由于资金不足，这家小型科学博物馆多年来一直**每况愈下**，展品一季比一季更加陈旧过时。"},
"ravage":{"e":"Wildfires ravaged the hillside community, leaving nothing standing except a few blackened chimneys among the ashes.","t":"野火**摧毁**了这个山坡社区，废墟中只剩下几根熏黑的烟囱还立着。"},
"exodus":{"e":"Rising rents triggered a mass exodus of young families from the neighborhood they had called home for generations.","t":"房租上涨引发了年轻家庭的大规模**外迁**，他们曾世代把这个社区当作自己的家。"},
"brief":{"e":"The CEO's brief statement gave almost no details, leaving reporters with far more questions than answers.","t":"首席执行官**简短**的声明几乎没有透露任何细节，留给记者的疑问远多于答案。"},
"subject":{"e":"Climate migration has become the subject of her doctoral dissertation, which she has been researching for nearly four years.","t":"气候移民已经成为她博士论文的**主题**，她为此已经研究了将近四年。"},
"couple":{"e":"The elderly couple had walked the same beach every evening for fifty years, hand in hand regardless of weather.","t":"这对老**夫妇**五十年来每晚都手牵手走在同一片海滩上，无论天气如何。"},
"downtown":{"e":"Every downtown restaurant was fully booked that Friday night, forcing us to drive nearly an hour to find a table.","t":"那个周五晚上**市中心**的每家餐厅都订满了，逼得我们开了将近一个小时的车才找到一张桌子。"},
"backlighting":{"e":"The photographer used dramatic backlighting to outline the dancer's silhouette sharply against the glowing orange evening horizon.","t":"摄影师运用强烈的**逆光**手法，将舞者的剪影清晰地勾勒在橙色的黄昏天际线上。"},
"mild":{"e":"Thanks to the region's unusually mild winters, residents rarely bother owning heavy coats or snow boots.","t":"得益于该地区异常**温和**的冬天，居民很少需要购置厚重的外套或雪地靴。"},
"soluble":{"e":"Unlike table salt, which dissolves quickly, some minerals are barely soluble in water even after hours of stirring.","t":"不像食盐那样很快溶解，有些矿物质即使搅拌数小时也几乎不**溶于**水。"},
"academy":{"e":"She earned admission to the prestigious military academy after scoring in the top one percent nationwide.","t":"她凭借全国排名前百分之一的成绩，被这所声望卓著的军事**学院**录取。"},
"optimistic":{"e":"Despite the grim forecast, the coach remained stubbornly optimistic that his injured team could still win the championship.","t":"尽管前景黯淡，教练依然固执地**乐观**相信他伤兵满营的球队仍能夺冠。"},
"marked":{"e":"There was a marked improvement in her test scores once she started studying with a tutor twice weekly.","t":"自从她开始每周两次跟家教学习之后，考试成绩有了**显著**的提高。"},
"typify":{"e":"The crumbling factories and boarded-up storefronts typify the economic decline that swept through this once-prosperous mill town.","t":"破败的工厂和钉着木板的店面正是这座曾经繁荣的磨坊小镇经济衰退的**典型写照**。"},
"gallery":{"e":"A small gallery downtown agreed to display her paintings, giving the unknown artist her very first public exhibition.","t":"市中心一家小**画廊**同意展出她的画作，让这位籍籍无名的艺术家迎来了首次公开展览。"},
"compile":{"e":"It took the editors nearly a year to compile every letter the poet had written into a single volume.","t":"编辑们花了将近一年时间，把这位诗人写过的每一封信**汇编**成一册。"},
"hoe":{"e":"Every summer morning, the old farmer would hoe his vegetable rows before the sun grew too hot to work.","t":"每个夏天的早晨，老农都会在太阳变得毒辣得无法劳作之前，把菜垄**锄**一遍。"},
"stride":{"e":"With one confident stride after another, she crossed the finish line well ahead of every other runner.","t":"她迈着一个个自信的**大步**，遥遥领先于其他所有跑者冲过了终点线。"},
"fade":{"e":"The curtains that once hung a rich crimson had faded to a dull, washed-out pink after years in sunlight.","t":"这些窗帘曾经是浓艳的深红色，经年累月的日晒已经**褪色**成暗淡发白的粉色。"},
"tunnel":{"e":"Workers spent six years boring a tunnel straight through the mountain to connect the two isolated valleys.","t":"工人们花了六年时间在山中凿通一条**隧道**，将两个与世隔绝的山谷连接起来。"},
"highlight":{"e":"The report highlighted several glaring safety violations that inspectors had somehow overlooked during the previous three visits.","t":"这份报告**着重指出**了几项明显的安全违规，而检查员在此前三次视察中竟都忽略了。"},
"calm":{"e":"The captain waited for the sea to grow calm before finally attempting to launch the small rescue boat.","t":"船长等到海面**平静**下来，才终于尝试放下那艘小型救生艇。"},
"wrinkle":{"e":"The cheap cotton shirt wrinkled badly after just one wash, no matter how carefully she ironed it afterward.","t":"这件廉价棉衬衫洗一次就**起皱**得很厉害，无论她之后多仔细地熨烫都没用。"},
"cube":{"e":"She dropped a single ice cube into the whiskey, just enough to soften the burn without diluting it much.","t":"她往威士忌里放了一颗**冰块**，刚好能缓和辣喉感，又不至于稀释太多酒味。"},
"plank":{"e":"One rotten plank in the old dock gave way beneath his foot, dropping him straight into the cold lake.","t":"老码头上一块腐烂的**木板**在他脚下塌陷，把他直接摔进了冰冷的湖水里。"},
"transfer":{"e":"Homesick and unhappy, she decided to transfer to a university closer to her family after just one semester.","t":"由于思乡且不开心，她读了才一学期就决定**转学**到一所离家更近的大学。"},
"situated":{"e":"The monastery is situated high on a remote cliffside, accessible only by a narrow, winding mountain trail.","t":"这座修道院**坐落**在一处偏远的悬崖高处，只能通过一条狭窄蜿蜒的山路抵达。"},
"eclecticism":{"e":"The architect's eclecticism combined Gothic arches, Art Deco lines, and traditional local stonework into one striking, unified facade.","t":"这位建筑师的**折中主义**风格把哥特式拱门、装饰艺术线条与传统本地石工融合成一个引人注目的统一立面。"},
"piracy":{"e":"Piracy off that stretch of coast grew so common that merchant ships began traveling only in armed convoys.","t":"那段海岸附近的**海盗活动**变得如此猖獗，商船开始只能在武装护航下航行。"},
"deception":{"e":"The entire scheme relied on deception, convincing investors that a nonexistent gold mine was about to strike it rich.","t":"整个骗局都建立在**欺骗**之上，让投资者相信一座根本不存在的金矿即将挖出财富。"},
"blanket":{"e":"A thick blanket of fog rolled over the harbor before dawn, hiding every ship anchored in the bay.","t":"黎明前，一层厚厚的**雾毯**笼罩了海港，把湾内停泊的每艘船都遮蔽了起来。"},
"dissenter":{"e":"Only one dissenter on the twelve-member jury refused to vote guilty, forcing the entire trial into a deadlock.","t":"十二人陪审团中只有一名**反对者**拒绝投票定罪，导致整个审判陷入僵局。"},
"habit":{"e":"Breaking the habit of checking her phone every few minutes proved far harder than she had ever expected.","t":"戒掉每隔几分钟就看一次手机的**习惯**，比她预想的要难得多。"},
"dictate":{"e":"Financial constraints, far more than personal preference, ultimately dictated which university she would end up attending that fall.","t":"经济上的限制，远比个人喜好更能**决定**她那年秋天最终会上哪所大学。"},
"friction":{"e":"Constant friction between the two co-founders eventually split the startup apart just as it began turning a profit.","t":"两位联合创始人之间持续的**摩擦**最终拆散了这家初创公司，就在它刚开始盈利之际。"},
"subway":{"e":"During rush hour, the subway platform grew so crowded that three trains passed before she could squeeze aboard.","t":"高峰时段**地铁**站台变得异常拥挤，过去了三班车她才终于挤上车。"},
"niche":{"e":"After years of drifting between jobs, she finally found her niche designing sustainable packaging for small food companies.","t":"辗转换了多年工作之后，她终于找到了自己的**定位**——为小型食品公司设计可持续包装。"},
"rush":{"e":"Panicked commuters rushed toward the closing subway doors, shoving past one another to squeeze inside before the alarm sounded.","t":"惊慌的通勤者们**冲**向即将关闭的地铁门，互相推搡着想在警报响起前挤进去。"},
"embody":{"e":"The cathedral's soaring arches embody the medieval belief that architecture could lift the human spirit toward the divine.","t":"大教堂高耸的拱门**体现**了中世纪的信念：建筑能将人类的精神提升至神圣之境。"},
"inviting":{"e":"After the long hike, the shaded lake looked so inviting that we stripped off our boots and waded in immediately.","t":"长途跋涉后，那片树荫下的湖泊看起来太**诱人**了，我们立刻脱掉靴子蹚了进去。"},
"elective":{"e":"Because calculus was elective rather than required, many students chose an easier course to protect their grade point average.","t":"因为微积分是**选修**课而非必修课，许多学生选择了较容易的课程来保住绩点。"},
"rhinoceros":{"e":"The rhinoceros charged across the savanna with surprising speed, its thick horn lowered toward the fleeing photographer's jeep.","t":"那头**犀牛**以惊人的速度冲过大草原，粗壮的角对准了正在逃跑的摄影师的吉普车。"},
"herald":{"e":"The first robin's song heralded the arrival of spring, promising an end to weeks of gray, bitter cold.","t":"第一只知更鸟的歌声**预示**着春天的到来，宣告数周灰暗严寒的天气即将结束。"},
"affirm":{"e":"The witness affirmed under oath that she had seen the defendant leave the building minutes before the fire started.","t":"证人宣誓后**断言**，她看见被告在火灾发生前几分钟离开了大楼。"},
"modem":{"e":"The old modem screeched and buzzed for nearly a minute before it finally established a slow connection to the internet.","t":"那台旧**调制解调器**尖叫嗡鸣了将近一分钟，才终于建立起缓慢的网络连接。"},
"compensate":{"e":"The airline agreed to compensate passengers for the canceled flight by covering their hotel costs and issuing travel vouchers.","t":"航空公司同意通过承担酒店费用并发放旅行代金券来**赔偿**因航班取消而受影响的乘客。"},
"wax":{"e":"Every Sunday my father waxed the old sedan until its faded paint gleamed like it had just left the showroom.","t":"每个周日，我父亲都会给那辆旧轿车**打蜡**，直到褪色的车漆闪耀得如同刚出厂一样。"},
"psychoanalysis":{"e":"Years of psychoanalysis helped her uncover childhood memories that explained her lifelong fear of abandonment.","t":"多年的**精神分析**帮助她发掘出解释她终生害怕被抛弃的童年记忆。"},
"least":{"e":"Of all the candidates, he had shown the least enthusiasm during the interview, barely making eye contact with the panel.","t":"在所有候选人中，他在面试时表现出的热情**最少**，几乎没有与评审团有眼神交流。"},
"cardinal":{"e":"Honesty is the cardinal virtue that every member of the medical board expects from its practicing physicians.","t":"诚实是医学委员会期望每位执业医生具备的**最重要**的美德。"},
"organism":{"e":"Even the simplest organism in the tide pool depends on a delicate balance of oxygen, salinity, and temperature to survive.","t":"即使是潮汐池中最简单的**生物**，也依赖氧气、盐度和温度之间微妙的平衡才能生存。"},
"herb":{"e":"My grandmother steeped a bitter herb in hot water every evening, insisting it would cure whatever ailed us.","t":"我祖母每晚都用热水浸泡一种苦涩的**药草**，坚称它能治愈我们的任何不适。"},
"federal":{"e":"Under the federal system, individual states retain significant authority even though a central government sets policy on national issues.","t":"在**联邦**制度下，尽管中央政府制定国家层面的政策，各州仍保留着相当大的自主权。"},
"differentiate":{"e":"Trained sommeliers can differentiate between two wines from neighboring vineyards based solely on subtle differences in aroma.","t":"训练有素的品酒师仅凭香气上的细微差别，就能**区分**来自相邻葡萄园的两款葡萄酒。"},
"otherwise":{"e":"The bridge's paint had faded badly, but otherwise the century-old structure remained structurally sound and safe to cross.","t":"这座桥的油漆已严重褪色，但**除此之外**，这座有百年历史的建筑依然结构稳固、可以安全通行。"},
"steady":{"e":"Despite the storm rocking the boat, the captain kept a steady hand on the wheel and guided us safely to harbor.","t":"尽管暴风雨摇晃着船只，船长仍**稳稳地**掌着舵，带领我们安全抵达港口。"},
"ignore":{"e":"The manager chose to ignore the safety complaints from workers, a decision that led directly to the factory accident.","t":"经理选择**忽视**工人们的安全投诉，这一决定直接导致了工厂事故。"},
"originate":{"e":"The tradition of exchanging rings during weddings originated in ancient Egypt, where circles symbolized eternity.","t":"婚礼上交换戒指的传统**起源于**古埃及，圆形在那里象征着永恒。"},
"aerial":{"e":"The photographer used a drone to capture aerial shots of the canyon that no ground-based camera could ever achieve.","t":"摄影师用无人机拍摄峡谷的**空中**照片，这是任何地面相机都无法实现的。"},
"lipid":{"e":"Cell membranes are built primarily from lipid molecules that arrange themselves into a flexible, water-resistant double layer.","t":"细胞膜主要由**脂质**分子构成，这些分子会自我排列成柔韧且防水的双层结构。"},
"interactive":{"e":"The museum's new exhibit is fully interactive, letting visitors touch screens and trigger animations instead of just reading placards.","t":"博物馆的新展览是完全**交互式**的，游客可以触摸屏幕并触发动画，而不只是阅读说明牌。"},
"disconcert":{"e":"The sudden silence from the usually talkative audience disconcerted the speaker so much that he lost his place in the speech.","t":"平时话多的观众突然陷入沉默，这**使演讲者惊慌不安**，以至于他忘记了讲到哪里。"},
"induct":{"e":"The veteran quarterback was inducted into the Hall of Fame during a ceremony attended by thousands of former teammates and fans.","t":"这位资深四分卫在数千名前队友和球迷出席的仪式上被**正式接纳**进入名人堂。"},
"wedge":{"e":"The carpenter hammered a wooden wedge beneath the table leg to stop it from wobbling on the uneven floor.","t":"木匠在桌腿下敲入一个木**楔子**，以防止它在不平的地板上摇晃。"},
"rape":{"e":"Environmentalists condemned the rape of the ancient forest, where centuries-old trees were clear-cut within a single reckless season.","t":"环保人士谴责了对这片古老森林的**肆意破坏**，数百年树龄的树木在短短一季内被鲁莽砍伐殆尽。"},
"culminate":{"e":"Months of secret negotiations culminated in a historic peace treaty that both nations' leaders signed before an international audience.","t":"数月的秘密谈判**达到顶点**，最终两国领导人在国际观众面前签署了一项具有历史意义的和平条约。"},
"predation":{"e":"Zebra herds move in tight formation on the open plain to reduce the risk of predation by lurking lions.","t":"斑马群在开阔的平原上紧密排列移动，以降低被潜伏的狮子**捕食**的风险。"},
"gloss":{"e":"The fresh coat of varnish gave the antique table a deep gloss that made its wood grain look almost wet.","t":"新刷的清漆让这张古董桌子呈现出深邃的**光泽**，木纹看起来几乎像是湿润的。"},
"adjoin":{"e":"The small chapel adjoins the main cathedral, sharing a single stone wall that dates back to the twelfth century.","t":"这座小教堂**紧挨**着主教堂，共用一堵可追溯至十二世纪的石墙。"},
"shear":{"e":"Every spring, the farmhands shear the sheep before the summer heat arrives, collecting wool that will later be spun into yarn.","t":"每年春天，农场工人们都会在夏日酷热来临之前给绵羊**剪毛**，收集的羊毛之后会被纺成纱线。"},
"puritanical":{"e":"Her puritanical upbringing left her uneasy about dancing, drinking, or anything else she considered frivolous or indulgent.","t":"她**极端拘谨保守**的成长环境让她对跳舞、饮酒或任何她认为轻浮放纵的事都感到不安。"},
"anonymous":{"e":"An anonymous donor paid off the hospital's entire debt, leaving only a handwritten note instead of a name.","t":"一位**匿名**捐赠者还清了医院的全部债务，只留下一张手写的字条，没有署名。"},
"savage":{"e":"The critic's savage review of the film left the young director in tears backstage after the premiere.","t":"评论家对这部电影**凶狠**的评论让这位年轻导演在首映式后台落泪。"},
"cider":{"e":"We warmed mugs of spiced cider over the campfire while the leaves turned gold and red around us.","t":"我们围着篝火加热几杯加了香料的**苹果酒**，四周的树叶正变得金黄火红。"},
"barn":{"e":"The farmer stacked bales of hay inside the old barn to keep them dry before the winter snows arrived.","t":"农夫把干草捆堆放在这座旧**谷仓**里，好在冬雪来临前让它们保持干燥。"},
"awake":{"e":"The smell of fresh bread awoke memories of her grandmother's kitchen that she had not thought about in years.","t":"新鲜面包的香气**唤醒**了她多年未曾想起的、关于祖母厨房的记忆。"},
"stingy":{"e":"Even though he had inherited a fortune, he remained too stingy to leave the waiter more than a few coins.","t":"尽管他继承了一大笔财富，他仍然**吝啬**得不愿多给服务员几个硬币以外的小费。"},
"bargain":{"e":"She found a genuine designer coat at the thrift shop for ten dollars, an absolute bargain by any standard.","t":"她在旧货店以十美元的价格淘到一件真正的设计师大衣，无论怎么看都是一笔**划算的交易**。"},
"exceed":{"e":"The marathon runner's finishing time exceeded even her own coach's most optimistic predictions for the race.","t":"这位马拉松选手的完赛成绩甚至**超过**了她教练对这场比赛最乐观的预测。"},
"concave":{"e":"Light rays entering the telescope bounce off a large concave mirror that curves inward to focus the image.","t":"进入望远镜的光线会反射到一面向内弯曲用于聚焦成像的巨大**凹**面镜上。"},
"acknowledge":{"e":"The company finally acknowledged that its product had a dangerous defect, months after the first customer complaints arrived.","t":"在第一批顾客投诉出现数月之后，这家公司终于**承认**其产品存在危险缺陷。"},
"boast":{"e":"He boasted for an hour about his fishing trip, though the photos revealed a fish barely bigger than his hand.","t":"他**吹嘘**了整整一个小时他的钓鱼之旅，尽管照片显示那条鱼几乎没有他手掌大。"},
"distribute":{"e":"Volunteers distributed blankets and hot meals to hundreds of flood victims sheltering in the gymnasium overnight.","t":"志愿者们向在体育馆过夜避难的数百名洪灾受害者**分发**了毛毯和热食。"},
"turnout":{"e":"Election officials were stunned by the record turnout, with lines of voters stretching around the block before polls even opened.","t":"选举官员对创纪录的**投票人数**感到震惊，投票站尚未开门，选民队伍就已排到了街区外。"},
"jolt":{"e":"The news of her sudden resignation jolted the entire office, leaving colleagues scrambling to reassign her unfinished projects.","t":"她突然辞职的消息**震惊**了整个办公室，同事们手忙脚乱地重新分配她未完成的项目。"},
"spiral":{"e":"Medical costs spiraled out of control after the accident, forcing the family to sell their home to cover the bills.","t":"事故发生后，医疗费用**急剧攀升**，失去控制，迫使这家人卖掉房子来支付账单。"},
"perspective":{"e":"Traveling alone through unfamiliar countries gave her a fresh perspective on problems that had once seemed unsolvable at home.","t":"独自穿越陌生的国度让她对那些在家乡曾显得无解的问题有了全新的**看法**。"},
"mask":{"e":"Behind his cheerful mask, the comedian struggled privately with a loneliness none of his fans ever suspected.","t":"在他开朗的**伪装**背后，这位喜剧演员私下里承受着粉丝们从未察觉的孤独。"},
"hitherto":{"e":"The manuscript revealed hitherto unknown details about the author's final years, details that historians had never uncovered.","t":"这份手稿揭示了关于作者晚年**迄今为止**不为人知的细节，是历史学家从未发掘过的。"},
"comet":{"e":"Astronomers around the world trained their telescopes on the comet as it blazed past Earth for the first time in centuries.","t":"世界各地的天文学家将望远镜对准了这颗**彗星**，它正数百年来首次掠过地球。"},
"sociology":{"e":"Her sociology thesis examined how neighborhood poverty shapes children's expectations about their own future success.","t":"她的**社会学**论文研究了社区贫困如何影响孩子们对自身未来成功的期望。"},
"vault":{"e":"The bank's vault remained sealed for decades, its combination lost after the last surviving manager passed away.","t":"这家银行的**金库**封闭了数十年，最后一位在世的经理去世后，密码也随之失传。"},
"efficiency":{"e":"The factory doubled its output without hiring anyone new, simply by improving the efficiency of its assembly line.","t":"这家工厂没有招聘任何新员工，仅仅通过提高装配线的**效率**就使产量翻了一番。"},
"mime":{"e":"Unable to speak the local language, the tourist mimed drinking from a cup to ask the waiter for water.","t":"由于不会说当地语言，这位游客**用手势比划**出喝水的动作，向服务员要水。"},
"stratigraphy":{"e":"Geologists relied on stratigraphy to date the canyon walls, reading each colored layer like pages in an ancient book.","t":"地质学家依靠**地层学**来判断峡谷崖壁的年代，像读古书的书页一样解读每一层不同颜色的岩层。"},
"advance":{"e":"The research team's discovery advanced the field of genetics by decades, opening doors that had seemed permanently closed.","t":"该研究团队的发现将遗传学领域**推进**了数十年，打开了曾经看似永久关闭的大门。"},
"estimate":{"e":"Contractors estimated that repairing the storm damage would take at least three months and cost well over a hundred thousand dollars.","t":"承包商**估计**修复风暴造成的损失至少需要三个月时间，花费将远超十万美元。"},
"impetus":{"e":"The oil crisis provided the impetus for governments worldwide to invest heavily in renewable energy research.","t":"石油危机为世界各国政府大力投资可再生能源研究提供了**推动力**。"},
"attend":{"e":"Nurses attended to the wounded soldiers around the clock, changing bandages and monitoring fevers through the night.","t":"护士们日夜不停地**照料**受伤的士兵，整夜更换绷带并监测体温。"},
"solar":{"e":"The remote village finally got reliable electricity after engineers installed solar panels across every rooftop.","t":"工程师们在每户屋顶安装了**太阳能**电池板后，这个偏远村庄终于获得了可靠的电力供应。"},
"lodge":{"e":"The beavers built their lodge from mud and branches in the middle of the pond, safe from most predators.","t":"海狸们用泥巴和树枝在池塘中央建造了它们的**巢穴**，从而避开了大多数天敌。"},
"commentary":{"e":"The retired coach provided sharp commentary during the broadcast, explaining plays that casual viewers would otherwise miss entirely.","t":"这位退役教练在转播中提供了犀利的**解说**，讲解了普通观众原本完全会错过的战术。"},
"instruct":{"e":"The pilot instructed passengers to fasten their seatbelts immediately as the plane approached an area of severe turbulence.","t":"飞机接近强烈颠簸区域时，飞行员**指示**乘客立即系好安全带。"},
"gorilla":{"e":"The silverback gorilla beat its chest and let out a deep roar to warn the intruders away from its territory.","t":"这只银背**大猩猩**捶打胸膛并发出低沉的吼叫，警告入侵者远离它的领地。"},
"logical":{"e":"Given the company's shrinking profits, the logical next step was to cut costs rather than expand into new markets.","t":"鉴于公司利润不断萎缩，**合乎逻辑**的下一步是削减成本，而不是拓展新市场。"},
"monster":{"e":"Local children swore that a monster lived beneath the old bridge, though no one had ever actually seen it.","t":"当地孩子们坚称有一个**怪物**住在那座老桥下，尽管从没有人真正见过它。"},
"intriguing":{"e":"The professor posed an intriguing question that kept the entire lecture hall debating long after class had ended.","t":"教授提出了一个**引人入胜**的问题，让整个阶梯教室的学生在下课后仍争论不休。"},
"sedimentary":{"e":"Layers of sedimentary rock along the cliff face recorded millions of years of rivers depositing sand and mud.","t":"悬崖表面的**沉积**岩层记录了数百万年来河流沉积沙土的过程。"},
"participate":{"e":"Every employee was encouraged to participate in the volunteer program, even if only for a few hours each month.","t":"每位员工都被鼓励**参与**这项志愿服务项目，哪怕每月只贡献几个小时。"},
"mason":{"e":"The mason carefully fitted each stone block into place without any mortar, relying purely on precise cutting.","t":"这位**石匠**在不使用任何灰浆的情况下小心地将每块石头嵌入到位，完全依靠精确的切割。"},
"nationalism":{"e":"Rising nationalism across the region made diplomats increasingly nervous about the prospect of open border conflicts.","t":"该地区日益高涨的**民族主义**情绪让外交官们对公开边境冲突的前景越发担忧。"},
"heading":{"e":"She organized the report under clear headings so that busy executives could skim straight to the sections they needed.","t":"她用清晰的**标题**来组织报告，以便忙碌的高管能够直接浏览到他们需要的部分。"},
"communal":{"e":"Residents of the apartment complex share a communal garden where anyone can plant vegetables or simply relax on weekends.","t":"这栋公寓的居民共用一个**公共**花园，任何人都可以在那里种菜或在周末放松休息。"},
"fragile":{"e":"The museum handled the fragile manuscript with cotton gloves, aware that a single careless touch could crumble the ancient pages.","t":"博物馆工作人员戴着棉手套处理这份**脆弱**的手稿，深知一次不小心的触碰就可能使古老的书页破碎。"},
"competence":{"e":"The new surgeon demonstrated remarkable competence during her first solo operation, impressing even the most skeptical senior doctors.","t":"这位新外科医生在第一次独立手术中展现出非凡的**能力**，连最怀疑她的资深医生都印象深刻。"},
"lettuce":{"e":"She tossed fresh lettuce, tomatoes, and cucumbers together for a simple salad to accompany the grilled chicken.","t":"她把新鲜的**生菜**、番茄和黄瓜拌在一起，做了一份简单的沙拉搭配烤鸡。"},
"vacant":{"e":"The old factory has stood vacant for fifteen years, its broken windows now home to pigeons and stray cats.","t":"这座老工厂已经**闲置**了十五年，破碎的窗户如今成了鸽子和流浪猫的栖身之所。"},
"apportion":{"e":"The judge apportioned blame for the accident equally between both drivers after reviewing the traffic camera footage.","t":"法官在审查了交通摄像头录像后，将这起事故的责任平均**分配**给两名司机。"},
"juvenile":{"e":"The wildlife rescue center currently cares for three juveniles that were separated from their mothers during the wildfire.","t":"这家野生动物救助中心目前照顾着三只在野火中与母亲失散的**幼崽**。"},
"status":{"e":"Winning the championship instantly elevated the underdog team's status from local curiosity to national sports phenomenon.","t":"赢得冠军后，这支不被看好的球队的**地位**瞬间从地方新奇事物变成了全国性的体育现象。"},
"promote":{"e":"The company promoted her to regional manager after she consistently exceeded every sales target for three straight years.","t":"在连续三年持续超额完成每一项销售指标后，公司将她**提升**为区域经理。"},
"academic":{"e":"The debate over whether ghosts exist remained purely academic to the scientist, who cared only about testable evidence.","t":"关于鬼魂是否存在的争论对这位只关心可检验证据的科学家来说纯属**空谈**。"},
"rigor":{"e":"The academy's rigor pushed many first-year cadets to their breaking point, with several dropping out before winter arrived.","t":"这所学院的**严格**要求把许多一年级学员逼到了崩溃边缘，有几人在冬天来临前就退学了。"},
"complex":{"e":"The negotiations grew so complex that lawyers from both sides needed an extra month just to review the contract's implications.","t":"谈判变得如此**复杂**，以至于双方的律师需要额外一个月的时间才能审阅完合同的各项影响。"},
"franchise":{"e":"The fast-food franchise expanded rapidly after the parent company began licensing its brand to independent local owners.","t":"在母公司开始将品牌**特许经营权**授权给独立的本地业主后，这家快餐连锁迅速扩张。"},
"item":{"e":"Before boarding, security flagged one item in her carry-on bag that needed to be inspected more closely.","t":"登机前，安检人员标记出她随身行李中的一**件物品**需要进一步检查。"},
"grip":{"e":"The thriller gripped readers so completely that many finished all four hundred pages in a single sleepless night.","t":"这部惊悚小说**牢牢吸引住**了读者，许多人在一个不眠之夜就读完了全部四百页。"},
"ridiculous":{"e":"It seemed ridiculous to cancel the entire festival just because of a slight chance of afternoon rain.","t":"仅仅因为下午有一点下雨的可能就取消整个节日，这似乎太**荒唐**了。"},
"mode":{"e":"Commuters increasingly chose cycling as their preferred mode of transportation once the city added protected bike lanes.","t":"自从城市增设了受保护的自行车道后，通勤者们越来越多地选择骑行作为首选的出行**方式**。"},
"cactus":{"e":"The desert hiker learned to spot water-storing cactus plants that could, in an emergency, provide a bit of moisture.","t":"这位沙漠徒步者学会了辨认能储水的**仙人掌**，紧急情况下它能提供一点水分。"},
"silica":{"e":"Manufacturers heat pure silica to extreme temperatures to produce the clear glass used in laboratory beakers.","t":"制造商将纯**硅石**加热到极高温度，以生产用于实验室烧杯的透明玻璃。"},
"insight":{"e":"The therapist's simple question gave her sudden insight into why she had been sabotaging her own relationships for years.","t":"治疗师的一个简单问题让她突然**领悟**到自己多年来为何一直在破坏自己的感情关系。"},
"concept":{"e":"Young children often struggle with the abstract concept of infinity, since nothing in their daily experience is truly endless.","t":"幼儿通常难以理解无穷这一抽象**概念**，因为他们日常经验中没有任何东西是真正无限的。"},
"swift":{"e":"The falcon's swift dive toward its prey covered nearly two hundred feet in under three seconds.","t":"这只猎鹰向猎物**迅捷**俯冲，不到三秒钟就飞过了近两百英尺。"},
"noted":{"e":"A noted heart surgeon flew in from another country specifically to consult on the child's rare condition.","t":"一位**著名**的心脏外科医生专程从另一个国家飞来，就这个孩子的罕见病情提供会诊。"},
"fable":{"e":"The teacher used an ancient fable about a tortoise and a hare to explain why patience often outlasts talent.","t":"老师用一则关于乌龟和兔子的古老**寓言**来解释为什么耐心往往比天赋更持久。"},
"diplomat":{"e":"The seasoned diplomat defused the tense standoff with careful wording that offended no one on either delegation.","t":"这位经验丰富的**外交官**用措辞谨慎的话语化解了紧张的僵局，没有冒犯任何一方代表团。"},
"mutual":{"e":"Their business partnership thrived for decades because it was built on mutual respect rather than a signed contract.","t":"他们的商业伙伴关系之所以能持续数十年，是因为它建立在**相互**尊重之上，而非一纸合同。"},
"odd":{"e":"Neighbors found it odd that the lights in the abandoned house kept turning on every night at exactly midnight.","t":"邻居们觉得那栋废弃房子里的灯每晚都恰好在午夜准时亮起，这十分**古怪**。"},
"confidant":{"e":"The queen trusted only one confidant with the secret of her failing health, swearing her to absolute silence.","t":"女王只把自己健康每况愈下的秘密告诉了一位**知己**，并让她发誓绝对保密。"},
"bureaucracy":{"e":"Applying for the permit required wading through so much bureaucracy that the small business nearly gave up entirely.","t":"申请这项许可需要应付大量**官僚**程序，以至于这家小企业差点彻底放弃。"},
"feign":{"e":"The soldier feigned sleep so convincingly that the guards walked right past his cell without a second glance.","t":"这名士兵**假装**睡着的样子如此逼真，以至于守卫径直走过他的牢房，没有多看一眼。"},
"disastrous":{"e":"The company's decision to skip quality testing proved disastrous when thousands of defective units had to be recalled.","t":"这家公司决定跳过质量检测的做法被证明是**灾难性**的，导致数千件缺陷产品不得不召回。"},
"complaint":{"e":"After receiving dozens of complaints about the noise, the restaurant finally agreed to close its outdoor patio by ten.","t":"在收到数十起关于噪音的**投诉**后，这家餐厅终于同意在十点前关闭其户外露台。"},
"frail":{"e":"The frail old man needed both a cane and his daughter's arm just to cross the short hallway.","t":"这位**体弱**的老人需要拄着拐杖并挽着女儿的手臂才能走过这短短的走廊。"},
"blaze":{"e":"Firefighters battled the blaze for six straight hours before finally bringing the warehouse fire under control.","t":"消防员连续奋战六个小时扑灭这场**大火**，才终于控制住仓库火情。"},
"snide":{"e":"His snide remark about her cooking left the whole table uncomfortably silent for several long seconds.","t":"他对她厨艺的**挖苦**评论让全桌人尴尬地沉默了好几秒钟。"},
"empiricism":{"e":"The philosopher's empiricism held that all genuine knowledge must ultimately trace back to direct sensory experience.","t":"这位哲学家的**经验主义**主张，一切真正的知识最终都必须追溯到直接的感官经验。"},
"falter":{"e":"Her voice faltered as she reached the part of the eulogy describing her father's final days.","t":"当她念到悼词中描述父亲最后时日的部分时，她的声音开始**颤抖**。"},
"mismanage":{"e":"Investors accused the fund's directors of mismanaging their savings, pointing to years of reckless and unexplained trades.","t":"投资者指责基金董事们**管理不当**他们的储蓄，指出多年来存在鲁莽且无法解释的交易。"},
"lust":{"e":"His lust for power drove him to betray every friend who had helped him climb to the top.","t":"他对权力的**强烈渴望**驱使他背叛了每一位曾帮助他攀上高位的朋友。"},
"stampede":{"e":"A sudden clap of thunder caused the entire herd of cattle to stampede toward the far fence.","t":"突然一声雷响，让整群牛**狂奔**向远处的围栏。"},
"overnight":{"e":"The startup's overnight success surprised even its founders, who had expected years of slow, gradual growth.","t":"这家初创公司**一夜之间**的成功连创始人自己都感到惊讶，他们原本预期会经历多年缓慢的增长。"},
"torpor":{"e":"The bear's body slows into a state of torpor throughout winter, allowing it to survive months without eating.","t":"熊的身体在整个冬天会进入一种**迟钝**的状态，使它能在数月不进食的情况下存活。"},
"shed":{"e":"Snakes periodically shed their old skin as their bodies grow too large for it to contain them.","t":"蛇会定期**脱掉**旧皮，因为它们的身体已长得太大，旧皮无法再容纳。"},
"hierarchy":{"e":"The company's rigid hierarchy made it nearly impossible for a junior employee's idea to reach senior management.","t":"这家公司森严的**等级制度**使得初级员工的想法几乎不可能传达到高层管理者那里。"},
"aluminum":{"e":"Engineers chose aluminum for the aircraft's frame because it offers strength without the heavy weight of steel.","t":"工程师为飞机机身选择了**铝**，因为它既坚固又不像钢材那样沉重。"},
"deplete":{"e":"Decades of overfishing have depleted the cod population so severely that some fishing grounds remain closed to this day.","t":"数十年的过度捕捞已使鳕鱼种群**枯竭**，以至于一些渔场至今仍处于禁渔状态。"},
"pattern":{"e":"Detectives noticed a pattern in the burglaries, each occurring exactly one week after the previous one on a Friday night.","t":"侦探们注意到这些盗窃案存在一种**规律**，每一起都恰好在上一起发生一周后的周五夜晚发生。"},
"shirk":{"e":"He never shirked his responsibilities, even when the assigned task was tedious, exhausting, or thoroughly unpleasant.","t":"即使分配的任务枯燥、累人或极其令人不快，他也从不**逃避**自己的责任。"},
"quasar":{"e":"Astronomers detected a distant quasar whose brightness outshines that of an entire galaxy of ordinary stars.","t":"天文学家探测到一个遥远的**类星体**，其亮度超过了一整个普通恒星星系。"},
"humorous":{"e":"The professor's humorous asides kept even the driest lecture on tax law entertaining for three straight hours.","t":"教授**幽默**的插话让即使是关于税法这样枯燥的讲座也能连续三个小时保持趣味性。"},
"cite":{"e":"The lawyer cited three previous court rulings to support her argument that the contract was legally void.","t":"这位律师**引用**了三个先前的判例来支持她关于该合同在法律上无效的论点。"},
"offensive":{"e":"Several viewers found the comedian's joke about the tragedy deeply offensive and demanded a public apology.","t":"一些观众认为这位喜剧演员关于这场悲剧的笑话极具**冒犯性**，要求公开道歉。"},
"emerge":{"e":"New evidence emerged during the trial that completely contradicted the testimony the main witness had given earlier.","t":"审判期间**浮现**出的新证据完全推翻了主要证人先前提供的证词。"},
"tactic":{"e":"The coach devised a defensive tactic specifically designed to neutralize the opposing team's fastest striker.","t":"教练设计了一种防守**战术**，专门用来克制对方最快的前锋。"},
"awareness":{"e":"The nonprofit's campaign raised public awareness about ocean pollution far more effectively than any government report had.","t":"这家非营利组织的宣传活动比任何政府报告都更有效地提高了公众对海洋污染的**意识**。"},
"rehabilitate":{"e":"The physical therapist worked for months to rehabilitate the athlete's torn ligament before clearing her to compete again.","t":"物理治疗师花了数月时间**修复**这位运动员撕裂的韧带，然后才允许她重新参赛。"},
"blizzard":{"e":"The blizzard dumped nearly three feet of snow overnight, forcing schools and offices across the state to close.","t":"这场**暴风雪**一夜之间降下近三英尺的积雪，迫使全州的学校和办公室停课停工。"},
"mold":{"e":"Black mold spread across the bathroom ceiling after the leaking pipe went unnoticed for several weeks.","t":"由于漏水的管道数周未被发现，黑色**霉菌**在浴室天花板上蔓延开来。"},
"ease":{"e":"The veteran pilot landed the damaged plane with remarkable ease, despite one engine having failed completely.","t":"尽管有一台引擎完全失灵，这位经验丰富的飞行员仍以惊人的**从容**降落了受损的飞机。"},
"roe":{"e":"The chef carefully spooned salmon roe onto each appetizer, adding a burst of salty brightness to the dish.","t":"厨师小心翼翼地将三文鱼**鱼卵**舀到每份开胃菜上，为菜肴增添一抹咸鲜的亮色。"},
"fin":{"e":"The shark's dorsal fin sliced through the surface of the water, sending nearby swimmers scrambling toward the shore.","t":"鲨鱼的背**鳍**划破水面，吓得附近的游泳者纷纷向岸边逃去。"},
"mythology":{"e":"Greek mythology explains natural phenomena like thunder and the changing seasons through stories of quarreling gods.","t":"希腊**神话**通过讲述众神争斗的故事来解释雷电和季节更替等自然现象。"},
"drastic":{"e":"The hospital took drastic measures during the outbreak, closing its doors to all visitors for nearly two months.","t":"疫情期间，医院采取了**剧烈**的措施，将近两个月内谢绝一切探视者。"},
"healing":{"e":"Local villagers still swear by the healing properties of the spring water that bubbles up near the old temple.","t":"当地村民仍然坚信从老庙附近涌出的泉水具有**治疗**功效。"},
"blush":{"e":"She blushed deeply when the professor read her anonymous essay aloud as an example of outstanding writing.","t":"当教授把她那篇匿名论文当作优秀范文大声朗读时，她**脸红**得厉害。"},
"melodic":{"e":"The composer's melodic lines stayed in listeners' heads for days after the symphony's premiere performance.","t":"这位作曲家优美的**旋律**在交响乐首演后仍萦绕在听众脑海中好几天。"},
"cubism":{"e":"Picasso's early experiments with cubism shattered familiar objects into fragmented planes viewed from several angles at once.","t":"毕加索早期对**立体主义**的探索将熟悉的物体打碎成从多个角度同时呈现的破碎平面。"},
"magnet":{"e":"The charismatic teacher became a magnet for struggling students who finally felt someone believed in their potential.","t":"这位富有魅力的老师成了那些学业困难学生的**磁石**，他们终于感觉到有人相信自己的潜力。"},
"pensive":{"e":"She sat by the window in a pensive mood, watching the rain and thinking about the decision she still had to make.","t":"她**若有所思**地坐在窗边，望着雨水，思考着自己仍需做出的决定。"},
"signify":{"e":"A red flag on the beach signifies that swimming conditions are dangerous and lifeguards may not be able to help.","t":"海滩上的红旗**表示**游泳条件危险，救生员可能无法提供帮助。"},
"aware":{"e":"Employees should remain aware of the new safety protocols before operating any machinery on the factory floor.","t":"员工在操作车间的任何机器之前，都应保持对新安全规程的**知晓**。"},
"informant":{"e":"The anthropologist relied on a village elder as her main informant for understanding the tribe's ancient burial customs.","t":"这位人类学家依靠一位村中长者作为她了解该部落古老丧葬习俗的主要**信息提供者**。"},
"narrate":{"e":"A soft-spoken actor narrated the entire documentary, guiding viewers gently through decades of the city's turbulent history.","t":"一位声音柔和的演员**讲述**了整部纪录片，带领观众平静地了解这座城市数十年的动荡历史。"},
"former":{"e":"The former mayor still attends every town meeting, offering advice even though he left office years ago.","t":"这位**前任**市长仍然出席每一次镇民大会，尽管他已卸任多年，依然提供建议。"},
"accredit":{"e":"The board voted to accredit the new medical school only after it met every rigorous standard for faculty and facilities.","t":"董事会只有在这所新医学院满足师资和设施方面的所有严格标准后，才投票**正式认可**了它。"},
"puddle":{"e":"Children jumped gleefully from puddle to puddle on their way home, soaking their shoes despite their mother's warnings.","t":"孩子们在回家的路上兴高采烈地从一个**水坑**跳到另一个水坑，尽管母亲警告过，鞋子还是湿透了。"},
"tragic":{"e":"The tragic collision claimed the lives of three passengers who had boarded the train only minutes earlier.","t":"这场**悲惨**的相撞事故夺去了三名乘客的生命，他们仅在几分钟前刚登上这列火车。"},
"assert":{"e":"The scientist asserted confidently that the new vaccine would reduce infection rates by more than half.","t":"这位科学家自信地**断言**，这种新疫苗能将感染率降低一半以上。"},
"concomitant":{"e":"Rapid urban growth brought concomitant problems of traffic congestion, air pollution, and rising housing costs.","t":"快速的城市增长带来了**伴随**而来的交通拥堵、空气污染和房价上涨等问题。"},
"oversleep":{"e":"He overslept on the morning of his final exam, waking up in a panic just twenty minutes before it began.","t":"他在期末考试当天早上**睡过了头**，在考试开始前二十分钟才惊慌醒来。"},
"terrific":{"e":"The chef prepared a terrific meal for the anniversary, complete with three courses and a homemade dessert.","t":"厨师为周年纪念准备了一顿**极好**的大餐，包括三道菜和一份自制甜点。"},
"motif":{"e":"A recurring motif of broken mirrors runs throughout the novel, symbolizing the protagonist's fractured sense of identity.","t":"破碎镜子这一反复出现的**主题**贯穿全书，象征着主人公支离破碎的身份认同感。"},
"parachute":{"e":"The skydiver's parachute failed to open automatically, forcing him to pull the emergency cord at the last second.","t":"跳伞者的**降落伞**未能自动打开，迫使他在最后一秒拉动了应急拉绳。"},
"shore":{"e":"Waves crashed against the rocky shore all night, keeping everyone in the nearby cottages awake.","t":"整夜巨浪拍打着这片多岩石的**海岸**，让附近小屋里的所有人都无法入睡。"},
"chapel":{"e":"The couple exchanged vows in a tiny stone chapel that had stood on the hillside for over three hundred years.","t":"这对新人在一座矗立于山坡上已有三百多年历史的石头**小教堂**里交换了誓言。"},
"pollinate":{"e":"Without bees to pollinate the orchard's blossoms, farmers would lose nearly their entire apple harvest each year.","t":"如果没有蜜蜂给果园的花朵**授粉**，果农每年几乎会损失全部的苹果收成。"},
"twig":{"e":"The bird carried a single dry twig back to the nest, adding it carefully to the growing pile.","t":"这只鸟叼着一根干燥的**小树枝**飞回巢穴，小心地把它添加到日渐增高的巢材堆里。"},
"ablaze":{"e":"The entire hillside was ablaze within minutes, forcing residents to evacuate before the fire reached their homes.","t":"整个山坡几分钟内就**熊熊燃烧**起来，居民们被迫在大火蔓延到家门前撤离。"},
"vacate":{"e":"Tenants were given thirty days to vacate the building before the demolition crew arrived to tear it down.","t":"在拆除队到来拆毁大楼之前，租户们被给予三十天时间**腾空**这座建筑。"},
"explosion":{"e":"An explosion of interest in home gardening swept the country after grocery shelves emptied during the shortage.","t":"在物资短缺导致杂货店货架清空之后，全国掀起了对家庭园艺兴趣的**激增**。"},
"virtue":{"e":"Patience is a virtue that every kindergarten teacher must cultivate, especially during the chaotic first weeks of school.","t":"耐心是每位幼儿园老师都必须培养的**美德**，尤其是在开学最初混乱的几周里。"},
"course":{"e":"The hurricane suddenly changed course overnight, veering away from the coastline that forecasters had expected it to strike.","t":"这场飓风在一夜之间突然改变了**路线**，转向偏离了预报员原本预期它会袭击的海岸线。"},
"feudal":{"e":"Under the feudal system, peasants worked the land in exchange for protection from the lord who owned it.","t":"在**封建**制度下，农民耕种土地以换取拥有这片土地的领主提供的保护。"},
"tend":{"e":"Older houses in this climate tend to develop cracks in their foundations after just a few harsh winters.","t":"在这种气候条件下，老房子往往**容易**在经历几个严冬后地基就出现裂缝。"},
"charcoal":{"e":"The artist preferred charcoal over pencil for quick sketches, since its dark, smudged lines conveyed movement so vividly.","t":"这位艺术家更喜欢用**木炭**而非铅笔来快速素描，因为它深黑晕染的线条能极其生动地传达动感。"},
"varied":{"e":"The museum's varied collection ranges from ancient Egyptian pottery to abstract paintings created just last year.","t":"这家博物馆**多样化**的藏品，从古埃及陶器到去年才创作的抽象画作，应有尽有。"},
"offer":{"e":"The stranger offered his umbrella to the shivering woman waiting alone at the bus stop in the downpour.","t":"那位陌生人把自己的雨伞**递给**了在暴雨中独自等公交、瑟瑟发抖的女子。"},
"axis":{"e":"Earth's tilted axis is the reason the Northern and Southern Hemispheres experience opposite seasons throughout the year.","t":"地球倾斜的**轴**是南北半球全年经历相反季节的原因。"},
"feminist":{"e":"The novelist became an outspoken feminist after witnessing how differently her brother and she were treated growing up.","t":"这位小说家在目睹自己与兄弟成长过程中受到的截然不同的对待后，成为了一名直言不讳的**女权主义者**。"},
"identification":{"e":"Security guards at the entrance requested photo identification from every visitor before allowing them past the front desk.","t":"入口处的保安要求每位访客出示带照片的**身份证明**，才允许他们通过前台。"},
"audio":{"e":"The podcast's audio quality improved dramatically once the host invested in a proper microphone and soundproofing foam.","t":"自从主播购置了合适的麦克风和隔音海绵后，这档播客的**音频**质量有了显著提升。"},
"caterpillar":{"e":"The caterpillar spent nearly two weeks wrapped in its cocoon before emerging as a fully formed butterfly.","t":"这只**毛毛虫**在茧中度过了将近两周，之后才羽化成一只完整的蝴蝶。"},
"rash":{"e":"Investing his entire savings in a single unproven startup was a rash decision he would soon deeply regret.","t":"把全部积蓄投入一家未经验证的初创公司，是一个他很快就会深感后悔的**鲁莽**决定。"},
"appeal":{"e":"The defense lawyers immediately appealed the verdict, arguing that crucial evidence had been improperly excluded from the trial.","t":"辩护律师立即对判决提出**上诉**，辩称关键证据在庭审中被不当排除。"},
"modify":{"e":"Engineers modified the bridge's design after wind-tunnel tests revealed it would sway dangerously in strong gusts.","t":"在风洞测试显示该桥梁在强风中会危险摇晃后，工程师们**修改**了它的设计。"},
"timber":{"e":"Loggers hauled freshly cut timber down the mountain river, floating each log toward the sawmill downstream.","t":"伐木工人将新砍伐的**木材**顺着山间河流运下山，让每根原木漂向下游的锯木厂。"},
"uniform":{"e":"Every cadet at the academy must keep their uniform spotless, with creases pressed sharp enough to cut paper.","t":"学院里的每位学员都必须保持自己的**制服**一尘不染，折痕锋利得足以裁纸。"},
"luminous":{"e":"The jellyfish's luminous body glowed a pale blue as it drifted silently through the darkened aquarium tank.","t":"这只水母**发光**的身体在昏暗的水族箱中静静漂浮时散发出淡蓝色光芒。"},
"tavern":{"e":"Weary travelers stopped at the roadside tavern for a hot meal and a bed before continuing their journey at dawn.","t":"疲惫的旅人在路边的**小酒馆**停下，享用一顿热饭并住上一晚，然后在黎明时分继续赶路。"},
"devout":{"e":"Her devout grandmother never missed a single Sunday service, even during the harshest winter storms.","t":"她**虔诚**的祖母从未错过任何一次周日礼拜，即使在最恶劣的冬季风暴中也不例外。"},
"gait":{"e":"The doctor immediately noticed the patient's uneven gait, suspecting a problem with his hip rather than his knee.","t":"医生立刻注意到病人**步态**不稳，怀疑问题出在他的髋部而非膝盖。"},
"gouge":{"e":"The mechanic was accused of gouging customers, charging triple the standard rate for a simple oil change.","t":"这位修理工被指控**敲诈**顾客，为一次简单的换油服务收取三倍于标准的费用。"},
"terrorism":{"e":"International cooperation increased sharply after the attack, as governments pooled intelligence to combat terrorism more effectively.","t":"袭击事件发生后，国际合作大幅增加，各国政府共享情报以更有效地打击**恐怖主义**。"},
"subjugate":{"e":"The empire subjugated dozens of neighboring kingdoms over two centuries, forcing each to pay tribute or face invasion.","t":"这个帝国在两个世纪里**征服**了数十个邻国，迫使它们纳贡称臣，否则就要面临入侵。"},
"throng":{"e":"A throng of reporters gathered outside the courthouse, shouting questions as the defendant was led up the steps.","t":"一**大群**记者聚集在法院外，在被告被押上台阶时高声提问。"},
"corporeal":{"e":"The ghost story insisted that the spirit had no corporeal form, only a faint chill that visitors felt in the hallway.","t":"这个鬼故事坚称那个幽灵没有**实体**形态，来访者只能在走廊里感受到一丝寒意。"},
"stray":{"e":"The lecture strayed so far from its announced topic that students began to wonder if they were in the wrong room.","t":"这场讲座**偏离**其宣布的主题如此之远，以至于学生们开始怀疑自己是不是走错了教室。"},
"practicable":{"e":"Building a tunnel beneath the strait was not practicable until engineers developed machinery capable of boring through solid rock.","t":"在工程师研发出能够穿透坚硬岩石的机械之前，在海峡下方修建隧道并不**可行**。"},
"modernity":{"e":"The film contrasts the village's ancient traditions with the jarring modernity of the skyscrapers rising just beyond its borders.","t":"这部电影将村庄古老的传统与其边界之外拔地而起的摩天大楼所代表的突兀**现代性**进行了对比。"},
"antonym":{"e":"Students were asked to find the antonym of each vocabulary word before using it correctly in an original sentence.","t":"学生们被要求先找出每个词汇的**反义词**，然后再正确地用该词造出一个原创句子。"},
"tuition":{"e":"Rising tuition forced many talented students to choose community college over the four-year universities that had accepted them.","t":"不断上涨的**学费**迫使许多有才华的学生放弃已经录取他们的四年制大学，转而选择社区大学。"},
"emergent":{"e":"Investors poured money into emergent technologies like battery storage, betting that demand would explode within the decade.","t":"投资者纷纷向电池储能等**新兴**技术投入资金，押注需求将在十年内爆发式增长。"},
"outrageous":{"e":"Guests were stunned by the outrageous price the hotel charged for a single bottle of water from the minibar.","t":"客人们被酒店迷你吧一瓶水收取的**离谱**价格惊呆了。"},
"vain":{"e":"Rescuers made a vain attempt to reach the stranded hikers before the avalanche buried the only remaining trail.","t":"在雪崩掩埋了最后一条通道之前，救援人员曾**徒劳**地试图接近被困的徒步者。"},
"advantage":{"e":"Her fluency in three languages gave her a distinct advantage over other candidates applying for the diplomatic post.","t":"精通三门语言使她在申请外交职位的众多候选人中拥有明显的**优势**。"},
"corona":{"e":"During the total eclipse, the sun's corona blazed around the darkened disk in a delicate silver ring visible only for minutes.","t":"日全食期间，太阳的**日冕**在变暗的日轮周围燃烧成一圈细银环，只能看到几分钟。"},
"neglect":{"e":"The landlord's chronic neglect of basic repairs left the building's wiring dangerously exposed and the pipes rusted through.","t":"房东长期**忽视**基本维修，导致大楼的电线严重外露，管道也锈穿了。"},
"deciduous":{"e":"Unlike the evergreen pines nearby, the deciduous maples shed their leaves every autumn and stood bare through winter.","t":"与附近常青的松树不同，这些**落叶**枫树每到秋天就会落叶，整个冬天光秃秃地立着。"},
"commission":{"e":"Because she earns a commission on every policy she sells, the insurance agent works late chasing new clients.","t":"由于每卖出一份保单都能拿到**佣金**，这位保险经纪人常常工作到很晚去争取新客户。"},
"breakthrough":{"e":"After a decade of failed trials, researchers finally achieved a breakthrough that made the vaccine both cheap and effective.","t":"经过十年的失败试验，研究人员终于取得了**突破**，使疫苗既便宜又有效。"},
"inspire":{"e":"Her grandmother's quiet courage during the war inspired her to volunteer for humanitarian missions in conflict zones abroad.","t":"祖母在战争期间表现出的沉静勇气**激励**她自愿到海外冲突地区参加人道主义救援任务。"},
"penicillin":{"e":"Fleming's accidental discovery of penicillin transformed medicine by giving doctors their first reliable weapon against bacterial infection.","t":"弗莱明偶然发现了**青霉素**，这一发现改变了医学，让医生首次拥有了对抗细菌感染的可靠武器。"},
"ethnology":{"e":"Fascinated by ethnology, she spent three years living among remote tribes to document their kinship systems and rituals.","t":"她痴迷于**民族学**，花了三年时间与偏远部落生活在一起，记录他们的亲属制度和仪式。"},
"volcano":{"e":"Villagers evacuated the slopes at once when the dormant volcano began spewing ash and rumbling ominously beneath their homes.","t":"当休眠的**火山**开始喷出灰烬并在他们家园下方发出不祥的轰鸣时，村民们立刻撤离了山坡。"},
"cellist":{"e":"The cellist practiced the same somber passage for hours, determined to master its shifting rhythms before the recital.","t":"这位**大提琴演奏家**把同一段忧郁的乐句练了几个小时，决心在独奏会前掌握其变化多端的节奏。"},
"neutron":{"e":"Bombarding the uranium atom with a single neutron triggered a chain reaction that released an enormous burst of energy.","t":"用一个**中子**轰击铀原子引发了链式反应，释放出巨大的能量。"},
"rate":{"e":"The unemployment rate climbed steadily for six months before factories reopened and hiring finally picked up again.","t":"失业**率**持续攀升了六个月，之后工厂重新开工，招聘才终于回暖。"},
"underneath":{"e":"The children hid a shoebox full of secret letters underneath the loose floorboard in the back bedroom closet.","t":"孩子们把一个装满秘密信件的鞋盒藏在后卧室衣柜里那块松动地板**下面**。"},
"maneuver":{"e":"The lawyer skillfully maneuvered the negotiation so that both sides believed they had won the better deal.","t":"这位律师巧妙地**操纵**了谈判过程，让双方都相信自己拿到了更好的条件。"},
"journalism":{"e":"Investigative journalism exposed the factory's illegal dumping long before any government agency bothered to inspect the site.","t":"早在任何政府机构费心去检查现场之前，调查性**新闻工作**就揭露了这家工厂的非法倾倒行为。"},
"terrain":{"e":"The rebel forces retreated into mountainous terrain that made pursuit by heavy vehicles nearly impossible for the army.","t":"叛军撤入多山的**地形**，使军队几乎不可能用重型车辆追击。"},
"saturation":{"e":"Once the soil reached saturation, additional rainfall simply pooled on the surface and flooded the surrounding fields.","t":"土壤一旦达到**饱和**，额外的降雨就只会在地表积聚，淹没周围的田地。"},
"abundant":{"e":"Wildlife here is so abundant that visitors often spot deer, foxes, and hawks within the first hour.","t":"这里的野生动物**丰富**到游客往往在头一个小时内就能看到鹿、狐狸和鹰。"},
"cascara":{"e":"Doctors once prescribed cascara for stubborn constipation, though gentler laxatives have largely replaced it in modern medicine.","t":"医生曾开**缓泻剂**来治疗顽固性便秘，不过在现代医学中，更温和的泻药已在很大程度上取代了它。"},
"glue":{"e":"She glued the broken teacup handle back together so carefully that the crack was almost invisible afterward.","t":"她小心翼翼地把摔断的茶杯把手重新**黏合**在一起，事后裂痕几乎看不出来。"},
"inflation":{"e":"Runaway inflation doubled the price of bread within a year, forcing families to cut their grocery budgets drastically.","t":"失控的**通货膨胀**在一年内让面包价格翻了一番，迫使家庭大幅削减食品预算。"},
"summit":{"e":"Exhausted climbers finally reached the summit just as the first rays of dawn broke over the ridge.","t":"精疲力竭的登山者们终于登上**峰顶**，此时第一缕晨曦刚好越过山脊。"},
"nucleus":{"e":"The original three employees formed the nucleus around which the entire startup later grew into a global company.","t":"最初的三名员工构成了**核心**，整个创业公司后来正是围绕着这个核心发展成一家全球性企业。"},
"attribute":{"e":"Patience is the single attribute that separates skilled negotiators from those who settle for a worse deal.","t":"耐心是这一**特征**，正是它把老练的谈判者与那些只能接受较差条件的人区分开来。"},
"certificate":{"e":"After finishing the six-month course, she proudly framed the certificate and hung it above her new desk.","t":"完成六个月的课程后，她自豪地把**证书**装裱起来，挂在了新书桌的上方。"},
"planetary":{"e":"The observatory's new telescope was designed specifically to track planetary motion far beyond the orbit of Neptune.","t":"天文台的新望远镜专门设计用来追踪海王星轨道以外的**行星**运动。"},
"delicate":{"e":"Restoring the delicate manuscript required tweezers and a magnifying glass, since one careless touch could crumble the pages.","t":"修复这份**易损**的手稿需要镊子和放大镜，因为稍不小心一碰，书页就可能碎裂。"},
"proficient":{"e":"Within two years abroad, he became proficient enough in Mandarin to negotiate contracts without needing an interpreter.","t":"在国外待了两年后，他的普通话已经**熟练**到可以不需要翻译就能谈判合同。"},
"unify":{"e":"The new constitution sought to unify dozens of rival provinces that had been governed separately for centuries.","t":"新宪法试图把数十个几百年来各自为政的敌对省份**统一**起来。"},
"relief":{"e":"The painkillers brought only temporary relief, and by midnight her headache had returned as sharp as before.","t":"止痛药只带来了暂时的**缓解**，到了半夜，她的头痛又像之前一样剧烈地发作了。"},
"miracle":{"e":"Doctors called her recovery a miracle, since the tumor had vanished completely without any further treatment at all.","t":"医生称她的康复是个**奇迹**，因为肿瘤已完全消失，没有再接受任何治疗。"},
"simultaneous":{"e":"The conference relied on simultaneous translation so delegates from a dozen countries could follow the speech in their own language.","t":"大会依靠**同步**翻译，让来自十几个国家的代表能用自己的语言听懂演讲内容。"},
"foliage":{"e":"Tourists flock to Vermont every October when the maple foliage turns brilliant shades of orange and crimson.","t":"每年十月，游客都会涌向佛蒙特州，观赏枫树**叶**变成绚丽的橙红色。"},
"quarry":{"e":"The falcon circled patiently above the field, waiting for its quarry to break cover and dash across the open grass.","t":"猎鹰耐心地在田野上空盘旋，等待它的**猎物**冲出隐蔽处，跑过空旷的草地。"},
"tragedy":{"e":"The mine collapse became a national tragedy after rescuers confirmed that none of the trapped workers had survived.","t":"矿难成了一场全国性的**惨剧**，救援人员证实被困工人无一幸存。"},
"deceptive":{"e":"The calm surface of the lake was deceptive, hiding a current strong enough to sweep swimmers far offshore.","t":"湖面看似平静，实则**具有迷惑性**，水下的暗流足以把游泳者卷到远离岸边的地方。"},
"outbreak":{"e":"Health officials scrambled to contain the outbreak before the virus could spread beyond the small farming village.","t":"卫生官员匆忙控制这次**爆发**，以免病毒蔓延到这个小农村之外。"},
"plateau":{"e":"After months of rapid improvement, her piano skills hit a plateau and seemed to stop advancing no matter how much she practiced.","t":"经过几个月的快速进步后，她的钢琴技艺进入了**停滞期**，无论怎么练习似乎都不再提高。"},
"novel":{"e":"The engineers proposed a novel solution that replaced the heavy metal frame with a lighter, cheaper composite material.","t":"工程师们提出了一个**新颖**的解决方案，用更轻、更便宜的复合材料取代了笨重的金属框架。"},
"decay":{"e":"Years of neglect allowed the once-grand mansion to decay into a crumbling shell overrun with vines and mold.","t":"多年无人照管，让这座曾经气派的宅邸**衰败**成了一具爬满藤蔓和霉斑的残壳。"},
"avenue":{"e":"Microloans opened a new avenue for rural entrepreneurs who had never qualified for a traditional bank loan before.","t":"小额贷款为那些从未获得过传统银行贷款资格的农村创业者开辟了一条新的**途径**。"},
"potency":{"e":"Storing the medicine in direct sunlight gradually weakened its potency until the dosage no longer relieved her symptoms.","t":"把药物存放在阳光直射处逐渐削弱了它的**效力**，以至于原来的剂量再也无法缓解她的症状。"},
"causal":{"e":"Scientists struggled to establish a causal link between the chemical additive and the sudden rise in bee deaths.","t":"科学家们努力想在这种化学添加剂与蜜蜂死亡率骤增之间确立**因果**关系。"},
"acquisition":{"e":"Children acquire grammar through a process linguists call language acquisition, absorbing rules long before they can explain them.","t":"儿童通过语言学家称之为语言**习得**的过程掌握语法，早在能解释规则之前就已吸收了它们。"},
"unanimous":{"e":"The jury reached a unanimous verdict after deliberating for barely twenty minutes, stunning even the presiding judge.","t":"陪审团仅仅商议了二十分钟就达成了**一致**裁决，连主审法官都感到震惊。"},
"ornamental":{"e":"The wrought-iron gate was purely ornamental, since a low hedge on either side offered no real security at all.","t":"这扇锻铁大门纯粹是**装饰性**的，因为两侧的矮树篱根本起不到真正的防护作用。"},
"blunt":{"e":"Rather than soften the bad news, the coach gave the team a blunt assessment of exactly why they had lost.","t":"教练没有把坏消息说得委婉一些，而是**直率**地向球队说明了他们输球的确切原因。"},
"fictitious":{"e":"To protect her identity, the whistleblower published the report under a completely fictitious name known to no one.","t":"为了保护自己的身份，这名举报人用一个完全**虚构**的、无人知晓的名字发表了报告。"},
"doodle":{"e":"Bored during the lecture, he doodled tiny spaceships in the margins of his notebook instead of taking notes.","t":"上课时觉得无聊，他没有记笔记，而是在笔记本空白处**乱涂**起了小飞船。"},
"allocate":{"e":"The city council voted to allocate additional funding toward repairing the crumbling bridges along the eastern highway.","t":"市议会投票决定将额外的资金**拨给**东部高速公路沿线破损桥梁的维修工程。"},
"blurt":{"e":"Startled by the sudden question, she blurted out the truth before she had time to consider the consequences.","t":"突如其来的问题让她一惊，她**脱口而出**说出了真相，都来不及考虑后果。"},
"cradle":{"e":"Historians often call Mesopotamia the cradle of civilization because writing, law, and cities first emerged along its rivers.","t":"历史学家常称美索不达米亚为文明的**发源地**，因为文字、法律和城市最早在其河流沿岸出现。"},
"aftermath":{"e":"In the aftermath of the flood, entire neighborhoods were left without clean water, electricity, or passable roads.","t":"洪水过后的**余波**中，整个社区都断绝了干净的水源、电力和可通行的道路。"},
"bleak":{"e":"Without foreign investment, economists warned, the country's prospects for recovery would remain bleak for another decade.","t":"经济学家警告说，如果没有外国投资，这个国家未来十年的复苏前景仍将十分**黯淡**。"},
"diminution":{"e":"The treaty called for a gradual diminution of nuclear stockpiles rather than an abrupt and destabilizing disarmament.","t":"该条约要求逐步**削减**核武库存，而不是采取突然且可能引发动荡的裁军行动。"},
"metaphor":{"e":"The poet compared grief to a stone in her chest, a metaphor that readers found unusually precise and haunting.","t":"诗人把悲伤比作胸口的一块石头，读者觉得这个**隐喻**格外精准而挥之不去。"},
"committee":{"e":"The committee spent three meetings arguing over the budget before finally approving funds for the new library wing.","t":"**委员会**为预算问题争论了三次会议，才最终批准了新图书馆侧楼的资金。"},
"tropic":{"e":"Ships crossing the tropic of Cancer often mark the occasion with an old naval ceremony welcoming first-timers.","t":"船只穿越北**回归线**时，常常会用一种古老的海军仪式来庆祝，欢迎首次经过的水手。"},
"exalted":{"e":"Even in such an exalted position, the queen insisted on visiting hospitals and speaking with ordinary patients herself.","t":"即便身居如此**显赫**的地位，女王仍坚持亲自探访医院，与普通病人交谈。"},
"octopus":{"e":"The octopus squeezed its entire boneless body through a gap barely wider than a coin to escape the tank.","t":"这只**章鱼**把它整个没有骨头的身体挤过一个仅比硬币宽一点的缝隙，逃出了水箱。"},
"ambience":{"e":"Candlelight and soft jazz gave the small restaurant an intimate ambience that kept customers lingering long after dessert.","t":"烛光和轻柔的爵士乐赋予这家小餐厅一种亲密的**氛围**，让顾客吃完甜点后仍久久不愿离去。"},
"voyage":{"e":"The voyage across the Atlantic took nearly six weeks, and several passengers fell seriously ill before reaching port.","t":"横渡大西洋的**航程**花了将近六周，好几名乘客在抵达港口之前就已病得很重。"},
"onslaught":{"e":"The coastal town braced for the onslaught of the hurricane, boarding up windows and stacking sandbags along the shore.","t":"沿海小镇为迎接飓风的**猛烈冲击**做好了准备，把窗户钉上木板，并沿岸堆起沙袋。"},
"arid":{"e":"Almost nothing grows in the arid stretches of the desert, where rain falls perhaps once every few years.","t":"沙漠中**干旱**的地带几乎寸草不生，那里也许每隔几年才下一次雨。"},
"clam":{"e":"At low tide, families waded into the mud with buckets, digging for clams buried just beneath the surface.","t":"退潮时，各家各户提着桶蹚进泥地，挖掘埋在浅表下的**蛤蜊**。"},
"nicotine":{"e":"The patch releases a steady dose of nicotine into the bloodstream, helping smokers curb their craving for cigarettes.","t":"这种贴片会向血液中持续释放一定剂量的**尼古丁**，帮助吸烟者抑制烟瘾。"},
"guideline":{"e":"The hospital issued a new guideline requiring every nurse to wash hands between patients regardless of time pressure.","t":"医院发布了一项新的**准则**，要求每位护士无论时间多紧都要在接触不同病人之间洗手。"},
"signal":{"e":"A sudden drop in the stock's trading volume was the first signal that investors had lost confidence entirely.","t":"该股票交易量的突然下滑是投资者已经完全失去信心的第一个**信号**。"},
"junction":{"e":"Traffic backed up for miles at the junction where the two highways merged into a single congested lane.","t":"在两条高速公路汇合成一条拥挤车道的**交汇处**，车流堵塞了好几英里。"},
"abnormal":{"e":"The technician flagged the scan immediately after noticing an abnormal growth near the patient's left kidney.","t":"技师注意到病人左肾附近有一处**异常**增生后，立即标记了这次扫描结果。"},
"sympathy":{"e":"Neighbors sent flowers and casseroles to express their sympathy after the family lost their home in the fire.","t":"这家人在火灾中失去了住所后，邻居们送来鲜花和炖菜，表达他们的**同情**。"},
"intellect":{"e":"Her sharp intellect impressed the interview panel long before her resume even mentioned her research publications.","t":"她敏锐的**才智**在面试小组面前留下了深刻印象，甚至早于简历提到她的研究成果之前。"},
"thrifty":{"e":"Growing up during the depression made him so thrifty that he still repairs old socks instead of replacing them.","t":"在大萧条时期长大让他变得非常**节俭**，至今仍会缝补旧袜子而不是换新的。"},
"drought":{"e":"The worst drought in fifty years withered the corn fields and forced ranchers to sell off much of their cattle.","t":"五十年来最严重的**旱灾**使玉米田枯萎，迫使牧场主卖掉了大部分牲畜。"},
"abandon":{"e":"Rescue workers refused to abandon the search even after three days without any sign of the missing hikers.","t":"即使三天过去仍毫无失踪徒步者的踪迹，救援人员依然拒绝**放弃**搜索。"},
"damp":{"e":"Mold spread quickly across the basement walls because the damp air never had a chance to circulate properly.","t":"霉菌迅速在地下室墙壁上蔓延，因为**潮湿**的空气一直没能好好流通。"},
"ignorant":{"e":"He was completely ignorant of local customs, so his blunt questions at dinner offended the entire host family.","t":"他对当地习俗完全**无知**，晚餐时那些直白的问题冒犯了整个东道主家庭。"},
"emission":{"e":"New regulations require factories to cut carbon emission levels by nearly half before the end of the decade.","t":"新规定要求工厂在这十年结束前将碳**排放**量削减近一半。"},
"vertebrate":{"e":"Sharks were among the earliest vertebrates to evolve a fully cartilaginous skeleton instead of one made of bone.","t":"鲨鱼是最早进化出完全软骨骨骼而非硬骨骨骼的**脊椎动物**之一。"},
"range":{"e":"The Rocky Mountain range stretches for more than three thousand miles from Canada down into New Mexico.","t":"落基**山脉**从加拿大一直延伸到新墨西哥州，绵延超过三千英里。"},
"emotion":{"e":"Grief is a complicated emotion that can surface unexpectedly months after the initial loss has been accepted.","t":"悲伤是一种复杂的**情绪**，即使最初的丧失已被接受，它也可能在数月后突然浮现。"},
"stiff":{"e":"After sleeping in the cramped car seat all night, his neck felt so stiff he could barely turn his head.","t":"整晚蜷缩在狭窄的车座上睡觉后，他的脖子**僵硬**得几乎转不动。"},
"microprocessor":{"e":"A single microprocessor the size of a fingernail now performs calculations that once required an entire room of machinery.","t":"如今，一枚指甲大小的**微处理器**就能完成曾经需要满满一屋子机器才能进行的运算。"},
"oceanographer":{"e":"The oceanographer spent months aboard a research vessel mapping currents that most sailors had only guessed at before.","t":"这位**海洋学者**在研究船上花了数月时间绘制洋流图，而此前大多数水手对这些洋流只能凭猜测。"},
"insanity":{"e":"The defense argued temporary insanity, claiming the defendant had no awareness of his actions during the incident.","t":"辩方以临时**精神错乱**为由进行辩护，声称被告在事发时对自己的行为毫无意识。"},
"successive":{"e":"The team celebrated its third successive championship, having dominated the league for three years running without interruption.","t":"该队庆祝了**连续**第三次夺冠，三年来一直统治着这个联赛，从未间断。"},
"alternate":{"e":"The two nurses alternate night shifts every other week so that neither one becomes completely exhausted from overwork.","t":"两名护士每隔一周就**轮流**上夜班，这样谁都不会因为过度劳累而彻底累垮。"},
"dull":{"e":"The lecture was so dull that half the students in the back row had fallen asleep by the second slide.","t":"这堂课**枯燥**极了，后排一半的学生在讲到第二张幻灯片时就已经睡着了。"},
"stanza":{"e":"The final stanza shifts abruptly in tone, abandoning the poem's earlier optimism for a bitter sense of loss.","t":"最后一**节**诗的语气骤然转变，抛弃了全诗先前的乐观情绪，转而流露出一种苦涩的失落感。"},
"cowhand":{"e":"Every summer, the young cowhand rode out before sunrise to check the fences along the ranch's northern boundary.","t":"每年夏天，这位年轻的**牧牛工**都会在日出前骑马出发，检查牧场北部边界的围栏。"},
"spacecraft":{"e":"The unmanned spacecraft transmitted its final images just seconds before losing contact with mission control forever.","t":"这艘无人**航天器**在与任务控制中心永久失联的前几秒钟，传回了它最后的图像。"},
"disgust":{"e":"The smell of rotting garbage in the stairwell disgusted every tenant who had to walk past it daily.","t":"楼梯间腐烂垃圾的臭味让每天必须经过那里的住户都感到**厌恶**。"},
"lore":{"e":"According to local lore, a ghostly ship still appears off the coast whenever a storm approaches the harbor.","t":"根据当地的**传说**，每当暴风雨逼近港口时，海岸外就会出现一艘幽灵船。"},
"dawn":{"e":"Fishermen set out before dawn so their catch would reach the market stalls while it was still fresh.","t":"渔民们在**黎明**前就出海，好让捕到的鱼趁新鲜运到集市的摊位上。"},
"bruise":{"e":"The peach bruised the moment it slipped off the counter, leaving a soft brown mark across its skin.","t":"桃子刚从台面上滑落，表皮就**碰伤了**，留下一块柔软的褐色印记。"},
"abut":{"e":"The new apartment complex abuts a protected wetland, so construction crews had to follow strict environmental guidelines.","t":"这座新公寓楼**毗邻**一片受保护的湿地，因此施工队必须遵守严格的环保规定。"},
"condiment":{"e":"Every table in the diner held a caddy of condiments, from ketchup and mustard to hot sauce and relish.","t":"小餐馆里每张桌子上都放着一个装满**调味品**的架子，从番茄酱、芥末到辣酱和甜酸酱应有尽有。"},
"discourage":{"e":"Repeated rejection letters might discourage a lesser writer, but she simply kept revising and submitting her manuscript.","t":"一次次的退稿信可能会让意志薄弱一点的作家**灰心**，但她只是不断修改并重新投稿。"},
"glitter":{"e":"Thousands of tiny quartz crystals glittered across the cave wall whenever a flashlight beam swept over them.","t":"每当手电筒的光束扫过，洞穴岩壁上成千上万颗细小的石英晶体就会**闪烁**起来。"},
"tortuous":{"e":"The mountain road grew so tortuous that drivers were advised to sound their horns before every blind curve.","t":"这条山路变得极为**蜿蜒曲折**，驾驶员被建议在每个看不清的弯道前都要鸣笛示意。"},
"dateline":{"e":"The article's dateline read Nairobi, confirming that the reporter had filed her story directly from the scene.","t":"这篇报道的**日期栏**上写着内罗毕，证实记者是直接从现场发回的这篇报道。"},
"antecede":{"e":"Ancient trade routes across the desert antecede the modern highways that now roughly follow the same paths.","t":"穿越沙漠的古代贸易路线**早于**如今大致沿着同样路径修建的现代公路。"},
"conducive":{"e":"A quiet, well-lit room is far more conducive to studying than a noisy kitchen full of distractions.","t":"安静、光线充足的房间远比充满干扰的嘈杂厨房更**有助于**学习。"},
"deem":{"e":"The committee deemed the bridge unsafe for heavy trucks and ordered an immediate weight restriction on the crossing.","t":"委员会**认为**这座桥对重型卡车而言不够安全，下令立即对过桥车辆实施限重。"},
"ripple":{"e":"A single stone tossed into the pond sent ripples spreading outward until they reached the far bank.","t":"一块石头被扔进池塘，激起的**涟漪**向外扩散，一直到达对岸。"},
"urbanization":{"e":"Rapid urbanization drew millions of farmers into the cities, leaving many rural villages nearly empty within a generation.","t":"快速的**城市化**把数百万农民吸引到城市，使许多乡村在一代人的时间里几乎变得空荡荡。"},
"slash":{"e":"The airline slashed ticket prices by forty percent to fill empty seats during the slow winter season.","t":"这家航空公司**大幅削减**了百分之四十的票价，以在冬季淡季填满空座位。"},
"elite":{"e":"Only elite athletes who had already broken national records were invited to compete in the qualifying trials.","t":"只有已经打破过全国纪录的**精英**运动员才受邀参加这次资格选拔赛。"},
"abolish":{"e":"Reformers campaigned for decades to abolish child labor before factories were finally required to hire only adults.","t":"改革者们为**废除**童工制度奔走呼号了几十年，工厂才最终被要求只雇用成年人。"},
"breach":{"e":"Sharing the client's confidential files with a competitor was a clear breach of the signed nondisclosure agreement.","t":"把客户的机密文件分享给竞争对手，明显**违反**了双方签署的保密协议。"},
"pupil":{"e":"The doctor shone a small light into each pupil to check whether they contracted at the same speed.","t":"医生用小灯光照射每一侧**瞳孔**，检查它们收缩的速度是否一致。"},
"condole":{"e":"Colleagues gathered at her desk to condole with her quietly after learning that her father had passed away.","t":"得知她父亲去世后，同事们聚在她桌旁，静静地向她**表示慰问**。"},
"grill":{"e":"Detectives grilled the suspect for nearly six hours before he finally admitted where he had hidden the evidence.","t":"侦探们**盘问**了嫌疑人将近六个小时，他才终于承认自己把证据藏在了哪里。"},
"paralyze":{"e":"A severe snowstorm paralyzed the entire subway system, stranding thousands of commuters underground for several frustrating hours.","t":"一场严重的暴风雪**瘫痪**了整个地铁系统，使数千名通勤者被困地下好几个小时，苦不堪言。"},
"disintegrate":{"e":"The old rope disintegrated the moment he pulled on it, scattering brittle fibers across the workshop floor.","t":"那根旧绳子他一拉就**散架**了，脆弱的纤维散落了一地车间地板。"},
"activate":{"e":"Pressing the red button activates the emergency alarm and automatically alerts the nearest fire station within seconds.","t":"按下红色按钮会**启动**紧急警报，并在几秒钟内自动通知最近的消防站。"},
"occasional":{"e":"Aside from occasional thunderstorms in late afternoon, the region enjoys clear skies for most of the summer.","t":"除了午后**偶尔**出现的雷暴，这个地区在整个夏天大部分时间里都是晴空万里。"},
"court":{"e":"The defendant's lawyer asked the court for a two-week postponement to gather additional evidence for the trial.","t":"被告的律师请求**法庭**延期两周，以便为审判收集更多证据。"},
"scene":{"e":"Paramedics arrived at the scene within minutes, but the wreckage made it clear no one could have survived.","t":"急救人员几分钟内就赶到了**现场**，但残骸的情况已表明没有人能够幸存。"},
"inconvenient":{"e":"The meeting was rescheduled to such an inconvenient hour that half the staff simply could not attend.","t":"会议被重新安排到一个如此**不便**的时间，以至于一半员工根本无法参加。"},
"expose":{"e":"The audit exposed years of financial mismanagement that the company's directors had carefully concealed from shareholders.","t":"审计**揭露**了公司董事们精心向股东隐瞒多年的财务管理不善问题。"},
"deter":{"e":"Bright motion-sensor lights around the yard were installed specifically to deter burglars from approaching after dark.","t":"院子四周安装了明亮的感应灯，专门用来**阻止**窃贼在天黑后靠近。"},
"occur":{"e":"Earthquakes occur most frequently along fault lines where two tectonic plates grind slowly against each other.","t":"地震最频繁**发生**在两个构造板块缓慢相互挤压的断层线附近。"},
"enterprise":{"e":"Starting a small bakery felt like a reckless enterprise until it grew into the town's most beloved shop.","t":"开一家小面包店起初感觉像是一场鲁莽的**事业**，直到它成长为这座小镇最受喜爱的店铺。"},
"chaos":{"e":"Chaos erupted in the terminal the moment the airline announced that every flight had been abruptly canceled.","t":"航空公司一宣布所有航班都被临时取消，航站楼里瞬间就陷入了**混乱**。"},
"violent":{"e":"The protest turned violent after police fired tear gas into a crowd that had been peaceful until then.","t":"警方向此前一直和平的人群发射催泪瓦斯后，抗议活动演变成了**暴力**冲突。"},
"homogeneous":{"e":"The suburb was remarkably homogeneous, with nearly every household sharing the same income level and background.","t":"这个郊区异常**同质化**，几乎每户家庭的收入水平和背景都相同。"},
"boundary":{"e":"A row of ancient oak trees marks the boundary between the two neighboring farms that have coexisted for generations.","t":"一排古老的橡树标示着两个世代毗邻共存的农场之间的**分界线**。"},
"male":{"e":"Only the male peacock displays those spectacular iridescent feathers, while the female remains plain and brown.","t":"只有**雄性**孔雀才展示那绚丽多彩的羽毛，而雌孔雀则保持朴素的棕色。"},
"sheath":{"e":"He slid the hunting knife carefully back into its leather sheath before hanging the belt on a hook.","t":"他小心地把猎刀重新滑入皮**鞘**，然后把腰带挂在钩子上。"},
"appointment":{"e":"She scheduled a dentist appointment for early Monday morning before the office filled up with other patients.","t":"她提前定下了周一清晨的牙医**预约**，以免诊所的号被其他病人约满。"},
"exhilarating":{"e":"Skydiving for the first time was so exhilarating that she immediately booked another jump for the following weekend.","t":"第一次跳伞的经历太**令人兴奋**了，她立刻又预订了下个周末的一次跳伞。"},
"delay":{"e":"Heavy fog at the airport delayed nearly every departing flight for more than three hours that morning.","t":"机场的浓雾**延误**了那天早上几乎所有的出发航班，延误时间超过三个小时。"},
"keen":{"e":"The old detective's keen eye caught a tiny inconsistency in the witness's story that everyone else had missed.","t":"老侦探**敏锐**的目光捕捉到了证人证词中一个其他人都忽略了的细微矛盾。"},
"seismology":{"e":"Advances in seismology now allow scientists to detect faint tremors that would have gone completely unnoticed decades ago.","t":"**地震学**的进步如今让科学家能够探测到几十年前根本无法察觉的微弱震动。"},
"welfare":{"e":"The new labor law expanded welfare benefits for part-time workers who previously received no healthcare coverage at all.","t":"新的劳动法扩大了兼职工人的**福利**待遇，此前他们完全没有医疗保障。"},
"gross":{"e":"The summer blockbuster grossed nearly a billion dollars worldwide within just three weeks of its theatrical release.","t":"这部暑期大片上映仅三周，全球**总收入**就将近十亿美元。"},
"edge":{"e":"Years of specialized training gave the sprinter a decisive edge over rivals who trained only casually.","t":"多年的专项训练让这位短跑运动员比那些只是随意训练的对手拥有决定性的**优势**。"},
"revert":{"e":"Once the lease expired, ownership of the land reverted automatically to the family that had originally owned it.","t":"租约一到期，这片土地的所有权就自动**归还**给了最初拥有它的那家人。"},
"appliance":{"e":"The renovated kitchen came equipped with every modern appliance, from a double oven to a built-in wine cooler.","t":"装修一新的厨房配备了各种现代化**电器**，从双层烤箱到内置酒柜一应俱全。"},
"noxious":{"e":"Workers were required to wear respirators whenever the factory released noxious fumes during the chemical mixing process.","t":"每当工厂在化学品混合过程中释放**有害**气体时，工人都必须佩戴呼吸器。"},
"calendar":{"e":"She marked every deadline in red on the office calendar so no one could claim they had forgotten.","t":"她把每个截止日期都用红色标在办公室的**日历**上，这样谁都不能说自己忘记了。"},
"quiz":{"e":"The teacher gave a surprise quiz on Friday, catching most of the class without having studied the chapter.","t":"老师星期五进行了一次突击**小测验**，让班上大多数学生都措手不及，因为他们没有复习那一章。"},
"universe":{"e":"Astronomers estimate that the observable universe contains roughly two trillion galaxies, each holding billions of stars.","t":"天文学家估计，可观测**宇宙**大约包含两万亿个星系，每个星系都拥有数十亿颗恒星。"},
"grant":{"e":"The judge granted the couple's request for a temporary restraining order against their increasingly aggressive neighbor.","t":"法官**批准**了这对夫妇的请求，对他们那位越来越咄咄逼人的邻居发布了临时限制令。"},
"perception":{"e":"Public perception of the politician shifted overnight once the scandal made headlines across every major newspaper.","t":"一旦这桩丑闻登上各大报纸头条，公众对这位政客的**看法**便在一夜之间发生了转变。"},
"ethic":{"e":"A strong work ethic carried him from an unpaid internship to a leadership role within just four years.","t":"强烈的职业**道德**让他仅用四年时间就从一名无薪实习生升到了领导职位。"},
"maglev":{"e":"The maglev train glides above the track on magnetic fields, reaching speeds no conventional railway can match.","t":"**磁悬浮**列车依靠磁场悬浮在轨道上方滑行，能达到任何传统铁路都无法企及的速度。"},
"cosmic":{"e":"Astrophysicists study cosmic radiation left over from the Big Bang to understand how the universe first expanded.","t":"天体物理学家研究大爆炸遗留下来的**宇宙**辐射，以了解宇宙最初是如何膨胀的。"},
"anchor":{"e":"Steel cables anchor the suspension bridge's towers deep into bedrock to withstand hurricane-force winds and earthquakes.","t":"钢缆将悬索桥的桥塔深深**固定**在基岩之中，以抵御飓风级大风和地震。"},
"engineering":{"e":"Brilliant engineering allowed the tunnel to pass safely beneath the river without a single structural leak in decades.","t":"精湛的**工程技术**让隧道得以安全地从河底穿过，几十年间未曾出现一处结构性渗漏。"},
"crew":{"e":"The film crew worked through the night to finish shooting before the rented location closed the next morning.","t":"**摄制组**通宵工作，赶在租用场地第二天早上关闭前完成了拍摄。"},
"halt":{"e":"A sudden power outage brought the entire assembly line to a complete halt just before the shift ended.","t":"一次突然的停电让整条装配线在轮班结束前彻底**停止**运转。"},
"staple":{"e":"Rice remains the staple of most diets across Asia, providing more daily calories than any other single food.","t":"大米仍是亚洲大多数地区饮食中的**主食**，提供的每日热量超过任何其他单一食物。"},
"vibrate":{"e":"The phone vibrated silently in her pocket three times before she finally noticed the missed calls from her mother.","t":"手机在她口袋里悄悄**震动**了三次，她才终于注意到母亲打来的未接电话。"},
"attempt":{"e":"Her first attempt at baking bread from scratch ended with a loaf so dense it could barely be sliced.","t":"她第一次**尝试**从头开始烤面包，结果面包硬得几乎切不动。"},
"mercury":{"e":"Mercury completes an entire orbit around the sun in just eighty-eight days, faster than any other planet.","t":"**水星**仅需八十八天就能绕太阳完成一整圈公转，比其他任何行星都快。"},
"fragrant":{"e":"Jasmine bushes along the garden path filled the evening air with a fragrant scent that drifted through open windows.","t":"花园小径旁的茉莉花丛让夜晚的空气中弥漫着**芬芳**的香气，飘进了敞开的窗户。"},
"scar":{"e":"The childhood accident scarred his forearm permanently, leaving a thin white line that never quite faded.","t":"童年的那次意外在他的前臂上永久**留下了疤痕**，一道细细的白线始终没有完全消退。"},
"log":{"e":"The captain recorded every unusual sighting in the ship's log, from strange lights to sudden shifts in current.","t":"船长把每一次异常目击都记录在船只的**日志**中，从奇怪的灯光到洋流的突然变化。"},
"stir":{"e":"The coach's halftime speech stirred something in the players, who returned to the field determined to fight back.","t":"教练中场休息时的讲话**激发**了球员们心中的斗志，他们重返赛场，决心奋力反击。"},
"refer":{"e":"Throughout the interview, the candidate kept referring to a mentor whose advice had shaped her entire career.","t":"整场面试中，这位候选人不断**提到**一位导师，正是他的建议塑造了她的整个职业生涯。"},
"yeast":{"e":"Adding too much yeast to the dough made it rise so fast that it collapsed before baking finished.","t":"面团里加了太多**酵母**，发得太快，结果还没烤完就塌陷了。"},
"wreck":{"e":"A single navigational error wrecked the tanker on the reef, spilling thousands of gallons of crude oil offshore.","t":"一次导航失误就让油轮**失事**触礁，数千加仑原油泄漏入海。"},
"incinerate":{"e":"The hospital incinerates all medical waste on-site rather than risk transporting hazardous materials across the city.","t":"医院直接在现场**焚毁**所有医疗废物，而不冒险将危险材料运送穿过整座城市。"},
"bronze":{"e":"She settled for bronze at the Olympics, missing silver by less than a tenth of a second.","t":"她在奥运会上只拿到了**铜牌**，与银牌之差不到十分之一秒。"},
"topsoil":{"e":"Decades of intensive farming stripped away the fertile topsoil, leaving behind hard clay that crops could barely penetrate.","t":"数十年的高强度耕作剥蚀了肥沃的**表层土**，只留下农作物根系几乎无法穿透的坚硬粘土。"},
"acquaint":{"e":"The new manager spent his first week simply acquainting himself with each department's workflow before proposing any changes.","t":"新任经理第一周只是让自己**熟悉**各部门的工作流程，之后才提出任何改动建议。"},
"bake":{"e":"Grandmother baked the same cinnamon bread every Sunday morning, filling the whole house with its warm smell.","t":"祖母每个星期天早上都会**烤**同一种肉桂面包，温暖的香气弥漫了整栋房子。"},
"submerge":{"e":"Rising floodwaters submerged the entire ground floor within an hour, forcing residents onto their rooftops for rescue.","t":"上涨的洪水在一小时内**淹没**了整个一楼，迫使居民爬上屋顶等待救援。"},
"sound":{"e":"Her financial advisor gave surprisingly sound advice that helped the young couple avoid a costly investment mistake.","t":"她的理财顾问给出了出乎意料**可靠**的建议，帮这对年轻夫妇避免了一次代价高昂的投资失误。"},
"malicious":{"e":"Someone spread malicious rumors about her online, forcing the company to issue a public statement in her defense.","t":"有人在网上散布关于她的**恶意**谣言，迫使公司发布公开声明为她辩护。"},
"equal":{"e":"Her latest sprint time equaled the school record that had stood unchallenged for nearly fifteen years.","t":"她最近一次的短跑成绩**追平**了那项将近十五年无人打破的校纪录。"},
"pulp":{"e":"The factory pulps recycled newspapers into a gray slurry before pressing it into fresh sheets of cardboard.","t":"工厂把回收的旧报纸**打成**灰色的浆液，然后压制成新的纸板。"},
"naked":{"e":"Stripped of diplomatic language, the ambassador's warning revealed the naked truth about the failing ceasefire negotiations.","t":"大使的警告摒弃了外交辞令，揭示了停火谈判正在失败的**赤裸裸**的真相。"},
"refrain":{"e":"Every verse of the folk song changed, but the same haunting refrain returned again and again at the end.","t":"这首民谣的每一段歌词都在变化，但同样萦绕人心的**副歌**却在结尾一次次重现。"},
"retract":{"e":"The newspaper was forced to retract its front-page story after the main source admitted to fabricating the entire account.","t":"在主要消息来源承认整个说法都是编造的之后，这家报纸被迫**撤回**了其头版报道。"},
"indolent":{"e":"Despite his indolent reputation, the student surprised everyone by finishing the entire project two days early.","t":"尽管这名学生一向以**懒散**出名，但他却出人意料地提前两天完成了整个项目。"},
"allure":{"e":"The allure of easy money drew hundreds of investors into a scheme that eventually collapsed and ruined them financially.","t":"轻松赚钱的**诱惑**吸引了数百名投资者加入这个骗局，最终骗局崩溃，让他们倾家荡产。"},
"widespread":{"e":"Widespread flooding across three provinces displaced tens of thousands of families and destroyed most of the harvest.","t":"**大范围**的洪灾席卷三个省份，导致数万个家庭流离失所，摧毁了大部分收成。"},
"interpret":{"e":"Analysts interpreted the central bank's vague statement as a clear signal that interest rates would soon rise.","t":"分析师将央行含糊的声明**解读**为利率即将上调的明确信号。"},
"biannual":{"e":"The clinic holds a biannual health screening every spring and fall to catch problems before they worsen.","t":"诊所每年春秋两季各举办一次**每年两次**的健康筛查，以便在问题恶化前及时发现。"},
"prophet":{"e":"Long before economists agreed with her, she was dismissed as an alarmist rather than treated as a prophet.","t":"早在经济学家认同她的观点之前，她一直被当作危言耸听者，而不是被视为**先知**。"},
"mainstream":{"e":"Once dismissed as fringe theory, the idea eventually entered the scientific mainstream after decades of accumulating evidence.","t":"这个理论曾被视为边缘学说，但经过数十年证据的积累，最终进入了科学**主流**。"},
"rip":{"e":"The strong wind ripped the tent's fabric clean off its poles within seconds of the first violent gust.","t":"第一阵狂风袭来，几秒钟内就把帐篷的布料从支架上**撕**了下来。"},
"code":{"e":"The engineer coded the entire login system over a single weekend, working almost without sleep to meet the deadline.","t":"这位工程师用一个周末就**编写**完了整个登录系统的代码，几乎没有合眼就赶上了截止日期。"},
"oppressive":{"e":"Citizens finally rose up against the oppressive regime that had censored the press for nearly four decades.","t":"民众终于奋起反抗这个近四十年来一直压制新闻自由的**压迫性**政权。"},
"impede":{"e":"Thick underbrush impeded the firefighters' progress, forcing them to hack a path through the forest by hand.","t":"茂密的灌木丛**阻碍**了消防员的前进，迫使他们徒手在森林中开辟出一条通道。"},
"endanger":{"e":"Overfishing has endangered the local salmon population so severely that the river now supports almost no wildlife.","t":"过度捕捞严重**危及**了当地的鲑鱼种群，以至于这条河流现在几乎无法维持任何野生动物生存。"},
"intermediate":{"e":"After finishing the beginner course, she enrolled in an intermediate class designed for students who already knew basic grammar.","t":"完成初级课程后，她报名参加了专为已掌握基础语法的学生设计的**中级**班。"},
"scornful":{"e":"The critic's scornful review dismissed the entire film as lazy, predictable, and utterly unworthy of its budget.","t":"这位影评人**轻蔑**的评论把整部电影贬得一无是处，说它懒散、老套，完全配不上它的预算。"},
"chip":{"e":"Careless movers chipped the corner of the antique dresser while carrying it down the narrow staircase.","t":"粗心的搬运工在把这件古董梳妆台搬下狭窄楼梯时，**磕掉了**它的一个角。"},
"imbibe":{"e":"Growing up surrounded by musicians, she imbibed an appreciation for jazz long before she ever picked up an instrument.","t":"在音乐家的环绕中长大，她早在拿起乐器之前就已经**吸收**了对爵士乐的鉴赏力。"},
"mass":{"e":"According to Newton's second law, the force needed to accelerate an object depends directly on its mass.","t":"根据牛顿第二定律，加速一个物体所需的力直接取决于它的**质量**。"},
"alkali":{"e":"Farmers added an alkali compound to the acidic soil to raise its pH before planting the next crop.","t":"农民在酸性土壤中添加了一种**碱**性化合物，以提高其酸碱值，然后再种植下一季作物。"},
"unearth":{"e":"Archaeologists unearthed a hoard of bronze coins buried for centuries beneath the ruins of the ancient marketplace.","t":"考古学家在古代集市遗址下**发掘**出一批埋藏了数百年的青铜钱币。"},
"suffragist":{"e":"The suffragist marched through the capital demanding that women finally be granted the right to vote.","t":"这位**女权运动者**在首都游行示威，要求最终赋予妇女投票权。"},
"amusement":{"e":"The children spent the entire rainy afternoon finding amusement in a simple cardboard box and some crayons.","t":"孩子们在这个下雨的下午，仅靠一个简单的纸箱和几支蜡笔就找到了**乐趣**，消磨了整个下午。"},
"pharmacy":{"e":"She rushed to the all-night pharmacy at midnight to fill her son's prescription before his fever worsened.","t":"她半夜赶到通宵营业的**药店**，赶在儿子发烧加重之前把处方药配齐。"},
"shallow":{"e":"Children splashed safely in the shallow end of the pool while their parents watched from nearby lounge chairs.","t":"孩子们安全地在泳池**浅**水区玩水嬉戏，家长们则坐在附近的躺椅上看着。"},
"irresistible":{"e":"The scent of fresh bread from the corner bakery proved irresistible, drawing hungry students away from their morning lectures.","t":"街角面包店飘出的新鲜面包香气让人**无法抗拒**，把饥肠辘辘的学生从早课上引开。"},
"monarch":{"e":"The young monarch inherited the throne at twelve and ruled the kingdom for six turbulent decades.","t":"这位年轻的**君主**十二岁就继承了王位，统治这个王国长达六十个动荡的年头。"},
"faint":{"e":"Through the thick fog, sailors could make out only a faint outline of the lighthouse ahead.","t":"透过浓雾，水手们只能看到前方灯塔**模糊**的轮廓。"},
"criterion":{"e":"Punctuality became the professor's sole criterion for grading class participation, regardless of how insightful a comment was.","t":"准时成了这位教授评判课堂参与度的唯一**标准**，无论发言多么有见地。"},
"epidemic":{"e":"A measles epidemic swept through the crowded refugee camp before health workers could distribute enough vaccines.","t":"麻疹**疫情**席卷了拥挤的难民营，卫生工作者还没来得及分发足够的疫苗。"},
"joint":{"e":"Years of kneeling on the cold factory floor left the mechanic with a swollen, aching joint in each knee.","t":"多年跪在冰冷的工厂地板上干活，让这位技工两个膝盖的**关节**又肿又疼。"},
"debris":{"e":"Rescue workers spent three days clearing debris from the collapsed bridge before finally reopening the highway to traffic.","t":"救援人员花了三天时间清理坍塌大桥的**残骸**，才重新开放了这条高速公路，恢复通车。"},
"permanent":{"e":"The surgeon warned that without immediate treatment, the nerve damage could become permanent within a matter of weeks.","t":"外科医生警告说，如果不立即治疗，神经损伤可能在几周内变成**永久性**的。"},
"annex":{"e":"The empire moved quickly to annex the neighboring province after its elderly ruler died without leaving an heir.","t":"邻邦年迈的统治者死后没有留下继承人，帝国便趁机**兼并**了这个省份。"},
"draft":{"e":"The editor scribbled dozens of corrections across the author's first draft before sending it back for revision.","t":"编辑在作者的初期**草稿**上写满了几十处修改意见，然后退回去让他修改。"},
"soccer":{"e":"Every Saturday, neighborhood kids gathered on the dusty lot to play soccer until the streetlights came on.","t":"每逢周六，邻里的孩子们都会聚在那片尘土飞扬的空地上踢**足球**，直到路灯亮起。"},
"ore":{"e":"Miners hauled cartloads of iron ore up from the tunnels to feed the roaring smelters above.","t":"矿工们把一车车铁**矿石**从隧道里拉上来，供给上面轰鸣的冶炼炉。"},
"cumbersome":{"e":"The old typewriter's cumbersome mechanism made it nearly impossible to type faster than a slow, deliberate pace.","t":"这台旧打字机**笨重**的机械构造让人几乎不可能打得比缓慢而刻意的节奏更快。"},
"gentility":{"e":"Despite growing up in poverty, she carried herself with a gentility that fooled every aristocrat at the ball.","t":"尽管在贫困中长大，她举止间流露出的**文雅**却骗过了舞会上的每一位贵族。"},
"stagecoach":{"e":"The weary travelers boarded the stagecoach at dawn, knowing the journey across the mountains would take a full week.","t":"疲惫的旅客们黎明时分登上**驿站马车**，知道穿越群山的旅程要花整整一周。"},
"folklore":{"e":"The old fisherman's tales of sea monsters belonged to local folklore passed down through generations of coastal villagers.","t":"老渔夫讲的海怪故事属于沿海村民世代相传的地方**民间传说**。"},
"glacial":{"e":"The valley's smooth, rounded boulders reveal a glacial history stretching back tens of thousands of years.","t":"山谷里那些光滑浑圆的巨石揭示了一段可追溯到数万年前的**冰川**历史。"},
"microscope":{"e":"Under the powerful microscope, the biology students finally saw the bacteria wriggling actively across the glass slide.","t":"在这台高倍**显微镜**下，生物系学生终于看到了细菌在载玻片上活跃地蠕动。"},
"beat":{"e":"The underdog team beat the defending champions in overtime, stunning everyone who had watched the season unfold.","t":"这支实力较弱的球队在加时赛中**击败**了卫冕冠军，让所有关注本赛季的人都大吃一惊。"},
"disorder":{"e":"The sudden power outage plunged the hospital ward into disorder as nurses scrambled to find backup equipment.","t":"突然停电让医院病房陷入一片**混乱**，护士们手忙脚乱地寻找备用设备。"},
"spinet":{"e":"Grandmother's spinet sat in the parlor for decades, its keys yellowed but still perfectly in tune.","t":"祖母那台**小型立式钢琴**在客厅里放了几十年，琴键已经泛黄，但音准依然完美。"},
"consume":{"e":"The wildfire began consuming the dry hillside brush within minutes, forcing residents to flee their homes.","t":"野火几分钟内就开始**吞噬**干燥的山坡灌木丛，迫使居民逃离家园。"},
"besides":{"e":"Besides the usual suspects of sugar and fat, researchers found hidden preservatives lurking in the snack.","t":"**除了**常见的糖和脂肪之外，研究人员还在这款零食里发现了隐藏的防腐剂。"},
"affect":{"e":"Chronic sleep deprivation can affect memory and decision-making far more severely than most busy professionals ever realize.","t":"长期睡眠不足对记忆力和决策能力的**影响**，可能比大多数忙碌的职场人士意识到的要严重得多。"},
"ethnic":{"e":"The weekend festival celebrated the city's ethnic diversity with food stalls representing dozens of different immigrant communities.","t":"这场周末节日庆典通过代表数十个不同移民社区的美食摊位，展现了这座城市的**民族**多样性。"},
"fitness":{"e":"The coach measured each recruit's fitness through a grueling series of sprints, push-ups, and endurance runs.","t":"教练通过一系列高强度的冲刺、俯卧撑和耐力跑来衡量每位新兵的**体能**。"},
"evacuation":{"e":"Local officials ordered the full evacuation of the coastal town just hours before the hurricane made landfall.","t":"当地官员在飓风登陆前几个小时就下令全面**撤离**这座沿海小镇。"},
"pamphlet":{"e":"Volunteers patiently handed out a pamphlet explaining voter registration procedures to everyone entering the crowded community center.","t":"志愿者耐心地向每个进入拥挤社区中心的人分发解释选民登记流程的**小册子**。"},
"concentrate":{"e":"The noisy construction outside made it nearly impossible for her to concentrate on the difficult final exam.","t":"外面嘈杂的施工声让她几乎无法**集中精力**应对这场艰难的期末考试。"},
"systematic":{"e":"The detective's systematic approach to the case involved cataloging every witness statement before drawing a single conclusion.","t":"这位侦探办案采用**系统性**的方法，先整理每一份证人证词，然后才下结论。"},
"client":{"e":"The attorney reviewed every clause with her client before he signed away rights to the property.","t":"律师在**委托人**签字放弃这处房产的权利之前，和他一条条核对了每一项条款。"},
"dye":{"e":"The weaver soaked the wool in a vat of indigo dye until it turned a deep, rich blue.","t":"织工把羊毛浸泡在靛蓝**染料**桶里，直到它变成深邃浓郁的蓝色。"},
"finance":{"e":"A wealthy alumnus agreed to finance the new science wing after touring the school's outdated labs.","t":"一位富有的校友在参观了学校陈旧的实验室后，同意为新建的科学楼**提供资金**。"},
"supervise":{"e":"The senior nurse was assigned to supervise three interns during their first overnight shift in the ward.","t":"这位资深护士被指派在实习生第一次值夜班期间**监督指导**三名新人。"},
"tariff":{"e":"The government imposed a steep tariff on imported steel to protect domestic manufacturers from cheaper competition.","t":"政府对进口钢材征收高额**关税**，以保护本国制造商免受廉价竞争的冲击。"},
"exposure":{"e":"Prolonged exposure to the midday sun left the hikers with painful sunburns by the time they reached camp.","t":"长时间**暴露**在正午的阳光下，徒步者们到达营地时都被晒得又疼又红。"},
"neoclassical":{"e":"The courthouse's tall columns and symmetrical facade closely reflect the neoclassical style popular among nineteenth-century architects.","t":"法院那高耸的立柱和对称的正面，鲜明地反映了十九世纪建筑师们钟爱的**新古典主义**风格。"},
"array":{"e":"The bakery display case held a dazzling array of pastries, from delicate macarons to towering cream cakes.","t":"面包店的展示柜里摆着令人眼花缭乱的**一系列**糕点，从精致的马卡龙到高耸的奶油蛋糕。"},
"counselor":{"e":"The grieving family met with a counselor weekly to work through the loss of their father.","t":"这个悲痛的家庭每周都会去见一位**心理顾问**，共同面对失去父亲的伤痛。"},
"overact":{"e":"The lead actor tended to overact during emotional scenes, drawing chuckles instead of tears from the audience.","t":"这位主演在感情戏中总是**表演过火**，惹得观众发笑而不是落泪。"},
"append":{"e":"The lawyer ultimately decided to append a clarifying footnote rather than rewrite the entire lengthy contract.","t":"律师最终决定**附加**一条说明性脚注，而不是重写整份冗长的合同。"},
"chilly":{"e":"Her reply to his apology was so chilly that he immediately regretted bringing up the subject at all.","t":"她对他道歉的回应如此**冷淡**，他立刻后悔提起这个话题。"},
"retrospect":{"e":"In retrospect, the committee slowly realized that rushing the merger had ignored several obvious early warning signs.","t":"**事后回顾**，委员会才慢慢意识到仓促推进这次合并忽视了几个明显的早期警示信号。"},
"havoc":{"e":"The rogue trading algorithm wreaked havoc on the exchange floor, erasing millions in value within mere seconds.","t":"这个失控的交易算法在交易所大厅造成了**大乱**，短短几秒钟内就抹去了数百万的市值。"},
"sacrifice":{"e":"The firefighter didn't hesitate to sacrifice his own safety to pull the trapped child from the burning house.","t":"这位消防员毫不犹豫地**牺牲**自己的安全，把被困的孩子从燃烧的房子里救出来。"},
"evacuate":{"e":"Firefighters ordered everyone to evacuate the building the moment smoke began seeping under the stairwell door.","t":"浓烟刚开始从楼梯间门下渗出，消防员就下令所有人**撤离**这栋楼。"},
"bilingualism":{"e":"Growing up, her family's bilingualism meant she switched effortlessly between Spanish and English at the dinner table.","t":"从小家庭里的**双语现象**让她在餐桌上能毫不费力地在西班牙语和英语之间切换。"},
"zest":{"e":"Even after forty years of teaching, she approached each new class with the same zest she had as a rookie.","t":"即便教了四十年书，她面对每个新班级依然带着当年新手时同样的**热情**。"},
"etiquette":{"e":"The diplomat's grasp of local etiquette impressed the hosts, who noted how naturally he bowed at the proper moments.","t":"这位外交官对当地**礼仪**的掌握给主人留下了深刻印象，他们注意到他在恰当的时刻自然地鞠躬。"},
"disinterest":{"e":"The judge's evident disinterest in either party's wealth or social status made her rulings widely respected throughout the region.","t":"这位法官对双方的财富或社会地位表现出明显的**超然公正**，使她的裁决在整个地区广受尊重。"},
"stipulate":{"e":"The signed contract clearly stipulated that the contractor must complete the roof before the rainy season began.","t":"签署的合同**明确规定**承包商必须在雨季开始前完成屋顶工程。"},
"oratorio":{"e":"The community choir spent months rehearsing Handel's famous oratorio before performing it inside the cathedral's stone nave.","t":"社区合唱团花了几个月排练亨德尔著名的**清唱剧**，才在大教堂的石砌中殿演出。"},
"morgue":{"e":"The tired detective drove straight to the city morgue to identify the body before the grieving family arrived.","t":"疲惫的侦探直接开车前往市**停尸房**，赶在悲痛的家属到达之前辨认尸体。"},
"democracy":{"e":"The fragile new democracy held its first free election amid fears that the old regime might seize power again.","t":"这个脆弱的新兴**民主政体**举行了首次自由选举，人们担心旧政权可能会再次夺权。"},
"coral":{"e":"Rising ocean temperatures have bleached vast stretches of coral along the reef, killing the vibrant ecosystem beneath the waves.","t":"海水温度上升使礁石上大片**珊瑚**白化，摧毁了海浪之下生机勃勃的生态系统。"},
"pheromone":{"e":"A single female moth can release enough pheromone to attract eager males from over a mile away.","t":"一只雌蛾释放的**信息素**足以吸引一英里外急切的雄蛾。"},
"ornament":{"e":"Each glass ornament on the tree had been handed down from her grandmother's collection in Prague.","t":"树上的每一件玻璃**装饰品**都是从她祖母在布拉格的收藏中传下来的。"},
"deport":{"e":"The government threatened to deport the activist after he criticized the ruling party in a televised interview.","t":"这位活动人士在电视采访中批评执政党后，政府威胁要将他**驱逐出境**。"},
"outgas":{"e":"Engineers had to outgas the spacecraft's components in a vacuum chamber before they could be safely installed.","t":"工程师必须先在真空舱里对航天器部件**除气**，才能安全安装它们。"},
"chaste":{"e":"The monastery's chaste interior held nothing but a wooden cross and a single bench for prayer.","t":"修道院**简朴**的内部装饰只有一个木十字架和一条祈祷用的长凳。"},
"tract":{"e":"The surgeon explained that the infection had spread along the digestive tract, complicating the planned operation.","t":"外科医生解释说感染已经沿着消化**道**扩散，使原定的手术复杂化了。"},
"cipher":{"e":"Wartime code breakers labored tirelessly for months to crack the enemy's cipher before the planned invasion began.","t":"战时的密码破译员不知疲倦地花了几个月，才在预定的入侵开始前破解敌军的**密码**。"},
"soloist":{"e":"The young violinist stepped forward as soloist, her bow trembling slightly before the first note filled the hall.","t":"这位年轻的小提琴手作为**独奏者**走上前台，第一个音符响彻大厅之前，她的琴弓微微颤抖。"},
"notwithstanding":{"e":"Notwithstanding the harsh reviews, the film went on to become one of the decade's highest-grossing releases.","t":"**尽管**评价不佳，这部电影后来还是成了这十年间票房最高的作品之一。"},
"protagonist":{"e":"The novel's protagonist spends the entire second act questioning whether her quest was ever worth the sacrifice.","t":"小说的**主角**在整个第二幕里都在质疑自己的追求是否值得付出这样的牺牲。"},
"prolonged":{"e":"Prolonged exposure to loud machinery gradually damaged the factory workers' hearing over the course of decades.","t":"**长期**暴露在嘈杂的机器声中，几十年下来逐渐损害了工厂工人的听力。"},
"bet":{"e":"He placed a bet on the underdog horse, certain the favorite would tire before the final stretch.","t":"他把**赌注**压在了那匹不被看好的马身上，确信热门马会在最后冲刺前体力不支。"},
"physical":{"e":"The therapist carefully designed a physical routine that gradually rebuilt strength in the patient's badly injured shoulder.","t":"治疗师精心设计了一套**身体**训练方案，逐步恢复病人严重受伤肩膀的力量。"},
"incursion":{"e":"The tired border guards repelled a nighttime incursion by smugglers attempting to cross the wide river undetected.","t":"疲惫的边防卫兵击退了走私者试图偷渡宽阔河流的夜间**突袭**。"},
"metric":{"e":"The lab required every measurement to be recorded in metric units to match international publication standards.","t":"实验室要求所有测量数据都用**公制**单位记录，以符合国际发表标准。"},
"transplant":{"e":"Surgeons worked through the entire night to transplant the donated kidney before the fragile organ deteriorated.","t":"外科医生连夜工作了一整晚，赶在这个脆弱的器官变质之前完成肾脏**移植**手术。"},
"fresco":{"e":"Restorers spent nearly a decade carefully removing centuries of grime from the chapel's magnificent ceiling fresco before reopening it.","t":"修复人员花了近十年时间，才把这座小教堂天花板宏伟的**湿壁画**上积累了几个世纪的污垢小心清除干净。"},
"mission":{"e":"The rescue team accepted the mission knowing that the mountain's weather could turn deadly within hours.","t":"救援队接下了这项**任务**，深知山上的天气可能在几小时内变得致命。"},
"spray":{"e":"Cold spray from the roaring waterfall drenched the hikers long before they even reached the viewing platform.","t":"轰鸣瀑布的冰冷**水花**早在徒步者到达观景台之前就把他们浇透了。"},
"tectonics":{"e":"Plate tectonics explains why earthquakes cluster along certain fault lines rather than occurring randomly across the globe.","t":"板块**构造学**解释了为什么地震会集中在特定断层线上，而不是在全球随机发生。"},
"assign":{"e":"The busy manager decided to assign the toughest client account to her most experienced sales representative available.","t":"忙碌的经理决定把最难缠的客户账户**分配**给手头最有经验的销售代表。"},
"swell":{"e":"The river began to swell rapidly after three days of continuous rain fell upstream, threatening to overflow its banks.","t":"上游连续三天下雨后，河水开始迅速**上涨**，眼看着就要漫过河岸。"},
"outlying":{"e":"Doctors in the outlying villages often traveled for hours just to reach patients without any transportation of their own.","t":"**偏远**村庄的医生常常要跋涉数小时，才能到达没有自备交通工具的病人身边。"},
"blink":{"e":"She didn't even blink when the interviewer finally asked the question everyone else had dreaded answering honestly.","t":"面试官最终问出大家都害怕如实回答的问题时，她连眼睛都没**眨**一下。"},
"dialect":{"e":"Linguists traveled to the remote valley specifically to record the dying dialect before its last speakers passed away.","t":"语言学家专程前往那个偏远的山谷，要在最后几位使用者去世前记录下这种濒临消失的**方言**。"},
"shortly":{"e":"The pilot calmly announced that the plane would land shortly, prompting nervous passengers to fasten their seatbelts.","t":"飞行员平静地宣布飞机**不久**就会降落，紧张的乘客们纷纷系好安全带。"},
"applaud":{"e":"The entire auditorium rose to applaud the retiring conductor after his final performance with the orchestra.","t":"这位指挥家与乐团完成最后一场演出后，全场观众起立**鼓掌**。"},
"larva":{"e":"The gardener discovered dozens of beetle larva feeding on the roots beneath the wilting tomato plants.","t":"园丁发现几十只甲虫**幼虫**正在枯萎番茄植株下的根部啃食。"},
"monastery":{"e":"The monks at the remote monastery rose before dawn each day to tend the vegetable gardens.","t":"这座偏远**修道院**的僧侣每天黎明前就起床打理菜园。"},
"facet":{"e":"The lawyer examined every facet of the case before deciding which argument would sway the jury.","t":"这位律师检视了这起案件的每一个**方面**，才决定哪种论点能说服陪审团。"},
"primal":{"e":"The nature documentary explored humanity's primal fear of darkness and its deep roots in ancient survival instincts.","t":"这部自然纪录片探讨了人类对黑暗的**原始**恐惧及其在远古生存本能中的深层根源。"},
"revolt":{"e":"Factory workers across the region threatened to revolt against management after their wages were slashed without any warning.","t":"全地区的工厂工人在工资被毫无预警地削减后，威胁要**反抗**管理层。"},
"ceremonial":{"e":"The tribal chief wore an elaborate ceremonial headdress reserved only for the tribe's most sacred annual gatherings.","t":"部落酋长戴着一顶精致的**仪式**头饰，这种头饰只在部落最神圣的年度集会上才会出现。"},
"seasoning":{"e":"The chef insisted that a pinch of the right seasoning could transform even the simplest broth into something memorable.","t":"这位厨师坚信，恰到好处的一撮**调料**能把最简单的高汤变成令人难忘的美味。"},
"abreast":{"e":"The three cyclists rode abreast down the empty country road, chatting easily in the morning light.","t":"三名骑行者在空旷的乡间小路上**并排**骑行，在晨光中轻松地聊着天。"},
"pioneer":{"e":"Marie Curie helped pioneer the field of radioactivity research at a time when few women were allowed in laboratories.","t":"居里夫人在很少有女性获准进入实验室的年代，协助**开创**了放射性研究这一领域。"},
"division":{"e":"The merger created a sharp division within the company between employees who welcomed change and those who resisted it.","t":"这次合并在公司内部造成了明显的**分歧**，一部分员工欢迎变革，另一部分则抵制。"},
"horn":{"e":"The enraged bull lowered its sharp horn and charged straight at the startled matador standing frozen in the ring.","t":"这头暴怒的公牛低下锋利的**角**，径直朝站在场地中央吓得僵住的斗牛士冲去。"},
"fix":{"e":"The skilled technician managed to fix the crashed server before the company's biggest client noticed any downtime.","t":"这位熟练的技术人员在公司最大的客户察觉到任何宕机之前，就设法**修好**了崩溃的服务器。"},
"ecological":{"e":"Removing the wolves from the park triggered an ecological imbalance that let the deer population explode unchecked.","t":"把狼从公园里移走引发了**生态**失衡，导致鹿群数量失控般激增。"},
"label":{"e":"The chemist carefully labeled each vial with the date and contents before storing them in the refrigerated cabinet.","t":"化学家仔细地给每个小瓶**标注**日期和内容物，然后才把它们存入冷藏柜。"},
"appropriate":{"e":"Congress voted overwhelmingly to appropriate additional emergency funds for flood relief soon after the aging levee finally failed.","t":"国会以压倒性票数决定为防洪救灾**拨款**追加紧急资金，就在老化的堤坝终于决口之后。"},
"scientific":{"e":"The panel dismissed the study's conclusions, citing a lack of scientific rigor in how the samples were collected.","t":"评审小组以样本采集缺乏**科学**严谨性为由，驳回了这项研究的结论。"},
"wear":{"e":"Decades of constant foot traffic had begun to wear the marble steps into smooth, shallow grooves.","t":"几十年不间断的人来人往已经把大理石台阶**磨**出了光滑的浅凹槽。"},
"increment":{"e":"Each year of loyal service earned the clerk a small increment added automatically to her base salary.","t":"这位职员每忠诚服务一年，基本工资就会自动**增加**一小笔。"},
"stiffen":{"e":"Her entire posture seemed to visibly stiffen the moment her former rival walked into the crowded room.","t":"她的老对手一走进拥挤的房间，她整个人的姿态似乎立刻明显**变得僵硬**起来。"},
"protrude":{"e":"A jagged rock protruded from the shallow water, invisible until the boat was nearly upon it.","t":"一块嶙峋的岩石从浅水中**突出**，船几乎撞上去之前都难以察觉。"},
"audition":{"e":"Hundreds of dancers showed up for the audition, but the director needed only six for the touring cast.","t":"数百名舞者前来参加**试演**，但导演的巡演阵容只需要六人。"},
"sexism":{"e":"The lawsuit accused the firm of systemic sexism after women were repeatedly passed over for promotion.","t":"这起诉讼指控该公司存在系统性**性别歧视**，因为女性员工屡次被跳过晋升机会。"},
"attentive":{"e":"The young waiter remained attentive throughout the entire meal, refilling water glasses before anyone even had to ask.","t":"这位年轻的服务员整顿饭都非常**细心周到**，不等客人开口就把水杯续满。"},
"graze":{"e":"Cattle grazed peacefully across the quiet hillside while clouds drifted slowly over the valley below them.","t":"牛群在宁静的山坡上安静地**吃草**，云朵在下面的山谷上空缓缓飘过。"},
"anguish":{"e":"The mother's anguish over her missing son was visible to everyone who saw her pacing outside the police station.","t":"这位母亲因儿子失踪而承受的**极度痛苦**，在她于警察局外来回踱步时表露无遗。"},
"implore":{"e":"The passengers began to implore the captain to turn back once the storm clouds darkened the horizon.","t":"暴风雨的乌云笼罩地平线后，乘客们开始**恳求**船长掉头。"},
"sage":{"e":"The young apprentice sought sage advice from the old blacksmith before opening his very own forge.","t":"这位年轻学徒在开设自己的锻造铺之前，向老铁匠寻求**贤明**的建议。"},
"ambiguous":{"e":"The contract's deliberately ambiguous wording allowed both companies to interpret the deadline however it best suited them.","t":"合同刻意**模棱两可**的措辞让两家公司都能按最有利于自己的方式解读截止日期。"},
"swirl":{"e":"A sudden swirl of autumn leaves danced across the empty parking lot in the cold afternoon wind.","t":"寒冷的午后风中，一阵突如其来的**漩涡**秋叶在空荡荡的停车场上翩翩起舞。"},
"crime":{"e":"Petty crime dropped sharply after the city finally installed brighter streetlights along the entire downtown corridor.","t":"市区整条走廊安装了更明亮的路灯后，轻微**犯罪**案件大幅下降。"},
"swear":{"e":"The new officers raised their right hands and swore to uphold the constitution before the assembled crowd.","t":"新任官员在聚集的人群面前举起右手，**宣誓**捍卫宪法。"},
"typical":{"e":"A typical morning at the clinic involves treating everything from minor colds to serious allergic reactions.","t":"诊所里**典型**的一个早晨要处理从普通感冒到严重过敏反应的各种病症。"},
"confirm":{"e":"Lab results eventually confirmed exactly what the doctor had suspected from the very first physical examination.","t":"化验结果最终**证实**了医生从第一次体检起就怀疑的病情。"},
"descent":{"e":"She proudly traced her family's descent back seven generations to a tiny fishing village in Portugal.","t":"她自豪地把家族**世系**追溯到七代之前葡萄牙的一个小渔村。"},
"scuba":{"e":"Wearing scuba gear, the marine biologist descended sixty feet to study the coral formations up close.","t":"海洋生物学家戴着**水肺**装备下潜六十英尺，近距离研究珊瑚礁的构造。"},
"bandanna":{"e":"The farmhand tied a faded red bandanna around his neck to keep the dust from his throat.","t":"这位农场工人在脖子上系了一条褪色的红**头巾**，防止灰尘呛到喉咙。"},
"technological":{"e":"The factory's sweeping technological upgrade cut production time in half while also reducing material waste significantly across every department.","t":"这家工厂全面的**技术**升级不仅把生产时间缩短了一半，还大幅减少了各部门的材料浪费。"},
"chant":{"e":"The protesters' angry chant grew louder and louder as they marched past the government building at noon.","t":"正午时分，抗议者经过政府大楼时，他们愤怒的**口号**越喊越响亮。"},
"firm":{"e":"After graduating from law school, she joined a small firm downtown that specialized exclusively in environmental litigation cases.","t":"法学院毕业后，她加入了市中心一家专门从事环境诉讼案件的小型**律师事务所**。"},
"overview":{"e":"The opening lecture began with a brief overview of the causes that eventually led to the revolution.","t":"开场讲座一开始先简要**概述**了最终导致这场革命爆发的各种原因。"},
"calculate":{"e":"The engineer carefully calculated the bridge's maximum load capacity before finally approving the design for construction to begin.","t":"工程师仔细**计算**出这座桥的最大承重量，才最终批准施工设计开始动工。"},
"gland":{"e":"An overactive thyroid gland can cause sudden, unexplained weight loss along with a persistently racing heartbeat and constant fatigue.","t":"甲状腺**腺体**功能亢进会导致体重骤然下降、心跳持续加速，还有挥之不去的疲劳感。"},
"landmark":{"e":"The old clock tower has served as a landmark for lost tourists navigating the city's winding streets.","t":"这座古老的钟楼一直是游客在这座城市蜿蜒街道中迷路时用来辨认方向的**地标**。"},
"season":{"e":"Farmers watched the sky anxiously during the planting season, praying the rains would arrive on time.","t":"农民们在播种**时节**焦急地望着天空，祈祷雨水能按时到来。"},
"topography":{"e":"The region's rugged topography, full of steep ridges and deep ravines, made building a direct railway line nearly impossible.","t":"这个地区崎岖的**地貌**布满陡峭的山脊和深邃的峡谷，让修建一条直达铁路线几乎不可能。"},
"proposal":{"e":"The city council firmly rejected the developer's proposal to build a shopping mall near the protected wetlands.","t":"市议会坚决否决了开发商在受保护湿地附近建造购物中心的**提议**。"},
"represent":{"e":"The young lawyer agreed to represent the tenants in their bitter dispute against the negligent landlord.","t":"这位年轻律师同意在租户与疏忽失职房东的激烈纠纷中**代表**他们。"},
"apparent":{"e":"It became painfully apparent within minutes that the negotiations had collapsed beyond any real hope of repair.","t":"几分钟内就痛苦地**明显**看出谈判已经破裂，毫无真正挽回的希望。"},
"summarize":{"e":"The intern was asked to summarize the quarterly report into a single slide for the board meeting.","t":"实习生被要求把季度报告**总结**成一张幻灯片，供董事会会议使用。"},
"aquatic":{"e":"The wetland supports a rich variety of aquatic plants that filter pollutants from the surrounding runoff.","t":"这片湿地孕育着种类丰富的**水生**植物，能过滤周边径流中的污染物。"},
"verify":{"e":"The cautious bank called immediately to verify the large transaction before allowing it to finally go through.","t":"谨慎的银行立刻打电话来**核实**这笔大额交易，然后才最终放行。"},
"notch":{"e":"The new smartphone model performs a notch above its predecessor in both processing speed and battery life.","t":"新款智能手机在处理速度和电池续航上都比上一代高出**一档**。"},
"intentionally":{"e":"The editor intentionally left the ending ambiguous, hoping readers would argue over its meaning for years.","t":"编辑**故意**把结局写得模棱两可，希望读者能为其含义争论多年。"},
"admiration":{"e":"The rookie's calm handling of the crisis earned the admiration of even the most skeptical veterans on the team.","t":"这名新人在危机中沉着应对的表现，赢得了团队里最挑剔的老将们的**钦佩**。"},
"eviscerate":{"e":"The old fisherman quickly eviscerated the day's catch on the dock before packing it neatly in ice.","t":"老渔夫在码头上迅速**取出当天渔获的内脏**，然后整齐地装冰保存。"},
"roost":{"e":"Hundreds of noisy starlings roost in the old barn every single evening before scattering again at first light.","t":"数百只吵闹的椋鸟每晚都在这座老谷仓里**栖息**，天刚亮就再次四散飞去。"},
"wane":{"e":"Public interest in the scandal began to wane once a more sensational story dominated the headlines.","t":"一则更耸人听闻的新闻占据头条后，公众对这桩丑闻的兴趣开始**减弱**。"},
"nutrient":{"e":"The badly depleted soil lacked the nutrient content needed to support a genuinely healthy corn crop.","t":"这片严重贫瘠的土壤缺乏支撑真正健康玉米作物所需的**养分**含量。"},
"motor":{"e":"The stroke had damaged the region of his brain responsible for fine motor control in his right hand.","t":"中风损伤了他大脑中负责右手精细**运动**控制的区域。"},
"ribbon":{"e":"She carefully tied a satin ribbon around the gift box before placing it gently under the tree.","t":"她仔细地在礼物盒上系了一条缎面**丝带**，然后轻轻放到圣诞树下。"},
"insist":{"e":"The doctor insisted firmly that the patient remain in the hospital overnight, despite his repeated protests and obvious impatience.","t":"医生**坚持要求**病人留院过夜观察，尽管他一再抗议，显得很不耐烦。"},
"basic":{"e":"Before tackling advanced calculus, every student must master the basic principles of algebra and plane geometry.","t":"在学习高等微积分之前，每个学生都必须先掌握代数和平面几何的**基本**原理。"},
"glossy":{"e":"The magazine's glossy cover photograph made the resort look far more luxurious than it actually was.","t":"杂志封面那张**光鲜**的照片让这家度假村看起来比实际豪华得多。"},
"separate":{"e":"A thin wooden partition separated the two workshops, muffling but not blocking the noise between them.","t":"一道薄薄的木隔断把两个车间**分隔**开来，能减弱但不能完全隔绝彼此的噪音。"},
"reception":{"e":"The debut novel's cold reception among critics genuinely surprised the publisher, who had expected glowing reviews.","t":"这部处女作小说在评论界遇冷的**反响**让出版商大感意外，他们原本期待好评如潮。"},
"hygiene":{"e":"Poor hygiene in the crowded camp allowed the infection to spread among hundreds of refugees within days.","t":"拥挤营地里糟糕的**卫生**条件使感染在几天内就在数百名难民中蔓延开来。"},
"metabolic":{"e":"A naturally slower metabolic rate as people age often explains why excess weight becomes harder to manage.","t":"随着年龄增长，自然减慢的**新陈代谢**速率往往能解释为什么多余的体重变得更难控制。"},
"cashier":{"e":"The tired cashier counted the register drawer twice before finally locking up the store for the night.","t":"疲惫的**收银员**在最终锁店结束当晚工作之前，把收银台抽屉里的钱数了两遍。"},
"furnish":{"e":"The charity furnishes school supplies to thousands of low-income families before the start of each academic year.","t":"这家慈善机构在每个学年开始前为数千个低收入家庭**提供**学习用品。"},
"librarian":{"e":"The librarian helped the freshman track down a rare manuscript buried deep in the archive's basement.","t":"**图书管理员**帮这名大一新生在档案馆地下室深处找到了一份珍稀手稿。"},
"prototype":{"e":"Engineers rigorously tested the prototype for six full months before finally approving it for large-scale mass production.","t":"工程师对**原型**机进行了整整六个月的严格测试，才最终批准大规模量产。"},
"wipe":{"e":"She quickly wiped the kitchen counter clean before setting down the freshly baked bread to cool.","t":"她迅速**擦**干净厨房台面，才把刚出炉的面包放上去晾凉。"},
"allude":{"e":"The cautious senator repeatedly alluded to corruption within the department without ever naming a specific official.","t":"这位谨慎的参议员反复**暗指**该部门存在腐败，却始终没有点名任何具体官员。"},
"challenge":{"e":"Raising three young children while running a small business presented a daily challenge she never fully anticipated.","t":"一边经营小生意一边抚养三个年幼的孩子，这是她从未完全预料到的日常**挑战**。"},
"frank":{"e":"The coach's brutally frank assessment of the team's weaknesses stung, but everyone quietly agreed it was necessary.","t":"教练对球队弱点极其**坦率**的评价让人难堪，但所有人都默默认同这是必要的。"},
"sweep":{"e":"A sudden wave of protests swept across the entire country after the controversial verdict was finally announced.","t":"这项有争议的判决最终公布后，一波突如其来的抗议浪潮**席卷**了整个国家。"},
"backup":{"e":"The IT department restored the entire database from a backup made just hours before the crash.","t":"IT部门用一份就在系统崩溃前几小时制作的**备份**，恢复了整个数据库。"},
"ledge":{"e":"The climber rested on a narrow ledge halfway up the cliff before continuing to the summit.","t":"攀登者在悬崖半山腰一处狭窄的**突出岩架**上休息，然后才继续向顶峰进发。"},
"analyze":{"e":"The forensic team analyzed the fibers found at the scene to determine what type of fabric they came from.","t":"法医团队**分析**了现场发现的纤维，以确定它们来自哪种布料。"},
"nest":{"e":"A pair of robins chose to nest in the gutter just above the front porch this spring.","t":"今年春天，一对知更鸟选择在前门廊正上方的排水槽里**筑巢**。"},
"revenue":{"e":"Ticket sales generated most of the small theater's revenue, though concessions contributed a surprisingly large share.","t":"门票销售是这家小剧院大部分**收入**的来源，不过小卖部的贡献也出人意料地可观。"},
"demobilize":{"e":"The exhausted government finally moved to demobilize thousands of soldiers once the peace treaty was officially signed.","t":"和平条约正式签署后，筋疲力尽的政府终于着手**遣散**数千名士兵。"},
"enrollment":{"e":"Student enrollment at the small rural school dropped sharply after the factory closed and families moved away.","t":"工厂关闭、家庭纷纷搬离后，这所乡村小学校的**在校人数**大幅下降。"},
"statesman":{"e":"History remembers him as a shrewd statesman who negotiated peace between nations on the brink of war.","t":"历史将他铭记为一位精明的**政治家**，他在濒临战争的国家之间斡旋达成了和平。"},
"accustom":{"e":"It took the exhausted new recruits several weeks to accustom themselves to the brutal daily training schedule.","t":"筋疲力尽的新兵们花了好几个星期才**习惯**了这套残酷的日常训练日程。"},
"labyrinth":{"e":"The old fortress's cellars formed a labyrinth of narrow passages that even the guards sometimes got lost in.","t":"这座古老要塞的地窖构成了一座狭窄通道的**迷宫**，连守卫有时都会在里面迷路。"},
"irregular":{"e":"The patient's irregular heartbeat during the routine checkup prompted the doctor to order an immediate electrocardiogram that afternoon.","t":"病人在常规体检中出现的**不规律**心跳，促使医生当天下午就安排了心电图检查。"},
"therapy":{"e":"After the accident, months of intensive physical therapy gradually restored movement to his badly injured leg.","t":"事故发生后，几个月高强度的物理**治疗**逐渐恢复了他严重受伤腿部的活动能力。"},
"artesian":{"e":"The farmer struck an artesian well that supplied fresh water without needing any pump at all.","t":"这位农民打出了一口**自流**井，完全不需要水泵就能供应淡水。"},
"gear":{"e":"A stripped gear inside the old clock finally caused it to stop ticking after decades of service.","t":"这台老钟表内部一个磨损的**齿轮**，在运转了几十年后终于让它停止了走动。"},
"physician":{"e":"The attending physician recommended a strict diet immediately after noticing the patient's blood sugar levels had spiked.","t":"主治**内科医生**一注意到病人的血糖水平飙升，就立刻建议他严格控制饮食。"},
"conductivity":{"e":"Copper's remarkably high electrical conductivity makes it the preferred material for nearly all household and industrial wiring.","t":"铜非凡的高电**传导性**使它成为几乎所有家用和工业电线的首选材料。"},
"Paleolithic":{"e":"Archaeologists uncovered a remarkable cache of Paleolithic tools buried for millennia beneath thick layers of hardened volcanic ash.","t":"考古学家在厚厚的硬化火山灰层下，发掘出一批埋藏了数千年、令人惊叹的**旧石器时代**工具。"},
"campus":{"e":"Freshmen wandered the sprawling campus for hours before finally locating the chemistry building tucked behind the library.","t":"大一新生在广阔的**校园**里转悠了好几个小时，才终于找到藏在图书馆后面的化学楼。"},
"polygamous":{"e":"Anthropologists carefully studied several polygamous communities to understand how resources were shared among multiple spouses fairly.","t":"人类学家仔细研究了几个**一夫多妻**的社群，以了解资源如何在多个配偶之间公平分配。"},
"flick":{"e":"She casually flicked the light switch and watched the old neon sign sputter reluctantly back to life.","t":"她随手**轻按**电灯开关，看着那块老旧的霓虹灯牌不情愿地闪烁着重新亮了起来。"},
"universal":{"e":"The deep human desire for safety and belonging seems nearly universal across every culture researchers have carefully studied.","t":"对安全感和归属感的深切人类渴望，在研究人员仔细考察过的几乎每种文化中都显得**普遍**存在。"},
"assess":{"e":"Inspectors were sent to assess the structural damage carefully before any of the insurance claims could be processed.","t":"检查员被派去仔细**评估**结构损失，之后任何保险理赔才能开始处理。"},
"prone":{"e":"Children who skip breakfast are more prone to losing focus during the first classes of the day.","t":"不吃早餐的孩子在一天最初几节课上更**容易**注意力涣散。"},
"afoul":{"e":"The ambitious startup ran afoul of federal regulations after launching its product without any proper safety testing.","t":"这家雄心勃勃的初创公司在未经任何充分安全测试就推出产品后，与联邦法规**发生了冲突**。"},
"bewilder":{"e":"The sudden change in exam format bewildered students who had prepared for a completely different set of questions.","t":"考试形式的突然改变让那些准备了完全不同题型的学生**不知所措**。"},
"pinch":{"e":"The crab's powerful claw can pinch hard enough to draw blood if the shell is handled carelessly.","t":"螃蟹强壮的钳子如果处理不当，能**夹**得很重，甚至夹出血来。"},
"malleable":{"e":"Pure gold is remarkably malleable, allowing skilled artisans to hammer it into sheets thinner than ordinary paper.","t":"纯金具有惊人的**延展性**，熟练的工匠能把它锤打成比普通纸还薄的薄片。"},
"interweave":{"e":"The talented novelist skillfully interweaves three separate storylines that only fully converge in the final chapter.","t":"这位才华横溢的小说家巧妙地**交织**了三条独立的故事线，直到最后一章才完全汇合。"},
"Mesolithic":{"e":"The riverbank excavation revealed a set of Mesolithic fishing hooks skillfully fashioned from carved animal bone centuries ago.","t":"河岸的发掘工作发现了一套**中石器时代**的鱼钩，是几个世纪前用兽骨精心雕刻而成的。"},
"gamble":{"e":"Investing his entire savings in the unproven startup was a gamble that eventually paid off handsomely.","t":"把全部积蓄投入这家未经市场检验的初创公司是一场**冒险**，最终却获得了丰厚回报。"},
"outweigh":{"e":"For most elderly patients, the clear benefits of the surgery outweigh the risks associated with the procedure.","t":"对大多数老年病人来说，手术明显的益处**超过**了该手术相关的风险。"},
"sterile":{"e":"Surgeons must keep every single instrument completely sterile to prevent dangerous infection during a lengthy operation.","t":"外科医生必须让每一件器械保持完全**无菌**，以防止漫长手术过程中发生危险的感染。"},
"component":{"e":"Trust is arguably the single most essential component of any successful, long-term business partnership between two companies.","t":"信任可以说是任何两家公司之间成功、长期商业合作关系中最重要的**组成部分**。"},
"ammonia":{"e":"The strong smell of ammonia in the cleaning solution made the janitor open every window in the hallway.","t":"清洁剂里浓烈的**氨**味让门卫把走廊里的每扇窗户都打开了。"},
"photosynthesis":{"e":"Without sufficient sunlight streaming through the canopy, the seedling cannot complete photosynthesis and will gradually starve.","t":"没有充足的阳光穿过树冠洒下，这株幼苗就无法完成**光合作用**，最终会逐渐枯死。"},
"mar":{"e":"A single careless scratch across the canvas would mar the painting's value beyond any hope of repair.","t":"画布上一道粗心的刮痕就会**损毁**这幅画的价值，让它再也无法挽回。"},
"consist":{"e":"The committee's final report consists of twelve chapters, each addressing a different aspect of the crisis.","t":"委员会的最终报告**由十二个章节构成**，每章都探讨危机的一个不同方面。"},
"flair":{"e":"The young chef displayed a natural flair for combining unexpected flavors that critics couldn't stop praising.","t":"这位年轻厨师展现出将意想不到的味道搭配在一起的天生**才能**，评论家们赞不绝口。"},
"selective":{"e":"The prestigious university remains highly selective, admitting fewer than five percent of its applicants each year.","t":"这所名校录取标准依然十分**严格挑剔**，每年录取的申请者不到百分之五。"},
"pin":{"e":"The wrestler managed to pin his opponent's shoulders to the mat within the first thirty seconds.","t":"这名摔跤手在开局三十秒内就设法把对手的肩膀**摁**在垫子上。"},
"concrete":{"e":"The determined prosecutor needed concrete evidence before she could convince the jury beyond any reasonable doubt.","t":"这位坚定的检察官需要**确凿**的证据，才能让陪审团排除一切合理怀疑地信服。"},
"temple":{"e":"Pilgrims climbed the mountain for three days to reach the ancient temple carved into the cliffside.","t":"朝圣者爬了三天的山，才到达那座雕刻在悬崖峭壁上的古老**寺庙**。"},
"battery":{"e":"Before clearing him for surgery, the doctors ordered a battery of tests to check his heart, lungs, and kidneys.","t":"在批准他接受手术之前，医生们安排了**一系列**检查来查看他的心脏、肺和肾脏。"},
"continuation":{"e":"The negotiations broke down twice, yet both sides agreed that a continuation of talks next spring offered the only realistic path to peace.","t":"谈判两次破裂，但双方都同意，来年春天**继续**会谈是通往和平的唯一现实途径。"},
"humanity":{"e":"The prison guard treated even the most hardened inmates with quiet humanity, offering blankets and a patient ear on cold nights.","t":"那位狱警甚至对最顽固的囚犯也怀着静默的**仁慈**，在寒冷的夜晚给他们毯子，耐心倾听。"},
"access":{"e":"Without reliable internet, rural students often lack access to the online courses that could otherwise expand their opportunities.","t":"没有可靠的网络，农村学生常常无法**获得**那些本可以拓展他们机会的在线课程。"},
"shade":{"e":"Hikers paused beneath the oak's dense shade to escape the midday sun before continuing up the rocky trail.","t":"徒步者们在橡树浓密的**阴凉处**停下，躲避正午的烈日，然后继续沿着多石的小径前行。"},
"manual":{"e":"Despite the factory's new robots, several tasks on the assembly line still require careful manual adjustment by skilled workers.","t":"尽管工厂引进了新机器人，装配线上的一些工序仍需要熟练工人进行细致的**手工**调整。"},
"bush":{"e":"A rabbit darted beneath the thorny bush the moment the garden gate creaked open behind us.","t":"就在我们身后的花园门吱呀一声打开的瞬间，一只兔子窜进了那丛多刺的**灌木**下面。"},
"hardware":{"e":"Upgrading the laptop's hardware, especially its memory and processor, made the outdated machine feel surprisingly fast again.","t":"升级这台笔记本电脑的**硬件**，尤其是内存和处理器，让这台过时的机器又变得出奇地快。"},
"proprietor":{"e":"The proprietor of the corner bakery still greets every regular customer by name after thirty years behind the counter.","t":"这家街角面包店的**老板**在柜台后站了三十年，至今仍能叫出每位常客的名字。"},
"terrestrial":{"e":"Unlike its aquatic cousins, this species of turtle is almost entirely terrestrial, spending its whole life wandering dry forest floors.","t":"与水生的同类不同，这种乌龟几乎完全是**陆栖**的，一生都在干燥的森林地面上游荡。"},
"flask":{"e":"The chemist swirled the bubbling liquid in the flask, watching its color shift from pale yellow to deep amber.","t":"化学家轻轻摇晃着**烧瓶**里冒泡的液体，看着它的颜色从淡黄色变成深琥珀色。"},
"crawl":{"e":"The toddler began to crawl across the kitchen floor the instant her mother turned to answer the phone.","t":"就在妈妈转身去接电话的瞬间，那个蹒跚学步的孩子开始在厨房地板上**爬行**。"},
"locomotive":{"e":"The restored steam locomotive pulled twelve wooden carriages up the steep mountain grade, hissing clouds of white vapor.","t":"这台修复的蒸汽**机车**拖着十二节木质车厢爬上陡峭的山坡，喷出团团白色蒸汽。"},
"pound":{"e":"Her heart began to pound against her ribs the moment the interviewer asked why she had left her last job.","t":"面试官一问她为什么离开上一份工作，她的心就开始**怦怦**撞击着肋骨狂跳。"},
"cereal":{"e":"Farmers across the plains rotate cereal crops like wheat and barley to keep the soil from losing its nutrients.","t":"平原上的农民们轮种小麦和大麦等**谷类**作物，以防止土壤流失养分。"},
"lunar":{"e":"The lunar calendar, based on the moon's phases rather than the sun's cycle, determines the dates of many traditional Chinese festivals.","t":"**阴历**是根据月相而非太阳周期制定的，许多中国传统节日的日期都由它决定。"},
"manufacture":{"e":"The factory manufactures thousands of ceramic tiles every day, shipping them to hardware stores across the country.","t":"这家工厂每天**大量生产**成千上万块瓷砖，并将其运往全国各地的五金店。"},
"seismograph":{"e":"The seismograph recorded a sudden spike in ground motion minutes before the earthquake's tremors reached the city.","t":"**地震仪**在地震的震动波及城市前几分钟，记录到地面运动的骤然飙升。"},
"prey":{"e":"The owl preys on small rodents at night, swooping down silently from its perch to snatch them.","t":"猫头鹰在夜间**捕食**小型啮齿动物，从栖息处悄无声息地俯冲下来将其抓住。"},
"fluctuate":{"e":"Gasoline prices fluctuate wildly with global oil supply, making it hard for drivers to budget for commutes.","t":"汽油价格随全球石油供应**大幅波动**，让司机很难为通勤费用做预算。"},
"solder":{"e":"The technician soldered the loose wire back onto the circuit board to restore power to the device.","t":"技术员把松脱的电线重新**焊接**到电路板上，恢复了设备的电力。"},
"outstanding":{"e":"The landlord sent a third reminder about the outstanding balance, still unpaid despite two months of notices.","t":"房东发来第三份提醒，提及这笔历经两个月催缴依然**未偿付**的欠款余额。"},
"cargo":{"e":"The freighter's cargo shifted violently during the storm, forcing the crew to redistribute the weight below deck.","t":"货轮的**货物**在暴风雨中剧烈移位，迫使船员重新分配甲板下的重量。"},
"inferior":{"e":"Critics dismissed the knockoff handbags as inferior to the originals, noting the cheap stitching and mismatched hardware throughout.","t":"评论者认为这些仿冒手提包远**逊色于**正品，指出其做工粗糙、五金件也不匹配。"},
"removal":{"e":"The removal of asbestos from the old school building required workers in full protective suits and respirators.","t":"从老校舍**清除**石棉需要工人穿戴全套防护服和呼吸器。"},
"tenement":{"e":"Generations of immigrant families crowded into the same cramped tenement, sharing a single bathroom down the hall.","t":"几代移民家庭挤在同一栋狭小的**廉租公寓**里，合用走廊尽头的一个卫生间。"},
"impermeable":{"e":"The hiking jacket's impermeable shell kept the rain from soaking through even during the heaviest downpour.","t":"这件徒步外套**不透水**的外层，即便在最大的暴雨中也能挡住雨水渗透。"},
"astronomy":{"e":"Her fascination with astronomy began the night she first saw Saturn's rings through a borrowed telescope.","t":"她对**天文学**的痴迷始于借来望远镜第一次看到土星光环的那个夜晚。"},
"intrusion":{"e":"Residents protested the developer's intrusion into the protected wetland, arguing it would destroy fragile nesting habitats nearby.","t":"居民抗议开发商对受保护湿地的**侵扰**，认为这将破坏附近脆弱的鸟类筑巢栖息地。"},
"spectator":{"e":"Thousands of spectators lined the marathon route, cheering exhausted runners on through the final grueling miles of the course.","t":"数千名**观众**沿马拉松赛道排列，为精疲力竭的跑者呐喊助威，直至赛程最后艰苦的几英里。"},
"adolescence":{"e":"Adolescence brings a turbulent mix of hormonal changes, new social pressures, and a growing desire for independence.","t":"**青春期**伴随着荷尔蒙剧变、新的社交压力，以及日益增长的独立渴望，是一段动荡的时期。"},
"snowflake":{"e":"Under the microscope, each snowflake revealed a unique six-sided crystal pattern that no two shared exactly.","t":"在显微镜下，每一片**雪花**都呈现出独特的六角形晶体结构，没有两片完全相同。"},
"audit":{"e":"Curious about linguistics but unwilling to commit to homework, she decided to audit the graduate seminar instead.","t":"她对语言学很感兴趣，却不想承担作业负担，于是决定**旁听**这门研究生研讨课。"},
"grading":{"e":"The professor's grading grew noticeably stricter after several students submitted essays copied nearly word for word.","t":"在几名学生提交的论文几乎逐字抄袭之后，教授的**评分**明显变得更加严格。"},
"exception":{"e":"Every applicant must submit official transcripts, with the sole exception of students transferring from partner universities abroad.","t":"每位申请人都必须提交正式成绩单，唯一的**例外**是从海外合作院校转学的学生。"},
"shell":{"e":"The hermit crab abandoned its outgrown shell and scuttled across the sand in search of a roomier one.","t":"寄居蟹抛弃了已经太小的**外壳**，急匆匆地爬过沙滩去寻找一个更宽敞的新壳。"},
"argue":{"e":"The defense attorney argued that the witness's testimony was too inconsistent to support a guilty verdict.","t":"辩护律师**辩称**，证人的证词前后矛盾，不足以支持有罪判决。"},
"municipal":{"e":"The municipal government installed new streetlights along the riverfront to improve safety for evening joggers and cyclists.","t":"**市政**当局在河畔沿线加装了新路灯，以提升夜跑者和骑行者的安全。"},
"lawn":{"e":"Every Saturday morning, he mowed the lawn before the heat of the afternoon made the chore unbearable.","t":"每周六早晨，他都会在下午的酷热让这活儿变得难以忍受之前，把**草坪**修剪好。"},
"wither":{"e":"Without regular watering, the tomato seedlings began to wither within days, their leaves curling and turning brown.","t":"由于缺乏定期浇水，番茄幼苗几天内就开始**枯萎**，叶片卷曲发黄。"},
"seashore":{"e":"Families gathered along the seashore at dusk to watch the fishing boats return with their day's catch.","t":"傍晚时分，一家家人聚集在**海滨**，观看渔船满载着一天的渔获归来。"},
"interest":{"e":"The bank raised the interest charged on unpaid credit card balances, alarming customers already struggling with debt.","t":"银行提高了对信用卡欠款收取的**利息**，让本就债台高筑的客户忧心忡忡。"},
"fantastic":{"e":"The costume designer created fantastic creatures with feathered wings and scaled tails unlike anything seen before on stage.","t":"服装设计师创造出长着羽翼和鳞尾的**奇幻**生物，是舞台上前所未见的形象。"},
"championship":{"e":"After three grueling sets, she finally claimed the championship, raising the trophy above her head in triumph.","t":"经过三盘艰苦的较量，她终于赢得了**冠军**，胜利地将奖杯高举过头顶。"},
"implication":{"e":"Doctors were slow to grasp the implication of the strange symptom, which later proved to signal a serious infection.","t":"医生们起初没能领会这个奇怪症状的**含义**，后来才发现它预示着严重感染。"},
"dump":{"e":"Factories along the river illegally dumped chemical waste at night, poisoning the water supply for nearby villages.","t":"河边的工厂在夜间非法**倾倒**化学废料，污染了附近村庄的供水。"},
"already":{"e":"By the time the ambulance arrived, the paramedics found that bystanders had already stabilized the injured cyclist.","t":"救护车抵达时，急救人员发现旁观者**已经**为受伤的骑行者做了稳定处理。"},
"preeminent":{"e":"Among cardiologists worldwide, she is regarded as preeminent, having pioneered techniques now standard in heart surgery.","t":"在全世界心脏病专家中，她被视为**卓越超群**的权威，她开创的技术如今已是心脏手术的标准做法。"},
"suction":{"e":"The vacuum cleaner's suction weakened noticeably once the dust bag filled past its recommended capacity, forcing a change.","t":"一旦集尘袋装得超过推荐容量，这台吸尘器的**吸力**就会明显减弱，必须更换集尘袋。"},
"excess":{"e":"Doctors warned that excess salt in processed foods was quietly driving up rates of high blood pressure.","t":"医生警告说，加工食品中**过量**的盐分正在悄悄推高高血压的发病率。"},
"associative":{"e":"Through associative memory, the scent of chalk dust instantly brought back her third-grade classroom and its stern teacher.","t":"凭借**联想**记忆，粉笔灰的气味瞬间把她带回三年级的教室和那位严厉的老师。"},
"cognitive":{"e":"Researchers found that regular chess playing improved cognitive function in older adults, particularly memory and problem-solving speed.","t":"研究人员发现，经常下棋能改善老年人的**认知**功能，尤其是记忆力和解决问题的速度。"},
"trek":{"e":"The climbers trekked for six days through knee-deep snow before reaching the remote base camp at dawn.","t":"登山者们在及膝深的积雪中**艰苦跋涉**了六天，才在黎明时分抵达偏远的大本营。"},
"baffle":{"e":"The sudden disappearance of the entire flock overnight baffled the ornithologists, who could find no trace of migration.","t":"整群鸟一夜之间突然消失，把鸟类学家们**难住了**，他们找不到任何迁徙的痕迹。"},
"corpus":{"e":"Linguists built a massive corpus of everyday speech to study how slang spreads across different regions.","t":"语言学家建立了一个庞大的日常口语**语料库**，用以研究俚语如何在不同地区传播。"},
"worship":{"e":"Pilgrims traveled hundreds of miles to worship at the ancient temple, leaving offerings of rice and incense.","t":"朝圣者跋涉数百英里前往那座古庙**朝拜**，献上大米和香烛作为供品。"},
"monotony":{"e":"The monotony of the assembly line, the same motion repeated thousands of times a shift, eventually numbed his mind.","t":"装配线上的**单调**——同一个动作一班要重复上千次——最终让他的思维变得麻木。"},
"dissuade":{"e":"Her mentor tried to dissuade her from quitting the stable job to chase an uncertain career in painting.","t":"导师试图**劝阻**她，不要辞去稳定的工作去追求前途未卜的绘画事业。"},
"slough":{"e":"Snakes periodically slough off their outer skin as their bodies grow too large for the old layer.","t":"蛇会定期**蜕去**外层皮肤，因为身体长大后旧皮已经容不下了。"},
"beneficent":{"e":"The beneficent landowner donated half his estate to build a free clinic for the surrounding farming villages.","t":"这位**乐善好施**的地主捐出了一半地产，为周边的农村地区兴建了一所免费诊所。"},
"extort":{"e":"The gang extorted protection money from shopkeepers, threatening to smash their windows if they refused to pay.","t":"那帮匪徒向店主**敲诈勒索**保护费，威胁如果不交钱就砸烂他们的橱窗。"},
"bluster":{"e":"The coach blustered about benching the whole team, but everyone knew he would calm down by practice.","t":"教练**气势汹汹地叫嚣**要让全队坐冷板凳，但大家都知道他到训练时就会消气。"},
"iceberg":{"e":"The captain steered hard to starboard when the lookout spotted an iceberg looming just ahead in the fog.","t":"了望员发现前方雾中赫然出现一座**冰山**时，船长立刻猛打右舵。"},
"energetic":{"e":"Even after the long flight, the toddler remained energetic, racing around the terminal instead of settling down.","t":"即便经过长途飞行，那个小孩依然**精力充沛**，在航站楼里跑来跑去，怎么也不肯安静下来。"},
"colonial":{"e":"The town's colonial architecture, with its narrow cobblestone streets, drew tourists eager to glimpse centuries-old buildings.","t":"这座小镇的**殖民时期**建筑及其狭窄的鹅卵石街道，吸引着渴望一睹数百年老建筑风貌的游客。"},
"slope":{"e":"The ski instructor warned beginners away from the steep slope, directing them instead to the gentler bunny hill.","t":"滑雪教练提醒初学者远离陡峭的**斜坡**，引导他们改去坡度更缓的初学者雪道。"},
"match":{"e":"No opponent in the regional league proved to be a match for the reigning champion's relentless serve.","t":"地区联赛中没有一个对手能成为卫冕冠军凌厉发球的**对手**。"},
"deal":{"e":"After months of tense negotiation, the two companies finally struck a deal to merge their shipping operations.","t":"经过数月紧张的谈判，两家公司终于达成**协议**，合并各自的航运业务。"},
"archaeology":{"e":"Her passion for archaeology took root during a school trip to an excavation site along the Nile.","t":"她对**考古学**的热情，是在一次前往尼罗河畔发掘现场的学校旅行中萌生的。"},
"legend":{"e":"According to local legend, a sea serpent still guards the sunken treasure beneath the harbor's rocky shoals.","t":"根据当地**传说**，一条海蛇至今仍守护着港湾礁石下沉没的宝藏。"},
"inanity":{"e":"The inanity of the talk show's endless celebrity gossip finally drove her to cancel her cable subscription.","t":"脱口秀节目里没完没了的名人八卦**空洞无聊**，最终让她取消了有线电视订阅。"},
"airborne":{"e":"Health officials confirmed the virus was airborne, spreading through tiny droplets exhaled in crowded, poorly ventilated rooms.","t":"卫生官员证实该病毒可通过**空气传播**，借由拥挤且通风不良房间中呼出的微小飞沫扩散。"},
"blues":{"e":"On rainy evenings, the old bar filled with the mournful sound of blues drifting from a lone saxophone.","t":"在下雨的傍晚，那家老酒吧里回荡着一支萨克斯独自吹奏的哀伤**布鲁斯乐曲**。"},
"crest":{"e":"The surfer timed her jump perfectly, catching the wave just as it reached its crest before crashing down.","t":"冲浪者完美把握了起跳的时机，恰好在浪头到达**浪尖**、即将崩溃之前将其接住。"},
"primitive":{"e":"Archaeologists uncovered primitive stone tools that suggested humans had inhabited the cave far earlier than previously believed.","t":"考古学家发现了**原始**石器，这表明人类栖居这个洞穴的时间比此前认为的要早得多。"},
"comic":{"e":"His comic timing during the toast had the entire wedding party laughing before he reached the punchline.","t":"他祝酒时的**滑稽**节奏逗得全场婚礼宾客还没等他说出包袱就已笑翻。"},
"buckle":{"e":"The old leather belt's buckle finally snapped, forcing him to hold his trousers up with one hand.","t":"那条旧皮带的**扣环**终于断裂，逼得他只能用一只手提着裤子。"},
"deform":{"e":"Years of standing on the factory floor had begun to deform the workers' feet, forcing painful, awkward gaits.","t":"多年站在工厂车间里工作，已经开始让工人们的双脚**变形**，走起路来又疼又别扭。"},
"ceremony":{"e":"The graduation ceremony stretched on for nearly three hours as each of the four hundred names was read aloud.","t":"毕业**典礼**持续了将近三个小时，因为四百个名字被逐一大声念出。"},
"informative":{"e":"The museum's new exhibit proved remarkably informative, explaining the region's volcanic history through interactive maps and models.","t":"博物馆的新展览**信息量极大**，通过互动地图和模型讲解了该地区的火山历史。"},
"mention":{"e":"She casually mentioned that she had once climbed Kilimanjaro, and the room instantly fell silent in astonishment.","t":"她随口**提起**自己曾经攀登过乞力马扎罗山，满屋子的人顿时惊讶得鸦雀无声。"},
"immunity":{"e":"Recovering from the infection left her with lasting immunity, so the second outbreak that winter never touched her.","t":"从这次感染中康复后，她获得了持久的**免疫力**，所以那年冬天第二波疫情根本没影响到她。"},
"origin":{"e":"Historians still dispute the exact origin of the custom, though most trace it back to medieval harvest festivals.","t":"历史学家至今仍在争论这一习俗的确切**起源**，不过大多数人认为它可追溯到中世纪的丰收节庆。"},
"arthritis":{"e":"Arthritis in her knees made the daily walk to the market increasingly painful as the winter dampness set in.","t":"随着冬季湿气渗入，膝盖的**关节炎**让她每天去市场的路变得越来越痛苦。"},
"poisonous":{"e":"The bright colors of the frog serve as a warning that its skin secretions are highly poisonous to predators.","t":"这种青蛙鲜艳的体色是一种警示，表明它皮肤分泌物对捕食者具有很强的**毒性**。"},
"humid":{"e":"The greenhouse was kept deliberately humid, since the orchids inside would wilt in anything drier than a rainforest.","t":"温室被特意保持**潮湿**，因为里面的兰花在比雨林更干燥的环境中就会枯萎。"},
"ecology":{"e":"Studying the ecology of coral reefs revealed how closely fish populations depend on the health of the coral itself.","t":"研究珊瑚礁的**生态**揭示了鱼类种群与珊瑚自身健康之间的密切依存关系。"},
"falcon":{"e":"The falconer released the falcon from her glove, watching it climb in tight circles before diving toward the lure.","t":"驯鹰人从手套上放飞**猎鹰**，看着它盘旋而上，然后俯冲向诱饵。"},
"acting":{"e":"The vice principal served as acting principal for the semester while the school searched for a permanent replacement.","t":"副校长在这一学期担任**代理**校长，同时学校也在寻找永久的继任人选。"},
"deficiency":{"e":"A deficiency of vitamin D during the long winter months left many residents feeling unusually tired and achy.","t":"在漫长的冬季里，维生素D的**缺乏**让许多居民感到异常疲惫和浑身酸痛。"},
"exchange":{"e":"Tourists lined up outside the bank to exchange their dollars for local currency before the holiday markets opened.","t":"游客们在银行外排队，赶在节日集市开门前把美元**兑换**成当地货币。"},
"complementary":{"e":"The chef paired the rich chocolate cake with a tart raspberry sauce, two flavors that proved wonderfully complementary.","t":"主厨把浓郁的巧克力蛋糕和酸甜的覆盆子酱搭配在一起，两种味道**相辅相成**，效果极好。"},
"grudge":{"e":"Despite losing the promotion to her rival, she refused to hold a grudge and congratulated him sincerely.","t":"尽管晋升的机会被对手夺走，她还是没有心怀**怨恨**，真诚地向他表示祝贺。"},
"bagel":{"e":"He toasted a bagel and smeared it with cream cheese before rushing out the door to catch his train.","t":"他烤了一个**硬面包圈**，抹上奶油奶酪，然后冲出门赶火车。"},
"eager":{"e":"The new intern arrived an hour early, eager to make a good impression on her first day.","t":"这位新实习生提前一小时到岗，**渴望**在第一天就给大家留下好印象。"},
"preserve":{"e":"The nonprofit works to preserve the coastal marshland, fighting off developers who want to build luxury condominiums there.","t":"这家非营利组织致力于**保护**沿海沼泽地，抵御那些想在那里建造豪华公寓的开发商。"},
"indicate":{"e":"A sudden drop in the stock's trading volume often indicates that investors are losing confidence in the company.","t":"股票交易量的骤然下降常常**表明**投资者正在对该公司失去信心。"},
"blossom":{"e":"Every April, the cherry blossoms along the riverbank draw crowds who picnic beneath the pale pink branches.","t":"每年四月，河畔的樱**花**都会吸引成群的人来到淡粉色的枝丫下野餐。"},
"watercourse":{"e":"Engineers rerouted the ancient watercourse to prevent it from flooding the new subway tunnel during heavy rains.","t":"工程师们改道了这条古老的**水道**，以防它在暴雨期间淹没新建的地铁隧道。"},
"statue":{"e":"Vandals spray-painted the bronze statue in the town square, prompting outrage from residents who cherished the monument.","t":"破坏者在镇广场的青铜**雕像**上喷涂了涂鸦，引发了珍视这座纪念碑的居民的愤怒。"},
"destined":{"e":"Even as a shy child, she seemed destined for the stage, always performing little plays for her family.","t":"即便小时候很害羞，她似乎也**注定**要走上舞台，总是给家人表演小话剧。"},
"miserable":{"e":"Stranded at the airport for fourteen hours without food vouchers, the passengers grew increasingly miserable as the night wore on.","t":"乘客们在机场滞留了十四个小时，没有餐食券，随着夜色渐深，他们变得越来越**痛苦难受**。"},
"algebra":{"e":"Struggling with algebra in ninth grade, he never imagined he would later become a celebrated mathematics professor.","t":"九年级时**代数**学得很吃力的他，从未想过自己后来会成为一位知名的数学教授。"},
"destructive":{"e":"The wildfire proved so destructive that it leveled entire neighborhoods and left thousands of families without homes.","t":"这场野火**破坏性**极大，夷平了整片街区，令数千个家庭无家可归。"},
"projector":{"e":"The old film projector clattered noisily in the back of the auditorium as it cast flickering images onto the screen.","t":"那台老式电影**放映机**在礼堂后方哐当作响，把闪烁的画面投射到银幕上。"},
"circumstance":{"e":"Under no circumstance would the airline refund a ticket purchased through a third-party travel site, the agent explained.","t":"代理解释说，无论何种**情况**，航空公司都不会为通过第三方旅行网站购买的机票办理退款。"},
"hazel":{"e":"Beneath the old hazel, squirrels buried acorns and nuts they would dig up again once winter arrived.","t":"在那棵老**榛树**下，松鼠们埋藏橡子和坚果，等冬天来临时再把它们挖出来。"},
"reward":{"e":"The company offered a generous reward to anyone who returned the missing prototype before the launch deadline.","t":"公司为任何能在发布截止日期前归还这个丢失原型机的人提供丰厚的**报酬**。"},
"sewerage":{"e":"The city's aging sewerage system overflowed during the storm, sending wastewater backward into hundreds of basement drains.","t":"这座城市老化的**排水系统**在暴风雨中溢流，导致污水倒灌进数百户人家的地下室排水管。"},
"even":{"e":"She trimmed the hedge carefully, making sure the top stayed perfectly even along its entire thirty-foot length.","t":"她小心翼翼地修剪树篱，确保整整三十英尺长的顶部保持完全**平整**。"},
"intense":{"e":"The negotiations grew so intense that both delegations demanded a recess before tempers flared any further.","t":"谈判变得异常**激烈**，双方代表团都要求休会，以免情绪进一步失控。"},
"beam":{"e":"The lighthouse beamed its rotating light across the harbor every ten seconds, guiding ships safely past the reef.","t":"灯塔每隔十秒就向港湾**发射**一道旋转的光束，引导船只安全绕过暗礁。"},
"crossing":{"e":"Children were taught never to run across the crossing without first checking both directions for oncoming traffic.","t":"孩子们被教导，穿过**人行横道**之前一定要先看清两个方向有没有来车，绝不能贸然跑过去。"},
"dedication":{"e":"Her coach praised the swimmer's dedication, noting that she trained before dawn every single day for a decade.","t":"教练称赞这位游泳选手的**奉献精神**，指出她十年来每天都在黎明前开始训练。"},
"rim":{"e":"Dust had settled along the rim of the antique teacup, suggesting it had sat untouched on the shelf for years.","t":"灰尘沿着这只古董茶杯的**杯沿**积了一层，说明它已经在架子上原封不动地放了好些年。"},
"jelly":{"e":"She spread a thick layer of grape jelly on the toast before handing it to her little brother.","t":"她在烤面包上涂了厚厚一层葡萄**果冻**，然后递给了弟弟。"},
"contain":{"e":"The levee was built to contain the river during flood season, though it nearly failed last spring.","t":"这座堤坝是为了在洪水季节**控制**河水而修建的，不过去年春天它险些溃决。"},
"frame":{"e":"The novel's loose frame, a series of letters exchanged over decades, allowed the story to skip across time freely.","t":"这部小说松散的**框架**——数十年间往来书信的集合——让故事得以自由跳跃于不同的时间点。"},
"vast":{"e":"The expedition crossed a vast stretch of frozen tundra where no settlement existed for hundreds of miles.","t":"探险队穿越了一片**广袤**的冰冻苔原，方圆数百英里内没有任何聚落。"},
"characteristic":{"e":"Patience is not a characteristic anyone would associate with the notoriously short-tempered head chef of that kitchen.","t":"耐心绝不是任何人会与那位出了名脾气暴躁的主厨联系在一起的**特质**。"},
"squash":{"e":"The crowd at the concert squashed together so tightly near the stage that several fans had to be pulled out.","t":"演唱会上的人群在舞台附近**挤**得如此紧密，以至于好几名歌迷不得不被拉出人群。"},
"announce":{"e":"The committee announced the winner of the fellowship only after every application had been reviewed twice.","t":"委员会直到每份申请都经过两轮审核后，才**宣布**了奖学金的获得者。"},
"dedicate":{"e":"The retired teacher dedicated her remaining years to building a library for children in her rural hometown.","t":"这位退休教师把余生**奉献**给了在自己乡村家乡为孩子们建一座图书馆的事业。"},
"personal":{"e":"The coach kept his personal opinions about certain players strictly separate from his decisions during the draft.","t":"教练把自己对某些球员的**个人**看法与选秀时的决策严格区分开来。"},
"simmer":{"e":"Resentment had simmered among the factory workers for months before it finally erupted into a full strike.","t":"工厂工人们的不满**暗中积聚**了数月，最终才爆发成一场全面罢工。"},
"mate":{"e":"The sailor's mate took over the night watch, allowing him a few hours of much-needed sleep below deck.","t":"水手的**同事**接手了夜间值班，让他能在甲板下睡几个小时急需的觉。"},
"ensconce":{"e":"By the time guests arrived, grandfather was already ensconced in his favorite armchair by the fireplace, pipe in hand.","t":"客人到达时，祖父早已**安稳地坐**在壁炉旁他最喜欢的扶手椅上，手里拿着烟斗。"},
"conjure":{"e":"The street magician conjured a bouquet of paper flowers seemingly out of thin air, delighting the children nearby.","t":"街头魔术师仿佛凭空**变出**一束纸花，让周围的孩子们兴奋不已。"},
"middleman":{"e":"By selling directly to customers online, the farmer eliminated the middleman and kept a larger share of the profit.","t":"通过直接在网上向顾客销售，这位农民省去了**中间商**，自己留下了更大份额的利润。"},
"secular":{"e":"The university, though founded by missionaries, has operated as a fully secular institution for more than a century.","t":"这所大学虽然是由传教士创办的，但一个多世纪以来一直作为完全**世俗**的机构运作。"},
"chromosome":{"e":"A single extra chromosome in the cell's nucleus was enough to trigger the genetic disorder researchers had been studying.","t":"细胞核中一条多余的**染色体**，就足以引发研究人员一直在研究的这种遗传疾病。"},
"righteous":{"e":"The whistleblower felt a righteous anger upon discovering that executives had hidden the safety violations for years.","t":"揭发者发现高管们多年来一直隐瞒安全违规行为后，感到一种**义愤**。"},
"audible":{"e":"Her whisper was barely audible over the roar of the waterfall, so she had to shout to be heard.","t":"在瀑布的轰鸣声中，她的低语几乎**听不见**，所以她不得不大喊才能被听到。"},
"mellow":{"e":"The aged whiskey had grown remarkably mellow over two decades in the oak barrel, losing its early harsh bite.","t":"这瓶陈年威士忌在橡木桶中陈放二十年后变得异常**醇厚**，失去了早年那种刺喉的辛辣感。"},
"deplore":{"e":"Human rights groups deplored the government's decision to shut down the last independent newspaper in the capital.","t":"人权组织**强烈谴责**政府关闭首都最后一家独立报纸的决定。"},
"laborious":{"e":"Restoring the water-damaged manuscript page by page proved a laborious process that took the archivist nearly two years.","t":"逐页修复这份被水损坏的手稿被证明是一个**艰苦费力**的过程，档案管理员为此花了将近两年时间。"},
"singular":{"e":"The violinist's singular talent set her apart from every other contestant in the competition's forty-year history.","t":"这位小提琴家**卓尔不群**的才华，让她在这项已有四十年历史的比赛中脱颖而出，无人能及。"},
"enthusiastic":{"e":"The new coach was so enthusiastic about the team's potential that she volunteered to run extra practices unpaid.","t":"新教练对这支球队的潜力感到十分**热情**，甚至自愿无偿加练。"},
"alienate":{"e":"The CEO's dismissive remarks about remote workers alienated much of the staff, sparking a wave of quiet resignations.","t":"首席执行官对远程办公员工的轻蔑言论**疏远**了大部分员工，引发了一波悄然离职潮。"},
"fabulous":{"e":"The chef's fabulous reputation drew diners from three states, even though the restaurant sat down a forgotten alley.","t":"这位主厨**极佳**的声誉吸引了来自三个州的食客，尽管这家餐厅藏身于一条不起眼的小巷深处。"},
"rectify":{"e":"The airline scrambled to rectify the booking error before the family's connecting flight departed without them.","t":"航空公司匆忙**纠正**这个订票错误，以免这家人的转乘航班在他们未登机的情况下起飞。"},
"circuit":{"e":"A short circuit in the old wiring sparked the fire that eventually consumed the abandoned warehouse overnight.","t":"老旧线路中的短**路**引发了火灾，最终在一夜之间烧毁了这座废弃仓库。"},
"mathematics":{"e":"She discovered a genuine love for mathematics only after a patient tutor showed her how elegant proofs could be.","t":"直到一位耐心的家教向她展示证明过程可以多么优美之后，她才真正发现自己对**数学**的热爱。"},
"scuffle":{"e":"Security guards broke up a scuffle between rival fans that erupted just outside the stadium's main entrance.","t":"保安人员制止了一场在体育场正门外爆发的、对立球迷之间的**扭打**。"},
"opposed":{"e":"Local farmers remained fiercely opposed to the pipeline project, fearing it would contaminate the groundwater beneath their fields.","t":"当地农民依然强烈**反对**这个管道项目，担心它会污染自家田地下方的地下水。"},
"construct":{"e":"Engineers constructed a temporary bridge across the ravine so relief supplies could reach the stranded mountain village.","t":"工程师们在峡谷上**搭建**了一座临时桥梁，以便救援物资能够送达被困的山村。"},
"visible":{"e":"From the summit, the distant coastline was barely visible through the thin morning haze settling over the valley.","t":"从山顶望去，透过笼罩山谷的薄薄晨雾，远处的海岸线只是**隐约可见**。"},
"juice":{"e":"She juiced a dozen oranges by hand every morning, refusing to let the noisy electric machine do the work.","t":"她每天早晨都亲手把一打橙子**榨汁**，不肯让那台吵闹的电动榨汁机代劳。"},
"rainfall":{"e":"Unusually heavy rainfall this spring saturated the soil, causing several hillside homes to slide dangerously downhill.","t":"今年春天异常丰沛的**降雨**使土壤饱和，导致好几栋山坡上的房屋出现危险的滑移。"},
"granite":{"e":"The countertop, cut from a single slab of granite, had taken the quarry workers nearly a week to extract.","t":"这块台面是从一整块**花岗岩**上切割而成的，采石场工人为开采它耗费了将近一周时间。"},
"rare":{"e":"Wildlife photographers waited three weeks in the rainforest just to capture a single image of the rare species.","t":"野生动物摄影师在雨林中等了三个星期，只为拍到这个**稀有**物种的一张照片。"},
"pure":{"e":"The spring water flowing from the mountain was so pure that villagers drank it straight from the source.","t":"从山上流下来的泉水**纯净**到村民们直接从源头就能饮用。"},
"criticize":{"e":"Reviewers criticized the sequel for abandoning the wit and pacing that had made the original film so beloved.","t":"评论家**批评**这部续集丢掉了让原作如此受喜爱的机智与节奏感。"},
"behave":{"e":"The toddler behaved surprisingly well throughout the four-hour flight, napping peacefully through most of the turbulence.","t":"这个小孩在四小时的航班中**表现**出乎意料地乖巧，大部分颠簸时间里都安然入睡。"},
"alumnus":{"e":"As a proud alumnus of the university, he returned every homecoming weekend to watch the football team play.","t":"作为这所大学一名自豪的**男校友**，他每年返校周末都会回来观看橄榄球队比赛。"},
"customs":{"e":"The trader had to pay steep customs on the imported silk before it could clear the port warehouse.","t":"商人必须为进口丝绸缴纳高额**关税**，才能让货物从港口仓库放行。"},
"memo":{"e":"The manager circulated a memo reminding staff that the office would close early for the holiday weekend.","t":"经理发了一份**备忘录**，提醒员工假期周末办公室将提前关闭。"},
"ascend":{"e":"The climbers ascended the final ridge slowly, pausing every few steps to catch their breath in the thin air.","t":"登山者们缓慢地**攀登**最后一道山脊，每走几步就要停下喘口气，适应稀薄的空气。"},
"press":{"e":"The scandal only became public after an investigative reporter for the local press uncovered hidden financial records.","t":"这桩丑闻直到当地**新闻界**的一名调查记者揭露出隐藏的财务记录后才公之于众。"},
"fiction":{"e":"Although the characters felt real, the author insisted the entire memoir was pure fiction, invented from beginning to end.","t":"尽管书中人物感觉十分真实，作者却坚称整部回忆录纯属**虚构**，从头到尾都是编造的。"},
"absorb":{"e":"The thick wool carpet absorbed most of the sound, so footsteps upstairs were barely noticeable in the room below.","t":"厚厚的羊毛地毯**吸收**了大部分声音，所以楼上的脚步声在楼下几乎察觉不到。"},
"framework":{"e":"The new employee handbook provides a clear framework for handling customer complaints across every department in the company.","t":"新的员工手册为公司各部门处理客户投诉提供了一个清晰的**框架**。"},
"install":{"e":"A technician came to install solar panels on the roof, promising to cut the family's electricity bill in half.","t":"一名技术员前来在屋顶**安装**太阳能电池板，承诺能把这家人的电费削减一半。"},
"plaque":{"e":"A bronze plaque beside the door commemorated the scientist who had once lived and worked in that very house.","t":"门边的一块青铜**匾牌**纪念着曾经在这栋房子里生活和工作过的那位科学家。"},
"hypothesize":{"e":"Before running a single experiment, the students had to hypothesize why the plants near the window grew faster.","t":"在进行任何实验之前，学生们必须先**假设**为什么靠窗的植物长得更快。"},
"tedium":{"e":"To break the tedium of the overnight shift, the security guards took turns telling stories about their strangest calls.","t":"为了打破夜班的**乏味**，保安们轮流讲述他们遇到过的最离奇的出警故事。"},
"layer":{"e":"A thin layer of ash from the distant volcano settled over every car parked in the neighborhood overnight.","t":"一夜之间，远处火山飘来的一薄**层**灰烬覆盖了街区里停放的每一辆车。"},
"deliver":{"e":"The midwife had delivered nearly two thousand babies in the rural clinic over her thirty-year career.","t":"这位助产士三十年的职业生涯里，在这家乡村诊所**接生**了将近两千个婴儿。"},
"versatile":{"e":"A versatile actor, he moved effortlessly between tragic roles, slapstick comedy, and even musical theater within the same season.","t":"作为一名**多才多艺**的演员，他能在同一个演出季里轻松驾驭悲剧角色、闹剧喜剧，甚至音乐剧。"},
"plate":{"e":"Geologists explained that the tectonic plate beneath the region shifts a few centimeters every year, causing minor tremors.","t":"地质学家解释说，该地区下方的构造**板块**每年会移动几厘米，从而引发轻微震动。"},
"anthropology":{"e":"She switched her major to anthropology after a summer spent living among a remote tribe in the Amazon.","t":"在亚马孙丛林中与一个偏远部落共同生活一个夏天之后，她把专业改成了**人类学**。"},
"regardless":{"e":"Regardless of the freezing temperatures, the vendors set up their stalls in the square every single morning.","t":"**不管**气温多么寒冷，小贩们每天早晨依旧在广场上支起自己的摊位。"},
"domestic":{"e":"The airline announced new domestic routes connecting smaller cities that had previously required a layover to reach.","t":"这家航空公司宣布开通新的**国内**航线，连接此前需要中转才能抵达的一些小城市。"},
"fume":{"e":"He fumed silently in the waiting room after learning his flight had been delayed for the third time.","t":"得知航班已经第三次延误后，他在候机室里默默**大为恼火**。"},
"pit":{"e":"Years of acid rain had pitted the marble facade, leaving countless tiny craters across its once-smooth surface.","t":"多年的酸雨已经把大理石外墙**蚀出斑点**，曾经光滑的表面如今布满无数细小的坑洼。"},
"quota":{"e":"The fishing boat had to return to port early once it reached its quota of tuna for the season.","t":"这艘渔船一旦达到本季金枪鱼的**配额**，就必须提前返港。"},
"barb":{"e":"Her remark carried a subtle barb aimed at his habit of arriving late to every single team meeting.","t":"她的话里藏着一根针对他每次团队会议都迟到这一习惯的委婉**刺**。"},
"harness":{"e":"Engineers designed the dam to harness the river's current, converting its force into electricity for the entire valley.","t":"工程师设计这座水坝是为了**利用**河流的水流，将其力量转化为整个山谷的电力。"},
"opportunity":{"e":"The scholarship gave her an opportunity she never expected, to study marine biology on a research vessel abroad.","t":"这份奖学金给了她一个从未想过的**机会**，能登上一艘海外科考船研究海洋生物学。"},
"initial":{"e":"Her initial reaction to the diagnosis was disbelief, though she gradually came to accept the treatment plan.","t":"她对这一诊断结果的**最初**反应是难以置信，不过她后来逐渐接受了治疗方案。"},
"pebble":{"e":"Children spent the afternoon skipping smooth pebbles across the pond, counting how many bounces each one made.","t":"孩子们整个下午都在池塘上打水漂，数着每块光滑的**小圆石**能弹跳几次。"},
"amble":{"e":"After dinner, the elderly couple ambled along the boardwalk, stopping occasionally to admire the sunset over the bay.","t":"晚饭后，这对老夫妇沿着木栈道**慢悠悠地散步**，不时驻足欣赏海湾上空的落日。"},
"sharpen":{"e":"The chef sharpened his knives before every shift, insisting that dull blades were more dangerous than sharp ones.","t":"这位主厨每次上班前都要**磨快**自己的刀具，坚持认为钝刀比快刀更危险。"},
"dormancy":{"e":"The seeds can remain in dormancy for decades, sprouting only after a wildfire cracks open their tough outer shells.","t":"这些种子可以**休眠**长达数十年，只有在野火烧裂其坚硬的外壳之后才会发芽。"},
"urge":{"e":"Her therapist urged her to set firm boundaries with her family instead of constantly sacrificing her own needs.","t":"她的心理医生**力劝**她与家人建立清晰的界限，而不是一味牺牲自己的需求。"},
"contribute":{"e":"Volunteers from the community contributed hundreds of hours restoring the historic theater before its grand reopening.","t":"社区志愿者在这座历史剧院盛大重新开放前，**贡献**了数百个小时进行修复工作。"},
"trilogy":{"e":"The author spent nearly a decade writing her fantasy trilogy, publishing the final volume only last autumn.","t":"这位作者花了将近十年时间创作她的奇幻**三部曲**，直到去年秋天才出版了最后一卷。"},
"embed":{"e":"The jeweler embedded tiny diamonds along the ring's band, so it sparkled from every angle in the light.","t":"珠宝匠把细小的钻石**镶嵌**在戒指的指环上，使它在光线下从每个角度都能闪耀。"},
"auction":{"e":"Collectors from around the world bid fiercely at the auction, driving the rare painting's price past ten million dollars.","t":"来自世界各地的收藏家在**拍卖会**上激烈竞价，将这幅珍稀画作的价格推高到超过一千万美元。"},
"feedback":{"e":"The professor's detailed feedback on her draft helped her reorganize the entire argument before the final submission.","t":"教授对她初稿详细的**反馈意见**，帮助她在最终提交前重新组织了整篇论证。"},
"sober":{"e":"Realizing he had to drive everyone home, he stayed sober for the entire party, sipping only sparkling water.","t":"意识到自己要负责送大家回家，他整场聚会都保持**清醒**，只喝了气泡水。"},
"taboo":{"e":"Discussing salaries openly remained a taboo at the firm, even among colleagues who had worked together for years.","t":"公开谈论薪资在这家公司仍是一种**禁忌**，即便是共事多年的同事之间也是如此。"},
"prioritize":{"e":"Overwhelmed by the growing workload, she learned to prioritize tasks by deadline rather than by how much she enjoyed them.","t":"面对不断增加的工作量，她学会了按截止日期而非个人喜好来**排定优先顺序**。"},
"impel":{"e":"A deep sense of guilt impelled him to confess the mistake to his supervisor before anyone else discovered it.","t":"深深的愧疚感**驱使**他在别人发现这个错误之前主动向主管坦白。"},
"delinquency":{"e":"Researchers linked the rise in juvenile delinquency to overcrowded schools and a severe shortage of after-school programs.","t":"研究人员将青少年**不良行为**的上升归因于学校过度拥挤以及课后项目的严重匮乏。"},
"ensue":{"e":"When the power grid failed during the heatwave, chaos ensued as traffic lights across the city went dark.","t":"热浪期间电网瘫痪，随之**接踵而至**的是一片混乱，全城的交通信号灯都陷入黑暗。"},
"consensus":{"e":"After hours of debate, the committee finally reached a consensus on which candidate best suited the position.","t":"经过数小时的辩论，委员会终于就哪位候选人最适合这个职位达成了**共识**。"},
"kindle":{"e":"A single documentary about coral bleaching kindled her lifelong passion for marine conservation and ocean policy.","t":"一部关于珊瑚白化的纪录片**点燃**了她对海洋保护和海洋政策毕生的热情。"},
"lateral":{"e":"The crab's lateral movement across the sand looked awkward, yet it let the animal escape predators remarkably fast.","t":"螃蟹在沙滩上的**横向**移动看起来笨拙，却能让它以惊人的速度逃脱捕食者。"},
"recede":{"e":"As the tide receded, the children raced across the newly exposed sand to collect shells before the water returned.","t":"随着潮水**退去**，孩子们跑过刚刚露出的沙滩，赶在海水回涨前捡拾贝壳。"},
"operant":{"e":"The revised traffic regulations become operant on the first of January, replacing the outdated rules that drivers have followed for a decade.","t":"修订后的交通法规将于一月一日起**生效**，取代司机们遵循了十年之久的旧规定。"},
"aspire":{"e":"She aspires to become a diplomat, spending her evenings studying foreign languages and international law instead of watching television.","t":"她**渴望**成为一名外交官，晚上花时间学习外语和国际法，而不是看电视。"},
"canoe":{"e":"Every summer the two friends canoe along the quiet river, gliding past willows and stopping to fish at a hidden sandbar.","t":"每年夏天，这两个朋友都会**划着独木舟**沿安静的河流而行，掠过柳树，还会在一处隐蔽的沙洲停下来钓鱼。"},
"patron":{"e":"A wealthy patron funded the young composer's first symphony, allowing him to hire a full orchestra for its premiere.","t":"一位富有的**赞助人**资助了这位年轻作曲家的第一部交响曲，使他得以雇请一整个管弦乐团进行首演。"},
"larynx":{"e":"A sudden infection inflamed her larynx so severely that she could barely whisper for nearly two weeks.","t":"一场突发感染使她的**喉部**发炎得十分严重，近两周几乎说不出话来。"},
"ferment":{"e":"Grape juice must ferment for several weeks in oak barrels before it develops the complex flavors associated with fine wine.","t":"葡萄汁必须在橡木桶中**发酵**数周，然后才能形成上等葡萄酒特有的复杂风味。"},
"breeze":{"e":"A gentle breeze drifted through the open window, cooling the stuffy classroom and rustling the papers on every desk.","t":"一阵柔和的**微风**吹过敞开的窗户，给闷热的教室带来凉意，吹得每张桌上的纸张沙沙作响。"},
"potential":{"e":"Her coach recognized an extraordinary potential in the young gymnast, one that years of rigorous training would eventually reveal.","t":"教练在这位年轻的体操运动员身上发现了非凡的**潜力**，这种潜力会在多年严格训练后逐渐显现。"},
"anxious":{"e":"Waiting outside the operating room, the anxious parents paced the hallway and jumped at every sound from within.","t":"在手术室外等候时，**焦虑不安**的父母在走廊里来回踱步，室内传出的每一点声响都让他们心头一紧。"},
"spinning":{"e":"The spinning blades of the ceiling fan created a faint hum that lulled the tired toddler to sleep.","t":"天花板吊扇**旋转的**扇叶发出轻微的嗡鸣声，哄得疲惫的幼儿渐渐入睡。"},
"fasten":{"e":"Before the plane began its descent, the flight attendant reminded every passenger to fasten their seatbelt securely.","t":"飞机开始下降之前，乘务员提醒每位乘客把安全带**系牢**。"},
"playwright":{"e":"The struggling playwright rewrote her third act eleven times before the director finally agreed to stage the production.","t":"这位举步维艰的**剧作家**把第三幕重写了十一次，导演才终于同意将该剧搬上舞台。"},
"bicameral":{"e":"Because the new constitution established a bicameral legislature, every bill now needs approval from both the upper and lower chambers.","t":"由于新宪法确立了**两院制**立法机构，现在每项法案都需要上下两院共同批准才能通过。"},
"salmon":{"e":"Each autumn, thousands of salmon fight their way upstream against the current to spawn in the same gravel beds where they hatched.","t":"每年秋天，成千上万条**鲑鱼**都要逆流而上，回到它们孵化时的同一片砾石河床产卵。"},
"major":{"e":"Overfishing, rather than pollution, remains the major cause of the sharp decline in the region's coral reef fish populations.","t":"过度捕捞而非污染，仍是该地区珊瑚礁鱼类数量骤减的**主要**原因。"},
"elegant":{"e":"The mathematician admired the proof's elegant simplicity, since it solved the problem in just three concise, beautifully arranged steps.","t":"这位数学家欣赏这个证明的**简练优美**，因为它仅用三个简洁精巧的步骤就解决了问题。"},
"stardom":{"e":"After her debut film became an unexpected hit, the young actress rose swiftly to international stardom within a single year.","t":"她的处女作意外走红后，这位年轻女演员在短短一年内迅速跻身国际**巨星之列**。"},
"carnivore":{"e":"Unlike the gentle herbivores grazing nearby, the lion is a carnivore that survives almost entirely on the flesh of other animals.","t":"与附近吃草的温顺食草动物不同，狮子是一种几乎完全靠捕食其他动物的肉为生的**食肉动物**。"},
"expedition":{"e":"The scientists organized a grueling expedition across the Antarctic ice sheet to collect core samples no one had ever gathered.","t":"科学家们组织了一次横穿南极冰盖的艰苦**探险**，去采集从未有人取得过的冰芯样本。"},
"metropolitan":{"e":"Traffic in the metropolitan area grows worse every year as more commuters pour into the city from surrounding suburbs.","t":"随着越来越多的通勤者从周边郊区涌入城市，这个**大都市地区**的交通一年比一年糟糕。"},
"wit":{"e":"Her quick wit turned an awkward dinner party into an evening of laughter, as she countered every insult with a clever reply.","t":"她的**机智**把一场尴尬的晚宴变成了欢声笑语的夜晚，因为她总能用巧妙的回应化解每一句冒犯。"},
"beverage":{"e":"The café offers a wide variety of beverages, from strong espresso to iced herbal tea, brewed fresh throughout the day.","t":"这家咖啡馆提供种类繁多的**饮品**，从浓咖啡到冰镇花草茶，全天现做现供应。"},
"sediment":{"e":"Over thousands of years, layers of sediment settled at the bottom of the lake, gradually hardening into stratified rock.","t":"数千年来，**沉积物**层层堆积在湖底，逐渐硬化成层状岩石。"},
"marble":{"e":"The ancient temple's columns were cut from white marble, quarried from mountains hundreds of miles to the north.","t":"这座古老神庙的石柱是用白色**大理石**凿成的，石料采自几百英里外的北方山脉。"},
"edifice":{"e":"The courthouse stands as an imposing edifice downtown, its grand façade dominating the skyline for over a century.","t":"市政法院大楼矗立在市中心，是一座宏伟的**建筑**，其壮观的正面一个多世纪以来始终主导着天际线。"},
"constricted":{"e":"The patient's airway felt constricted, making each breath a shallow, labored struggle until the doctor administered medication.","t":"病人的气道感到**收缩**，每次呼吸都变得浅促而费力，直到医生用药才缓解。"},
"sidewalk":{"e":"Vendors lined the crowded sidewalk, selling roasted chestnuts and handmade jewelry to pedestrians hurrying past in the cold.","t":"小贩们沿着拥挤的**人行道**摆摊，向在寒风中匆匆走过的行人兜售烤栗子和手工首饰。"},
"absence":{"e":"Her absence from the meeting went unnoticed until someone finally asked why the project lead wasn't there.","t":"她在会议上的**缺席**一直没人注意到，直到有人终于问起为什么项目负责人不在场。"},
"commerce":{"e":"The new highway boosted regional commerce by cutting shipping times between the port and inland factories nearly in half.","t":"新建的高速公路使港口与内陆工厂之间的运输时间几乎缩短了一半，极大促进了地区**商业**发展。"},
"tundra":{"e":"Beneath the frozen tundra, a layer of permafrost keeps trees from ever taking root on this vast northern plain.","t":"在冰冻的**苔原**之下，一层永久冻土使这片广袤的北方平原上的树木始终无法扎根。"},
"bubble":{"e":"A single bubble rose slowly through the murky pond water before reaching the surface and vanishing with a faint pop.","t":"一个**气泡**缓缓穿过浑浊的池塘水面，最后轻轻一声破裂消失。"},
"abolition":{"e":"The abolition of slavery in the nineteenth century transformed the nation's economy and ignited decades of political conflict.","t":"十九世纪废除奴隶制的**废奴运动**改变了这个国家的经济，并引发了数十年的政治冲突。"},
"reliable":{"e":"Because the technician's diagnoses were always reliable, customers drove from neighboring towns just to have their cars serviced there.","t":"因为这位技师的诊断总是**可靠**，顾客们甚至从邻近城镇专程开车来这里修车。"},
"warehouse":{"e":"The company stores its unsold inventory in a massive warehouse on the edge of town until orders finally arrive.","t":"公司把未售出的库存存放在镇边一座巨大的**仓库**里，直到订单最终到来。"},
"remote":{"e":"The research station sits in such a remote corner of the mountains that supplies arrive only twice a year by helicopter.","t":"这个科考站位于群山中极为**偏僻**的角落，补给物资一年只能靠直升机运来两次。"},
"mature":{"e":"Despite being only sixteen, she handled the crisis with a mature calm that impressed even the seasoned adults around her.","t":"尽管只有十六岁，她处理危机时表现出的**成熟**沉着，连身边经验丰富的成年人都为之惊叹。"},
"authentic":{"e":"Every dumpling on the menu is prepared using authentic recipes passed down from the owner's grandmother in rural Sichuan.","t":"菜单上的每一道饺子都采用店主祖母在四川乡下传下来的**正宗**配方制作。"},
"meridian":{"e":"Navigators once relied on the prime meridian passing through Greenwich to calculate longitude for ships crossing the open ocean.","t":"航海者曾依靠经过格林尼治的本初**子午线**来计算远洋船只的经度。"},
"combustible":{"e":"Firefighters warned residents to keep combustible materials like gasoline and paint thinner far away from any open flame.","t":"消防员提醒居民，要把汽油和稀释剂等**易燃**物品远离任何明火存放。"},
"leap":{"e":"The company's profits took a sudden leap after the new product launched, nearly doubling within just two quarters.","t":"新产品上市后，公司利润出现了突然的**激增**，短短两个季度内几乎翻了一番。"},
"malnutrition":{"e":"Years of drought left entire villages struggling with malnutrition, as crops failed and food supplies dwindled to almost nothing.","t":"连年干旱使整个村庄都在与**营养不良**作斗争，因为庄稼歉收，食物供应几乎耗尽。"},
"trash":{"e":"Overflowing trash littered the streets after the holiday festival, forcing the city to send extra crews for cleanup.","t":"节日庆典结束后，满溢的**垃圾**散落街头，市政府不得不派额外的清洁队来处理。"},
"cookout":{"e":"Every Fourth of July, our neighbors host a backyard cookout with grilled corn, burgers, and homemade lemonade for everyone.","t":"每年七月四日，我们的邻居都会在后院举办**户外烧烤聚会**，准备烤玉米、汉堡和自制柠檬水招待大家。"},
"scruffy":{"e":"The scruffy stray dog wandering behind the diner had matted fur and hadn't been fed in what looked like days.","t":"在小餐馆后面游荡的那只**邋遢**流浪狗毛发打结，看起来已经好几天没吃东西了。"},
"threat":{"e":"Rising sea levels pose a growing threat to coastal cities, forcing engineers to design ever taller seawalls and levees.","t":"海平面上升对沿海城市构成日益严重的**威胁**，迫使工程师设计越来越高的海堤和堤坝。"},
"craft":{"e":"The old shoemaker spent forty years perfecting his craft, stitching each leather boot entirely by hand in his small shop.","t":"老鞋匠花了四十年时间打磨自己的**手艺**，在他的小店里完全靠手工缝制每一双皮靴。"},
"adverse":{"e":"The medication proved effective, though doctors warned that some patients might experience adverse reactions such as dizziness or fatigue.","t":"这种药物确实有效，不过医生提醒某些病人可能会出现头晕或疲劳等**不良**反应。"},
"layout":{"e":"The architect redesigned the office layout so that natural light would reach every desk throughout the entire workday.","t":"建筑师重新设计了办公室的**布局**，让每一张办公桌整个工作日都能照到自然光。"},
"cousin":{"e":"My cousin flew in from Beijing for the wedding, and we hadn't seen each other since we were both children.","t":"我的**表哥**从北京飞来参加婚礼，我们从小时候起就再也没见过面。"},
"porcelain":{"e":"The museum displays a delicate porcelain vase from the Ming dynasty, its blue glaze still remarkably vivid after centuries.","t":"博物馆展出一件精致的明代**瓷器**花瓶，历经数百年，蓝釉依然鲜艳夺目。"},
"decimal":{"e":"Students often struggle to convert fractions into decimal form until they practice dividing the numerator by the denominator repeatedly.","t":"学生们常常难以把分数换算成**小数**形式，直到反复练习用分子除以分母才熟练掌握。"},
"transit":{"e":"The city invested heavily in public transit, adding new subway lines to reduce traffic congestion during rush hour.","t":"这座城市大力投资公共**交通运输系统**，新增地铁线路以缓解高峰时段的交通拥堵。"},
"germ":{"e":"Washing your hands thoroughly before meals kills most of the germs that could otherwise make you seriously ill.","t":"饭前彻底洗手能杀死大部分可能让你严重生病的**细菌**。"},
"perfume":{"e":"She dabbed a few drops of floral perfume behind each ear before stepping out for the evening gala.","t":"她在赴晚宴前，在耳后轻轻抹了几滴花香**香水**。"},
"radius":{"e":"Anyone living within a five-mile radius of the chemical plant was ordered to evacuate before the storm made landfall.","t":"化工厂周围五英里**半径**范围内的所有居民都被要求在风暴登陆前撤离。"},
"compress":{"e":"The software can compress a two-hour video file down to a fraction of its original size without losing much quality.","t":"这款软件可以把一段两小时的视频文件**压缩**到原始大小的一小部分，而不会损失太多画质。"},
"innovate":{"e":"Small startups often innovate faster than large corporations because they aren't burdened by years of bureaucratic red tape.","t":"小型初创公司往往比大企业**创新**得更快，因为它们不必背负多年的官僚主义束缚。"},
"reliever":{"e":"Doctors recommended a simple pain reliever to ease her headache instead of prescribing anything stronger for now.","t":"医生建议先用一种简单的止痛**缓解药**来缓解她的头痛，暂时不开更强的药。"},
"load":{"e":"The truck driver checked each strap carefully before setting off, since an unbalanced load could tip the vehicle on sharp curves.","t":"卡车司机出发前仔细检查了每一根绑带，因为不平衡的**载重**可能会让车辆在急弯处翻倒。"},
"narrative":{"e":"The documentary weaves a compelling narrative from interviews with survivors, archival footage, and letters written during the war.","t":"这部纪录片通过幸存者的访谈、历史影像资料和战时书信，编织出一段引人入胜的**叙事**。"},
"reapply":{"e":"After his visa expired, he had to reapply for a new one before he could legally return to work.","t":"签证过期后，他不得不**重新申请**一份新签证，才能合法回去工作。"},
"hypocritical":{"e":"Critics called the senator hypocritical for preaching frugality while spending public funds on lavish dinners and private jets.","t":"批评者指责这位参议员**虚伪**，一边宣扬节俭，一边却用公款挥霍在奢华晚宴和私人飞机上。"},
"grid":{"e":"A sudden ice storm knocked out the regional power grid, leaving nearly two million households without electricity for days.","t":"一场突如其来的冰暴击垮了区域**电网**，导致近两百万户家庭连续数日断电。"},
"hypertext":{"e":"Clicking any underlined hypertext link on the page instantly jumps the reader to a related article or definition.","t":"点击页面上任何带下划线的**超文本**链接，都能立即跳转到相关文章或释义。"},
"indecipherable":{"e":"The doctor's handwriting on the prescription was so indecipherable that the pharmacist had to call the office to confirm it.","t":"医生处方单上的字迹**难以辨认**，药剂师不得不打电话到诊所去确认。"},
"optimize":{"e":"Engineers spent months tweaking the algorithm to optimize battery life without sacrificing the phone's processing speed.","t":"工程师们花了数月调整算法，力求在不牺牲手机处理速度的前提下**优化**电池续航。"},
"perceptual":{"e":"Optical illusions reveal how easily our perceptual system can be tricked into seeing motion or depth that isn't really there.","t":"视错觉揭示了我们的**知觉**系统多么容易被欺骗，误以为看到了并不存在的运动或深度。"},
"alienable":{"e":"Under the new contract, the patent rights are fully alienable, meaning the inventor can sell or transfer them to anyone.","t":"根据新合同，这些专利权是完全**可转让的**，也就是说发明人可以把它们卖给或转让给任何人。"},
"quantum":{"e":"Physicists have long debated how a single quantum of light can behave as both a particle and a wave.","t":"物理学家们长期争论，一个**量子**的光如何能同时表现出粒子和波的性质。"},
"retrieval":{"e":"The new indexing system dramatically speeds up document retrieval, letting analysts find any file within a few seconds.","t":"新的索引系统大幅提升了文档**检索**速度，让分析师能在几秒钟内找到任何文件。"},
"virtual":{"e":"Students attended the entire semester through a virtual classroom, logging into lectures from their laptops instead of a physical building.","t":"整个学期学生们都通过**虚拟**教室上课，用笔记本电脑登录听课，而不是去实体教室。"},
"sequential":{"e":"The instructions must be followed in strict sequential order, or the machine will fail to assemble the parts correctly.","t":"这些指令必须严格按**顺序**执行，否则机器就无法正确组装零件。"},
"interface":{"e":"Designers simplified the app's interface so that even elderly users could navigate the menus without any confusion.","t":"设计师简化了这款应用的**界面**，让即使是老年用户也能毫无困惑地浏览菜单。"},
"template":{"e":"Rather than designing each slide from scratch, she used a company template to keep every presentation visually consistent.","t":"她没有从零开始设计每张幻灯片，而是使用公司**模板**来保持每份演示文稿风格统一。"},
"synchronizer":{"e":"The engineer installed a synchronizer between the two engines so their rotors would spin at exactly the same speed.","t":"工程师在两台发动机之间安装了一个**同步装置**，使它们的转子能以完全相同的速度旋转。"},
"telecommunication":{"e":"Advances in telecommunication technology now let doctors in rural clinics consult specialists thousands of miles away in real time.","t":"**电信**技术的进步如今让偏远诊所的医生能实时与数千英里外的专家会诊。"},
"ventilation":{"e":"The basement lacked proper ventilation, so a musty smell lingered until workers installed fans to circulate fresh air.","t":"地下室缺乏良好的**通风**，霉味一直挥之不去，直到工人们安装风扇使空气流通。"},
"advisory":{"e":"The weather service issued an advisory warning urging residents near the coast to prepare for possible flooding overnight.","t":"气象局发布了一份**警示性**预警，敦促沿海居民为夜间可能发生的洪水做好准备。"},
"magnetic":{"e":"Iron filings scattered near the wire arranged themselves along invisible magnetic field lines the moment current flowed through it.","t":"电流一通过导线，散落在旁边的铁屑立刻沿着看不见的**磁场**线排列起来。"},
"static":{"e":"Shuffling over the carpet in wool socks built up enough static that she got a small shock touching the doorknob.","t":"穿着羊毛袜子在地毯上走动积累了不少**静电**，她一碰门把手就被电了一下。"},
"count":{"e":"In competitive debate, how persuasively you present an argument counts just as much as the facts backing it up.","t":"在竞技辩论中，你论证的说服力和支撑它的事实一样**重要**。"},
"tinker":{"e":"On weekends, my grandfather liked to tinker with old radios in the garage, coaxing broken ones back to life.","t":"周末，我祖父喜欢在车库里**捣鼓**修理旧收音机，把坏掉的收音机重新修好。"},
"jumble":{"e":"The movers accidentally jumbled the labeled boxes together, so we spent an entire afternoon sorting kitchenware from books again.","t":"搬家工人不小心把贴了标签的箱子**混杂**在了一起，我们花了一整个下午重新把厨具和书分开。"},
"brittle":{"e":"After decades in the attic, the old newspaper pages had grown so brittle that they crumbled at the slightest touch.","t":"在阁楼放了几十年后，这些旧报纸变得非常**脆弱**，轻轻一碰就碎了。"},
"insulate":{"e":"Thick layers of foam insulate the walls of the cabin, keeping it warm even when temperatures drop far below freezing.","t":"厚厚的泡沫层**隔绝**了小屋的墙壁，即使气温降到冰点以下很多，屋内依然温暖。"},
"favor":{"e":"She asked her neighbor for a small favor, hoping he could watch her cat while she traveled abroad.","t":"她请邻居帮个小**忙**，希望他能在她出国旅行期间照看一下她的猫。"},
"segregate":{"e":"The old policy used to segregate students by neighborhood, sending wealthier children to better-funded schools on the other side of the district.","t":"过去的政策曾按居住街区将学生**隔离**开来，把家境富裕的孩子送到学区另一端资金更充足的学校。"},
"dimension":{"e":"Losing his job added a financial dimension to the family's crisis that no one had anticipated when his illness began.","t":"失业给这个家庭的危机增添了一个谁也没有预料到的经济**方面**，而这一切始于他患病之时。"},
"nonverbal":{"e":"Much of human communication is nonverbal, conveyed through facial expressions, posture, and subtle shifts in tone rather than words.","t":"人类交流中很大一部分是**非语言的**，通过面部表情、姿态和语调的细微变化而非言语传递。"},
"barrier":{"e":"Language remained the biggest barrier during her first year abroad, until months of daily practice finally built her confidence.","t":"在国外生活的第一年，语言一直是最大的**障碍**，直到数月的日常练习才终于建立起她的信心。"},
"throw":{"e":"The sudden collapse of the bridge threw the entire evening drive into complete chaos for thousands of drivers.","t":"大桥突然坍塌，让数千名司机的傍晚出行陷入一片**混乱**。"},
"shipwright":{"e":"The shipwright spent three months hand-fitting the wooden planks that would form the schooner's curved hull.","t":"这位**造船工匠**花了三个月时间手工拼装木板，打造出纵帆船那弯曲的船体。"},
"automatic":{"e":"Modern cars come equipped with automatic braking systems that react faster than any human driver possibly could.","t":"现代汽车配备了**自动**刹车系统，其反应速度比任何人类司机都要快。"},
"naturalist":{"e":"As a young naturalist, Darwin filled notebook after notebook with sketches of beetles, birds, and unfamiliar plants he collected.","t":"作为一名年轻的**博物学家**，达尔文在一本又一本笔记里画满了他采集到的甲虫、鸟类和陌生植物的素描。"},
"orbit":{"e":"Engineers calculated the precise thrust needed to place the satellite into a stable orbit around the Earth.","t":"工程师计算出了精确的推力，以便把卫星送入围绕地球运行的稳定**轨道**。"},
"kiln":{"e":"The potter fired her clay bowls in a wood-burning kiln for nearly twelve hours before they hardened completely.","t":"陶艺师把她的陶碗放进烧柴的**窑**里烧了将近十二个小时才完全变硬。"},
"proofread":{"e":"Before submitting her thesis, she asked two classmates to proofread every chapter for grammar mistakes and awkward phrasing.","t":"提交论文前，她请两位同学帮忙**校对**每一章，检查语法错误和生硬的措辞。"},
"arithmetic":{"e":"Long before calculators existed, merchants relied on simple arithmetic to tally sales and balance their accounts each evening.","t":"在计算器出现之前，商人们全靠简单的**算术**来统计销售额，每晚核对账目。"},
"landscape":{"e":"From the mountain's summit, hikers could see the entire landscape stretching below, dotted with lakes and small farming villages.","t":"站在山顶，徒步者能看到脚下整片**景色**延展开去，点缀着湖泊和小小的农业村落。"},
"doctrine":{"e":"The professor traced how a single religious doctrine splintered into dozens of competing sects over three centuries.","t":"教授追溯了一个宗教**教义**如何在三个世纪里分裂成数十个相互竞争的教派。"},
"suppose":{"e":"Scientists initially supposed that the strange fossil belonged to a small dinosaur, until further analysis proved otherwise.","t":"科学家们起初**推测**这块奇特的化石属于一种小型恐龙，直到进一步分析证明并非如此。"},
"matrimony":{"e":"After eight years of dating, they finally entered into matrimony surrounded by family and friends in a small chapel.","t":"恋爱八年后，他们终于在一座小教堂里，在亲友的见证下步入了**婚姻**。"},
"adapt":{"e":"Desert foxes have adapted remarkably well to extreme heat, developing enormous ears that release excess body warmth.","t":"沙漠狐狸已经极好地**适应**了极端高温，进化出巨大的耳朵来散发多余的体热。"},
"span":{"e":"The new suspension bridge has a span of nearly two kilometers, connecting the island directly to the mainland.","t":"这座新建的悬索桥**跨度**将近两公里，把这座岛屿与大陆直接连接起来。"},
"veto":{"e":"The president threatened to veto the bill unless lawmakers removed the controversial tax provision buried in its final pages.","t":"总统威胁要**否决**这项法案，除非议员们删除藏在最后几页中那条有争议的税收条款。"},
"mechanic":{"e":"The mechanic spent all afternoon replacing the car's worn brake pads before finally giving it back to its owner.","t":"这位**机修工**花了整个下午更换汽车磨损的刹车片，才终于把车还给车主。"},
"glimpse":{"e":"Through a gap in the curtains, she caught a brief glimpse of the stranger standing motionless outside on the street.","t":"透过窗帘的缝隙，她**瞥见**那个陌生人一动不动地站在街上。"},
"claim":{"e":"The company denied any wrongdoing, even as former employees continued to claim that safety reports had been deliberately falsified.","t":"尽管前员工不断**声称**安全报告被蓄意篡改，公司仍否认存在任何不当行为。"},
"arouse":{"e":"The mysterious disappearance of the painting aroused suspicion among museum staff, who began quietly questioning one another.","t":"那幅画的神秘失踪**引起**了博物馆工作人员的怀疑，他们开始悄悄地相互盘问。"},
"landmass":{"e":"Geologists believe this ancient landmass once connected present-day Africa and South America before continental drift pulled them apart.","t":"地质学家认为，这块古老的**大陆**曾经把如今的非洲和南美洲连在一起，后来大陆漂移才将它们分开。"},
"treadmill":{"e":"Rain kept her indoors, so she ran five miles on the treadmill instead of following her usual outdoor route.","t":"下雨天她只能待在室内，于是在**跑步机**上跑了五英里，没能走平常的户外路线。"},
"ecosystem":{"e":"Removing a single predator species can push an entire ecosystem out of balance within just a few short years.","t":"移除单一捕食物种就可能在短短几年内打破整个**生态系统**的平衡。"},
"opal":{"e":"The ring's centerpiece was a fiery opal that shifted color from blue to green depending on the light.","t":"这枚戒指的主石是一颗火彩十足的**蛋白石**，颜色会随光线在蓝绿之间变化。"},
"centric":{"e":"Critics argue the curriculum is too Western-centric, largely ignoring the history and literature of Asia and Africa.","t":"批评者认为这套课程过于**以西方为中心**，很大程度上忽视了亚洲和非洲的历史与文学。"},
"attorney":{"e":"Before signing anything, she hired an attorney to review the contract and explain every clause in plain language.","t":"在签署任何文件之前，她请了一位**律师**来审阅合同，并用通俗的语言解释每一条条款。"},
"idiom":{"e":"Learning that 'kick the bucket' is an idiom for dying saved her from a very confusing conversation at the funeral.","t":"得知\"kick the bucket\"是表示\"死亡\"的**习语**，让她在葬礼上避免了一场十分尴尬的误会。"},
"fort":{"e":"Soldiers built a wooden fort along the river to guard the settlement from raids during the harsh winter months.","t":"士兵们沿河修建了一座木制**要塞**，在严冬的几个月里保护定居点免遭袭击。"},
"immune":{"e":"Regular exposure to mild pathogens as a child can leave the immune system better equipped to fight infections later.","t":"儿童时期经常接触温和的病原体，可以让**免疫**系统日后更有能力对抗感染。"},
"quilt":{"e":"Her grandmother taught her to quilt scraps of old fabric into a warm blanket over several patient winter evenings.","t":"祖母在几个耐心的冬夜里教她把旧布头**缝制**成一条暖和的被子。"},
"coincide":{"e":"Her graduation happened to coincide with her brother's wedding, forcing the family to split into two separate celebrations.","t":"她的毕业典礼碰巧和哥哥的婚礼**同时发生**，一家人不得不分头参加两场庆祝活动。"},
"carve":{"e":"The sculptor spent nearly six months patiently carving a lifelike falcon from a single enormous block of walnut wood.","t":"这位雕塑家花了将近六个月时间，耐心地用一整块巨大的胡桃木**雕刻**出一只栩栩如生的猎鹰。"},
"solid":{"e":"Unlike the flimsy plastic chairs, this one was built from solid oak and could support far more weight.","t":"与那些不结实的塑料椅子不同，这把椅子是用**坚实**的橡木打造的，能承受更大的重量。"},
"ranch":{"e":"Her uncle runs a sprawling cattle ranch in Texas, where hundreds of animals graze over thousands of open acres.","t":"她叔叔在得克萨斯州经营着一座辽阔的**牧场**，数百头牲畜在数千英亩的开阔土地上吃草。"},
"sociable":{"e":"Even at crowded parties full of strangers, he remained effortlessly sociable, chatting easily with anyone who approached him.","t":"即使在满是陌生人的拥挤派对上，他依然轻松**合群**，能自如地和任何靠近他的人聊天。"},
"across":{"e":"The old ferry carried passengers across the river every thirty minutes, long before the new bridge was ever built.","t":"在新桥建成之前，这艘老渡轮每三十分钟就载着乘客**渡过**河流。"},
"observe":{"e":"Researchers spent weeks quietly observing the wolves from a distance, recording every detail of their hunting behavior.","t":"研究人员花了数周时间在远处安静地**观察**这群狼，记录下它们捕猎行为的每一个细节。"},
"commute":{"e":"Rather than commute two hours each way, she finally decided to move into an apartment near her office downtown.","t":"与其每天单程**通勤**两小时，她最终决定搬到市中心办公室附近的公寓住。"},
"episode":{"e":"The show's finale episode left millions of viewers stunned, wrapping up a storyline that had unfolded over six seasons.","t":"这部剧的最后一**集**让数百万观众目瞪口呆，为一条延续了六季的故事线画下句点。"},
"caribou":{"e":"Every autumn, massive herds of caribou migrate hundreds of miles southward in search of food before winter sets in.","t":"每年秋天，成群的**北美驯鹿**都会向南迁徙数百英里去寻找食物，为过冬做准备。"},
"source":{"e":"Investigators eventually traced the contamination to a single source: a cracked pipe leaking chemicals into the groundwater.","t":"调查人员最终把污染追溯到一个单一**来源**：一根破裂的管道正把化学物质渗入地下水。"},
"campaign":{"e":"She campaigned tirelessly for months, knocking on doors throughout the district to introduce herself to every voter.","t":"她坚持不懈地**竞选**了数月，挨家挨户走遍整个选区向每一位选民自我介绍。"},
"musical":{"e":"Even as a toddler, she showed remarkable musical talent, picking out melodies on the piano by ear alone.","t":"她还是个蹒跚学步的孩子时就展现出非凡的**音乐**天赋，仅凭耳朵就能在钢琴上弹出旋律。"},
"emphasize":{"e":"The coach constantly emphasized teamwork over individual glory, insisting that no single player could win a championship alone.","t":"教练一直**强调**团队合作胜过个人荣誉，坚持认为没有哪个球员能独自赢得冠军。"},
"cater":{"e":"A local restaurant agreed to cater the wedding reception, preparing enough food for over two hundred guests.","t":"一家本地餐厅答应为婚宴**提供餐饮服务**，准备足够两百多位宾客享用的食物。"},
"fuse":{"e":"The chef's new dish fuses traditional Sichuan spices with delicate French techniques to create something entirely original.","t":"这位厨师的新菜将传统川味香料与精致的法式烹饪技法**融合**在一起，创造出全新的风味。"},
"involve":{"e":"The investigation eventually involved three separate government agencies, each examining a different piece of the financial fraud.","t":"这项调查最终**牵涉**到三个不同的政府机构，各自调查这起金融欺诈案的不同环节。"},
"brew":{"e":"Dark clouds gathered on the horizon, and everyone on the porch sensed that a serious storm was brewing.","t":"地平线上乌云聚集，门廊上的每个人都感觉到一场大风暴正在**酝酿**。"},
"cast":{"e":"Workers poured molten bronze into molds to cast the statue's massive head in a single continuous process.","t":"工人们把熔化的青铜倒入模具，一次连续的工序就**浇铸**出雕像巨大的头部。"},
"surrender":{"e":"After weeks under siege with no food or reinforcements, the garrison finally had no choice but to surrender.","t":"在围困中挨了数周，既无粮草又无援军，守军最终别无选择只能**投降**。"},
"foremost":{"e":"Dr. Chen is widely regarded as the foremost expert on coral reef restoration, having published over a hundred papers.","t":"陈博士被广泛认为是珊瑚礁修复领域**最杰出**的专家，已发表了上百篇论文。"},
"drill":{"e":"Workers had to drill through nearly a meter of dense granite before reaching the underground water pipe.","t":"工人们必须**钻穿**将近一米厚的致密花岗岩，才能接触到地下水管。"},
"confront":{"e":"She finally decided to confront her business partner directly about the missing funds instead of avoiding the conversation any longer.","t":"她终于决定直接**质问**生意伙伴关于那笔失踪资金的事，而不再回避这个话题。"},
"era":{"e":"The invention of the printing press ushered in a new era of widespread literacy throughout medieval Europe.","t":"印刷机的发明开启了中世纪欧洲识字率普及的新**时代**。"},
"glamorous":{"e":"Behind the glamorous red-carpet photos lies years of grueling rehearsals, rejected auditions, and financial struggle most fans never see.","t":"在**光鲜亮丽**的红毯照片背后，是大多数粉丝从未见过的多年艰苦排练、屡次落选的试镜和经济上的挣扎。"},
"stark":{"e":"The stark contrast between the wealthy downtown skyline and the crumbling neighborhoods nearby shocked every first-time visitor.","t":"富裕的市中心天际线与附近破败街区之间**鲜明**的对比，震撼了每一位初次到访的游客。"},
"apprise":{"e":"The lawyer promptly apprised her client of the new evidence before the trial resumed the following morning.","t":"律师在庭审于次日早晨恢复之前，及时**告知**了委托人这项新证据。"},
"bait":{"e":"The fisherman threaded a live worm onto his hook as bait, hoping to lure a trout from the depths.","t":"渔夫把一条活虫穿在鱼钩上当**诱饵**，希望能从深水里钓上一条鳟鱼。"},
"stylish":{"e":"She walked into the interview wearing a stylish tailored blazer that immediately set her apart from other candidates.","t":"她穿着一件**时髦**的定制西装外套走进面试现场，立刻让自己在其他候选人中脱颖而出。"},
"brisk":{"e":"A brisk walk through the park each morning left her feeling energized and ready to tackle the workday ahead.","t":"每天早晨在公园里**轻快**地走一走，让她感到精力充沛，准备好迎接一天的工作。"},
"intact":{"e":"Despite the earthquake leveling nearby buildings, the old wooden temple somehow remained completely intact, without even a cracked beam.","t":"尽管地震夷平了附近的建筑，这座古老的木质寺庙却奇迹般地保持**完好无损**，连一根横梁都没裂开。"},
"clasp":{"e":"The old leather satchel's brass clasp had rusted shut, so she had to pry it open with a screwdriver.","t":"这个旧皮包的黄铜**搭扣**已经锈死了，她只好用螺丝刀把它撬开。"},
"soda":{"e":"Bakers add a pinch of baking soda to the batter, which reacts with the acid to make the cake rise.","t":"烘焙师在面糊里加入一小撮**小苏打**，它与酸发生反应能让蛋糕膨发起来。"},
"clip":{"e":"Every Saturday morning, the gardener clips the hedges into neat rectangular shapes along the front of the estate.","t":"每周六早晨，园丁都会把庄园前的树篱**修剪**成整齐的矩形。"},
"cramp":{"e":"A sudden cramp in her calf forced the runner to stop just two miles short of finishing the marathon.","t":"小腿突然一阵**抽筋**，迫使这名跑者在距离马拉松终点仅两英里处停了下来。"},
"expenditure":{"e":"The town board approved a massive expenditure on new school buildings despite objections from several budget-conscious residents.","t":"尽管几位精打细算的居民提出反对，镇委员会仍批准了新校舍建设的巨额**支出**。"},
"reflection":{"e":"She caught her own reflection in the shop window and barely recognized how much she had changed over the years.","t":"她在商店橱窗里瞥见自己的**倒影**，几乎认不出这些年自己变化有多大。"},
"cuisine":{"e":"The restaurant specializes in regional Sichuan cuisine, famous for its bold use of chili peppers and numbing peppercorns.","t":"这家餐厅专营四川地方**菜系**，以大胆使用辣椒和麻味花椒而闻名。"},
"domicile":{"e":"The court required proof of a permanent domicile within the state before it would grant her a voting registration.","t":"法院要求她提供在该州拥有固定**住所**的证明，才会批准她的选民登记。"},
"loose":{"e":"One of the bicycle's pedals had come loose during the ride, wobbling dangerously with every downward push.","t":"骑行途中自行车的一只脚踏板**松动**了，每蹬一下都危险地晃动。"},
"embark":{"e":"Passengers began to embark on the cruise ship at dawn, dragging suitcases up the long boarding ramp.","t":"乘客们在黎明时分开始**登上**游轮，拖着行李箱走上长长的登船坡道。"},
"slog":{"e":"Exhausted and soaked to the bone, the hikers had to slog through knee-deep mud for the final three miles.","t":"精疲力竭又浑身湿透的徒步者们，最后三英里只能在没过膝盖的泥浆中**艰难跋涉**。"},
"translucent":{"e":"Sunlight filtered softly through the translucent curtains, casting a warm, hazy glow over the otherwise empty room.","t":"阳光透过**半透明**的窗帘柔和地洒进来，给这间原本空荡的房间镀上一层朦胧暖光。"},
"imaginary":{"e":"As a child, she invented an imaginary friend who accompanied her everywhere and vanished the moment anyone else appeared.","t":"她小时候曾幻想出一个**假想**朋友，这个朋友无处不在地陪着她，一旦有别人出现就会消失。"},
"brilliant":{"e":"Her brilliant solution to the engineering problem saved the company millions of dollars in redesign costs.","t":"她为这个工程难题提出的**卓越**解决方案，为公司节省了数百万美元的重新设计成本。"},
"cohesion":{"e":"Shared hardship during the long voyage forged a remarkable sense of cohesion among crew members who had once been strangers.","t":"漫长航行中共同经历的艰辛，在曾经素不相识的船员之间锻造出一种非凡的**凝聚力**。"},
"Pueblo":{"e":"Archaeologists carefully excavated the ancient Pueblo dwellings built into the cliffside, uncovering pottery left behind centuries ago.","t":"考古学家小心翼翼地发掘了依山而建的古老**普韦布洛人**居所，出土了数百年前遗留下来的陶器。"},
"belt":{"e":"Farmers in the Midwest's corn belt watched anxiously as the drought threatened to wipe out this year's entire harvest.","t":"中西部玉米**产区**的农民们焦虑地看着干旱威胁要摧毁今年的全部收成。"},
"council":{"e":"The city council voted unanimously to build a new public library in the neighborhood that needed it most.","t":"市**议会**一致投票通过，要在最需要的社区新建一座公共图书馆。"},
"license":{"e":"She studied for months before finally passing the rigorous exam required to earn her professional nursing license.","t":"她学习了数月，终于通过了严格的考试，取得了专业护士**执照**。"},
"silicon":{"e":"Modern computer chips depend on thin wafers of silicon, a common element refined from ordinary sand.","t":"现代电脑芯片依赖薄薄的**硅**晶圆，这种常见元素是从普通沙子中提炼出来的。"},
"formal":{"e":"The invitation specified formal attire, so guests arrived in tuxedos and floor-length evening gowns for the gala.","t":"请柬上注明要穿**正式**礼服，于是宾客们都穿着燕尾服和曳地晚礼服出席这场盛会。"},
"humidity":{"e":"The unbearable humidity in the rainforest left our clothes damp and clinging to our skin within minutes of arrival.","t":"雨林里令人难以忍受的**湿度**，让我们的衣服到达几分钟内就变得潮湿贴身。"},
"journal":{"e":"The professor's groundbreaking research was finally published in a prestigious medical journal read by physicians all over the world.","t":"这位教授的开创性研究终于发表在一份权威医学**期刊**上，受到全世界医生的关注。"},
"territory":{"e":"Wolves fiercely defend their territory, marking its boundaries with scent and chasing off any rival pack that wanders too close.","t":"狼群会凶猛地捍卫自己的**领地**，用气味标记边界，并驱赶任何靠得太近的对手狼群。"},
"sneaker":{"e":"He laced up his worn-out sneakers and jogged along the riverbank before the sun had even fully risen.","t":"他系好那双磨旧的**运动鞋**，趁太阳还没完全升起就沿着河岸慢跑起来。"},
"retire":{"e":"After forty years teaching high school chemistry, Mr. Alvarez finally decided to retire and spend his days gardening.","t":"教了四十年高中化学之后，阿尔瓦雷斯先生终于决定**退休**，把日子花在园艺上。"},
"bustle":{"e":"Away from the bustle of the crowded market, the temple courtyard offered a rare pocket of complete silence.","t":"远离拥挤集市的**喧嚣**，这座寺庙的庭院提供了一片难得的宁静之地。"},
"civil":{"e":"The dispute between the two neighbors over the fence was settled in civil court rather than escalating into a criminal case.","t":"两邻居因篱笆产生的纠纷是在**民事**法庭解决的，而没有升级成刑事案件。"},
"mannerism":{"e":"The actor was famous for a distinctive mannerism, tilting his head slightly whenever he delivered a punchline.","t":"这位演员以一个独特的**怪癖**而出名：每次说出笑点台词时都会微微偏头。"},
"bark":{"e":"The tree's rough, gray bark peeled away in thin strips wherever the woodpecker had pecked small holes.","t":"每当啄木鸟啄出小洞的地方，这棵树粗糙的灰色**树皮**就会一片片剥落。"},
"spice":{"e":"The market stall overflowed with fragrant spices, from crimson paprika to golden turmeric piled in wooden bowls.","t":"集市摊位上摆满了芬芳的**香料**，从鲜红的红椒粉到金黄的姜黄粉，堆满了木碗。"},
"crown":{"e":"The queen's crown, studded with rubies and sapphires, had been passed down through eleven generations of the royal family.","t":"女王的**王冠**镶满红宝石和蓝宝石，已经在王室传承了十一代。"},
"shelter":{"e":"When the tornado sirens sounded, the entire family rushed to the basement, the only reliable shelter in the house.","t":"龙卷风警报响起时，全家人都冲向地下室，那是屋子里唯一可靠的**避难所**。"},
"aspect":{"e":"Every aspect of the wedding, from the flowers to the seating chart, had been planned months in advance.","t":"婚礼的每一个**方面**，从鲜花到座位安排，都提前几个月就计划好了。"},
"sow":{"e":"Farmers traditionally sow wheat seeds in early autumn so the crop can establish roots before the first frost arrives.","t":"农民们传统上会在初秋**播种**小麦，好让作物在第一场霜冻来临前扎根生长。"},
"reside":{"e":"Most of the professor's extended family still resides in the small coastal village where she herself was born.","t":"这位教授的大部分远亲仍然**居住**在她自己出生的那个海边小村庄。"},
"amplify":{"e":"The microphone amplifies even the faintest whisper on stage so that everyone in the back row can hear clearly.","t":"麦克风能把台上最轻微的耳语都**放大**，让坐在最后一排的人也能听得清清楚楚。"},
"cosmos":{"e":"Ancient astronomers gazed up at the night sky, trying to make sense of the vast, mysterious cosmos surrounding them.","t":"古代天文学家仰望夜空，试图理解围绕着他们的这个浩瀚神秘的**宇宙**。"},
"laureate":{"e":"The Nobel laureate spent her acceptance speech thanking the mentors who had guided her through decades of failed experiments.","t":"这位诺贝尔奖**得主**在她的获奖感言中，感谢了指导她走过数十年失败实验的导师们。"},
"conscious":{"e":"She grew increasingly conscious of the awkward silence filling the room and quickly changed the subject to something lighter.","t":"她越来越**意识到**房间里弥漫的尴尬沉默，赶紧把话题转向了更轻松的内容。"},
"unaided":{"e":"Remarkably, the toddler climbed the entire staircase unaided, refusing any hand her worried parents tried to offer.","t":"这个蹒跚学步的孩子**无需帮助**就爬完了整段楼梯，拒绝了她担心的父母想要伸出的手。"},
"optional":{"e":"Attendance at the review session is optional, though the professor strongly recommended it before the final exam.","t":"复习课的出席是**自愿**的，不过教授强烈建议大家在期末考试前参加。"},
"admission":{"e":"The museum waived its usual admission fee for the weekend, drawing crowds far larger than the staff had expected.","t":"博物馆在周末免除了平常的**入场**费，吸引了比工作人员预期多得多的人群。"},
"dolphin":{"e":"A pod of dolphins followed alongside the boat for nearly a mile, leaping playfully through the ship's wake.","t":"一群**海豚**跟着船游了将近一英里，在船的尾流中欢快地跳跃。"},
"spill":{"e":"The toddler reached over the table and knocked over his cup, letting milk spill all over the freshly ironed tablecloth.","t":"小孩伸手越过桌子碰倒了杯子，牛奶**溢出**弄脏了刚熨好的桌布。"},
"phenomenon":{"e":"Bioluminescence, the phenomenon that makes certain jellyfish glow in the dark, still puzzles scientists studying life in the deep sea.","t":"生物发光是一种让某些水母在黑暗中发光的**现象**，至今仍让研究深海生命的科学家们感到困惑。"},
"counseling":{"e":"After the accident, the school offered free counseling to any student who wanted to talk through the trauma.","t":"事故发生后，学校为任何想要倾诉这段创伤的学生提供免费**心理辅导**。"},
"nickel":{"e":"Stainless steel owes its resistance to rust largely to the chromium and nickel mixed into the alloy.","t":"不锈钢之所以能抗锈，很大程度上要归功于合金中混入的铬和**镍**。"},
"mine":{"e":"Companies have mined this mountain for copper since the nineteenth century, leaving behind a maze of abandoned tunnels.","t":"自十九世纪以来，各家公司一直在这座山**开采**铜矿，留下了一座座废弃隧道组成的迷宫。"},
"nauseous":{"e":"The turbulent flight left several passengers feeling nauseous, clutching their stomachs as the plane bounced through the storm.","t":"颠簸的航班让好几位乘客感到**恶心**，飞机在风暴中颠簸时他们紧紧捂着肚子。"},
"hoard":{"e":"Fearing another shortage, the elderly couple began to hoard canned goods and bottled water in their basement.","t":"担心再次出现短缺，这对老夫妇开始在地下室**囤积**罐头食品和瓶装水。"},
"parallel":{"e":"The two rivers run parallel to each other for nearly a hundred miles before finally converging near the coast.","t":"这两条河流几乎**平行**地流淌上百英里，才最终在海岸附近汇合。"},
"litter":{"e":"The stray cat surprised everyone by giving birth to a litter of five kittens beneath the porch steps.","t":"那只流浪猫让所有人大吃一惊，在门廊台阶下生了**一窝**五只小猫。"},
"underlying":{"e":"Doctors suspected that an underlying medical condition, rather than stress alone, was causing her chronic fatigue.","t":"医生怀疑导致她慢性疲劳的是某种**潜在的**疾病，而不仅仅是压力。"},
"symbol":{"e":"In many cultures, the dove has long served as a symbol of peace and reconciliation after conflict.","t":"在许多文化中，鸽子长期以来都是冲突过后和平与和解的**象征**。"},
"diet":{"e":"A balanced diet rich in vegetables and lean protein helped the athlete recover faster between training sessions.","t":"富含蔬菜和瘦肉蛋白的均衡**饮食**帮助这位运动员在训练间隙更快恢复体力。"},
"positive":{"e":"Her relentlessly positive attitude during the budget crisis reassured the entire team and kept morale from collapsing.","t":"预算危机期间她始终**积极**的态度安抚了整个团队，避免了士气的彻底崩溃。"},
"lumber":{"e":"The exhausted bear began to lumber slowly back toward its den as the season's first snow started falling.","t":"疲惫的熊开始**笨拙地**慢慢走回它的洞穴，这时今年第一场雪开始飘落。"},
"fervor":{"e":"The young missionary preached with such fervor that even the most skeptical villagers paused to listen closely.","t":"这位年轻的传教士布道时**热情**洋溢，就连最怀疑的村民也停下来仔细聆听。"},
"affection":{"e":"Over the years, the old dog's quiet affection for its owner never wavered, even as its health declined.","t":"多年来，这只老狗对主人默默的**喜爱**从未动摇，即使它的健康每况愈下。"},
"upheaval":{"e":"The sudden political upheaval forced thousands of families to abandon their homes and flee across the border.","t":"突如其来的政治**剧变**迫使成千上万的家庭抛弃家园，逃往边境对面。"},
"simplify":{"e":"The new software update was designed to simplify the tedious, error-prone process of filing quarterly tax reports.","t":"这次软件更新旨在**简化**繁琐且容易出错的季度报税流程。"},
"dozen":{"e":"She ordered a dozen fresh bagels from the corner bakery to share with her coworkers on Friday morning.","t":"她从街角面包店订了**一打**新鲜百吉饼，周五早上和同事们分享。"},
"realtor":{"e":"Before listing their house, the young couple hired an experienced realtor who knew the neighborhood market thoroughly.","t":"在挂牌卖房之前，这对年轻夫妇聘请了一位十分熟悉当地市场的**房地产经纪人**。"},
"bacteria":{"e":"Harmful bacteria multiplied rapidly inside the undercooked chicken that had been left sitting at room temperature overnight.","t":"有害**细菌**在那块没煮熟、整夜放在室温下的鸡肉里迅速繁殖。"},
"aerobics":{"e":"To improve her cardiovascular endurance before the marathon, she started taking aerobics classes three mornings a week.","t":"为了在马拉松赛前提高心肺耐力，她开始每周三个早晨上**有氧运动**课。"},
"filament":{"e":"When the fragile filament inside the antique bulb finally snapped, the entire room went suddenly and completely dark.","t":"当那只老式灯泡里脆弱的**灯丝**终于断掉时，整个房间瞬间完全黑了下来。"},
"gossip":{"e":"Malicious gossip about the new manager spread through the office before she had even unpacked her desk.","t":"关于新经理的恶意**流言蜚语**在她还没整理好办公桌之前就已传遍了整个办公室。"},
"hitch":{"e":"Stranded after missing the last bus, the hikers decided to hitch a ride from a passing farmer.","t":"错过末班车后被困在路边，徒步旅行者决定向一位路过的农民**搭便车**。"},
"grump":{"e":"Every Monday morning, my uncle would grump about the traffic before he had even finished his coffee.","t":"每周一早上，我叔叔还没喝完咖啡就开始**发牢骚**抱怨交通。"},
"indigent":{"e":"The charity clinic provides free medical care to indigent families who cannot afford basic health insurance.","t":"这家慈善诊所为负担不起基本医疗保险的**贫困**家庭提供免费医疗服务。"},
"lighthearted":{"e":"Despite the looming deadline, she kept the meeting lighthearted with jokes that eased everyone's growing tension.","t":"尽管截止日期迫在眉睫，她还是用笑话让会议保持**愉快**，缓解了大家日益增长的紧张情绪。"},
"necessitate":{"e":"The factory's rapid expansion will necessitate hiring dozens of additional workers before the holiday season begins.","t":"工厂的快速扩张将**需要**在假日季开始前雇佣数十名额外工人。"},
"pedestrian":{"e":"The city installed brighter crosswalk signals after a pedestrian was nearly struck at that busy intersection.","t":"在一名**行人**在那个繁忙路口险些被撞后，市政府安装了更亮的人行横道信号灯。"},
"hull":{"e":"Barnacles had encrusted the ship's hull so thickly that the crew scraped for days before repainting it.","t":"藤壶把船的**船体**覆盖得如此之厚，船员们刮了好几天才重新刷漆。"},
"taut":{"e":"The sailors pulled the rope taut before the storm hit, making sure the mast wouldn't snap loose.","t":"水手们在暴风雨来临前把绳子拉得**绷紧**，确保桅杆不会松脱折断。"},
"sleigh":{"e":"Bundled in thick blankets, the children rode a horse-drawn sleigh across the frozen countryside at dusk.","t":"孩子们裹着厚厚的毯子，黄昏时分乘着马拉的**雪橇**穿过冰封的乡野。"},
"transport":{"e":"The city's public transport system was overwhelmed when thousands of commuters tried to leave downtown simultaneously.","t":"当数千名通勤者同时试图离开市中心时，这座城市的公共**运输**系统不堪重负。"},
"nutrition":{"e":"Proper nutrition during early childhood has a lasting effect on a person's cognitive development and immune strength.","t":"幼儿时期充足的**营养**会对一个人的认知发育和免疫力产生持久影响。"},
"daylight":{"e":"We hiked faster once we realized barely two hours of daylight remained before the mountain trail grew dangerous.","t":"我们意识到只剩不到两个小时的**日光**，山路很快会变得危险，于是加快了脚步。"},
"gilding":{"e":"Centuries of handling had worn away most of the gilding on the cathedral's ornate wooden altar.","t":"几个世纪的触摸磨掉了大教堂华丽木制祭坛上大部分的**镀金层**。"},
"intoxication":{"e":"The driver was arrested for intoxication after swerving across three lanes on the highway at midnight.","t":"这名司机因午夜在高速公路上连续跨越三条车道而被以**醉酒**驾驶罪名逮捕。"},
"rotate":{"e":"Engineers designed the satellite's solar panels to rotate slowly, tracking the sun as the spacecraft orbited Earth.","t":"工程师设计卫星的太阳能板能缓慢**旋转**，在航天器绕地球运行时追踪太阳。"},
"spike":{"e":"Analysts attributed the sudden spike in gasoline prices to unexpected disruptions at three major regional refineries.","t":"分析师将汽油价格的突然**猛增**归因于三家主要炼油厂出现的意外中断。"},
"locality":{"e":"The museum's new exhibit traces how each artifact's locality influenced the materials early craftsmen chose to use.","t":"博物馆的新展览追溯了每件文物的**所在地点**如何影响早期工匠选用的材料。"},
"undergo":{"e":"The old bridge will undergo extensive structural repairs next spring to withstand heavier modern traffic loads.","t":"这座老桥明年春天将**经历**大规模的结构维修，以承受更重的现代车流负荷。"},
"colony":{"e":"By the eighteenth century, the colony had grown wealthy through the export of sugar and tobacco.","t":"到十八世纪，这个**殖民地**已经通过出口蔗糖和烟草变得富庶起来。"},
"mottled":{"e":"Sunlight filtering through the leaves cast a mottled pattern of light and shadow across the forest floor.","t":"透过树叶洒下的阳光在林地上投下一片光影**斑驳**的图案。"},
"suite":{"e":"For their anniversary, they splurged on a luxury suite overlooking the harbor with a private balcony.","t":"为了庆祝结婚纪念日，他们奢侈地订了一间俯瞰港湾、带私人阳台的豪华**套房**。"},
"military":{"e":"The general spent decades studying military strategy before he was ever placed in command of troops.","t":"这位将军在被任命指挥部队之前，花了几十年研究**军事**战略。"},
"enclose":{"e":"A tall wooden fence was built to enclose the pasture and keep the wandering sheep from escaping.","t":"人们建了一道高高的木栅栏来**围住**牧场，防止四处游荡的羊逃跑。"},
"livelihood":{"e":"For generations, fishing had remained the only trade the family knew, carefully passed down from father to son.","t":"几代人以来，捕鱼一直是这家人唯一懂得的**谋生手段**，代代相传。"},
"sole":{"e":"She became the sole heir to her grandmother's estate after her two cousins declined their share.","t":"在两个表亲放弃继承份额后，她成了祖母遗产的**唯一**继承人。"},
"mountainous":{"e":"Because the region is so mountainous, engineers had to blast several tunnels before the railway could proceed.","t":"由于这个地区**多山**，工程师们不得不炸开好几条隧道，铁路才能继续修建。"},
"sample":{"e":"The lab technician carefully labeled every blood sample before sending them off for further detailed analysis.","t":"实验室技术员仔细标记了每一份血液**样本**，然后才送去做进一步详细分析。"},
"flux":{"e":"Company policy remained in constant flux throughout the merger, leaving employees unsure what rules to follow.","t":"在合并期间，公司政策一直处于不断**变动**之中，让员工们不知该遵循哪些规定。"},
"veil":{"e":"The nervous bride lifted her delicate lace veil just before her father walked her down the aisle.","t":"紧张的新娘在父亲挽着她走上红毯之前，掀起了她精致的蕾丝**面纱**。"},
"infest":{"e":"Termites had infested the old barn's wooden beams so severely that the structure was ready to collapse.","t":"白蚁**大批滋生**在这座老谷仓的木梁里，情况严重到整座建筑随时可能坍塌。"},
"tolerant":{"e":"Growing up in a diverse neighborhood made him remarkably tolerant of customs and beliefs different from his own.","t":"在多元社区中长大让他对与自己不同的习俗和信仰变得格外**宽容**。"},
"forecast":{"e":"Meteorologists forecast heavy snowfall for the weekend, prompting schools across the county to cancel classes early.","t":"气象学家**预报**周末将有大雪，促使全县学校提前停课。"},
"mobile":{"e":"She left her mobile charging on the kitchen counter and didn't notice the missed calls until evening.","t":"她把**手机**放在厨房台面上充电，直到晚上才注意到那些未接来电。"},
"linear":{"e":"Unlike organic architecture, the new office tower relies on strict linear forms and sharp right angles.","t":"与有机建筑不同，这座新的办公大楼依靠的是严格的**直线**造型和分明的直角。"},
"confidence":{"e":"Winning the regional championship gave the young team enough confidence to compete at the national level.","t":"赢得地区冠军赛让这支年轻的队伍有了足够的**信心**去参加全国级别的比赛。"},
"stash":{"e":"The smugglers routinely used to stash counterfeit goods inside hollowed-out furniture before quietly shipping everything overseas.","t":"走私者过去常把假冒商品**藏匿**在挖空的家具里，然后悄悄运往海外。"},
"inflate":{"e":"Volunteers spent the entire morning helping inflate hundreds of colorful balloons for the parade's opening ceremony.","t":"志愿者们花了一整个上午帮忙给数百个彩色气球**充气**，为游行开幕式做准备。"},
"amid":{"e":"Rescue workers searched amid the rubble for survivors long after the earthquake's tremors had finally stopped.","t":"救援人员在地震余震终于停止后很久，仍在废墟**之中**搜寻幸存者。"},
"paddle":{"e":"He lost his grip on the paddle and watched helplessly as it drifted downstream past the rapids.","t":"他没抓住**船桨**，只能眼睁睁看着它顺流漂过急流，无能为力。"},
"cornerstone":{"e":"Mutual trust has always remained the cornerstone of the lasting partnership between the two founding families.","t":"互相信任一直是这两个创始家族之间长久合作关系的**基石**。"},
"fund":{"e":"The nonprofit organization established an emergency fund to help families recover quickly after natural disasters strike.","t":"这家非营利组织设立了一项应急**基金**，帮助家庭在自然灾害发生后迅速恢复。"},
"venture":{"e":"Their first business venture failed within a year, but the lessons learned shaped every project afterward.","t":"他们的第一个商业**风险项目**不到一年就失败了，但从中吸取的教训影响了此后的每一个项目。"},
"unequal":{"e":"Historians argue that unequal access to education deepened the economic divide between the two regions for generations.","t":"历史学家认为，**不平等的**教育机会让这两个地区之间的经济差距持续了数代人之久。"},
"chorus":{"e":"Every Thursday evening, cheerful retirees from the neighborhood gather to rehearse with the community chorus downtown.","t":"每周四晚上，社区里精神矍铄的退休老人都会聚在一起，和市中心的**合唱队**一起排练。"},
"nonsense":{"e":"The professor quickly dismissed the conspiracy theory as complete nonsense unsupported by any credible scientific evidence.","t":"教授立即驳斥这个阴谋论纯属**胡说**，没有任何可信的科学证据支持。"},
"purple":{"e":"The evening sky turned a deep purple just before the thunderstorm rolled in over the mountains.","t":"就在雷暴滚滚而来、笼罩群山之前，傍晚的天空变成了深**紫色**。"},
"ration":{"e":"During the war, each household received a weekly ration of sugar, butter, and flour from the government.","t":"战争期间，每户人家每周都能从政府那里领到糖、黄油和面粉的**配给量**。"},
"mat":{"e":"She wiped her muddy boots on the mat before stepping into the freshly cleaned living room.","t":"她在**垫子**上擦干净沾满泥巴的靴子，然后才走进刚打扫过的客厅。"},
"profound":{"e":"The invention of the printing press had a profound effect on the spread of literacy across Europe.","t":"印刷机的发明对识字率在欧洲的普及产生了**深远的**影响。"},
"attire":{"e":"Guests were asked to wear formal attire for the gala dinner held at the historic opera house.","t":"宾客们被要求穿**正装**参加这场在历史悠久的歌剧院举行的晚宴。"},
"ornithology":{"e":"After retiring from teaching, she devoted herself entirely to ornithology, cataloging rare species along the coast.","t":"退休后，她全身心投入**鸟类学**研究，记录沿海地区的稀有物种。"},
"palatable":{"e":"The chef reduced the bitterness of the kale by adding lemon, making the salad far more palatable.","t":"厨师加了柠檬来减轻羽衣甘蓝的苦味，让这道沙拉变得更加**可口**。"},
"account":{"e":"Renewable energy sources now account for nearly a third of the entire nation's total electricity generation.","t":"可再生能源目前**占**该国电力总产量的近三分之一。"},
"cease":{"e":"The factory's aging machines finally ceased operating after running almost continuously for nearly forty-eight hours straight.","t":"这家工厂老旧的机器在连续运转了将近四十八小时后终于**停止**运作。"},
"turkey":{"e":"Every Thanksgiving, my grandmother roasts a whole turkey and stuffs it with cornbread and fresh herbs.","t":"每年感恩节，我祖母都会烤一整只**火鸡**，里面塞满玉米面包和新鲜香草。"},
"impulse":{"e":"Against her better judgment, she gave in to the impulse and bought the expensive coat immediately.","t":"尽管理智告诉她不该这样，她还是屈服于一时的**冲动**，立刻买下了那件昂贵的外套。"},
"normally":{"e":"Traffic normally clears up by nine, but construction on the bridge kept it congested until noon.","t":"交通**通常**到九点就会疏通，但桥上的施工让拥堵一直持续到中午。"},
"property":{"e":"After her divorce, she had to sell the property they had jointly owned for over a decade.","t":"离婚后，她不得不卖掉他们共同拥有了十多年的这处**房产**。"},
"absolute":{"e":"The king demanded absolute loyalty from his advisors and punished even the slightest hint of dissent.","t":"国王要求顾问们**绝对**忠诚，哪怕最轻微的异议迹象也会受到惩罚。"},
"switch":{"e":"He fumbled in the dark for the light switch, knocking over a lamp in the process.","t":"他在黑暗中摸索着找电灯**开关**，过程中还碰倒了一盏台灯。"},
"intelligent":{"e":"The dolphin's ability to solve novel puzzles convinced researchers it was remarkably intelligent for a marine mammal.","t":"海豚解决新奇谜题的能力让研究人员确信，作为海洋哺乳动物，它异常**聪明**。"},
"depart":{"e":"The overnight express train is scheduled to depart from the central station at exactly eleven fifteen.","t":"这趟夜班快车预计将于十一点十五分准时从中央车站**出发**。"},
"expand":{"e":"The startup plans to expand into three new international markets by the end of next year.","t":"这家初创公司计划到明年年底前**扩张**到三个新的国际市场。"},
"rite":{"e":"The tribe still faithfully performs an ancient rite to mark every child's passage into full adulthood.","t":"这个部落至今仍虔诚地举行一种古老的**仪式**，来标志每个孩子步入成年。"},
"curriculum":{"e":"The school recently revised its entire curriculum to include far more hands-on science and technology courses.","t":"这所学校最近修订了整个**课程体系**，加入了更多动手实践的科学和技术课程。"},
"strategic":{"e":"Controlling that narrow strait gave the empire a decisive strategic advantage over rival trading powers nearby.","t":"控制那条狭窄的海峡让这个帝国相对邻近的贸易对手拥有了决定性的**战略**优势。"},
"inject":{"e":"The veterinarian carefully injected a mild sedative before gently examining the injured wolf's badly broken leg.","t":"兽医先小心地**注射**了一针温和的镇静剂，然后才检查这只受伤野狼严重骨折的腿。"},
"puzzle":{"e":"Why the ancient city was suddenly abandoned remains a puzzle that archaeologists have debated for decades.","t":"这座古城为何突然被遗弃，至今仍是一个**谜**，考古学家们争论了数十年。"},
"stick":{"e":"The stubborn label wouldn't stick to the jar no matter how firmly she pressed it down.","t":"无论她把标签按得多用力，这张顽固的标签就是**粘**不到罐子上。"},
"primordial":{"e":"Scientists believe lightning striking primordial oceans may have triggered the chemical reactions that produced early life.","t":"科学家认为，闪电击中**原始**海洋可能引发了产生早期生命的化学反应。"},
"raft":{"e":"The stranded hikers built a makeshift raft from fallen logs to cross the swollen river safely.","t":"被困的徒步旅行者用倒下的原木搭了一个简易**木筏**，安全渡过了暴涨的河流。"},
"sledding":{"e":"Negotiations proved to be rough sledding, with both sides refusing to compromise on the key terms.","t":"谈判**进展**十分艰难，双方都不肯在关键条款上做出让步。"},
"forward":{"e":"Please forward the client's email to the accounting department so they can process the refund promptly.","t":"请把客户的邮件**转交**给财务部，以便他们及时处理退款。"},
"technical":{"e":"The manual was so full of technical jargon that most beginners gave up after the first page.","t":"这本手册充满了**技术**术语，以至于大多数初学者看完第一页就放弃了。"},
"hook":{"e":"The technician quickly managed to hook the antenna directly into the old radio's receiver within minutes.","t":"技术员几分钟内就把天线**连接**到了那台旧收音机的接收器上。"},
"random":{"e":"The researchers selected a random sample of five hundred voters to minimize bias in their survey.","t":"研究人员选取了五百名选民的**随机**样本，以尽量减少调查中的偏差。"},
"lounge":{"e":"Passengers with delayed flights waited restlessly in the airport lounge, scrolling through their phones for updates.","t":"航班延误的乘客们焦躁地在机场**休息室**等候，不停刷手机查看最新消息。"},
"staggered":{"e":"To avoid overcrowding, the factory adopted staggered shift schedules so workers arrived at different times each morning.","t":"为了避免人员过于拥挤，这家工厂采用了**交错**排班制，让工人每天早上分批到岗。"},
"pine":{"e":"The sharp scent of pine filled the cabin after we dragged the fresh Christmas tree inside.","t":"我们把新砍的圣诞树拖进屋后，浓郁的**松树**香气弥漫了整座小木屋。"},
"naval":{"e":"The admiral oversaw the construction of an entirely new naval base along the country's southern coast.","t":"海军上将监督了在该国南部沿海建造一座全新**海军**基地的工程。"},
"avoid":{"e":"Drivers were urged to avoid the downtown area entirely because of the ongoing water main repairs.","t":"由于正在进行供水干管维修，司机们被要求完全**避开**市中心区域。"},
"biography":{"e":"The award-winning biography revealed private letters that completely reshaped how historians viewed the president's final years.","t":"这部获奖**传记**披露的私人信件彻底改变了历史学家对这位总统晚年的看法。"},
"elm":{"e":"A century-old elm shaded the entire front yard until disease forced the city to cut it down.","t":"一棵百年**榆树**曾为整个前院遮荫，直到病害迫使市政府将它砍掉。"},
"implicit":{"e":"Her silence during the meeting carried an implicit agreement with everything the manager had just proposed.","t":"她在会议上的沉默**含蓄地**表达了对经理刚才提议的赞同。"},
"hardly":{"e":"After the long flight, she was so exhausted that she could hardly keep her eyes open.","t":"经过长途飞行，她累得**几乎**睁不开眼睛。"},
"centigrade":{"e":"The thermometer showed the water had already reached ninety degrees centigrade before it began to boil.","t":"温度计显示水在开始沸腾之前已经达到了九十度**摄氏**温度。"},
"barbecue":{"e":"Neighbors gathered in the backyard for a barbecue, grilling burgers and corn late into the evening.","t":"邻居们聚在后院举行**烧烤野餐**，一直到深夜还在烤汉堡和玉米。"},
"element":{"e":"Surprise is a crucial element of good storytelling, keeping readers engaged until the very last page.","t":"悬念是精彩故事的关键**要素**，能让读者一直读到最后一页。"},
"sensory":{"e":"The therapy room was designed with soft lighting and gentle music to reduce sensory overload in children.","t":"这间治疗室采用柔和的灯光和轻柔的音乐设计，以减少儿童的**感官**过度刺激。"},
"yarn":{"e":"My grandmother spent every winter evening knitting sweaters from thick wool yarn she had dyed herself.","t":"祖母每个冬天的夜晚都用她自己染色的粗**毛线**编织毛衣。"},
"analogy":{"e":"The teacher used a simple analogy comparing the heart to a pump to help students understand circulation.","t":"老师用把心脏比作水泵的简单**类比**，帮助学生理解血液循环。"},
"convenience":{"e":"For the convenience of commuters, the new subway line connects directly to the airport's main terminal.","t":"为了**方便**通勤者，这条新地铁线路直接连接到机场主航站楼。"},
"publication":{"e":"The novel's publication was delayed nearly a full year after the original manuscript was accidentally lost.","t":"由于原始手稿意外遗失，这本小说的**出版**推迟了将近整整一年。"},
"compulsory":{"e":"Military service remains compulsory for young men in that country, regardless of their personal career plans.","t":"在那个国家，无论个人有什么职业规划，兵役对年轻男性来说仍是**强制性的**。"},
"pointed":{"e":"She made a pointed remark about his constant lateness that left the whole table in awkward silence.","t":"她针对他总是迟到这件事说了一句**尖锐**的评语，让满桌人都陷入了尴尬的沉默。"},
"spread":{"e":"Wildfires fueled by strong winds continued to spread across the dry hillside despite firefighters' exhausting efforts.","t":"尽管消防员竭尽全力，强风助长的野火仍在干燥的山坡上继续**蔓延**。"},
"assemble":{"e":"Workers on the factory line assemble each engine by hand before it undergoes a final quality inspection.","t":"工厂流水线上的工人手工**装配**每一台发动机，然后再进行最终的质量检验。"},
"clone":{"e":"Scientists successfully created a genetic clone of the endangered sheep using cells from a preserved sample.","t":"科学家利用保存样本中的细胞，成功培育出这只濒危绵羊的基因**克隆体**。"},
"discourse":{"e":"Public discourse surrounding climate policy has grown noticeably more polarized over the past several election cycles.","t":"围绕气候政策的公共**话语**在过去几次选举周期中变得日益两极化。"},
"aquifer":{"e":"Farmers in the valley depend heavily on a shrinking aquifer that took thousands of years to form.","t":"山谷里的农民严重依赖一个正在萎缩的**含水层**，而它是历经数千年才形成的。"},
"conversion":{"e":"The old warehouse's gradual conversion into loft apartments attracted young professionals seeking affordable downtown housing nearby.","t":"这座旧仓库逐渐**改建**成loft公寓，吸引了不少想在市中心找到经济适用房的年轻白领。"},
"summary":{"e":"The professor asked each student to submit a one-page summary of the article before Monday's discussion.","t":"教授要求每个学生在周一讨论前提交一份关于这篇文章的一页纸**摘要**。"},
"carbon":{"e":"Burning fossil fuels releases large amounts of carbon into the atmosphere, accelerating global climate change significantly.","t":"燃烧化石燃料会向大气中释放大量**碳**，显著加速全球气候变化。"},
"petroleum":{"e":"The tiny nation's entire economy depends almost entirely on revenue generated from exporting crude petroleum abroad.","t":"这个小国的整个经济几乎完全依赖出口原**石油**所产生的收入。"},
"accessory":{"e":"She always adds one bold accessory, like a chunky necklace, to complete an otherwise simple outfit.","t":"她总会加上一件醒目的**配饰**，比如一条粗项链，来点缀原本简单的穿搭。"},
"planet":{"e":"Astronomers recently discovered a distant planet orbiting its star within the narrow zone suitable for liquid water.","t":"天文学家最近发现了一颗遥远的**行星**，它围绕恒星运行的轨道恰好处于适宜液态水存在的狭窄区域。"},
"appreciation":{"e":"Years of studying classical music gave him a deep appreciation for the complexity of Beethoven's later symphonies.","t":"多年研究古典音乐让他对贝多芬晚期交响曲的复杂性有了深刻的**欣赏**。"},
"elongate":{"e":"As the giraffe slowly evolved, its neck vertebrae gradually began to elongate over millions of generations.","t":"随着长颈鹿缓慢进化，它的颈椎在数百万代间逐渐**延长**。"},
"therefore":{"e":"The bridge failed a routine safety inspection and was therefore closed to all traffic until repairs finish.","t":"这座桥未通过例行安全检查，**因此**在维修完成之前将禁止一切车辆通行。"},
"imagist":{"e":"Ezra Pound's early imagist poems favored sharp, concrete images over the flowery language of Victorian verse.","t":"埃兹拉·庞德早期的**意象派**诗歌偏爱鲜明具体的意象，而非维多利亚时代诗歌的华丽辞藻。"},
"path":{"e":"A narrow gravel path wound through the garden, leading visitors past roses and toward the old fountain.","t":"一条狭窄的碎石**小径**蜿蜒穿过花园，引导游客经过玫瑰丛，走向那座古老的喷泉。"},
"yoke":{"e":"The farmer fitted the wooden yoke over the oxen's necks before plowing the muddy spring field.","t":"农夫把木**轭**套在牛的脖子上，然后开始犁那片泥泞的春田。"},
"collaborate":{"e":"The two rival laboratories finally agreed to collaborate on a vaccine after years of separate, duplicated research.","t":"经过多年各自重复的研究，这两个竞争实验室终于同意**合作**开发疫苗。"},
"controversial":{"e":"The mayor's controversial proposal to close the downtown park sparked heated debate at every town meeting.","t":"市长提出关闭市中心公园的**有争议**提案，在每一次市镇会议上都引发了激烈辩论。"},
"agenda":{"e":"Before finally adjourning, the committee chair reviewed several items still remaining on the meeting's crowded agenda.","t":"在最终休会之前，委员会主席回顾了会议拥挤**议程**上仍未处理的几个事项。"},
"latitude":{"e":"Crops that thrive at this latitude often struggle to survive once transplanted closer to the equator.","t":"在这个**纬度**茁壮成长的农作物，一旦被移植到更靠近赤道的地方，往往难以存活。"},
"appraise":{"e":"An independent expert was hired to appraise the antique painting before the estate could legally be settled.","t":"在遗产能够合法清算之前，他们请了一位独立专家来**估价**这幅古董画。"},
"session":{"e":"The therapist scheduled another follow-up session for the following week to closely monitor his continued progress.","t":"治疗师安排了下周的另一次跟进**治疗会**，以便密切关注他的持续恢复情况。"},
"hail":{"e":"Golf-ball-sized hail violently battered the parked cars and shattered several windshields during the sudden afternoon storm.","t":"高尔夫球大小的**冰雹**在那场突如其来的午后暴风雨中猛烈砸向停放的汽车，打碎了好几块挡风玻璃。"},
"aptitude":{"e":"The young pianist showed a remarkable aptitude for music long before she ever received formal lessons.","t":"这位年轻钢琴家在接受正式课程训练之前，早就展现出非凡的音乐**天赋**。"},
"trifle":{"e":"He refused to let such a minor trifle ruin an otherwise pleasant evening with old friends.","t":"他不愿让这样一件微不足道的**小事**毁掉与老朋友原本愉快的夜晚。"},
"dismiss":{"e":"The entire board voted unanimously to dismiss the CEO once the accounting scandal became public knowledge.","t":"一旦会计丑闻公之于众，董事会全体一致投票**解雇**了这位首席执行官。"},
"browse":{"e":"She liked to browse the secondhand bookstore for hours, never quite sure what she might find.","t":"她喜欢在那家二手书店里**浏览**上好几个小时，从不确定自己会发现什么。"},
"collaborative":{"e":"The museum's newest exhibit was a truly collaborative effort between local artists and university design students.","t":"博物馆最新的展览是当地艺术家与大学设计系学生之间真正**协作**的成果。"},
"prefer":{"e":"Given the choice between the two internships, most students prefer the one offering hands-on laboratory experience.","t":"在两个实习机会中，大多数学生**更喜欢**能提供实验室实践经验的那一个。"},
"frenzy":{"e":"News of the limited-edition sneaker release sent collectors into a frenzy outside the store before dawn.","t":"限量版运动鞋发售的消息让收藏者们在天亮前就在店外陷入一片**狂热**。"},
"remarkable":{"e":"Given her limited training, the young gymnast's performance at the championship was truly remarkable to watch.","t":"考虑到她训练时间有限，这位年轻体操运动员在锦标赛上的表现堪称**非凡**。"},
"radioactive":{"e":"Workers wore heavy protective suits while carefully removing radioactive waste from the damaged reactor's cooling chamber.","t":"工人们穿着厚重的防护服，小心地从受损反应堆的冷却舱中清除**放射性**废料。"},
"incapacitate":{"e":"A severe knee injury during training was enough to incapacitate the star player for the entire season.","t":"训练中一次严重的膝伤足以让这位明星球员整个赛季都**丧失比赛能力**。"},
"potassium":{"e":"Ripe bananas are frequently recommended to athletes because they provide an excellent natural source of potassium.","t":"成熟的香蕉常被推荐给运动员食用，因为它们是天然**钾**元素的绝佳来源。"},
"crippling":{"e":"Years of crippling debt from constant overspending eventually forced the once-thriving family company into complete bankruptcy.","t":"多年来因持续超支而背负的**极其沉重**的债务，最终迫使这家曾经兴旺的家族企业彻底破产。"},
"slip":{"e":"She stepped onto the icy porch too quickly and felt her boots slip out from under her instantly.","t":"她太快踏上结冰的门廊，一下子就感觉脚下的靴子**打滑**，整个人失去了平衡。"},
"impending":{"e":"A sense of impending doom settled over the crew as the storm clouds darkened the horizon.","t":"当暴风云笼罩地平线时，船员们心中弥漫起一种**即将来临**的厄运预感。"},
"decline":{"e":"Local fish populations have shown a steady decline since the new dam altered the river's natural flow.","t":"自从新水坝改变了河流的自然流向以来，当地鱼类种群数量一直持续**下降**。"},
"pepper":{"e":"She ground fresh black pepper generously over the soup just before setting the bowl on the table.","t":"她把汤端上桌之前，在上面慷慨地磨了些新鲜的黑**胡椒粉**。"},
"bison":{"e":"Herds of bison once roamed the Great Plains by the millions before hunters nearly drove them extinct.","t":"成群的**野牛**曾以数百万计漫步在大平原上，直到猎人们几乎将它们赶尽杀绝。"},
"gist":{"e":"Although she missed the first ten minutes, she quickly grasped the gist of the professor's argument.","t":"虽然她错过了前十分钟，但她很快就抓住了教授论点的**要点**。"},
"illustrative":{"e":"The textbook includes several illustrative diagrams that make the otherwise abstract chemical process much easier to follow.","t":"这本教科书配有几幅**说明性**图表，让原本抽象的化学过程变得容易理解得多。"},
"perspicuous":{"e":"Her perspicuous writing style made even the densest legal arguments accessible to readers without formal training.","t":"她**明白晓畅**的写作风格让即便是最艰深的法律论证，未受过专业训练的读者也能看懂。"},
"intern":{"e":"The hospital assigned a nervous first-year intern to shadow the senior surgeon throughout the entire operation.","t":"医院安排了一名紧张的一年级**实习生**，全程跟随这位资深外科医生观摩手术。"},
"skim":{"e":"Rather than read every page closely, she chose to skim the report for its main conclusions.","t":"她没有逐页仔细阅读，而是选择**略读**这份报告，只抓取其中的主要结论。"},
"podium":{"e":"The valedictorian gripped the podium nervously as she began delivering her speech to the packed auditorium.","t":"致告别词的优秀毕业生紧张地抓住**讲台**，开始向座无虚席的礼堂发表演讲。"},
"swap":{"e":"The two roommates decided to swap bedrooms after realizing the smaller room actually got more sunlight.","t":"两个室友发现较小的房间其实采光更好后，决定**互换**卧室。"},
"batter":{"e":"Waves continued to batter the lighthouse throughout the night, but the old structure held remarkably firm.","t":"整夜巨浪不断**猛烈拍打**灯塔，但这座老建筑依然异常坚固。"},
"landing":{"e":"The pilot skillfully executed a smooth emergency landing despite one engine failing shortly after morning takeoff.","t":"尽管一台引擎在早晨起飞后不久就发生故障，飞行员仍娴熟地完成了一次平稳的紧急**降落**。"},
"syllabus":{"e":"On the first day, the professor handed out a syllabus outlining every reading assignment for the semester.","t":"第一天上课，教授就发了一份**教学大纲**，列出了整个学期的所有阅读作业。"},
"curtsy":{"e":"The young girl practiced her curtsy for weeks before being presented to the visiting members of royalty.","t":"这个小女孩练习了好几周的**屈膝礼**，才被引见给来访的王室成员。"},
"feast":{"e":"The whole village gathered for a harvest feast featuring roasted lamb, fresh bread, and honeyed pastries.","t":"全村人聚在一起举行丰收**盛宴**，有烤羊肉、新鲜面包和蜂蜜糕点。"},
"gorge":{"e":"After the long hike, the exhausted scouts began to gorge themselves on sandwiches and trail mix.","t":"长途徒步之后，疲惫的童子军们开始**狼吞虎咽**地吃起三明治和什锦干果。"},
"lope":{"e":"The wolf began to lope effortlessly across the tundra, covering ground far faster than it appeared.","t":"那只狼开始**轻松大步**穿过冻原，前进的速度比看起来快得多。"},
"systematize":{"e":"The new librarian spent months trying to systematize the archive's chaotic collection of unlabeled historical documents.","t":"新来的图书管理员花了几个月时间，试图把档案馆里杂乱无章、未标注的历史文献**系统化**。"},
"disturb":{"e":"A sign on the door politely asked visitors not to disturb the patient while she was resting.","t":"门上的告示礼貌地要求访客不要在病人休息时**打扰**她。"},
"monitor":{"e":"Nurses continued to closely monitor the newborn's heart rate throughout the entire first critical seventy-two hours.","t":"护士们在最初七十二个小时的关键时期，持续密切**监控**新生儿的心率。"},
"submit":{"e":"All applicants must submit three letters of recommendation along with their transcripts before the January deadline.","t":"所有申请者必须在一月截止日期前**提交**三封推荐信及成绩单。"},
"palate":{"e":"Years of working as a sommelier had trained her palate to detect the faintest hint of oak.","t":"多年的品酒师工作训练出了她敏锐的**味觉**，能察觉出最细微的橡木气息。"},
"manage":{"e":"Despite the blizzard, the delivery driver somehow managed to reach every last house on his route.","t":"尽管遭遇暴风雪，这位送货司机还是**设法**把货物送到了路线上的每一户人家。"},
"squabble":{"e":"The siblings began to squabble over the last slice of pizza before their mother intervened firmly.","t":"兄妹俩开始为最后一片披萨**争吵**起来，直到母亲坚定地出面干预。"},
"recommend":{"e":"Her mentor recommended her for the fellowship after watching her publish three papers in a single year.","t":"在看到她一年内发表三篇论文后，她的导师**推荐**她申请这项奖学金。"},
"unity":{"e":"The coach always emphasized team unity above individual talent, insisting that trust wins championships, not egos.","t":"教练一直强调团队**团结**比个人天赋更重要，坚持认为赢得冠军靠的是信任而非自负。"},
"parliament":{"e":"The bill must pass through parliament twice before it can officially become the law of the land.","t":"这项法案必须两次通过**议会**审议，才能正式成为国家法律。"},
"mere":{"e":"What seemed like an impossible feat turned out to be a mere formality once the paperwork arrived.","t":"看似不可能完成的壮举，等文件一到，结果竟不过是一个**纯粹**的手续问题。"},
"hive":{"e":"During the harsh winter months, the entire extended family would hive together inside the ancestral farmhouse.","t":"在严酷的冬季里，整个大家庭都会**群居**在祖传的农舍里。"},
"resort":{"e":"When diplomacy failed repeatedly, the increasingly desperate negotiators finally had to resort to economic sanctions instead.","t":"在外交手段屡屡失败后，越发绝望的谈判代表最终不得不**求助于**经济制裁。"},
"ravine":{"e":"The hikers had to climb down a steep ravine before finding a safe place to cross the stream.","t":"徒步旅行者不得不爬下一道陡峭的**溪谷**，才找到一处安全的地方过河。"},
"meteorologist":{"e":"The local meteorologist warned residents that the approaching hurricane could strengthen rapidly overnight before making landfall.","t":"当地**气象学家**警告居民，逼近的飓风可能在登陆前一夜之间迅速增强。"},
"vocation":{"e":"After years in corporate law, she finally left to pursue teaching, a vocation she had always felt drawn to.","t":"在从事多年公司法律工作后，她最终辞职去教书，这是她一直感到召唤的**使命**。"},
"crevice":{"e":"A tiny fern had somehow taken root in a narrow crevice between two massive granite boulders.","t":"一株小小的蕨类植物不知怎么就在两块巨大花岗岩之间的狭窄**裂缝**中扎了根。"},
"trial":{"e":"The defendant's trial was postponed twice after several key witnesses failed to appear before the court.","t":"由于几名关键证人未能出庭，被告的**审讯**被推迟了两次。"},
"contest":{"e":"The losing candidate vowed to contest the election results in court, alleging widespread irregularities at several polling stations.","t":"落败的候选人誓言要在法庭上对选举结果**提出异议**，声称多个投票站存在大规模违规行为。"},
"recognize":{"e":"Even after thirty years apart, she immediately recognized her childhood friend's laugh across the crowded room.","t":"即使分别了三十年，她还是立刻在拥挤的房间里**认出**了童年好友的笑声。"},
"split":{"e":"Bitter disagreements over the inheritance eventually caused the once-close siblings to split and stop speaking entirely.","t":"关于遗产的激烈争执最终导致这对曾经亲密的兄妹**分裂**，彻底不再往来。"},
"receiver":{"e":"She slammed the receiver down in frustration after being placed on hold for nearly an hour.","t":"在被搁置等待了将近一个小时后，她愤怒地把**听筒**摔了下去。"},
"facility":{"e":"The pharmaceutical company built a brand-new, state-of-the-art facility capable of producing millions of vaccine doses monthly.","t":"这家制药公司建造了一座最先进的**设施**，每月能够生产数百万剂疫苗。"},
"infection":{"e":"Doctors quickly prescribed strong antibiotics to prevent the wound infection from spreading further into her bloodstream.","t":"医生迅速开了强效抗生素，以防止伤口**感染**进一步扩散到她的血液中。"},
"crater":{"e":"The massive meteorite left a crater nearly a mile wide when it struck the desert floor.","t":"那颗巨大的陨石撞击沙漠地面时，留下了一个将近一英里宽的**坑**。"},
"balcony":{"e":"Every morning, she watered her potted herbs on the tiny balcony overlooking the busy street below.","t":"每天早晨，她都会在俯瞰楼下繁忙街道的小小**阳台**上给盆栽香草浇水。"},
"strike":{"e":"Thousands of transit workers finally decided to strike after contract negotiations with the city collapsed entirely.","t":"在与市政府的合同谈判彻底破裂后，数千名公交工人最终决定**罢工**。"},
"chunk":{"e":"She sliced off a generous chunk of cheddar cheese to go with the crackers and grapes.","t":"她切下一大**块**切达奶酪，配着饼干和葡萄一起吃。"},
"sac":{"e":"The spider carefully wrapped her eggs inside a silken sac attached to the underside of a leaf.","t":"蜘蛛小心地把卵包裹在一个丝质**囊**里，粘附在一片叶子的背面。"},
"scratch":{"e":"The careless mover accidentally let the heavy dresser scratch a long line across the hardwood floor.","t":"粗心的搬运工不小心让沉重的五斗柜在硬木地板上**划**出一道长长的痕迹。"},
"vaccine":{"e":"Health officials urged parents to get their children the measles vaccine before the new school year began.","t":"卫生官员敦促家长在新学年开始前给孩子接种麻疹**疫苗**。"},
"version":{"e":"The director released an extended version of the film with nearly thirty minutes of previously deleted scenes.","t":"导演发布了这部电影的加长**版本**，收录了近三十分钟此前被删除的片段。"},
"provincialism":{"e":"Her provincialism became obvious when she dismissed every idea that hadn't already caught on in her hometown.","t":"她的**乡土观念**显而易见——凡是家乡还没流行起来的想法，她一概不屑一顾。"},
"sharply":{"e":"Coffee prices rose sharply across the region after a prolonged drought destroyed much of last spring's harvest.","t":"一场持续的干旱摧毁了去年春天的大部分收成后，该地区的咖啡价格**急剧上涨**。"},
"colonize":{"e":"Lichens were among the first organisms to colonize the bare volcanic rock left by the eruption.","t":"地衣是最早**定居**在火山喷发后裸露岩石上的生物之一。"},
"extrinsic":{"e":"The committee argued that fame is an extrinsic reward that shouldn't distract young musicians from perfecting their craft.","t":"委员会认为名气是一种**外在的**奖励，不该让年轻音乐家因此分心而忘记精进技艺。"},
"insert":{"e":"The editor asked the intern to insert a footnote explaining the obscure historical reference before publication.","t":"编辑要求实习生在出版前**插入**一条脚注，解释那个晦涩的历史典故。"},
"authorize":{"e":"Only the board of directors can authorize spending above fifty thousand dollars on a single project.","t":"只有董事会才能**批准**单个项目五万美元以上的支出。"},
"margin":{"e":"The senator won reelection by such a narrow margin that officials ordered an automatic recount of the ballots.","t":"这位参议员以极小的**优势差距**连任成功，以至于官员下令自动重新计票。"},
"disadvantage":{"e":"Being the shortest player on the team put him at a clear disadvantage whenever the ball came near the net.","t":"作为队里个子最矮的球员，每当球飞近球网时，他都明显处于**不利地位**。"},
"surplus":{"e":"The farm's grain surplus was so large that the family sold the extra bushels to neighboring villages.","t":"这家农场的粮食**盈余**多得惊人，一家人便把多余的谷物卖给了邻村。"},
"Saturn":{"e":"Through the telescope, Saturn's rings appeared as a thin, glowing band encircling the pale yellow planet.","t":"透过望远镜可以看到，**土星**的光环犹如一条细窄的发光带，环绕着这颗淡黄色的行星。"},
"acoustic":{"e":"The singer traded her electric guitar for an acoustic one before performing the stripped-down version of the ballad.","t":"这位歌手在演唱这首民谣的简化版之前，把电吉他换成了**原声吉他**。"},
"disprove":{"e":"New fossil evidence quickly disproved the theory that the species had vanished millions of years earlier.","t":"新的化石证据很快就**推翻**了该物种早在数百万年前便已灭绝的理论。"},
"mosaic":{"e":"Thousands of tiny colored tiles formed an intricate mosaic depicting a hunting scene across the ancient floor.","t":"数以千计的彩色小瓷砖拼成了一幅精美的**镶嵌画**，描绘着古老地板上的一场狩猎场景。"},
"simulate":{"e":"Engineers built an elaborate wind tunnel to simulate hurricane-force gusts before certifying the bridge's final design.","t":"工程师们建造了一座精密的风洞，用来**模拟**飓风级的阵风，之后才为大桥的最终设计定案。"},
"funding":{"e":"The research team lost its funding halfway through the study, forcing scientists to abandon years of careful data collection.","t":"研究团队的**经费**在研究进行到一半时中断，科学家们被迫放弃多年精心收集的数据。"},
"influenza":{"e":"The influenza outbreak spread so quickly through the dormitory that the university had to cancel classes for a week.","t":"**流感**疫情在宿舍楼里蔓延得太快，学校不得不停课一周。"},
"advanced":{"e":"By the time doctors discovered the tumor, the cancer had already reached an advanced stage that resisted most treatments.","t":"等医生发现肿瘤时，癌症已经发展到**晚期**，大多数治疗手段都难以奏效。"},
"abbey":{"e":"Tourists wandered through the ruined abbey, photographing the crumbling arches that monks had built centuries earlier.","t":"游客们漫步在这座残破的**修道院**中，拍下僧侣们几个世纪前建造的那些正在坍塌的拱门。"},
"depot":{"e":"Exhausted travelers huddled inside the train depot, waiting for the delayed express to finally arrive at midnight.","t":"疲惫的旅客们挤在火车**站**里，等着那趟晚点的特快列车终于在午夜抵达。"},
"romantic":{"e":"His romantic notion that talent alone guarantees success ignored the years of grinding practice every champion endures.","t":"他那**不切实际**的想法——认为单凭天赋就能成功——忽略了每位冠军背后多年艰苦的训练。"},
"tycoon":{"e":"The shipping tycoon donated half his fortune to build hospitals in the port cities that had made him rich.","t":"这位航运**大亨**将一半财富捐出，在那些让他致富的港口城市建起了医院。"},
"justice":{"e":"The victim's family spent decades pursuing justice, refusing to let the unsolved case fade from public memory.","t":"受害者家属花了几十年追寻**正义**，绝不让这桩悬案从公众记忆中淡去。"},
"panel":{"e":"A panel of five judges deliberated for hours before awarding the young violinist first prize in the competition.","t":"由五名评委组成的**评审团**商议了数小时，最终将比赛一等奖授予了这位年轻的小提琴手。"},
"guilty":{"e":"She felt guilty for weeks after completely forgetting her best friend's birthday during the chaos of finals season.","t":"考试季一片混乱，她把最好朋友的生日忘得一干二净，为此**内疚**了好几个星期。"},
"cushion":{"e":"Thick pine needles on the forest floor cushioned her fall when she slipped off the narrow trail.","t":"林地上厚厚的松针在她从窄径滑落时**缓冲**了这一跌。"},
"microorganism":{"e":"A single teaspoon of ordinary garden soil can contain billions of microorganisms invisible to the naked eye.","t":"一茶匙普通的花园土壤中就可能含有数十亿肉眼看不见的**微生物**。"},
"awful":{"e":"The soup tasted so awful that even the starving hikers pushed their bowls aside after one spoonful.","t":"这汤难喝得**糟糕**至极，就连饿坏了的徒步者也只尝了一口就把碗推到一边。"},
"surgery":{"e":"The surgeon warned that the surgery carried real risks but offered the only chance to save his leg.","t":"外科医生警告说这场**手术**确实有风险，但这是保住他这条腿的唯一机会。"},
"impact":{"e":"Rising sea levels will impact coastal communities long before most inland residents notice any change at all.","t":"海平面上升将**影响**沿海社区，而大多数内陆居民届时还根本察觉不到任何变化。"},
"crustacean":{"e":"The marine biologist spent her career studying how crustaceans molt and regrow their hardened outer shells.","t":"这位海洋生物学家将职业生涯都用于研究**甲壳类动物**如何蜕壳并重新长出坚硬的外壳。"},
"obtain":{"e":"All applicants must obtain written approval from the department chair before enrolling in the graduate seminar.","t":"所有申请人必须先**获得**系主任的书面批准，才能选修这门研究生研讨课。"},
"respondent":{"e":"Most respondents to the survey admitted they rarely read the terms and conditions before clicking accept.","t":"大多数**受访者**承认，他们在点击同意之前很少真正阅读条款细则。"},
"particular":{"e":"Her grandfather was so particular about his coffee that he refused any brand besides the one imported from Colombia.","t":"她祖父对咖啡**挑剔**得很，除了从哥伦比亚进口的那个牌子，别的一概不要。"},
"newsprint":{"e":"The old printing presses consumed enormous rolls of cheap newsprint each night to produce the morning edition.","t":"老式印刷机每晚都要消耗大卷廉价的**新闻纸**，才能印出早报。"},
"gregarious":{"e":"Unlike her shy older brother, Maria was gregarious, chatting easily with strangers at every party she attended.","t":"玛丽亚和她腼腆的哥哥不同，天生**爱交际**，在每场聚会上都能轻松地和陌生人聊起来。"},
"chafe":{"e":"The young apprentice chafed under the strict routine, longing for the freedom to experiment with his own designs.","t":"这位年轻学徒对严格的日常规矩感到**焦躁不满**，渴望有自由去尝试自己的设计。"},
"lizard":{"e":"A small lizard darted across the sun-baked rock and vanished into a crack before the hawk could dive.","t":"一只小**蜥蜴**飞快地窜过被太阳晒得滚烫的岩石，在老鹰俯冲下来之前钻进了石缝。"},
"manner":{"e":"The professor explained the proof in such a clear, patient manner that even struggling students finally understood.","t":"教授以如此清晰耐心的**方式**讲解这道证明题，连吃力的学生最终也听懂了。"},
"artifact":{"e":"Archaeologists carefully brushed dirt away from the clay artifact before cataloging it as evidence of early trade.","t":"考古学家小心翼翼地拂去这件陶土**手工制品**上的泥土，随后将它记录为早期贸易的证据。"},
"gravel":{"e":"The truck dumped a fresh load of gravel onto the driveway to fill in the muddy ruts.","t":"卡车把一车新的**碎石**倒在车道上，用来填平那些泥泞的车辙。"},
"string":{"e":"A string of unexpected injuries forced the coach to rearrange the entire starting lineup before the championship.","t":"**一连串**意外的伤病迫使教练在锦标赛前重新调整整个首发阵容。"},
"panorama":{"e":"From the summit, hikers could see a sweeping panorama of valleys, rivers, and distant snow-capped peaks.","t":"从山顶望去，徒步者可以看到山谷、河流和远处雪峰构成的壮阔**全景**。"},
"ambitious":{"e":"The startup's ambitious plan to launch in twelve countries within a year struck most investors as reckless.","t":"这家初创公司要在一年内进军十二个国家的**雄心勃勃**的计划，让大多数投资者觉得太冒险。"},
"afflict":{"e":"A rare genetic disorder afflicted three generations of the same family, baffling doctors for nearly a century.","t":"一种罕见的遗传病**折磨**了同一个家族三代人，让医生们困惑了近一个世纪。"},
"stripe":{"e":"Each species of zebra has a slightly different stripe pattern, as unique as a human fingerprint.","t":"每种斑马的**条纹**图案都略有不同，就像人类的指纹一样独一无二。"},
"clay":{"e":"The potter kneaded the wet clay for several minutes to remove air bubbles before shaping it on the wheel.","t":"陶艺师把湿**黏土**揉了好几分钟以排出气泡，然后才放到轮盘上塑形。"},
"comment":{"e":"The professor's brief comment in the margin completely changed how the student understood her own argument.","t":"教授在页边写下的简短**评语**，彻底改变了这名学生对自己论点的理解。"},
"scholarship":{"e":"Winning the scholarship meant she could finally attend the university without burdening her parents with debt.","t":"赢得这份**奖学金**意味着她终于能上大学，而不必让父母背负债务。"},
"patch":{"e":"The sailors worked through the night to patch the torn sail before the next storm reached them.","t":"水手们通宵工作，赶在下一场风暴来临之前**修补**好那张撕裂的帆。"},
"restrict":{"e":"The new policy will restrict fishing in the bay to protect the dwindling population of sea turtles.","t":"新政策将**限制**海湾内的捕鱼活动，以保护数量日益减少的海龟种群。"},
"accurate":{"e":"The old barometer proved surprisingly accurate, predicting the sudden storm hours before any weather service did.","t":"这台旧气压计出人意料地**精准**，比任何气象部门都早了好几个小时预测出这场突如其来的风暴。"},
"comprise":{"e":"The full orchestra comprises nearly a hundred musicians, each trained for years at a top conservatory.","t":"整个交响乐团**由近百名音乐家组成**，个个都在顶尖音乐学院训练多年。"},
"enzyme":{"e":"A specific enzyme in human saliva begins breaking down starch the moment food enters the mouth.","t":"人类唾液中的一种特定**酶**，从食物进入口腔的那一刻起就开始分解淀粉。"},
"sumptuous":{"e":"The ambassador hosted a sumptuous banquet with imported wine and dishes prepared by three award-winning chefs.","t":"大使举办了一场**奢华**的宴会，备有进口美酒，还有三位得奖名厨掌勺的佳肴。"},
"allegiance":{"e":"New citizens must publicly pledge their allegiance to the country before receiving their naturalization certificates at the ceremony.","t":"新公民必须在仪式上公开宣誓对国家的**效忠**，才能领取入籍证书。"},
"invasion":{"e":"Historians still debate whether the invasion could have been prevented if the warnings had been taken seriously.","t":"历史学家至今仍在争论，如果当初认真对待那些警告，这场**入侵**是否本可以避免。"},
"cabinet":{"e":"The prime minister quietly reshuffled his entire cabinet after three ministers resigned amid the corruption scandal.","t":"在三名部长因腐败丑闻辞职后，首相悄然改组了整个**内阁**。"},
"hover":{"e":"A hummingbird hovered beside the feeder, its wings beating so fast they blurred into a haze.","t":"一只蜂鸟**悬停**在喂食器旁，翅膀扇动得太快，几乎模糊成一片。"},
"accuracy":{"e":"The archer practiced daily for years to improve the accuracy of her shots under windy conditions.","t":"这位射箭手多年来每天练习，只为提高在大风条件下射箭的**精准度**。"},
"expire":{"e":"Her passport will expire next month, so she needs to renew it before the family trip abroad.","t":"她的护照下个月就要**到期**了，所以得赶在全家出国旅行前把它续签好。"},
"gasoline":{"e":"The old truck guzzled so much gasoline that the farmer eventually switched to a smaller, more efficient model.","t":"这辆旧卡车太费**汽油**了，农场主最终换成了一辆更小、更省油的车型。"},
"angular":{"e":"The sculptor exaggerated the general's angular jaw and sharp cheekbones to convey his unyielding wartime resolve.","t":"雕塑家刻意夸大了将军**棱角分明**的下颌和高耸的颧骨，以此表现他在战时坚毅不屈的意志。"},
"immense":{"e":"The explorers stood in silence before the immense glacier that stretched farther than any of them could see.","t":"探险者们静静地站在这座**巨大**的冰川前，它绵延的距离超出了每个人的视野。"},
"percussion":{"e":"The conductor added extra percussion, including drums and cymbals, to intensify the symphony's thunderous final movement.","t":"指挥加入了额外的**打击乐器**，包括鼓和钹，让交响曲雷霆万钧的终章更加震撼。"},
"crooked":{"e":"Investigators eventually exposed the crooked accountant who had been quietly siphoning funds from client accounts for years.","t":"调查人员最终揭穿了这名**心术不正**的会计，他多年来一直在悄悄挪用客户账户里的资金。"},
"stratum":{"e":"The sprawling novel follows characters from every stratum of society, from factory workers to wealthy landowners.","t":"这部篇幅宏大的小说描写了社会各个**阶层**的人物，从工厂工人到富有的地主。"},
"instead":{"e":"Rather than apologize, the manager instead blamed the entire team for the mistake he himself had made.","t":"经理没有道歉，**反而**把自己犯下的错误怪罪到整个团队头上。"},
"populate":{"e":"Dense pine forests once populated this entire valley before decades of logging cleared the hillsides bare.","t":"在数十年的伐木活动将山坡砍伐殆尽之前，茂密的松树林曾**遍布**整个山谷。"},
"ultimate":{"e":"Winning a single match mattered less to her than the ultimate goal of qualifying for the Olympics.","t":"对她来说，赢下某一场比赛远不如获得奥运会参赛资格这个**最终**目标来得重要。"},
"evergreen":{"e":"Unlike the maples nearby, the evergreen pines kept their needles green throughout the harshest winter months.","t":"与附近的枫树不同，这些**常绿**松树即使在最严酷的冬季也依旧针叶青翠。"},
"plumage":{"e":"Male peacocks display their iridescent plumage in an elaborate fan to attract potential mates during breeding season.","t":"雄孔雀在繁殖季节会张开绚丽多彩的**羽毛**，展成一把精美的扇子来吸引配偶。"},
"decadent":{"e":"Critics called the emperor's final years decadent, marked by extravagant feasts while the empire slowly collapsed around him.","t":"评论家称这位皇帝的晚年**堕落颓废**，帝国在他周围渐渐崩塌之时，他仍沉溺于奢华的宴饮。"},
"subspecies":{"e":"Biologists recently identified a new subspecies of beetle isolated on the island for thousands of generations.","t":"生物学家最近确认了一个新的甲虫**亚种**，它在这座岛上已隔离演化了数千代。"},
"hummingbird":{"e":"A tiny hummingbird can beat its wings dozens of times per second while hovering beside a flower.","t":"一只小小的**蜂鸟**悬停在花朵旁时，每秒钟能振翅数十次。"},
"estate":{"e":"After her grandfather passed away, his entire estate was divided evenly among his four surviving grandchildren.","t":"祖父去世后，他全部的**遗产**被平均分给了四个在世的孙辈。"},
"stylistic":{"e":"The editor noted several jarring stylistic inconsistencies, where formal vocabulary suddenly gave way to casual slang.","t":"编辑指出了几处突兀的**文体**不一致之处，正式词汇忽然又变成了随意的俚语。"},
"declare":{"e":"All travelers must declare any amount of cash over ten thousand dollars when entering the country.","t":"所有旅客入境时，携带超过一万美元现金都必须**申报**。"},
"varnish":{"e":"The carpenter carefully varnished the oak table three times to give it a deep, glossy finish.","t":"木匠给这张橡木桌反复**上了三遍清漆**，让它呈现出深邃而有光泽的效果。"},
"wonder":{"e":"She often wondered why her brother never mentioned the accident that had changed their family forever.","t":"她常常**纳闷**，哥哥为什么从不提那场改变了全家命运的事故。"},
"justify":{"e":"No amount of profit can justify a company knowingly dumping toxic waste into a public river.","t":"无论获利多少，都不能为一家公司故意向公共河流倾倒有毒废物**开脱**。"},
"peninsula":{"e":"The narrow peninsula juts into the sea, connected to the mainland by only a thin strip of sand.","t":"这座狭长的**半岛**伸入大海，仅靠一条细窄的沙带与大陆相连。"},
"quiver":{"e":"A quiver ran through her hands as she stepped onto the stage for her very first solo performance.","t":"她第一次独奏登台时，双手不禁一阵**颤抖**。"},
"saunter":{"e":"Tourists sauntered lazily along the riverbank all afternoon, pausing occasionally to photograph the swans gliding past.","t":"游客们整个下午都沿着河岸悠闲地**闲逛**，不时停下来给滑过的天鹅拍照。"},
"tackle":{"e":"The new mayor promised to tackle the city's housing shortage within her first hundred days in office.","t":"新市长承诺要在上任的头一百天内**着手解决**这座城市的住房短缺问题。"},
"usher":{"e":"The usher politely guided latecomers to their seats only during a pause between the symphony's movements.","t":"**引座员**只在交响乐乐章之间的停顿时段，礼貌地引导迟到的观众入座。"},
"vigor":{"e":"Despite being well past eighty, the retired coach still spoke about basketball with youthful vigor and enthusiasm.","t":"尽管已年过八旬，这位退休教练谈起篮球时依然充满年轻人般的**活力**与热情。"},
"solitude":{"e":"After years of touring with a band, the musician finally craved the solitude of a quiet cabin.","t":"在乐队巡演多年后，这位音乐人终于渴望起一间安静小屋里的**独处**时光。"},
"apparatus":{"e":"The chemistry lab's expensive new apparatus allowed students to measure gas pressure with far greater precision.","t":"化学实验室新添的昂贵**装置**让学生们能够更精确地测量气体压力。"},
"vogue":{"e":"Bell-bottom jeans suddenly came back into vogue decades after they first defined an entire generation's style.","t":"喇叭牛仔裤在定义了整整一代人的风格几十年后，又重新变得**流行**起来。"},
"brace":{"e":"The captain told the crew to brace themselves as the ship plunged into the towering wave.","t":"船长让船员们**做好准备**，因为船正冲入一道高耸的巨浪之中。"},
"censor":{"e":"The censor removed three scenes from the film before it could be shown in theaters nationwide.","t":"**审查员**删掉了影片中的三个场景，之后它才得以在全国影院上映。"},
"respire":{"e":"Deep-sea fish have evolved specialized gills that allow them to respire in water with almost no oxygen.","t":"深海鱼进化出了特殊的鳃，使它们能在几乎不含氧气的水中**呼吸**。"},
"morphology":{"e":"The biology course devoted an entire unit to insect morphology, examining how wing shape affects flight.","t":"这门生物课用整整一个单元讲授昆虫**形态学**，研究翅膀形状如何影响飞行。"},
"moss":{"e":"Thick green moss covered the north side of nearly every tree in the damp, shaded forest.","t":"厚厚的绿色**苔藓**覆盖着这片潮湿阴暗的森林里几乎每棵树的北面。"},
"perch":{"e":"A lone falcon perched atop the cathedral spire, surveying the city below for hours without moving.","t":"一只孤独的猎鹰**栖息**在大教堂尖顶上，一动不动地俯瞰着下方的城市长达数小时。"},
"recipient":{"e":"As the sole recipient of her aunt's letters, she felt responsible for preserving them for future generations.","t":"作为姑姑来信的唯一**接收者**，她觉得自己有责任把这些信保存下来留给后代。"},
"fare":{"e":"Small family farms fared poorly during the drought, while large irrigated operations barely noticed the dry spell.","t":"干旱期间，小型家庭农场**境况**很糟，而大型灌溉农场几乎没受什么影响。"},
"neon":{"e":"Flickering neon signs lit up the narrow alley, advertising noodle shops that stayed open long after midnight.","t":"闪烁的**霓虹灯**招牌照亮了这条狭窄的小巷，为那些深夜仍营业的面馆打广告。"},
"permeate":{"e":"The smell of fresh bread permeated every corner of the small bakery from early morning onward.","t":"新鲜面包的香气从清晨开始就**弥漫**在这家小面包店的每个角落。"},
"midterm":{"e":"Every student in the crowded lecture hall looked exhausted the week before the midterm exam began.","t":"**期中**考试开始前的那一周，讲堂里每个学生看起来都精疲力竭。"},
"stress":{"e":"Chronic stress from the demanding job eventually forced him to see a doctor about his constant headaches.","t":"这份繁重工作带来的长期**压力**，最终迫使他就持续头痛的问题去看医生。"},
"digest":{"e":"Newborn infants cannot yet digest solid food, so they rely entirely on milk for the first months.","t":"新生婴儿还不能**消化**固体食物，所以出生后最初几个月完全依赖奶水。"},
"pancreas":{"e":"The human pancreas releases insulin into the bloodstream whenever blood sugar levels rise after a meal.","t":"每当餐后血糖升高，**胰腺**就会向血液中释放胰岛素。"},
"Gothic":{"e":"The cathedral's soaring Gothic spires and elegant pointed arches took nearly two centuries to fully complete.","t":"这座大教堂高耸的**哥特式**尖塔与优雅的尖拱，耗费了近两个世纪才最终建成。"},
"undergraduate":{"e":"As an undergraduate at a large state school, she switched majors three times before settling on marine biology.","t":"还是**本科生**时，她换了三次专业，最终才选定了海洋生物学。"},
"conversation":{"e":"A brief conversation with the mentor changed the direction of her entire career within a matter of minutes.","t":"与导师的一次简短**交谈**，在几分钟内就改变了她整个职业生涯的方向。"},
"rust":{"e":"The old bicycle had rusted so badly after years in the rain that the chain wouldn't turn.","t":"这辆旧自行车在雨中放了多年，已经**生锈**得厉害，链条根本转不动了。"},
"testimony":{"e":"The witness's testimony contradicted the police report, raising doubts about who had actually caused the accident.","t":"证人的**证词**与警方报告相互矛盾，让人对到底是谁造成了这场事故产生了怀疑。"},
"wick":{"e":"The candle's cotton wick burned down quickly, leaving nothing but a small puddle of melted wax.","t":"蜡烛的棉**烛芯**很快就燃尽了，只留下一小滩融化的蜡油。"},
"perish":{"e":"Thousands of sailors perished when the fleet was caught in an unexpected typhoon far from shore.","t":"当船队在远离海岸处遭遇突如其来的台风时，数以千计的水手**丧生**了。"},
"nocturnal":{"e":"Because owls are nocturnal hunters, they sleep through most of the daylight hours in hidden nests.","t":"由于猫头鹰是**夜行性**猎手，它们白天大部分时间都躲在隐蔽的巢里睡觉。"},
"application":{"e":"Her application for the summer internship arrived two days after the department's strict deadline had passed.","t":"她的暑期实习**申请**在系里严格的截止日期过去两天后才送到。"},
"distant":{"e":"After the bitter argument, her once-close cousin grew distant, replying to messages only after several days.","t":"那次激烈争吵之后，曾经亲密的表姐变得**疏远**起来，好几天才回一次消息。"},
"polygon":{"e":"The architect designed the pavilion's roof as an irregular polygon to mirror the shape of the lake below.","t":"建筑师把这座亭子的屋顶设计成一个不规则的**多边形**，以呼应下方湖泊的形状。"},
"arbitrary":{"e":"The judge criticized the new rule as arbitrary, noting it applied to some tenants but not others.","t":"法官批评这项新规**过于随意**，指出它只适用于部分租户，而非全体。"},
"membrane":{"e":"A thin membrane separates the egg's yolk from the surrounding white, keeping the two from mixing.","t":"一层薄薄的**膜**把蛋黄和周围的蛋清分隔开，使两者不会混在一起。"},
"venomous":{"e":"Hikers were warned that the venomous snake native to this canyon could strike without any visible provocation.","t":"徒步者被提醒，这个峡谷特有的**毒**蛇可能在毫无明显挑衅的情况下发起攻击。"},
"chamber":{"e":"The heart's left chamber pumps oxygenated blood out to every organ and muscle in the body.","t":"心脏左**心室**将富含氧气的血液泵送到全身每一个器官和肌肉。"},
"reversible":{"e":"Doctors reassured the family that this particular type of nerve damage was completely reversible with early treatment.","t":"医生向家属保证，这种特定类型的神经损伤只要及早治疗就完全**可以逆转**。"},
"sleek":{"e":"The new sports car's sleek, aerodynamic body cut through the wind with remarkably little resistance at speed.","t":"这辆新跑车**线条流畅**的空气动力学车身，高速行驶时阻力小得惊人。"},
"copilot":{"e":"When the captain suddenly fell ill, the copilot had to land the plane entirely on her own.","t":"机长突然病倒后，**副驾驶**不得不独自一人把飞机降落。"},
"variant":{"e":"Researchers quickly identified a new variant of the virus that spread more easily among unvaccinated populations.","t":"研究人员很快确认了这种病毒的一个新**变体**，它在未接种疫苗的人群中传播得更容易。"},
"choppy":{"e":"The small ferry rocked violently as it crossed the choppy waters stirred up by yesterday's storm.","t":"小渡轮猛烈摇晃着穿过昨日风暴掀起的**波涛汹涌**的水域。"},
"yolk":{"e":"She carefully separated the yolk from the egg white before whisking it into the smooth cake batter.","t":"她小心地把**蛋黄**从蛋白中分离出来，再打入细滑的蛋糕面糊中。"},
"cavern":{"e":"Explorers descended nearly a mile underground to reach the vast limestone cavern hidden beneath the mountain.","t":"探险者们向地下深入了近一英里，才抵达隐藏在山下那座巨大的石灰岩**洞穴**。"},
"landslide":{"e":"Heavy monsoon rains triggered a landslide that buried the mountain road under tons of mud and rock.","t":"强劲的季风降雨引发了一场**山体滑坡**，数吨泥石掩埋了这条山路。"},
"moor":{"e":"Fishermen moored their small boats along the harbor wall before the incoming tide grew too dangerous.","t":"渔民们趁着涨潮变得太危险之前，把小船**系泊**在港口的防波堤边。"},
"crescent":{"e":"A thin crescent moon hung low over the horizon, barely visible through the evening haze and clouds.","t":"一弯细细的**新月**低悬在地平线上，透过傍晚的薄雾和云层几乎看不清。"},
"missile":{"e":"The country secretly tested a new long-range missile capable of reaching targets thousands of miles away.","t":"这个国家秘密试射了一枚新型远程**导弹**，能够打击数千英里外的目标。"},
"mound":{"e":"Archaeologists carefully excavated an ancient burial mound and found pottery buried alongside the skeletal remains inside.","t":"考古学家仔细挖掘了一座古老的墓葬**土丘**，在骸骨旁发现了陪葬的陶器。"},
"creative":{"e":"The teacher encouraged creative solutions instead of forcing every student to follow the same rigid formula.","t":"老师鼓励**富有创造力**的解法，而不是强迫每个学生都套用同一套死板的公式。"},
"solo":{"e":"The young clarinetist's haunting solo silenced the entire concert hall for nearly a full minute afterward.","t":"这位年轻单簧管演奏者那段摄人心魄的**独奏**，让整个音乐厅安静了将近一分钟。"},
"volume":{"e":"The neighbors complained after he turned the volume up so high that windows across the street rattled.","t":"他把**音量**开得太大，震得街对面的窗户都在响，邻居们随即投诉了。"},
"temperate":{"e":"Grapes for this wine thrive only in the temperate valleys where summers stay mild and winters stay short.","t":"酿造这款葡萄酒的葡萄只在气候**温和**的山谷中茁壮生长，那里夏季凉爽，冬季短暂。"},
"asset":{"e":"Her fluency in three languages proved a tremendous asset when the firm expanded into overseas markets.","t":"公司拓展海外市场时，她精通三门语言成了一项极大的**优势**。"},
"cliff":{"e":"The lighthouse stood precariously at the edge of a cliff that had been eroding for decades.","t":"这座灯塔摇摇欲坠地矗立在一处已侵蚀了数十年的**悬崖**边缘。"},
"mess":{"e":"The accountant's sloppy record-keeping left the new manager with a financial mess that took months to untangle.","t":"这位会计做账马虎，给新经理留下了一团财务**烂摊子**，花了好几个月才理清。"},
"neutral":{"e":"Switzerland remained neutral throughout both world wars, refusing to align with either side of the conflict.","t":"瑞士在两次世界大战中始终保持**中立**，拒绝倒向冲突的任何一方。"},
"delight":{"e":"The magician's clever tricks delighted the children, who begged their parents to stay for a second show.","t":"魔术师巧妙的戏法让孩子们**欣喜不已**，他们央求父母留下来再看一场。"},
"plot":{"e":"Critics praised the novel's intricate plot, which wove three separate timelines into a single satisfying conclusion.","t":"评论家称赞这部小说**情节**精巧，将三条独立的时间线编织成一个圆满的结局。"},
"crustal":{"e":"Geologists study crustal movement along fault lines to predict where the next major earthquake might strike.","t":"地质学家研究断层沿线的**地壳**运动，以预测下一次大地震可能发生在哪里。"},
"glow":{"e":"Embers in the fireplace continued to glow faintly long after the family had gone upstairs to sleep.","t":"全家人上楼睡觉很久之后，壁炉里的余烬依然在微微**发光**。"},
"upset":{"e":"The unexpected cancellation upset her so much that she could barely focus on anything else that day.","t":"这次意外的取消让她**心烦意乱**，那一整天她几乎无法专注于其他任何事情。"},
"notate":{"e":"The composer painstakingly notated every subtle rhythm she had improvised during the previous night's long rehearsal.","t":"作曲家煞费苦心地把前一晚彩排时即兴创作的每一个细微节奏都**记录成乐谱符号**。"},
"pose":{"e":"The sudden rise in sea levels poses a serious threat to every low-lying coastal city on the planet.","t":"海平面骤然上升，对地球上每一座低洼沿海城市都**构成**严重威胁。"},
"hurricane":{"e":"Residents boarded up their windows and stocked emergency supplies as the massive hurricane approached the coastline overnight.","t":"居民们钉上窗板、囤积应急物资，因为这场强烈的**飓风**将在夜间逼近海岸。"},
"interact":{"e":"Scientists observed how the two chemicals interact when combined at extremely high temperatures in the lab.","t":"科学家观察了这两种化学物质在实验室高温下混合时如何**相互作用**。"},
"pore":{"e":"The lawyer pored over every clause of the contract, searching for language the other side might exploit.","t":"律师**仔细钻研**合同的每一条款，寻找对方可能利用的漏洞措辞。"},
"granular":{"e":"The soil sample had a coarse, granular texture that made it drain water far too quickly.","t":"这份土壤样本质地粗糙、**颗粒状**，导致排水速度过快。"},
"bead":{"e":"A bead of sweat rolled down the runner's forehead just seconds before she crossed the finish line.","t":"就在冲过终点线的前几秒，一颗**汗珠**从这位跑者额头滚落下来。"},
"craftsman":{"e":"Every chair in the workshop was built by hand, a testament to the craftsman's decades of patient skill.","t":"工坊里的每把椅子都是手工打造的，见证着这位**工艺师**数十年耐心磨练的技艺。"},
"grasp":{"e":"It took the young students several lessons to fully grasp the abstract concept of negative numbers.","t":"这些小学生花了好几节课，才彻底**理解**负数这个抽象概念。"},
"predict":{"e":"Meteorologists struggled to predict exactly when the storm would finally make landfall along the fragmented coastline.","t":"气象学家很难**预测**这场风暴究竟何时会在这段支离破碎的海岸线登陆。"},
"triangle":{"e":"The surveyor divided the irregular plot into a series of triangles to calculate its exact total area.","t":"测量员把这块不规则地块划分成一系列**三角形**，以计算出其精确的总面积。"},
"outcome":{"e":"Nobody could have predicted the outcome of the trial, which stunned even the most experienced attorneys present.","t":"没人能预料到这场审判的**结果**，连在场最资深的律师都感到震惊。"},
"decorate":{"e":"Volunteers spent the entire afternoon decorating the gymnasium with streamers and balloons for the graduation dance.","t":"志愿者们花了一整个下午用彩带和气球**装饰**体育馆，为毕业舞会做准备。"},
"unconsolidated":{"e":"Builders avoided that section of the hillside because the unconsolidated soil could collapse under heavy rain.","t":"建筑商避开了山坡的那一段，因为**松散**的土壤在暴雨下可能会塌方。"},
"citadel":{"e":"The ancient citadel had withstood countless sieges, its thick stone walls never once breached by an enemy.","t":"这座古老的**要塞**曾抵挡过无数次围攻，厚重的石墙从未被敌人攻破。"},
"pinpoint":{"e":"Investigators used satellite data to pinpoint the exact location where the signal had suddenly gone silent.","t":"调查人员利用卫星数据**精准定位**了信号突然中断的确切地点。"},
"hatch":{"e":"Sea turtle eggs typically hatch at night, when the newly emerged hatchlings face fewer predators on the beach.","t":"海龟蛋通常在夜间**孵化**，这样刚破壳而出的幼龟在沙滩上遭遇天敌的概率会更小。"},
"approach":{"e":"The therapist suggested a gentler approach, one that focused on small, achievable goals rather than sudden change.","t":"治疗师建议采用一种更温和的**方法**，专注于微小、可实现的目标，而非骤然的改变。"},
"fossil":{"e":"The museum's most prized fossil belonged to a dinosaur species no one had ever documented before.","t":"这家博物馆最珍贵的**化石**属于一种此前从未有人记录过的恐龙。"},
"turnpike":{"e":"Traffic on the turnpike crawled for hours after an overturned truck blocked three of the four lanes.","t":"一辆翻倒的卡车堵住了四条车道中的三条后，这条**收费公路**上的车流几个小时都寸步难行。"},
"detectable":{"e":"The gas leak was barely detectable until the technician used a specialized sensor near the pipeline joint.","t":"这处天然气泄漏原本几乎**无法察觉**，直到技术员在管道接口附近使用了专用传感器。"},
"contrast":{"e":"The documentary sharply contrasts the bustling capital with the quiet, unhurried villages scattered across the countryside.","t":"这部纪录片将喧嚣的首都与散布在乡间那些宁静悠然的村庄进行了鲜明的**对照**。"},
"oasis":{"e":"After three days crossing the dunes, the caravan finally reached an oasis ringed with date palms.","t":"穿越沙丘三天之后，商队终于抵达了一片被枣椰树环绕的**绿洲**。"},
"primary":{"e":"Reducing traffic accidents remained the city council's primary concern throughout the entire year-long infrastructure funding debate.","t":"在整整一年的基建拨款争论中，减少交通事故始终是市议会**首要**关切的问题。"},
"gulf":{"e":"A widening gulf between the two negotiating teams made any peaceful settlement seem increasingly unlikely to occur.","t":"谈判双方之间日益扩大的**分歧**，让和平解决方案看起来越来越不可能实现。"},
"pale":{"e":"Her face turned pale the moment she heard the news about the accident on the highway.","t":"一听到高速公路事故的消息，她的脸瞬间变得**苍白**。"},
"image":{"e":"The company spent millions rebuilding its damaged public image after the factory scandal made national headlines.","t":"工厂丑闻登上全国头条后，这家公司花费数百万重塑受损的公众**形象**。"},
"spherical":{"e":"Early astronomers had trouble accepting that the Earth was spherical rather than flat like a plate.","t":"早期天文学家很难接受地球是**球形**的，而非像盘子一样平坦。"},
"permit":{"e":"Construction cannot legally begin until the contractor obtains a permit from the city's building department office.","t":"承包商必须先从市建筑部门取得**许可证**，施工才能合法开始。"},
"addition":{"e":"The chef considered the roasted garlic a brilliant addition that transformed an otherwise perfectly ordinary soup.","t":"主厨认为烤蒜是绝妙的**添加食材**，让这道原本平平无奇的汤脱胎换骨。"},
"divorce":{"e":"Their bitter divorce dragged through the courts for nearly two years before the custody dispute was resolved.","t":"他们那场充满怨怼的**离婚**官司在法庭上拖了近两年，抚养权纠纷才终于解决。"},
"category":{"e":"The judges placed her sculpture in the wrong category, comparing it unfairly against much larger installations.","t":"评委把她的雕塑归错了**类别**，让它不公平地与规模大得多的装置作品相比较。"},
"portrait":{"e":"The artist spent six months painting a formal portrait of the retiring university president for the gallery.","t":"这位艺术家花了六个月为即将退休的大学校长绘制一幅正式**肖像**，供画廊收藏。"},
"dioxide":{"e":"Green plants absorb carbon dioxide from the surrounding air and release oxygen as a byproduct of photosynthesis.","t":"绿色植物从周围空气中吸收**二氧化碳**，并将氧气作为光合作用的副产物释放出来。"},
"methanol":{"e":"Some vehicles can run on methanol instead of gasoline, though the fuel produces less energy per gallon.","t":"有些车辆可以用**甲醇**代替汽油运行，尽管这种燃料每加仑产生的能量更少。"},
"feasible":{"e":"Engineers eventually concluded that building a bridge across the strait was technically feasible but prohibitively expensive.","t":"工程师们最终得出结论：跨海峡建桥在技术上**可行**，但造价高得令人望而却步。"},
"pleasing":{"e":"The garden's pleasing symmetry, with matching flower beds on either side, drew visitors back year after year.","t":"这座花园**赏心悦目**的对称布局，两侧花坛相互呼应，让游客年复一年地回访。"},
"score":{"e":"The visiting team's final score surprised everyone, since they had lost their last six games in a row.","t":"客队最终的**比分**让所有人大吃一惊，因为他们此前已经连输六场比赛。"},
"simply":{"e":"The solution wasn't complicated at all; the machine simply needed a new battery to start working again.","t":"解决办法一点也不复杂，这台机器**仅仅**需要换一块新电池就能重新运转。"},
"fertile":{"e":"Centuries of flooding left the river valley remarkably fertile, ideal for growing rice and wheat alike.","t":"数百年的洪水泛滥让这片河谷变得异常**肥沃**，非常适合种植水稻和小麦。"},
"penmanship":{"e":"Her grandmother's elegant penmanship made even a simple grocery list look like a piece of art.","t":"祖母优雅的**书法**，让哪怕一张简单的购物清单看起来也像一件艺术品。"},
"wispy":{"e":"Wispy clouds drifted high above the valley, too thin to block even a moment of sunlight.","t":"**纤薄**的云朵飘在山谷上方高空，稀薄得连一瞬间的阳光都遮不住。"},
"respect":{"e":"Employees respected the new supervisor almost immediately, impressed by how fairly she handled every single complaint.","t":"员工们几乎立刻就**尊重**起这位新主管，因为她处理每一桩投诉都十分公正。"},
"effluent":{"e":"The factory was fined heavily after inspectors traced toxic effluent leaking directly into the local river.","t":"调查人员追踪到有毒**污水**直接排入当地河流后，这家工厂受到了重罚。"},
"integrity":{"e":"Colleagues deeply admired the judge's integrity, knowing she would never let personal relationships sway her rulings.","t":"同事们都深深敬佩这位法官的**正直**，知道她绝不会让私人关系左右自己的判决。"},
"zone":{"e":"City planners designated the riverfront a protected zone, banning any new construction within a hundred meters.","t":"城市规划者将河滨地带划定为受保护**区域**，禁止在一百米范围内进行任何新建工程。"},
"jar":{"e":"The sudden, blaring alarm jarred everyone awake at three in the morning, sending the whole house into panic.","t":"凌晨三点，突如其来的刺耳警报把所有人都**惊醒**了，全家顿时陷入恐慌。"},
"accordion":{"e":"An old man on the street corner played the accordion, filling the square with a cheerful folk melody.","t":"街角一位老人弹奏着**手风琴**，欢快的民谣旋律回荡在整个广场上。"},
"sodium":{"e":"Doctors advised him to cut sodium from his diet after his blood pressure climbed dangerously high.","t":"医生建议他在血压危险地升高后，从饮食中减少**钠**的摄入。"},
"centennial":{"e":"The small town organized a parade and fireworks display to celebrate the centennial of its founding.","t":"这座小镇组织了一场游行和烟花表演，庆祝建镇**百年纪念**。"},
"series":{"e":"A series of small tremors preceded the major earthquake by nearly two weeks, though few residents noticed.","t":"在这次大地震发生前近两周，曾出现**一系列**小型震动，但很少有居民注意到。"},
"tendon":{"e":"The sprinter tore a tendon in her ankle just meters from the finish line during the final race.","t":"这位短跑运动员在决赛的最后几米处，脚踝的**肌腱**不幸撕裂。"},
"maturity":{"e":"The vineyard's oldest vines finally reached full maturity after nearly a decade of careful, patient cultivation.","t":"这片葡萄园里最老的葡萄藤，历经近十年的悉心栽培,终于**成熟**了。"},
"boulder":{"e":"A massive boulder blocked the trail, forcing hikers to scramble around it through the dense underbrush.","t":"一块巨大的**石砾**挡住了小径，徒步者只得绕过茂密的灌木丛才能通过。"},
"careless":{"e":"A careless mistake in the lab report cost the entire team several points on their final grade.","t":"实验报告里一个**粗心**的错误，让整个小组的期末成绩被扣掉了好几分。"},
"clarify":{"e":"The spokesperson held a press conference to clarify the company's confusing statement from earlier that week.","t":"发言人召开新闻发布会，**澄清**公司本周早些时候那份令人困惑的声明。"},
"relay":{"e":"The scout climbed the ridge to relay news of the approaching enemy column back to camp.","t":"侦察兵爬上山脊，把敌军纵队逼近的消息**转达**回营地。"},
"molten":{"e":"Molten rock poured from the fissure and slowly hardened into a black glassy ridge across the valley floor.","t":"**熔化的**岩浆从裂缝中喷涌而出，缓缓凝固成横贯谷底的黑色玻璃状山脊。"},
"acute":{"e":"The refugees faced an acute shortage of clean water, and aid workers scrambled to truck in emergency supplies before disease spread.","t":"难民面临着**严重的**清洁水资源短缺，救援人员匆忙运送应急物资以防疫病蔓延。"},
"diverse":{"e":"The rainforest supports an extraordinarily diverse array of insects, many of which scientists have yet to name or classify.","t":"这片雨林孕育着**多种多样**的昆虫，其中许多至今仍未被科学家命名或分类。"},
"meteorite":{"e":"A meteorite the size of a grapefruit crashed through the farmhouse roof and left a smoking crater in the kitchen floor.","t":"一颗葡萄柚大小的**陨石**砸穿了农舍屋顶，在厨房地板上留下一个冒烟的坑。"},
"shrub":{"e":"Gardeners pruned the flowering shrub every autumn, shaping its tangled branches into a neat rounded dome beside the porch.","t":"园丁每年秋天都会修剪这丛开花的**灌木**，把它纠结的枝条修整成门廊旁一个浑圆的花丛。"},
"orient":{"e":"New students spent the first week orienting themselves to campus, memorizing shortcuts between the library and the dining hall.","t":"新生们花了第一周的时间**熟悉**校园方位，记住图书馆和食堂之间的近路。"},
"pinnacle":{"e":"Winning the championship marked the pinnacle of her career, a moment she had trained toward since she was seven years old.","t":"赢得冠军标志着她职业生涯的**顶峰**，这是她从七岁起就一直为之训练的时刻。"},
"endless":{"e":"The desert highway stretched on in an endless straight line, with no gas station or tree breaking the horizon for hours.","t":"沙漠公路笔直延伸，**望不到尽头**，几个小时里既没有加油站也没有树木打破地平线的单调。"},
"frigid":{"e":"A frigid wind swept off the glacier and cut straight through the climbers' jackets before they could reach the shelter.","t":"一阵**刺骨寒冷的**风从冰川上刮来，攀登者还没赶到庇护所就已经冻透了外套。"},
"fluid":{"e":"Mechanics traced the brake failure to a slow fluid leak that had been dripping onto the garage floor for weeks.","t":"技师们查明刹车失灵的原因是一处缓慢渗漏的**液体**，几周来一直滴落在车库地面上。"},
"crack":{"e":"The old ceramic vase cracked down the middle the moment the delivery box was dropped onto the concrete steps.","t":"快递箱一摔到水泥台阶上，那只旧陶瓷花瓶就从中间**裂开**了。"},
"tectonic":{"e":"Geologists attributed the sudden earthquake to shifting tectonic plates grinding against each other far beneath the ocean floor.","t":"地质学家将这场突发地震归因于深海海底相互摩擦挤压的**地壳构造**板块运动。"},
"democrat":{"e":"As a lifelong democrat, she believed every citizen deserved an equal voice, regardless of wealth, education, or social standing.","t":"作为一名终身的**民主主义者**，她认为无论贫富、学历或社会地位如何，每个公民都应享有平等的发言权。"},
"photodissociation":{"e":"Ultraviolet radiation triggers photodissociation in the upper atmosphere, splitting oxygen molecules apart and eventually forming the protective ozone layer.","t":"紫外线辐射在高层大气中引发**光解作用**，将氧分子分裂开来，并最终形成具有保护作用的臭氧层。"},
"soprano":{"e":"The soprano's voice soared above the entire orchestra during the final aria, silencing even the restless children in the back row.","t":"在最后一首咏叹调中，这位**女高音**的歌声高过了整个管弦乐团，连后排坐不住的孩子们都安静了下来。"},
"format":{"e":"The magazine switched to a smaller format last year, trading its bulky glossy pages for a compact size that fits in a bag.","t":"这本杂志去年改用更小的**版式**，把厚重的铜版纸页面换成了能装进包里的紧凑尺寸。"},
"expressive":{"e":"Her hands were remarkably expressive on stage, conveying grief and hope in the same gesture without a single spoken word.","t":"她在舞台上的双手异常**富有表现力**，一个手势便传达出悲伤与希望，无需一言一语。"},
"acidity":{"e":"Winemakers measure the acidity of each batch carefully, since even a slight imbalance can make the final wine taste flat or sour.","t":"酿酒师会仔细测量每一批酒液的**酸度**，因为哪怕轻微的失衡都会让成品酒尝起来寡淡或过酸。"},
"focalize":{"e":"The lecture helped focalize the students' scattered ideas about the novel into a single, defensible argument for their essays.","t":"这堂讲座帮助学生们把关于这部小说的零散想法**聚焦**成一个站得住脚的论点，用于他们的论文。"},
"observatory":{"e":"Visitors climbed the winding stairs of the mountaintop observatory to peer through its enormous telescope at Saturn's rings.","t":"游客们爬上山顶**天文台**蜿蜒的楼梯，透过巨大的望远镜窥视土星环。"},
"prospector":{"e":"The old prospector panned the icy creek for months, convinced that a vein of gold lay hidden somewhere upstream.","t":"那位老**淘金者**在冰冷的小溪里淘洗了数月，坚信上游某处藏着一条金矿脉。"},
"rotational":{"e":"The factory adopted a rotational schedule so that no single team of workers had to cover every night shift alone.","t":"工厂采用了**轮班制**的排班表，这样就不会只有一个班组独自负责所有夜班。"},
"swampy":{"e":"The trail turned swampy after the storm, and hikers sank ankle-deep into mud with every careless step they took.","t":"暴风雨过后小径变得**泥泞沼泽**，徒步者每走错一步都会陷进没过脚踝的烂泥里。"},
"troposphere":{"e":"Nearly all weather we experience, from thunderstorms to gentle breezes, forms within the troposphere, the atmosphere's lowest and densest layer.","t":"我们经历的几乎所有天气现象，从雷暴到微风，都形成于**对流层**——大气层中最低也最稠密的一层。"},
"wintry":{"e":"A wintry silence settled over the negotiating table after the CEO flatly refused to consider the union's latest proposal.","t":"首席执行官断然拒绝考虑工会最新提议后，谈判桌上笼罩着一片**冷淡**的沉默。"},
"buoyant":{"e":"Despite the layoffs elsewhere in the industry, the startup remained buoyant, confident that its new app would attract investors.","t":"尽管业内其他公司都在裁员，这家初创企业依然**乐观向好**，相信自己的新应用能吸引投资者。"},
"cement":{"e":"The two companies' shared struggle during the recession helped cement a partnership that has lasted more than twenty years.","t":"这两家公司在经济衰退期间共同的挣扎经历，**巩固**了一段延续二十多年的合作关系。"},
"spatial":{"e":"Architects rely on strong spatial reasoning to imagine how a flat blueprint will feel once it becomes a three-dimensional room.","t":"建筑师依靠出色的**空间**推理能力，去想象一张平面蓝图变成立体房间后的实际感受。"},
"dynamical":{"e":"The professor modeled the solar system as a dynamical system, where every planet's motion depends on the pull of every other body.","t":"教授把太阳系建模为一个**动态**系统，其中每颗行星的运动都取决于其他天体的引力。"},
"entity":{"e":"Although the two departments share an office, the accounting team operates as a separate entity with its own budget and manager.","t":"尽管这两个部门共用一间办公室，会计团队仍作为一个独立的**实体**运作，拥有自己的预算和经理。"},
"fusion":{"e":"Scientists have spent decades trying to harness nuclear fusion, hoping it might one day supply the planet with nearly limitless clean energy.","t":"科学家们数十年来一直试图驾驭核**聚变**，希望有朝一日它能为地球提供近乎无限的清洁能源。"},
"hydraulic":{"e":"A hydraulic lift raised the entire bus off the ground so mechanics could inspect the engine and axles underneath.","t":"一台**液压**升降机把整辆公交车抬离地面，方便技师检查下方的发动机和车轴。"},
"allergy":{"e":"His allergy to peanuts was so severe that even trace amounts in shared kitchen equipment could send him to the hospital.","t":"他对花生的**过敏反应**极为严重，哪怕共用厨具上残留的微量成分都可能让他被送进医院。"},
"variable":{"e":"Before drawing conclusions from the experiment, the researchers had to control every variable that might have skewed the results.","t":"在从实验中得出结论之前，研究人员必须控制每一个可能扭曲结果的**变量**。"},
"evolution":{"e":"Textbooks trace the evolution of the telephone from a bulky wall-mounted box to a slim device that fits inside a pocket.","t":"教科书追溯了电话的**演变**历程，从笨重的壁挂式装置演变成能装进口袋的纤薄设备。"},
"representative":{"e":"A union representative met with management every Friday to negotiate better wages and safer conditions on the factory floor.","t":"一位工会**代表**每周五都会与管理层会面，为工厂车间争取更好的薪资和更安全的条件。"},
"crystallize":{"e":"Her vague ambitions finally crystallized into a concrete plan the summer she watched her first documentary about deep-sea creatures.","t":"那年夏天，她看了第一部关于深海生物的纪录片后，模糊的志向终于**明确**成了一个具体计划。"},
"gorgeous":{"e":"The bride wore a gorgeous gown embroidered with tiny pearls that caught the light every time she moved across the dance floor.","t":"新娘穿着一件**华丽**的礼服，上面绣满细小的珍珠，每次她走过舞池都会闪闪发光。"},
"angle":{"e":"The journalist approached the corruption scandal from an unusual angle, focusing on the janitors who had quietly witnessed everything.","t":"这位记者从一个不寻常的**角度**切入这桩腐败丑闻，聚焦于那些默默目睹一切的清洁工。"},
"impose":{"e":"The city council voted to impose a strict curfew on the downtown area after three consecutive nights of vandalism.","t":"市议会投票决定在市中心地区**实施强制**宵禁，此前该地区已连续三晚发生破坏公物事件。"},
"apologize":{"e":"The airline apologized publicly for the canceled flights and offered every stranded passenger a full refund plus a hotel voucher.","t":"这家航空公司就航班取消一事公开**道歉**，并向每位滞留的乘客提供全额退款和酒店代金券。"},
"pump":{"e":"Firefighters pumped thousands of gallons of water from the nearby lake to keep the wildfire from reaching the town.","t":"消防员从附近的湖里**抽取**了数千加仑水，以阻止野火蔓延到镇上。"},
"marine":{"e":"Marine biologists tagged the migrating whales off the coast to track their route through the Pacific over the next year.","t":"**海洋**生物学家给近海迁徙的鲸鱼做了标记，以便在接下来一年追踪它们穿越太平洋的路线。"},
"board":{"e":"The board rejected the merger proposal unanimously, arguing that it would leave the smaller company with almost no independent control.","t":"**董事会**一致否决了这项并购提案，认为这将使较小的公司几乎丧失独立控制权。"},
"colleague":{"e":"A trusted colleague covered her classes for the week she spent in the hospital recovering from a minor surgery.","t":"她住院做小手术恢复的那一周，一位值得信赖的**同事**替她代了课。"},
"orientation":{"e":"All new employees attend a two-day orientation, where they learn company policies and meet the colleagues on their team.","t":"所有新员工都要参加为期两天的**入职培训**，学习公司政策并结识本团队的同事。"},
"aggressive":{"e":"The company launched an aggressive marketing campaign, flooding every social media platform with ads within a single weekend.","t":"这家公司发起了一场**强势**的营销活动，一个周末内就让各大社交媒体平台上充斥着广告。"},
"cling":{"e":"The frightened toddler clung to her father's leg and refused to let go even after the dog had left the room.","t":"受惊的小女孩**紧紧抱住**父亲的腿，即使那只狗已经离开房间也不肯松手。"},
"output":{"e":"The new assembly line doubled the factory's daily output without requiring a single additional worker on the floor.","t":"新的装配线使工厂的日**产量**翻了一番，却无需在车间增加一名工人。"},
"hostile":{"e":"The negotiators walked into a visibly hostile room, where the striking workers glared at management across a narrow table.","t":"谈判代表走进一间明显充满**敌意**的房间，罢工工人隔着一张窄桌怒视着管理层。"},
"tile":{"e":"The contractor spent an entire week laying tile across the bathroom floor, cutting each piece to fit around the drain.","t":"承包商花了整整一周时间在浴室地面铺**瓷砖**，把每一块都裁切得能绕开排水口。"},
"undertaking":{"e":"Restoring the crumbling cathedral turned out to be a far larger undertaking than the city's engineers had originally anticipated.","t":"修复这座摇摇欲坠的大教堂，最终被证明是一项远比市里工程师最初预想更庞大的**工程**。"},
"sloth":{"e":"The sloth moved so slowly across the branch that algae had time to grow in the fur along its back.","t":"这只**树懒**在树枝上移动得如此缓慢，以至于藻类都有时间在它背上的毛皮里生长。"},
"popular":{"e":"The professor's lecture on black holes became so popular that students lined up an hour early just to find a seat.","t":"这位教授关于黑洞的讲座变得极其**受欢迎**，学生们提前一小时排队只为占到一个座位。"},
"furry":{"e":"A furry creature darted across the porch light's beam and vanished into the hedge before anyone could tell what it was.","t":"一个**毛茸茸的**生物窜过门廊灯光的光束，消失在树篱里，谁都没看清那是什么。"},
"luminosity":{"e":"Astronomers rank stars partly by luminosity, comparing how much light each one actually radiates rather than how bright it merely appears from Earth.","t":"天文学家部分依据**光度**给恒星分级，比较的是每颗恒星实际辐射的光量，而非它在地球上看起来有多亮。"},
"outermost":{"e":"Neptune, the outermost planet in our solar system, takes about a hundred and sixty-five years to complete a single orbit.","t":"海王星是我们太阳系中**最外层**的行星，绕太阳运行一周大约需要一百六十五年。"},
"slight":{"e":"Even a slight change in temperature inside the greenhouse could cause the delicate orchids to wilt within a few hours.","t":"即使温室内的温度只有**轻微**变化，也可能让娇嫩的兰花在几个小时内枯萎。"},
"butter":{"e":"She spread a thick layer of butter across the warm toast before the last bit of steam had escaped.","t":"趁着最后一丝热气还没散尽，她在温热的吐司上厚厚地抹了一层**黄油**。"},
"vegetative":{"e":"During its vegetative stage, the tomato plant channels nearly all its energy into growing leaves and stems rather than fruit.","t":"在**营养生长**阶段，番茄植株几乎把所有能量都用于长叶和长茎，而非结果。"},
"plasma":{"e":"Inside the sun's core, matter exists as plasma, a superheated state in which electrons are stripped entirely from their atoms.","t":"在太阳核心内部，物质以**等离子体**的形式存在，这是一种电子完全从原子中剥离出来的超高温状态。"},
"swarm":{"e":"Bees swarmed around the broken hive, frantically searching for a new queen to lead them to safety.","t":"蜜蜂**成群聚集**在破损的蜂巢周围，疯狂寻找一只能带领它们走向安全的新蜂后。"},
"locomotion":{"e":"Snakes achieve locomotion without any limbs at all, rippling their muscles in waves that push against the ground beneath them.","t":"蛇完全没有四肢也能实现**移动**，它们让肌肉呈波浪状起伏，从而推动身体压向地面前进。"},
"utmost":{"e":"The surgeon handled the newborn with the utmost care, aware that a single wrong movement could cause lasting harm.","t":"外科医生以**极其**谨慎的态度对待这名新生儿，深知任何一个错误动作都可能造成持久的伤害。"},
"dignity":{"e":"Even after losing everything in the flood, the old farmer carried himself with a quiet dignity that impressed every volunteer.","t":"即便在洪水中失去了一切，这位老农依然保持着一种令每位志愿者都印象深刻的静默**尊严**。"},
"spot":{"e":"A sharp-eyed birdwatcher spotted the rare falcon perched motionless on a cliff ledge nearly half a mile away.","t":"一位眼力敏锐的观鸟者**发现**了那只罕见的隼，它一动不动地栖息在近半英里外的悬崖边上。"},
"bud":{"e":"The cherry trees along the avenue had already begun to bud, promising a brief but spectacular week of blossoms.","t":"大道两旁的樱桃树已经开始**萌芽**，预示着即将迎来短暂却绚烂的一周花期。"},
"remainder":{"e":"After dividing the prize money among the five founders, they donated the remainder to the charity that had first believed in them.","t":"在五位创始人分完奖金后，他们把**剩余的部分**捐给了最初相信他们的那家慈善机构。"},
"depend":{"e":"Whether the picnic happens tomorrow will depend entirely on whether the storm clears out of the valley by morning.","t":"明天野餐能否进行，完全**取决于**暴风雨是否能在早晨之前离开山谷。"},
"slumber":{"e":"The old cat slumbered on the windowsill all afternoon, undisturbed by the children shouting in the yard below.","t":"那只老猫整个下午都在窗台上**沉睡**，丝毫没被楼下院子里孩子们的喊叫声打扰。"},
"strive":{"e":"Every coach on the team strives to build character in young athletes, not merely to win the next tournament.","t":"这支队伍里的每位教练都**努力**培养年轻运动员的品格，而不仅仅是为了赢得下一场比赛。"},
"figure":{"e":"Historians still debate whether the explorer was a heroic figure or simply a ruthless opportunist who got lucky.","t":"历史学家至今仍在争论，这位探险家究竟是一位英雄**人物**，还是仅仅一个走运的无情投机者。"},
"assimilate":{"e":"Immigrant children often assimilate the new language faster than their parents, absorbing slang from classmates within just a few months.","t":"移民儿童往往比他们的父母更快**吸收**新语言，几个月内就能从同学那里学会俚语。"},
"credit":{"e":"The coach credited the team's unexpected victory to months of grueling early-morning practices that nobody outside the locker room ever saw.","t":"教练把球队出人意料的胜利**归功于**数月来外人从未见过的艰苦晨练。"},
"spaghetti":{"e":"The toddler grabbed a fistful of spaghetti and flung it across the kitchen before anyone could stop him.","t":"那个小孩一把抓起一把**意大利面**，还没等人来得及阻止就扔到了厨房各处。"},
"outcry":{"e":"The proposed demolition of the historic theater sparked a public outcry, and hundreds of residents signed a petition within days.","t":"拆除这座历史剧院的提议引发了公众的强烈**抗议**，数百名居民在几天内签署了请愿书。"},
"inertia":{"e":"Years of bureaucratic inertia kept the outdated regulation on the books long after everyone agreed it made no sense.","t":"多年的官僚**惰性**使这条过时的规定一直留在法典里，尽管早就人人都认为它毫无道理。"},
"shrimp":{"e":"Fishermen hauled up nets bursting with shrimp before dawn, racing to get the fresh catch to market by sunrise.","t":"渔民们在黎明前拖起装满**虾**的渔网，抢着在日出前把新鲜的渔获运到市场。"},
"editorial":{"e":"The newspaper's editorial condemned the mayor's proposal, calling it a shortsighted attempt to please wealthy donors at taxpayer expense.","t":"这家报纸的**社论**谴责了市长的提案，称其为一次目光短浅、意图讨好富有捐助者却让纳税人埋单的举动。"},
"focus":{"e":"The therapist encouraged him to focus on small, achievable goals instead of dwelling on everything that had gone wrong that year.","t":"治疗师鼓励他**专注于**小而可实现的目标，而不是纠结于那一年出错的所有事情。"},
"soybean":{"e":"Farmers across the region switched from corn to soybean crops after prices for the legume climbed sharply on the global market.","t":"在**大豆**价格在全球市场大幅上涨后，该地区的农民纷纷把玉米地改种大豆。"},
"annoyed":{"e":"She grew visibly annoyed when the waiter brought the wrong order for the third time in a single evening.","t":"服务员在同一个晚上第三次上错菜时，她已经明显**生气**了。"},
"banner":{"e":"Volunteers strung a hand-painted banner across the finish line, welcoming every marathon runner by name as they crossed.","t":"志愿者们在终点线上拉起一条手绘的**横幅**，每位跑者冲线时都被点名欢迎。"},
"factor":{"e":"Diet is only one factor influencing how quickly an athlete recovers between grueling training sessions each week.","t":"饮食只是影响运动员在每周高强度训练之间恢复速度的众多**因素**之一。"},
"infiltrate":{"e":"Undercover agents infiltrated the smuggling ring for nearly a year before making a single arrest, gathering evidence patiently.","t":"卧底特工**潜入**这个走私团伙近一年，耐心收集证据，直到才实施第一次抓捕。"},
"leach":{"e":"Heavy rain gradually leached essential nutrients out of the topsoil, leaving the once-fertile field nearly barren within a decade.","t":"大雨逐渐把重要养分从表层土壤中**溶滤**出去，使这片曾经肥沃的田地在十年内几近贫瘠。"},
"momentum":{"e":"The campaign lost momentum after the scandal broke, and donations that had once poured in slowed to a trickle.","t":"丑闻曝光后，这场竞选失去了**势头**，曾经如潮水般涌入的捐款也逐渐减少到涓涓细流。"},
"odorous":{"e":"The odorous marsh gas seeping from the swamp forced the survey team to wrap bandanas around their noses and mouths.","t":"沼泽中渗出的**气味刺鼻的**沼气迫使勘测队用头巾裹住口鼻。"},
"percolate":{"e":"Rumors of the merger percolated through the office for weeks before management finally confirmed the news at a staff meeting.","t":"关于并购的传闻在办公室里**逐渐流传**了好几周，管理层这才终于在员工大会上证实了这一消息。"},
"supersonic":{"e":"The experimental jet reached supersonic speed within seconds of takeoff, producing a sonic boom that rattled windows for miles.","t":"这架实验喷气机起飞几秒钟内就达到了**超音速**，产生的音爆震得数英里外的窗户都在颤动。"},
"thermal":{"e":"The glider pilot circled patiently until she found a strong thermal that lifted her thousands of feet without using any engine.","t":"滑翔机飞行员耐心盘旋，直到找到一股强劲的**上升热气流**，不借助任何引擎就把她带升到数千英尺高空。"},
"coefficient":{"e":"Engineers had to calculate the friction coefficient between the tire rubber and the wet asphalt before certifying the car safe.","t":"工程师必须先算出轮胎橡胶与湿沥青路面之间的摩擦**系数**，才能认证这辆车的安全性。"},
"differential":{"e":"Economists studied the wage differential between men and women in the same job to measure how much discrimination still persisted.","t":"经济学家研究了从事同一工作的男女之间的薪酬**差异**，以此衡量歧视现象仍有多严重。"},
"vaporize":{"e":"The intense laser beam vaporized the thin metal sheet almost instantly, leaving nothing but a faint wisp of smoke.","t":"强烈的激光束几乎瞬间就把这片薄薄的金属板**汽化**了，只留下一缕淡淡的青烟。"},
"waggle":{"e":"The puppy waggled its whole hindquarters with excitement the instant it heard the sound of the treat bag opening.","t":"小狗一听到零食袋打开的声音，整个后半身就兴奋地**摇摆**起来。"},
"approximation":{"e":"The contractor's initial quote was only a rough approximation, and the final bill ended up nearly double that estimate.","t":"承包商最初的报价只是一个粗略的**估算值**，最终账单竟高达该估计的近两倍。"},
"bisect":{"e":"A single dirt road bisects the ranch, separating the grazing pastures from the fields where the family grows wheat.","t":"一条土路把这座牧场**一分为二**，将放牧的草场与这家人种小麦的田地分隔开来。"},
"calculable":{"e":"Insurance premiums rely on risks being calculable, which is why insurers struggle to price coverage against wholly unprecedented disasters.","t":"保险费率的设定依赖于风险是**可计算的**，这就是为什么保险公司很难为前所未有的灾难定价。"},
"ellipse":{"e":"Kepler discovered that each planet traces an ellipse around the sun rather than the perfect circle astronomers had long assumed.","t":"开普勒发现，每颗行星绕太阳运行的轨迹是**椭圆形**，而非天文学家长期以来所假设的完美圆形。"},
"dividend":{"e":"Shareholders cheered when the company announced its largest quarterly dividend in a decade, rewarding investors who had stayed patient.","t":"当公司宣布派发十年来最高的季度**股息**时，股东们欢呼雀跃，那些耐心持股的投资者终于得到了回报。"},
"formula":{"e":"The chemist scribbled the formula on a napkin, certain she had finally found a stable compound that wouldn't degrade in sunlight.","t":"化学家在一张餐巾纸上潦草地写下**化学式**，确信自己终于找到了一种不会在阳光下降解的稳定化合物。"},
"weathering":{"e":"Centuries of weathering had worn the once-sharp inscriptions on the tombstone down to barely visible grooves in the stone.","t":"数百年的**风化**侵蚀已把墓碑上曾经清晰的铭文磨损得只剩下几乎看不见的沟槽。"},
"tarnish":{"e":"A single dishonest remark to reporters tarnished the senator's reputation for integrity that had taken decades to build.","t":"对记者说的一句不诚实的话，就**玷污**了这位参议员花了数十年才建立起来的诚信声誉。"},
"inquire":{"e":"A cautious neighbor inquired about the strange noises coming from the abandoned house before finally calling the police.","t":"一位谨慎的邻居先**打听**了那栋废弃房屋传来的怪声，然后才终于报了警。"},
"extrapolate":{"e":"From just a handful of fossil fragments, the paleontologist extrapolated the creature's full size and probable hunting behavior.","t":"仅凭几块化石碎片，古生物学家就**推断**出了这种生物的完整体型和可能的捕猎行为。"},
"remains":{"e":"Archaeologists carefully brushed away centuries of sediment to uncover the remains of a Roman bathhouse beneath the parking lot.","t":"考古学家小心翼翼地刷去数百年沉积的泥土，发掘出停车场下方一座罗马浴场的**遗迹**。"},
"flexibility":{"e":"Working remotely gave employees far more flexibility to arrange their schedules around childcare, doctor visits, and other daily obligations.","t":"远程办公让员工在安排日程时拥有更大的**灵活性**，能兼顾接送孩子、看医生和其他日常事务。"},
"mural":{"e":"Local students spent the summer painting a vibrant mural across the school's entire back wall, depicting the town's founding families.","t":"当地学生花了一整个夏天在学校后墙上绘制了一幅色彩鲜艳的**壁画**，描绘这座小镇的建镇家族。"},
"balance":{"e":"Working parents constantly struggle to balance long office hours with the attention their young children still desperately need.","t":"职场父母不断挣扎着，要在漫长的办公时间和年幼孩子仍然迫切需要的关注之间**取得平衡**。"},
"telegraph":{"e":"Before telephones became common, families separated by war relied on the telegraph to send brief but urgent news home.","t":"在电话普及之前，被战争分隔两地的家庭全靠**电报**发送简短却紧急的家书。"},
"privilege":{"e":"Growing up with running water and electricity was a privilege that many children in the region simply never had.","t":"从小就能用上自来水和电，是该地区许多孩子从未享有过的**特权**。"},
"chart":{"e":"The old captain had charted every reef in these waters by hand, long before satellite navigation existed.","t":"早在卫星导航出现之前，这位老船长就已经徒手**绘制**出了这片水域中每一处暗礁的图。"},
"scan":{"e":"The lifeguard scanned the crowded beach every few minutes, watching for any swimmer who drifted too close to the rip current.","t":"救生员每隔几分钟就会**扫视**一遍拥挤的海滩，留意有没有泳客漂得太靠近离岸流。"},
"congress":{"e":"Congress spent months debating the budget bill before finally reaching a compromise that neither party found entirely satisfying.","t":"**国会**花了数月时间辩论这项预算法案，最终才达成一项两党都不完全满意的妥协方案。"},
"amenity":{"e":"The new apartment complex advertises amenities like a rooftop pool, a fitness center, and free parking for every resident.","t":"这个新公寓楼盘宣传的**便利设施**包括屋顶泳池、健身中心以及为每位住户提供的免费停车位。"},
"pretension":{"e":"The chef abandoned any pretension to fine dining and simply served hearty, unpretentious stews in mismatched bowls.","t":"这位厨师放弃了任何追求高级餐饮的**虚饰**，只是用不成套的碗盛上丰盛朴实的炖菜。"},
"sensual":{"e":"The poet's imagery was intensely sensual, dwelling on the taste of ripe fruit and the warmth of sunlight on skin.","t":"这位诗人的意象极具**感官**色彩，反复描写熟透水果的味道和阳光洒在肌肤上的温暖。"},
"grimly":{"e":"The surgeon nodded grimly and told the family that the next twenty-four hours would determine whether the patient survived.","t":"外科医生**严峻地**点了点头，告诉家属接下来的二十四小时将决定病人能否挺过去。"},
"mechanics":{"e":"Understanding the mechanics of negotiation helped her secure a far better salary than she had expected during the interview.","t":"掌握谈判的**技巧方法**帮助她在面试中争取到了远超预期的薪资。"},
"presentation":{"e":"The intern's presentation to the board impressed even the skeptical executives, who had expected a far less polished pitch.","t":"这位实习生向董事会做的**陈述**给一向持怀疑态度的高管们都留下了深刻印象，他们本以为提案会远不够精致。"},
"ancient":{"e":"Beneath the modern highway, workers discovered the foundations of an ancient settlement dating back more than three thousand years.","t":"在这条现代公路下方，工人们发现了一座可追溯到三千多年前的**古代**聚落遗址地基。"},
"picturesque":{"e":"Tourists flock to the picturesque fishing village every summer to photograph its pastel cottages perched along the rocky harbor.","t":"游客们每年夏天都会涌向这座**如画**般的渔村，拍摄沿着礁石港湾错落分布的粉彩小屋。"},
"portable":{"e":"The nurse carried a portable oxygen tank up three flights of stairs to reach the elderly patient stranded during the power outage.","t":"护士扛着一台**便携式**氧气罐爬了三段楼梯，去救助停电时被困的老年病人。"},
"disciple":{"e":"The aging painter trained a single disciple for over a decade, passing down brushwork techniques that took a lifetime to master.","t":"这位年迈的画家花了十多年时间培养了一名**弟子**，把耗费一生才掌握的笔法传授给他。"},
"rekindle":{"e":"A chance encounter at the reunion rekindled a friendship that had quietly faded after they graduated from different colleges.","t":"同学聚会上的一次偶遇，**重新点燃**了一段在他们各自从不同大学毕业后悄然淡去的友谊。"},
"strap":{"e":"The paramedics quickly strapped the injured skier onto the stretcher before sliding him carefully down the icy slope.","t":"急救人员迅速把受伤的滑雪者**用带子固定**在担架上，然后小心地沿着结冰的斜坡把他运下去。"},
"urban":{"e":"Rapid urban growth over the past decade has pushed housing prices in the city far beyond what most teachers can afford.","t":"过去十年**城市**的快速扩张，已经把该市的房价推高到大多数教师都负担不起的水平。"},
"deteriorate":{"e":"The patient's condition deteriorated rapidly overnight, forcing doctors to move her into intensive care before dawn.","t":"病人的病情一夜之间迅速**恶化**，医生们不得不在天亮前把她转入重症监护室。"},
"salamander":{"e":"The biology students found a spotted salamander hiding beneath a damp log during their field trip through the forest.","t":"生物课的学生们在森林实地考察时，发现一只斑点**蝾螈**藏在一根潮湿的木头下面。"},
"bond":{"e":"Surviving the shipwreck together forged an unbreakable bond between the two strangers that lasted for the rest of their lives.","t":"共同挺过海难的经历，在两个陌生人之间锻造出一种牢不可破的**纽带**，持续了他们的余生。"},
"handy":{"e":"A small flashlight kept in the glove compartment proved handy the night their car broke down on a dark country road.","t":"手套箱里放着的一支小手电筒，在他们的车抛锚在黑暗乡间小路的那个晚上证明了自己的**实用**。"},
"gauge":{"e":"The teacher asked a few quick questions at the start of class to gauge how much students remembered from the previous lesson.","t":"老师在课程开始时问了几个简短的问题，以**测度**学生们对上节课内容还记得多少。"},
"embryo":{"e":"Under the microscope, the fertilized embryo had already begun dividing into a small cluster of identical cells.","t":"在显微镜下，这枚受精**胚胎**已经开始分裂成一小团相同的细胞。"},
"quadruple":{"e":"Ticket sales quadrupled within a week after the band announced a surprise reunion tour across twelve cities.","t":"乐队宣布将在十二座城市举行惊喜重聚巡演后，门票销量在一周内**翻了两番**。"},
"urgent":{"e":"The hospital issued an urgent appeal for blood donors after a highway accident left dozens of people critically injured.","t":"一场高速公路事故造成数十人重伤后，医院发布了**紧急**的献血呼吁。"},
"quotient":{"e":"Dividing forty-eight by six gives a quotient of eight, a calculation the teacher expected every fourth grader to know instantly.","t":"四十八除以六得到的**商**是八，老师期望每个四年级学生都能立刻算出这道题。"},
"annual":{"e":"The company's annual report revealed steady growth in overseas sales despite a sluggish domestic market throughout the year.","t":"这家公司的**年度**报告显示，尽管全年国内市场低迷，海外销售额仍稳步增长。"},
"multiplicative":{"e":"Compound interest works through a multiplicative process, where each year's growth is calculated on top of all previous gains, not just the original sum.","t":"复利通过一种**乘法式**的过程增长，每年的收益都是在之前所有累积收益的基础上计算的，而不仅仅是本金。"},
"studio":{"e":"The sculptor rented a small studio above the bakery, where afternoon light poured through skylights onto her half-finished statues.","t":"这位雕塑家在面包店楼上租了一间小**工作室**，午后的阳光透过天窗洒在她尚未完工的雕像上。"},
"geometric":{"e":"The quilt featured a striking geometric pattern of interlocking triangles stitched from dozens of brightly colored fabric scraps.","t":"这床被子呈现出一种醒目的**几何**图案，由几十块彩色布头拼接成相互交织的三角形。"},
"minus":{"e":"The final invoice came to two thousand dollars minus a ten percent discount for paying the balance early.","t":"最终账单是两千美元，**减去**提前结清余款所享的百分之十折扣。"},
"ordinate":{"e":"On the graph, the ordinate represented rainfall in inches, while the horizontal axis tracked the months of the entire year.","t":"在这张图表上，**纵坐标**代表以英寸计的降雨量，而横轴则标示全年的各个月份。"},
"flame":{"e":"A single candle flame flickered in the drafty cabin window, somehow surviving hours of wind that had knocked out the power.","t":"一豆孤独的蜡烛**火焰**在漏风的小屋窗边摇曳，竟撑过了那场刮停电力的数小时大风。"},
"numeric":{"e":"The database assigns each customer a unique numeric code instead of storing names, which keeps the records easier to search.","t":"数据库给每位客户分配一个独一无二的**数字**代码，而不是存储姓名，这样记录起来更便于检索。"},
"oblong":{"e":"The carpenter cut an oblong hole in the wall exactly the size and shape of the new window frame.","t":"木匠在墙上切出一个**长方形**的洞，大小和形状都刚好和新窗框吻合。"},
"quantitative":{"e":"Before launching the product, the marketing team gathered quantitative data on pricing preferences from thousands of surveyed customers.","t":"在产品上市之前，营销团队从数千名受访顾客那里收集了关于定价偏好的**定量**数据。"},
"reciprocal":{"e":"The two nations signed a reciprocal trade agreement, each lowering tariffs on the other's goods by the same percentage.","t":"这两个国家签署了一份**互惠**贸易协定，双方都以相同的比例下调对方商品的关税。"},
"tangent":{"e":"The engineer drew a tangent line at that exact point on the curve to calculate the roller coaster's instantaneous speed.","t":"工程师在曲线上那个精确点画了一条**切线**，以此计算过山车的瞬时速度。"},
"allot":{"e":"The committee allotted each department a fixed budget for the semester, leaving no room for unexpected expenses later on.","t":"委员会给每个部门**分配**了固定的学期预算，没有为后续的意外开支留下任何余地。"},
"boycott":{"e":"Consumers boycotted the clothing brand after reports surfaced that its factories paid workers far below the legal minimum wage.","t":"有报道称该服装品牌旗下工厂给工人的薪资远低于法定最低标准后，消费者纷纷**抵制**这个品牌。"},
"compensation":{"e":"The factory workers demanded fair compensation for the injuries they suffered from faulty machinery that management had ignored for years.","t":"工厂工人们要求为他们因管理层多年忽视的故障机器而受的伤获得公平的**赔偿**。"},
"ordinal":{"e":"The child proudly recited the ordinal numbers, counting first, second, and third as she climbed each stair of the porch.","t":"这个孩子骄傲地背诵着**序数词**，一边爬上门廊的台阶一边数着第一、第二、第三。"},
"perimeter":{"e":"Guards patrolled the perimeter of the base every two hours, checking the fence for any sign of tampering.","t":"警卫每两个小时就会巡逻一次基地的**外围**，检查围栏有无被动过的痕迹。"},
"triple":{"e":"Demand for the vaccine tripled overnight once health officials confirmed the outbreak had spread to three neighboring counties.","t":"一旦卫生官员证实疫情已扩散到三个邻县，疫苗的需求量一夜之间**增至三倍**。"},
"motto":{"e":"The coach's motto, painted above the locker room door, reminded every player that effort mattered more than raw talent.","t":"教练的**座右铭**被漆在更衣室门上方，提醒每一位球员努力比天赋更重要。"},
"reject":{"e":"The admissions committee rejected her application twice before finally accepting her on the third attempt after a stronger essay.","t":"招生委员会两次**拒绝**了她的申请，直到第三次凭借一篇更出色的文书才终于录取她。"},
"vent":{"e":"After the meeting, she finally vented her frustration to a close friend instead of bottling it up any longer.","t":"会议结束后，她终于向一位密友**发泄**了自己的沮丧，而不是继续把情绪憋在心里。"},
"jog":{"e":"Every morning before sunrise, she jogged along the riverbank, greeting the same handful of regulars she passed each day.","t":"每天日出之前，她都会沿着河岸**慢跑**，和每天都会遇到的那几个熟面孔打招呼。"},
"laboratory":{"e":"The virus samples were shipped to a high-security laboratory where researchers could study them without risking any outside exposure.","t":"病毒样本被运往一间高安全级别的**实验室**，研究人员可以在那里研究它们而不必担心外部暴露风险。"},
"criss-cross":{"e":"Narrow hiking trails criss-cross the entire mountainside, occasionally merging before splitting off again toward different scenic overlooks.","t":"狭窄的徒步小径在整个山坡上**纵横交错**，偶尔汇合又再次分岔通向不同的观景台。"},
"sour":{"e":"Their once-friendly partnership soured after a bitter dispute over who deserved credit for the invention's success.","t":"一场关于这项发明的成功该归功于谁的激烈争执后，他们曾经友好的合作关系**变得恶劣**了。"},
"critique":{"e":"The professor critiqued each student's thesis draft line by line, offering blunt but genuinely constructive feedback before the deadline.","t":"教授逐行**评点**了每个学生的论文草稿，在截止日期前给出了直率却确实有建设性的反馈。"},
"viral":{"e":"The homemade video of the dancing dog went viral overnight, racking up millions of views before the family even woke up.","t":"那段小狗跳舞的自制视频一夜之间**爆红网络**，那家人还没醒来就已经积累了数百万次播放。"},
"fault":{"e":"Seismologists traced the tremor to a previously unmapped fault running directly beneath the elementary school's playground.","t":"地震学家追踪到这次震动源于一条此前未被标绘、恰好穿过小学操场下方的**断层**。"},
"schedule":{"e":"The surgeon scheduled the follow-up appointment for early Friday morning, giving the anxious family only two days to wait.","t":"外科医生把复诊**安排**在周五清晨，让焦虑的家属只需再等两天。"},
"latter":{"e":"Offered a choice between a cash bonus and extra vacation days, most employees chose the latter without much hesitation.","t":"在现金奖金和额外假期之间做选择时，大多数员工几乎没怎么犹豫就选择了**后者**。"},
"minimal":{"e":"The new software update required minimal effort to install, taking less than two minutes and no restart at all.","t":"这次软件更新只需要**最低限度**的操作即可完成安装，用时不到两分钟，也无需重启。"},
"refrigerate":{"e":"The label warned that once opened, the sauce must be refrigerated immediately or it would spoil within a few hours.","t":"标签上警告说，这瓶酱料一旦打开就必须立即**冷藏**，否则几个小时内就会变质。"},
"fountain":{"e":"Children tossed coins into the plaza fountain, each one whispering a wish before the coin sank beneath the water.","t":"孩子们把硬币扔进广场的**喷泉**里，每人都在硬币沉入水中前默默许了个愿。"},
"horizontal":{"e":"The carpenter used a level to make sure the shelf was perfectly horizontal before drilling the final screw into place.","t":"木匠用水平仪确认架子完全**水平**之后，才拧下最后一颗螺丝固定它。"},
"appetite":{"e":"Months of chemotherapy had destroyed her appetite completely, and even her favorite childhood dishes now smelled unbearable to her.","t":"数月的化疗彻底摧毁了她的**食欲**，就连她儿时最爱的菜肴现在闻起来都让她难以忍受。"},
"perpendicular":{"e":"The new bridge support was built perpendicular to the riverbank, distributing the weight far more evenly than the old angled pillar.","t":"新的桥墩被建造成与河岸**垂直**，比旧的斜向立柱更均匀地分散了重量。"},
"impressive":{"e":"The young violinist gave an impressive performance, drawing a standing ovation from an audience that included several professional musicians.","t":"这位年轻的小提琴手献上了一场**令人印象深刻**的演出，赢得了包括几位职业音乐家在内的观众起立鼓掌。"},
"generous":{"e":"An anonymous donor made a generous contribution that covered the entire cost of rebuilding the flooded community center.","t":"一位匿名捐赠者做出了**慷慨**的捐款，足以覆盖重建被淹社区中心的全部费用。"},
"liberate":{"e":"Advancing troops liberated the prisoners from the camp just days before winter would have made survival there impossible.","t":"推进中的部队**解放**了营地里的囚犯，就在冬天让那里的生存变得不可能之前的几天。"},
"completion":{"e":"The bridge's completion was delayed by nearly two years after engineers discovered unstable bedrock beneath one of the support towers.","t":"工程师发现一座支撑塔下方的基岩不稳定后，这座桥的**完工**延迟了将近两年。"},
"inherent":{"e":"Every investment carries an inherent risk, and no financial advisor can promise a guaranteed return no matter how confident they sound.","t":"每一项投资都带有**固有的**风险，无论理财顾问听起来多么自信，都无法保证收益。"},
"disinterested":{"e":"Because the judge had no personal ties to either family, she could weigh the custody dispute in a truly disinterested manner.","t":"由于这位法官与双方家庭都没有私人关系，她能够以真正**公正无私**的方式权衡这起监护权纠纷。"},
"asthma":{"e":"Her asthma flared up whenever pollen counts rose in spring, forcing her to carry an inhaler everywhere she went.","t":"每逢春天花粉浓度升高，她的**哮喘**就会发作，逼得她无论去哪儿都得随身携带吸入器。"},
"mania":{"e":"A sudden mania for collecting vintage sneakers swept through the school, with students trading pairs worth hundreds of dollars.","t":"一股收集复古运动鞋的**狂热**突然席卷了整个学校，学生们交易着价值数百美元的鞋子。"},
"inspect":{"e":"Health officials inspected the restaurant kitchen without warning and found three serious violations behind the walk-in refrigerator.","t":"卫生官员在毫无预警的情况下**检查**了这家餐厅的厨房，在步入式冰箱后面发现了三项严重违规。"},
"scorch":{"e":"The relentless summer sun scorched the wheat fields, leaving the once-golden stalks brittle and brown before harvest even began.","t":"无情的夏日骄阳**炙烤**着麦田，还没等到收割，曾经金黄的麦秆就已变得又脆又焦黄。"},
"aggregate":{"e":"The aggregate rainfall for the entire monsoon season broke a regional record that had stood for nearly forty years.","t":"整个季风季的**总**降雨量打破了一项保持近四十年的地区纪录。"},
"cylinder":{"e":"One faulty cylinder in the old engine caused the entire truck to shudder violently every time it idled at a stoplight.","t":"这台旧发动机里一个故障的**气缸**导致整辆卡车每次在红灯前怠速时都剧烈抖动。"},
"impair":{"e":"Years of loud concerts without ear protection had permanently impaired the drummer's hearing in his left ear.","t":"多年在没有护耳的情况下参加吵闹的音乐会，永久**损害**了这位鼓手左耳的听力。"},
"quality":{"e":"The furniture maker refused to cut corners on quality, hand-selecting every plank of oak before it entered his workshop.","t":"这位家具匠人在**质量**上绝不妥协，每一块橡木板进入他的工坊前都要亲手挑选。"},
"bureau":{"e":"The weather bureau issued a flood warning for the entire coastal region just hours before the storm made landfall.","t":"气象**局**在风暴登陆前几个小时就为整个沿海地区发布了洪水预警。"},
"excavation":{"e":"The excavation at the old burial site revealed pottery shards and jewelry that had remained untouched for over two thousand years.","t":"这处古墓的**发掘**工作出土了两千多年来从未被触碰过的陶片和首饰。"},
"spin":{"e":"The figure skater spun so fast in the final second of her routine that the audience gasped in unison.","t":"花样滑冰选手在她的节目最后一秒**旋转**得如此之快，观众们不约而同地倒吸一口气。"},
"settle":{"e":"The two neighbors finally settled their decade-long property dispute after a mediator suggested moving the fence six inches.","t":"在一位调解员建议把围栏移动六英寸后，这两位邻居终于**解决**了长达十年的地产纠纷。"},
"virus":{"e":"A stubborn virus swept through the dormitory, leaving half the students too feverish to attend their final exams.","t":"一种顽固的**病毒**席卷了整栋宿舍楼，导致半数学生发烧得无法参加期末考试。"},
"state":{"e":"The contract clearly states that either party may terminate the agreement with thirty days' written notice.","t":"合同中明确**规定**，任何一方都可以提前三十天书面通知终止协议。"},
"Fahrenheit":{"e":"The old thermometer still measured temperature in Fahrenheit, so the visiting scientists had to convert every reading before recording it.","t":"这支旧温度计测的仍是**华氏**温度，来访的科学家们必须先换算每一个读数才能记录下来。"},
"creep":{"e":"Fog crept slowly across the harbor at dusk, swallowing the fishing boats one by one until nothing remained visible.","t":"黄昏时分，雾气**缓缓弥漫**过港湾，把渔船一艘接一艘地吞没，直到什么都看不见。"},
"thorough":{"e":"The inspector gave the old house a thorough examination, checking every wire and pipe before approving it for sale.","t":"检查员对这栋老房子进行了**彻底的**检查，核实了每一根电线和管道才批准将其挂牌出售。"},
"spectrum":{"e":"When sunlight passes through a prism, it splits into the full spectrum of colors visible in a rainbow.","t":"当阳光穿过棱镜时，它会分解成彩虹中可见的完整**光谱**色彩。"},
"innate":{"e":"Some psychologists argue that an innate sense of fairness appears in children long before they learn any explicit moral rules.","t":"一些心理学家认为，**天生的**公平感在孩子们学会任何明确的道德规则之前很久就已经显现。"},
"graphite":{"e":"Pencil leads are made mostly of graphite mixed with clay, and the ratio determines how dark or light the mark appears.","t":"铅笔芯主要由**石墨**与黏土混合制成，二者的比例决定了笔迹显得深还是浅。"},
"encourage":{"e":"Her grandmother constantly encouraged her to pursue painting, even when the rest of the family dismissed it as an impractical hobby.","t":"她的祖母一直**鼓励**她追求绘画，即使家里其他人都认为这只是个不切实际的爱好。"},
"shuffle":{"e":"The dealer shuffled the deck three times before dealing each player their first five cards of the game.","t":"发牌员在给每位玩家发出本局前五张牌之前，先**洗**了三次牌。"},
"modulate":{"e":"The radio host learned to modulate her voice, softening it during interviews so nervous guests would relax and speak freely.","t":"电台主持人学会了**调节**自己的声音，在采访中放柔，好让紧张的嘉宾放松下来畅所欲言。"},
"finch":{"e":"The finch that nested behind our garden shed every spring returned again this year, its small beak already darting after seeds.","t":"每年春天都在我们花园小屋后面筑巢的那只**雀**今年又回来了，它的小喙已经在啄食种子。"},
"pants":{"e":"She rolled up her pants to keep the wet cuffs from dragging through the muddy trail behind the cabin.","t":"她把**裤子**卷起来，免得湿裤脚拖过小屋后面泥泞的小径。"},
"fluctuation":{"e":"Investors grew anxious as wild fluctuations in the currency's value made it impossible to predict next month's shipping costs.","t":"由于货币价值剧烈**波动**，投资者忧心忡忡，根本无法预测下个月的运输成本。"},
"subsidiary":{"e":"The parent company folded its unprofitable subsidiary into a larger division rather than shutting the smaller operation down entirely.","t":"母公司将旗下亏损的**子公司**并入了一个更大的部门，而不是将这家小机构彻底关闭。"},
"import":{"e":"The diplomat's offhand remark carried more import than anyone in the room realized until war broke out weeks later.","t":"那位外交官随口的一句话所包含的**意义**远比当时在场的人所意识到的更为重大，直到几周后战争爆发。"},
"mortgage":{"e":"After years of renting, the young couple finally secured a mortgage and moved into their first house near the coast.","t":"租房多年后，这对年轻夫妇终于办下了**抵押贷款**，搬进了他们在海边的第一套房子。"},
"necessity":{"e":"Clean drinking water is not a luxury but an absolute necessity for every community, regardless of how remote or poor it is.","t":"干净的饮用水不是奢侈品，而是每个社区绝对的**必需**，无论它多么偏远或贫穷。"},
"externality":{"e":"Economists warned that pollution from the factory was a negative externality, imposing costs on nearby residents who received none of the profits.","t":"经济学家警告说，工厂排放的污染是一种负**外部性**，给附近居民带来了成本，而他们却没有从利润中分得任何好处。"},
"negotiate":{"e":"The union spent three tense weeks negotiating with management before both sides finally agreed on a modest increase in wages.","t":"工会花了三个紧张的星期与管理层**谈判**，双方才终于就适度加薪达成一致。"},
"recoup":{"e":"The studio hoped the sequel's overseas ticket sales would recoup the enormous losses the first film suffered domestically.","t":"制片公司希望续集的海外票房收入能够**弥补**第一部电影在国内遭受的巨额亏损。"},
"monetary":{"e":"The central bank tightened monetary policy, raising interest rates sharply to slow inflation before it spiraled out of control.","t":"央行收紧了**货币**政策，大幅提高利率，以在通货膨胀失控之前加以抑制。"},
"choir":{"e":"Every Sunday the small church choir rehearsed for two hours, blending their voices until the harmonies filled the entire building.","t":"每个星期天，这个小教堂的**唱诗班**都要排练两个小时，让各种声音融合在一起，直到和声响彻整栋建筑。"},
"stagnant":{"e":"Wages remained stagnant for a decade even as the cost of housing and groceries climbed steadily higher each year.","t":"尽管住房和食品价格逐年稳步攀升，工资却**停滞**了整整十年。"},
"basin":{"e":"Rainfall across the entire river basin determines how much water eventually reaches the reservoir that supplies the capital city.","t":"整个河流**盆地**的降雨量决定了最终有多少水能汇入为首都供水的水库。"},
"premise":{"e":"The entire argument rested on a false premise, so once that assumption collapsed, the professor's conclusion no longer made sense.","t":"整个论证都建立在一个错误的**前提**之上，所以一旦这个假设站不住脚，教授的结论也就不成立了。"},
"surcharge":{"e":"The airline quietly added a fuel surcharge to every ticket, so the final price was far higher than travelers expected.","t":"航空公司悄悄给每张机票都加了燃油**附加费**，导致最终价格远高于旅客的预期。"},
"transact":{"e":"Merchants along the old caravan route learned to transact business in several languages, switching fluently depending on who approached their stall.","t":"沿着古商队路线做生意的商人们学会了用好几种语言**交易**，根据谁走近摊位就流利地切换语言。"},
"rodent":{"e":"A single rodent had chewed through the barn's wiring, leaving the farmer without electricity for nearly a week.","t":"一只**啮齿动物**咬穿了谷仓的电线，让这位农民将近一周都没有电用。"},
"punctual":{"e":"Her boss valued punctual employees so highly that arriving even two minutes late could jeopardize a promotion.","t":"她的老板极其看重员工**守时**，哪怕迟到两分钟都可能影响晋升。"},
"dogged":{"e":"Through years of rejection letters, the novelist's dogged determination never wavered until a small publisher finally said yes.","t":"历经多年退稿信的打击，这位小说家**顽强**的决心从未动摇，直到一家小出版社终于答应出版。"},
"transform":{"e":"The new principal managed to transform the failing school within three years, raising test scores and rebuilding morale among teachers.","t":"新校长在三年内成功**改造**了这所濒临倒闭的学校，提高了考试成绩，重建了教师们的士气。"},
"aurora":{"e":"Travelers flew to northern Norway hoping the clear winter sky would reveal a shimmering aurora above the frozen fjords.","t":"游客们飞往挪威北部，希望晴朗的冬季夜空能在冰封的峡湾上空展现出闪烁的**极光**。"},
"interstellar":{"e":"The probe was designed to survive decades of interstellar travel, drifting silently through the vast emptiness between star systems.","t":"这枚探测器被设计成能承受数十年的**星际**旅行，在恒星系统之间浩瀚的虚空中静静漂流。"},
"realm":{"e":"Advances in gene editing have pushed medicine into a realm once confined entirely to science fiction novels.","t":"基因编辑技术的进步已经把医学推进到了一个曾经完全局限于科幻小说的**领域**。"},
"consideration":{"e":"Cost was only one consideration among many that the committee weighed before choosing where to build the new hospital.","t":"成本只是委员会在决定新医院建址之前权衡的众多**考虑因素**之一。"},
"aviation":{"e":"Early pioneers of aviation risked their lives testing flimsy wooden aircraft that often crashed within minutes of leaving the ground.","t":"**航空**事业的早期先驱们冒着生命危险测试脆弱的木制飞机，这些飞机常常在离地几分钟内就坠毁。"},
"manipulate":{"e":"The con artist knew exactly how to manipulate lonely victims, gaining their trust before draining their savings accounts.","t":"这个骗子非常清楚如何**操纵**孤独的受害者，先获取他们的信任，再掏空他们的存款账户。"},
"hammer":{"e":"The blacksmith would hammer the glowing iron rod again and again until it slowly curved into a horseshoe.","t":"铁匠一次又一次地**锤打**那根发红的铁棒，直到它慢慢弯成马蹄铁的形状。"},
"synthetic":{"e":"Because natural rubber had become scarce during the war, factories switched to a synthetic material that performed nearly as well.","t":"由于战争期间天然橡胶变得稀缺，工厂们转而使用一种性能几乎同样出色的**合成**材料。"},
"census":{"e":"Government workers conducted a census every ten years, going door to door to count every resident in the county.","t":"政府工作人员每十年进行一次**人口普查**，挨家挨户统计县里的每一位居民。"},
"clutch":{"e":"The frightened child clutched her mother's sleeve, refusing to let go even after the thunder had stopped completely.","t":"受惊的孩子紧紧**抓住**妈妈的袖子，即使雷声已经完全停了也不肯松手。"},
"target":{"e":"Reducing carbon emissions by half within a decade became the factory's most ambitious target under the new environmental regulations.","t":"在新的环保法规下，十年内将碳排放量减少一半成为这家工厂最雄心勃勃的**目标**。"},
"flamboyant":{"e":"The retired actor still dressed in flamboyant velvet suits, drawing stares whenever he strolled through the quiet village market.","t":"这位退休演员仍然穿着**艳丽**的天鹅绒西装，每次漫步走过安静的村庄集市都会引来注目。"},
"vein":{"e":"The nurse struggled to find a vein in the elderly patient's arm, finally succeeding on the third attempt.","t":"护士很难在这位老年患者的手臂上找到**静脉**，试了三次才终于成功。"},
"jewelry":{"e":"The thief broke into the shop at midnight and made off with nearly all the jewelry displayed in the front window.","t":"小偷在午夜闯入店铺，几乎卷走了橱窗里陈列的所有**首饰**。"},
"pack":{"e":"She began to pack her suitcase the night before the flight, folding sweaters carefully so they wouldn't wrinkle.","t":"她在航班起飞前一晚开始**打包**行李箱，小心地把毛衣叠好以免起皱。"},
"satellite":{"e":"Engineers celebrated when the satellite finally reached orbit and began transmitting weather data back to stations across the country.","t":"当**卫星**终于进入轨道并开始向全国各地的站点传回气象数据时，工程师们欢呼庆祝。"},
"correspondent":{"e":"The network's foreign correspondent filed nightly reports from the war zone despite the constant danger surrounding her hotel.","t":"尽管周围持续存在危险，这家电视网的驻外**记者**仍然每晚从战区发回报道。"},
"shower":{"e":"A sudden shower forced the picnickers to gather their blankets and run for shelter under the nearest tree.","t":"一场突如其来的**阵雨**迫使野餐的人们收起毯子，跑到最近的树下避雨。"},
"charter":{"e":"The diving club decided to charter a boat for the weekend so members could explore reefs far from the crowded shore.","t":"潜水俱乐部决定周末**包租**一艘船，好让会员们能探索远离拥挤海岸的珊瑚礁。"},
"forefront":{"e":"The university's research lab has remained at the forefront of battery technology for nearly two decades.","t":"这所大学的研究实验室近二十年来一直处于电池技术的**最前沿**。"},
"spun":{"e":"The dessert was topped with delicate spun sugar that shattered like glass the moment a fork touched it.","t":"这道甜点上覆盖着精致的**拉丝**糖，叉子一碰就像玻璃一样碎裂。"},
"accessible":{"e":"The museum redesigned its entrance and installed ramps so that every gallery became fully accessible to visitors using wheelchairs.","t":"博物馆重新设计了入口并安装了坡道，让每个展厅对使用轮椅的游客都完全**易于进入**。"},
"undertake":{"e":"The city council agreed to undertake a complete renovation of the crumbling bridge before another harsh winter arrived.","t":"市议会同意在又一个严冬来临之前**承担**对这座破败大桥的全面翻修。"},
"splash":{"e":"The toddler loved to splash water out of the bathtub, soaking the tiles no matter how many towels lined the floor.","t":"小孩子喜欢把浴缸里的水往外**溅**，不管地板上铺了多少毛巾，瓷砖总是被弄湿。"},
"weave":{"e":"The old craftsman would weave strips of dried reed into baskets sturdy enough to carry fish from the river.","t":"这位老工匠会把晒干的芦苇条**编织**成篮子，结实得足以从河边运鱼。"},
"gull":{"e":"A single gull circled the fishing boat for hours, diving occasionally to snatch scraps tossed overboard by the crew.","t":"一只**海鸥**在渔船上空盘旋了数小时，偶尔俯冲下来抢夺船员扔下船的碎鱼。"},
"prose":{"e":"The novelist's prose was so spare and precise that readers often finished entire chapters without noticing a single wasted word.","t":"这位小说家的**散文**如此简练精准，读者常常读完整章都没注意到一个多余的字。"},
"flint":{"e":"Early hunters struck flint against steel to spark a fire before settling in for the freezing night.","t":"早期的猎人在安顿下来过寒夜之前，会用**燧石**敲击钢铁打出火花生火。"},
"considerate":{"e":"Her new roommate turned out to be remarkably considerate, always lowering the music whenever she noticed anyone studying nearby.","t":"她的新室友非常**体贴**，只要注意到附近有人在学习就会主动把音乐声调低。"},
"extension":{"e":"The professor granted a two-day extension on the essay after several students complained about the broken library printers.","t":"由于几名学生抱怨图书馆打印机故障，教授给论文批了两天的**延期**。"},
"ceramic":{"e":"The artist spent months glazing each ceramic bowl by hand before firing them in a kiln behind her studio.","t":"这位艺术家花了几个月的时间手工给每一个**陶瓷**碗上釉，然后在工作室后面的窑里烧制。"},
"reactor":{"e":"Engineers shut down the aging reactor for inspection after sensors detected an unusual rise in core temperature.","t":"传感器检测到堆芯温度异常升高后，工程师们关闭了这座老旧的**反应堆**进行检修。"},
"adhere":{"e":"Every surgeon in the operating room must adhere strictly to sterilization protocols, or the risk of infection rises sharply.","t":"手术室里的每位外科医生都必须严格**遵守**消毒规程，否则感染风险会急剧上升。"},
"token":{"e":"The soldier kept a faded photograph as a token of the family he hoped to return to someday.","t":"这名士兵保留着一张褪色的照片，作为他希望有朝一日能回归的家庭的**象征**。"},
"startling":{"e":"The report revealed a startling increase in ocean temperatures that scientists had not predicted even five years earlier.","t":"这份报告揭示了海洋温度**惊人**的上升，这是科学家们甚至在五年前都未曾预料到的。"},
"imperative":{"e":"Securing clean and reliable water sources became absolutely imperative once the drought entered its third consecutive summer without relief.","t":"一旦干旱毫无缓解地进入连续第三个夏天，确保清洁可靠的水源就变得绝对**必要**。"},
"choreograph":{"e":"The director asked a young dancer to choreograph the opening number, trusting her fresh ideas over the veteran team's tired routines.","t":"导演请一位年轻舞者为开场节目**编舞**，相信她的新颖创意胜过资深团队那些老套的编排。"},
"applicable":{"e":"The safety regulations remained applicable to every branch of the company, regardless of which country the factory operated in.","t":"这些安全规定对公司的每一个分支都**适用**，无论工厂在哪个国家运营。"},
"prosper":{"e":"Small businesses along the newly built highway began to prosper once tourists discovered the scenic detour through town.","t":"自从游客发现了穿过小镇的这条风景小道，沿着新修高速公路的小商户们开始**繁荣**起来。"},
"literature":{"e":"Her thesis examined how nineteenth-century Russian literature shaped the political imagination of an entire generation of revolutionaries.","t":"她的论文探讨了十九世纪俄国**文学**如何塑造了整整一代革命者的政治想象。"},
"backhand":{"e":"Her backhand improved so dramatically over the summer that opponents stopped attacking that side of the court entirely.","t":"她的**反手击球**在这个夏天进步神速，以至于对手完全不再攻击球场的那一侧。"},
"collapse":{"e":"The bridge's sudden collapse during rush hour left investigators searching for structural flaws that inspectors had somehow missed for years.","t":"大桥在高峰时段突然**崩塌**，让调查人员开始寻找检查员多年来竟然都遗漏的结构缺陷。"},
"formation":{"e":"The geese flew in a tight V formation, taking turns at the front to conserve energy on the long migration.","t":"大雁排成紧密的V字**编队**飞行，轮流领头以在漫长的迁徙途中节省体力。"},
"radar":{"e":"The coast guard's radar detected an unidentified vessel drifting dangerously close to the rocky shoals before dawn.","t":"海岸警卫队的**雷达**在黎明前探测到一艘身份不明的船只危险地漂近礁石浅滩。"},
"fascinating":{"e":"The lecture on deep-sea creatures proved so fascinating that not a single student checked their phone the entire hour.","t":"这场关于深海生物的讲座如此**迷人**，以至于整整一个小时没有一个学生看手机。"},
"devour":{"e":"The starving hikers devoured the entire loaf of bread within minutes of reaching the rescue camp.","t":"饥饿的徒步者们一到救援营地，几分钟内就把整条面包**狼吞虎咽**地吃光了。"},
"sculpt":{"e":"The artist spent an entire winter sculpting a single block of marble into a lifelike figure of a sleeping child.","t":"这位艺术家花了整整一个冬天，把一整块大理石**雕刻**成一个栩栩如生的熟睡孩童雕像。"},
"melody":{"e":"A haunting melody drifted from the old piano upstairs, though no one in the house admitted to playing it.","t":"一段萦绕不去的**旋律**从楼上那架旧钢琴飘出，尽管家里没人承认是自己弹的。"},
"launch":{"e":"Scientists watched anxiously as the rocket prepared to launch, carrying years of research toward the edge of the solar system.","t":"科学家们焦急地注视着火箭准备**发射**，它将承载多年的研究成果飞向太阳系边缘。"},
"genre":{"e":"The author refused to be confined to a single genre, moving effortlessly between mystery, romance, and historical fiction.","t":"这位作家拒绝被局限在单一**类型**里，在悬疑、爱情和历史小说之间轻松切换。"},
"coarse":{"e":"The sailor's hands had grown coarse and calloused from decades of hauling wet rope across the deck.","t":"这位水手的双手因为几十年在甲板上拖拽湿绳索而变得**粗糙**且长满老茧。"},
"pitch":{"e":"The singer struggled to hit the highest pitch in the aria, cracking slightly during the final rehearsal before opening night.","t":"这位歌手在咏叹调的最高**音高**处力不从心，在首演前的最后一次彩排中略微破音。"},
"millennium":{"e":"Archaeologists carefully uncovered fragile pottery shards that had survived nearly a millennium buried beneath the ruined stone temple.","t":"考古学家小心翼翼地发掘出脆弱的陶片，它们埋在废弃的石造神庙下，历经近一个**千年**才得以保存。"},
"care":{"e":"The elderly widow required round-the-clock care after the stroke left her unable to walk or feed herself.","t":"中风后，这位年迈的寡妇丧失了行走和自理进食的能力，需要全天候的**照料**。"},
"ivory":{"e":"Poachers slaughtered entire herds of elephants for their ivory, driving the species toward extinction within a single generation.","t":"偷猎者为了获取**象牙**屠杀整群整群的大象，短短一代人的时间就把这个物种逼向灭绝。"},
"entail":{"e":"Building a career in diplomacy often entails years spent in postings far from family and familiar comforts.","t":"从事外交事业往往**牵涉**多年驻扎在远离家人和熟悉环境的岗位上。"},
"wrap":{"e":"Grandmother would wrap each ornament in newspaper before packing the box away in the attic every January.","t":"每年一月，奶奶都会把每一件装饰品用报纸**包**好，然后把箱子收进阁楼。"},
"ultraviolet":{"e":"Dermatologists warn that ultraviolet rays penetrate clouds easily, so sunscreen remains necessary even on overcast days.","t":"皮肤科医生警告说，**紫外线**很容易穿透云层，所以即使在阴天也需要涂防晒霜。"},
"league":{"e":"The small nations formed a defensive league, pledging to come to one another's aid if any single member faced invasion.","t":"这些小国组成了一个防御**联盟**，承诺一旦任何一个成员遭到入侵，其他成员都会施以援手。"},
"consonant":{"e":"Young children learning to read often confuse similar consonant sounds, mixing up letters like b and d.","t":"学习阅读的小孩子经常混淆相似的**辅音**发音，把b和d这样的字母搞混。"},
"well-heeled":{"e":"The well-heeled neighborhood was lined with restored mansions, each guarded by iron gates and trimmed boxwood shrubs.","t":"这个**富有**的社区两旁排列着修缮一新的豪宅，每一栋都由铁门和修剪整齐的黄杨树丛守护着。"},
"binary":{"e":"Computers ultimately reduce every image, sound, and document into a long string of binary code made of ones and zeros.","t":"计算机最终会把每一张图片、每一段声音和每一份文档都简化成由0和1组成的一长串**二进制**代码。"},
"digitize":{"e":"The understaffed library spent five long years working to digitize its entire archive of fragile nineteenth-century newspapers.","t":"这家人手不足的图书馆花了整整五年时间致力于将其全部脆弱的十九世纪报纸档案**数字化**。"},
"subdivide":{"e":"The ambitious developer planned to subdivide the sprawling old ranch into dozens of smaller residential building lots.","t":"这位雄心勃勃的开发商计划把这片广袤的旧牧场**细分**成几十块较小的住宅建筑用地。"},
"pathetic":{"e":"The stray dog looked so pathetic, shivering in the rain outside the grocery store, that a stranger finally brought it home.","t":"那只流浪狗在杂货店外面雨中瑟瑟发抖，样子**可怜**极了，最终一位陌生人把它带回了家。"},
"gloomy":{"e":"The cabin's gloomy interior, lit only by a single flickering candle, made the travelers eager to leave before nightfall.","t":"小屋内部**阴沉**昏暗，只有一支摇曳的蜡烛照明，这让旅行者们急于在天黑前离开。"},
"tangible":{"e":"Investors wanted tangible proof that the startup's new technology actually worked before committing another large round of funding.","t":"投资者想要**切实**的证据证明这家初创公司的新技术确实管用，然后才愿意投入新一轮大额资金。"},
"chronological":{"e":"The museum arranged the exhibit in strict chronological order, guiding visitors from the earliest fossils to the most recent discoveries.","t":"博物馆严格按照**年代顺序**布置展览，引导游客从最早的化石一直看到最新的发现。"},
"overgraze":{"e":"Ranchers who overgraze their fields often find the grass never fully recovers, leaving the soil exposed to erosion.","t":"**过度放牧**田地的牧场主常常发现草地再也无法完全恢复，导致土壤暴露于侵蚀之中。"},
"criteria":{"e":"The scholarship committee established strict criteria that applicants had to meet before their essays would even be reviewed.","t":"奖学金委员会制定了严格的**标准**，申请者必须达到这些标准，他们的文章才会被审阅。"},
"swoon":{"e":"Victorian novels often featured delicate heroines who would swoon dramatically at the slightest hint of scandal.","t":"维多利亚时代的小说常常描写娇弱的女主角，只要稍有丑闻的苗头就会夸张地**昏厥**过去。"},
"monument":{"e":"The town erected a bronze monument in the square to honor the firefighters who died battling the great blaze.","t":"小镇在广场上竖立了一座青铜**纪念碑**，纪念在扑灭那场大火中牺牲的消防员。"},
"definite":{"e":"The coach refused to give a definite answer about who would start Saturday's game until the final practice ended.","t":"教练拒绝在最后一次训练结束前给出周六比赛谁会首发的**明确**答案。"},
"spring":{"e":"New coffee shops seemed to spring up on every corner of the neighborhood within just a few months.","t":"短短几个月内，这个社区的每个街角似乎都**涌现**出了新的咖啡店。"},
"withdraw":{"e":"She had to withdraw a large sum from her savings account to cover the unexpected medical bills.","t":"她不得不从储蓄账户里**提取**一大笔钱来支付意外的医疗账单。"},
"patent":{"e":"The inventor filed for a patent on her water-purifying device before revealing the design at the conference.","t":"这位发明家在会议上公开设计之前，先为她的净水装置申请了**专利**。"},
"nourishment":{"e":"Premature infants sometimes need supplemental nourishment through a feeding tube until they grow strong enough to nurse on their own.","t":"早产儿有时需要通过喂食管获得额外的**营养**，直到他们长得足够强壮能够自主吮吸。"},
"supplier":{"e":"The factory dropped its longtime supplier after the company repeatedly failed to deliver parts on schedule.","t":"由于这家公司屡次未能按时交付零件，工厂放弃了长期合作的这家**供应商**。"},
"congressional":{"e":"The senator's staff spent weeks preparing for the congressional hearing on the agency's handling of the crisis.","t":"参议员的幕僚花了数周时间为这场关于该机构如何处理危机的**国会**听证会做准备。"},
"interfere":{"e":"Neighbors were warned not to interfere in the family dispute, even though shouting could be heard through the walls.","t":"邻居们被警告不要**干涉**这场家庭纠纷，尽管透过墙壁都能听到争吵声。"},
"respective":{"e":"After the meeting, the delegates returned to their respective countries to report on the agreement reached that afternoon.","t":"会议结束后，代表们返回**各自**的国家，汇报当天下午达成的协议。"},
"inherit":{"e":"The youngest daughter unexpectedly inherited the family farm, surprising relatives who assumed her older brother would take over.","t":"小女儿意外地**继承**了家族农场，让原以为她哥哥会接手的亲戚们大吃一惊。"},
"flexible":{"e":"The new manager offered flexible working hours, letting employees start anytime between seven and ten in the morning.","t":"新经理提供了**灵活**的工作时间，让员工可以在早上七点到十点之间任意时间开始上班。"},
"sacrificial":{"e":"In the ancient ritual, priests led a sacrificial lamb to the temple altar at the first light of dawn.","t":"在这场古老的仪式中，祭司们在黎明的第一缕光线中把一只**献祭**用的羊羔牵到神庙祭坛前。"},
"pendant":{"e":"She never removed the silver pendant her grandmother had given her, even while swimming in the ocean.","t":"她从不摘下祖母送给她的那枚银**垂饰**，哪怕是在海里游泳时也戴着。"},
"tornado":{"e":"A tornado tore through the small town overnight, flattening barns and snapping trees along its entire path.","t":"一场**龙卷风**一夜之间横扫这座小镇，沿途夷平了谷仓，折断了树木。"},
"characterize":{"e":"Sharp wit and relentless sarcasm characterize almost every character the playwright has ever written for the stage.","t":"犀利的机智与无休止的讽刺，成为这位剧作家笔下几乎每个角色的**标志性特征**。"},
"audience":{"e":"The comedian scanned the audience nervously, searching for a friendly face before delivering his opening joke.","t":"喜剧演员紧张地扫视**观众**，想在说出开场笑话之前找到一张友善的面孔。"},
"pasture":{"e":"The shepherd led his sheep down the hillside to a fresh pasture where the grass grew tall and green.","t":"牧羊人把羊群赶下山坡，来到一片青草茂盛的新**牧场**。"},
"delta":{"e":"Sediment carried downstream for centuries gradually built the fertile delta where the river finally meets the sea.","t":"数百年来顺流而下的泥沙逐渐堆积形成了这片肥沃的**三角洲**，河流最终在此汇入大海。"},
"cram":{"e":"Students crammed for the final exam all night, fueled by energy drinks and stale coffee from the vending machine.","t":"学生们整夜**临时抱佛脚**为期末考试突击复习，靠能量饮料和自动售货机里不新鲜的咖啡撑着。"},
"station":{"e":"Commuters huddled under the station's narrow awning, waiting for a train that was already twenty minutes late.","t":"通勤者们挤在**车站**狭窄的雨棚下，等待已经晚点二十分钟的火车。"},
"teem":{"e":"The coral reef teemed with color, from darting parrotfish to anemones swaying gently in the current.","t":"珊瑚礁**充满**了色彩，有穿梭的鹦嘴鱼，也有在水流中轻轻摇曳的海葵。"},
"rank":{"e":"Film critics consistently rank the director's second movie above everything else he has ever produced for the screen.","t":"影评人一致把这位导演的第二部电影**列为**他为大银幕制作过的所有作品中最出色的一部。"},
"alga":{"e":"A single-celled alga can multiply so rapidly in warm water that it turns an entire pond bright green within days.","t":"一种单细胞**藻类**能在温水中迅速繁殖，短短几天就能把整个池塘染成鲜绿色。"},
"devise":{"e":"Engineers had to devise a clever workaround after the original cooling system proved too expensive to install.","t":"由于最初的冷却系统安装成本过高，工程师们不得不**想出**一个巧妙的变通方案。"},
"quit":{"e":"After eleven exhausting years, she finally decided to quit her job and travel across South America alone.","t":"在筋疲力尽的十一年后，她终于决定**辞去**工作，独自穿越南美洲旅行。"},
"hinterland":{"e":"Goods unloaded at the busy port were shipped by rail deep into the country's agricultural hinterland.","t":"在繁忙港口卸下的货物由铁路运往这个国家农业**腹地**的深处。"},
"relate":{"e":"Researchers found that sleep quality could directly relate to a person's ability to concentrate the following day.","t":"研究人员发现睡眠质量可能与一个人第二天的注意力**有关**。"},
"tutor":{"e":"Her parents hired a math tutor twice a week after her grades began slipping in the fall semester.","t":"秋季学期成绩开始下滑后，她的父母每周请两次数学**家庭教师**给她补课。"},
"domain":{"e":"Quantum computing remains largely the domain of specialized researchers, though its applications are slowly spreading into finance and medicine.","t":"量子计算在很大程度上仍然是专业研究人员的**领域**，尽管它的应用正慢慢扩展到金融和医学领域。"},
"stellar":{"e":"The young violinist delivered a stellar performance that earned her a standing ovation from the entire concert hall.","t":"这位年轻的小提琴家献上了一场**精彩**的演出，赢得了整个音乐厅观众的起立鼓掌。"},
"marvel":{"e":"Tourists marveled at the ancient aqueduct, astonished that Roman engineers had built something so precise without modern tools.","t":"游客们对着这座古老的引水渠**赞叹不已**，惊讶于罗马工程师竟能在没有现代工具的情况下建造出如此精密的建筑。"},
"cannibalism":{"e":"Biologists carefully documented cannibalism among the spiders, noting that females frequently consumed smaller males soon after mating.","t":"生物学家仔细记录了这些蜘蛛之间的**同类相食**现象，指出雌蛛在交配后不久常常吃掉体型较小的雄蛛。"},
"fraction":{"e":"Only a small fraction of the applicants who submitted résumés were ever invited in for an interview.","t":"在提交简历的申请者中，只有极小的**一部分**曾获邀参加面试。"},
"syllable":{"e":"The poet counted each syllable carefully, shaping every line of the sonnet into a strict, unbroken rhythm.","t":"诗人仔细数着每一个**音节**，把十四行诗的每一行都打磨成严格而连贯的节奏。"},
"grain":{"e":"The carpenter sanded along the grain of the oak plank so the surface would feel perfectly smooth.","t":"木匠顺着橡木板的**纹理**打磨，好让表面感觉完全光滑。"},
"diagram":{"e":"The assembly instructions included a simple diagram showing exactly which screws belonged in which pre-drilled holes.","t":"组装说明书里附有一张简单的**图解**，清楚地展示了哪些螺丝该拧进哪些预先打好的孔里。"},
"scavenger":{"e":"Vultures and hyenas act as nature's scavengers, cleaning carcasses from the savanna before disease can spread.","t":"秃鹫和鬣狗是大自然的**食腐动物**，它们在疾病传播之前把草原上的尸体清理干净。"},
"multitude":{"e":"A multitude of protesters gathered outside the courthouse, chanting slogans long after the verdict had been announced.","t":"**大批**抗议者聚集在法院外面，在判决宣布后很长时间仍在高呼口号。"},
"lost-and-found":{"e":"She checked the airport's lost-and-found counter three separate times before someone finally turned in her missing umbrella.","t":"她去机场的**失物招领处**查了三次，才终于有人把她丢失的雨伞送回来。"},
"statistic":{"e":"One alarming statistic revealed that nearly a third of the bridges in the state needed urgent structural repairs.","t":"一项令人担忧的**统计数字**显示，该州近三分之一的桥梁都急需进行结构维修。"},
"break":{"e":"A single gunshot broke the silence of the forest, sending every bird within earshot scattering into the sky.","t":"一声枪响**打破**了森林的寂静，惊得方圆之内的每一只鸟都四散飞向天空。"},
"impart":{"e":"The old sailor loved to impart hard-won wisdom to younger crew members during the long, quiet night watches.","t":"这位老水手喜欢在漫长安静的夜班时间里把自己来之不易的智慧**传授**给年轻船员。"},
"cautious":{"e":"Doctors urged cautious optimism about the new treatment, warning that larger trials were still needed before any celebration.","t":"医生们呼吁对这种新疗法保持**谨慎**乐观，并警告说在庆祝之前还需要进行更大规模的试验。"},
"precious":{"e":"The locket was the only precious object she managed to save before the house burned to the ground.","t":"那个小盒式项链是她在房子被烧毁殆尽之前唯一设法抢救出来的**珍贵**物件。"},
"amount":{"e":"A surprising amount of food gets wasted in restaurants every single night, much of it still perfectly edible.","t":"餐厅每晚都会浪费**数量**惊人的食物，其中很多其实完全还能吃。"},
"steer":{"e":"The captain had to steer the ship carefully around the icebergs drifting silently through the dark northern waters.","t":"船长不得不小心地**驾驶**这艘船，绕开在黑暗的北方水域中悄然漂移的冰山。"},
"violate":{"e":"The factory was fined heavily after inspectors discovered it had violated safety codes for nearly two years.","t":"检查员发现这家工厂近两年来一直**违反**安全规范后，工厂被处以重罚。"},
"interval":{"e":"The nurse checked the patient's pulse at regular intervals throughout the night to catch any sudden change.","t":"护士整夜按固定**间隔**检查病人的脉搏，以便及时发现任何突发状况。"},
"ponderous":{"e":"The professor's ponderous lecture style put half the auditorium to sleep before the first hour had even ended.","t":"教授**沉闷**的授课风格让半个礼堂的人在第一个小时结束前就已经睡着了。"},
"visualize":{"e":"Athletes are often trained to visualize every step of the race before they ever set foot on the track.","t":"运动员常常被训练在踏上赛道之前先在脑海中**想象**比赛的每一步。"},
"emerald":{"e":"The ring's centerpiece was a flawless emerald that had been mined decades earlier in the Colombian mountains.","t":"这枚戒指的主石是一颗完美无瑕的**祖母绿**，几十年前开采自哥伦比亚山区。"},
"reference":{"e":"The novel makes a subtle reference to a war that is never named directly but shadows every chapter.","t":"这部小说对一场从未被直接点明、却笼罩着每一章的战争作了隐晦的**提及**。"},
"passive":{"e":"Rather than remaining passive during the discussion, she interrupted twice to correct the numbers on the contract.","t":"她没有在讨论中保持**被动**，而是两次打断对方以纠正合同上的数字。"},
"deductive":{"e":"The detective relied on deductive reasoning, eliminating suspects one by one until only a single possibility remained.","t":"这位侦探依靠**演绎**推理，逐一排除嫌疑人，直到只剩下一种可能。"},
"illustrate":{"e":"The teacher used a simple analogy about traffic to illustrate how electrical current flows through a circuit.","t":"老师用一个关于交通的简单类比来**说明**电流是如何在电路中流动的。"},
"advisable":{"e":"Given the approaching storm, the rangers decided it was no longer advisable for hikers to attempt the summit.","t":"鉴于暴风雨即将来临，护林员们认为徒步者再尝试登顶已经不再**可取**。"},
"hedge":{"e":"Gardeners trimmed the tall hedge into a neat rectangular shape every autumn before the first frost arrived.","t":"园丁们每年秋天第一场霜冻来临之前，都会把高高的**树篱**修剪成整齐的长方形。"},
"pyramid":{"e":"Thousands of laborers spent decades hauling limestone blocks to build the great pyramid for the pharaoh.","t":"数千名劳工花了数十年时间搬运石灰岩巨石，为法老建造这座宏伟的**金字塔**。"},
"liable":{"e":"The contract stated clearly that the landlord, not the tenant, would be liable for any structural damage.","t":"合同明确规定，对任何结构性损坏**负有责任**的是房东，而不是租客。"},
"exhort":{"e":"The old general would exhort his troops before every battle, reminding them why their cause mattered.","t":"这位老将军每次战斗前都会**告诫**他的部队，提醒他们为何而战。"},
"homosexuality":{"e":"The professor's course carefully traced how public attitudes toward homosexuality shifted dramatically across the entire twentieth century.","t":"教授的课程仔细追溯了整个二十世纪公众对**同性恋**的态度是如何发生巨大转变的。"},
"vivify":{"e":"The director's bold use of color and sound seemed to vivify every scene, even the quiet ones.","t":"导演大胆运用色彩与音效，似乎让每一个场景都**变得生动**起来，即便是安静的场景也不例外。"},
"ignite":{"e":"A single spark from the campfire was enough to ignite the dry brush covering the hillside.","t":"篝火里的一颗火星就足以**点燃**覆盖山坡的干燥灌木丛。"},
"spurn":{"e":"The young composer spurned every offer from major record labels, insisting on releasing his album independently.","t":"这位年轻的作曲家**拒绝**了各大唱片公司的所有邀约，坚持独立发行自己的专辑。"},
"uproot":{"e":"The hurricane's ferocious winds were strong enough to uproot century-old oak trees along the entire coastline.","t":"飓风狂猛的风力强大到足以把沿海岸线生长了一个世纪的橡树**连根拔起**。"},
"repetition":{"e":"Constant repetition of the same drill eventually allowed the pianist to play the passage without a single mistake.","t":"对同一个练习不断**重复**，最终让这位钢琴家能够毫无差错地演奏这一段落。"},
"assail":{"e":"Doubts began to assail her the night before the wedding, though she never mentioned them to anyone.","t":"婚礼前一晚，疑虑开始**困扰**着她，尽管她从未向任何人提起过。"},
"exemplify":{"e":"The tiny fishing village perfectly exemplifies the quiet resilience that has defined this coastline for generations.","t":"这个小渔村完美地**体现**了世代定义这片海岸线的那种沉静的韧性。"},
"permanence":{"e":"The sculptor chose granite specifically for its permanence, knowing the statue needed to survive centuries of harsh weather.","t":"雕塑家特意选择花岗岩正是因为它的**持久性**，他知道这座雕像需要经受住数百年恶劣天气的考验。"},
"recess":{"e":"The judge called a brief recess after the witness suddenly began sobbing uncontrollably while seated on the stand.","t":"证人突然在证人席上失声痛哭后，法官宣布**暂时休庭**。"},
"gang":{"e":"Police say a small gang had been responsible for a string of burglaries across the northern suburbs.","t":"警方称一个小型**团伙**对北部郊区发生的一连串入室盗窃案负有责任。"},
"ingenious":{"e":"The prisoners came up with an ingenious escape plan involving a tunnel hidden beneath a stack of library books.","t":"囚犯们想出了一个**巧妙**的越狱计划，在一堆图书馆书籍下面藏了一条隧道。"},
"replace":{"e":"The old wooden bridge was finally replaced with a steel structure able to withstand much heavier trucks.","t":"这座老旧的木桥终于被一座能承受更重卡车的钢结构桥**取代**。"},
"twist":{"e":"She twisted her ankle badly while running downhill, and the swelling kept her off the field for weeks.","t":"她在下坡跑步时严重**扭伤**了脚踝，肿胀让她好几周都无法参赛。"},
"extreme":{"e":"The desert swings between extremes of temperature, scorching by day and dropping below freezing after sunset.","t":"这片沙漠的气温在**极端**之间摆动，白天酷热难耐，日落后又骤降到冰点以下。"},
"alphabet":{"e":"Missionaries created a written alphabet for the previously unwritten language so scripture could finally be translated.","t":"传教士为这门此前没有文字的语言创造了一套**字母表**，使经文终于得以翻译。"},
"melanin":{"e":"Skin cells produce more melanin after sun exposure, which is why tanning happens as a protective response.","t":"皮肤细胞在受到日晒后会产生更多**黑色素**，这就是晒黑作为一种保护性反应发生的原因。"},
"zealous":{"e":"The zealous volunteer showed up before dawn every single day of the campaign, refusing to take even one morning off.","t":"这位**狂热**的志愿者在整个活动期间每天都在黎明前就到场，一个早晨都不肯休息。"},
"drawback":{"e":"The apartment was spacious and cheap, but its one serious drawback was the constant noise from the highway below.","t":"这套公寓宽敞又便宜，但它唯一严重的**缺点**就是楼下高速公路持续不断的噪音。"},
"somewhat":{"e":"The medication made her somewhat drowsy, though not enough to prevent her from driving home afterward.","t":"这种药让她**稍微**有些昏昏欲睡，但还不至于影响她之后开车回家。"},
"perform":{"e":"The orchestra will perform the entire symphony without a single pause, a demanding feat few ensembles ever attempt.","t":"这支管弦乐队将不间断地**演奏**整部交响曲，这是很少有乐团敢尝试的高难度壮举。"},
"buddy":{"e":"Every diver is assigned a buddy before entering the water, since no one is allowed to swim alone at that depth.","t":"每位潜水员下水前都会被分配一名**搭档**，因为在那个深度不允许任何人独自游泳。"},
"swallow":{"e":"The pelican tilted its head sharply back to swallow the entire fish in one smooth, practiced motion.","t":"塘鹅把头猛地向后一仰，用一个流畅娴熟的动作就把整条鱼**吞**了下去。"},
"pierce":{"e":"The arrow pierced the wooden board's outer ring, though it fell just short of the bullseye everyone had hoped for.","t":"这支箭**刺穿**了木板的外环，但离大家期望的靶心还差那么一点。"},
"recoil":{"e":"She recoiled instinctively in horror when the huge spider dropped from the ceiling onto the kitchen counter.","t":"当那只大蜘蛛从天花板掉落到厨房台面上时，她惊恐地本能**向后退缩**。"},
"infrastructure":{"e":"The government pledged billions toward rebuilding infrastructure damaged by the earthquake, starting with roads and hospitals.","t":"政府承诺投入数十亿资金重建被地震破坏的**基础设施**，从道路和医院开始。"},
"engraving":{"e":"The collector paid a small fortune for an original engraving created by the Flemish master himself.","t":"这位收藏家为一幅由那位佛兰德大师亲手创作的原版**版画**支付了一大笔钱。"},
"vehicle":{"e":"Every emergency vehicle in the county was dispatched to the wildfire within minutes of the first alarm.","t":"第一次警报响起后几分钟内，全县所有的应急**车辆**都被派往了那场野火现场。"},
"meteorological":{"e":"The expedition delayed its departure after meteorological data predicted a severe storm rolling in from the coast.","t":"探险队在**气象**数据预测到一场从海岸方向袭来的强风暴后推迟了出发时间。"},
"core":{"e":"Honesty forms the essential core of every relationship the therapist tries to help her clients slowly rebuild.","t":"诚实是这位治疗师试图帮助来访者慢慢重建的每一段关系的**核心**。"},
"strip":{"e":"The Olympic committee voted unanimously to strip the athlete of his medal after evidence of doping emerged.","t":"奥委会在兴奋剂证据浮出水面后一致投票决定**剥夺**这名运动员的奖牌。"},
"lace":{"e":"The wedding gown was trimmed with delicate lace that had been handmade by the bride's grandmother.","t":"婚纱上镶着精致的**蕾丝**边，是新娘的祖母亲手制作的。"},
"vacation":{"e":"The family postponed their vacation twice before finally flying to the coast for two relaxing weeks.","t":"这家人把**假期**推迟了两次，最终才飞往海边度过了两周的悠闲时光。"},
"stationary":{"e":"The exercise bike remained stationary no matter how hard she pedaled, since it was designed purely for indoor workouts.","t":"无论她蹬得多用力，这辆健身单车始终保持**静止**，因为它本就是专为室内锻炼设计的。"},
"notation":{"e":"Musicians of every tradition rely on standard notation to communicate rhythm and tempo across languages and generations.","t":"各种传统流派的音乐家都依靠标准**记谱法**来跨越语言和世代传达节奏与速度。"},
"prime":{"e":"The butcher reserved his prime cuts of beef for regular customers who had shopped there for years.","t":"这位屠夫把**上等**牛肉留给了那些在这里光顾多年的老顾客。"},
"specific":{"e":"The recipe called for one specific type of vinegar that proved nearly impossible to find outside Italy.","t":"这份食谱需要一种**特定**的醋，而这种醋在意大利以外几乎不可能找到。"},
"flock":{"e":"A massive flock of starlings swept low across the evening sky in shifting, tightly synchronized patterns.","t":"一大**群**椋鸟低低掠过傍晚的天空，形成变幻莫测又高度同步的图案。"},
"nectar":{"e":"Hummingbirds can visit more than a thousand flowers a day searching for enough nectar to fuel their rapid metabolism.","t":"蜂鸟一天能造访一千多朵花，只为寻找足够的**花蜜**来维持它们快速的新陈代谢。"},
"enactment":{"e":"The enactment of stricter emissions standards forced automakers to redesign their engines within just two years.","t":"更严格的排放标准的**颁布**迫使汽车制造商在短短两年内重新设计发动机。"},
"sluggish":{"e":"The old computer grew increasingly sluggish, taking nearly a full minute just to open a single document.","t":"这台旧电脑变得越来越**迟缓**，光是打开一个文档就要花将近一整分钟。"},
"district":{"e":"The historic district downtown attracts thousands of visitors each weekend who come to admire the colonial architecture.","t":"市中心的历史**街区**每个周末都吸引数千名游客前来欣赏殖民时期的建筑。"},
"silicate":{"e":"Geologists identified the greenish tint in the rock as evidence of a rare silicate mineral formed under intense pressure.","t":"地质学家判断这块岩石中的绿色调是一种在高压下形成的稀有**硅酸盐**矿物的证据。"},
"moral":{"e":"The philosopher argued that lying to protect a friend still raised a genuine moral dilemma worth examining.","t":"这位哲学家认为，为保护朋友而撒谎仍然引发了一个值得探讨的真正**道德**困境。"},
"pigeon":{"e":"City pigeons had grown so accustomed to tourists that they no longer bothered flying away when approached.","t":"城市里的**鸽子**已经习惯了游客，靠近时甚至懒得飞走。"},
"adaptive":{"e":"Species with highly adaptive behaviors tend to survive sudden environmental shifts far better than specialized ones.","t":"具有高度**适应性**行为的物种往往比高度特化的物种更能应对突如其来的环境变化。"},
"raw":{"e":"The chef insisted the tuna stay raw, sliced thin and served with nothing but soy sauce and wasabi.","t":"主厨坚持金枪鱼保持**生**的状态，只切薄片，配酱油与芥末食用。"},
"negotiation":{"e":"After months of tense negotiation, the two companies finally agreed on a price both sides could accept.","t":"经过几个月紧张的**谈判**，两家公司终于就一个双方都能接受的价格达成一致。"},
"delectable":{"e":"The bakery's delectable pastries drew a line down the block every Saturday morning before the doors even opened.","t":"这家面包店**美味可口的**糕点每周六早上开门前就已经排起长队。"},
"abrasion":{"e":"Years of sandstorms left visible abrasion on the statue's face, wearing its once-sharp features into a smooth blur.","t":"多年的沙尘暴在雕像脸上留下明显的**磨损**痕迹，把曾经分明的五官磨成一片模糊。"},
"fiber":{"e":"Doctors recommend eating more fiber, since it helps digestion and keeps blood sugar levels from spiking after meals.","t":"医生建议多摄入**纤维素**，因为它有助于消化，还能防止餐后血糖骤升。"},
"burrow":{"e":"The rabbit began to burrow frantically under the fence the moment it spotted the approaching fox.","t":"兔子一发现狐狸靠近，就开始在篱笆下疯狂地**挖洞**。"},
"regular":{"e":"Regular exercise, even just twenty minutes a day, can noticeably improve both your mood and your sleep quality.","t":"**有规律的**运动，哪怕每天只有二十分钟，也能明显改善情绪和睡眠质量。"},
"sum":{"e":"The total sum owed on the mortgage still felt overwhelming, even after a decade of steady monthly payments.","t":"抵押贷款所欠的**总额**依然令人生畏，尽管已经十年如一日地按月还款。"},
"defecate":{"e":"Veterinarians warn that a cat which suddenly stops trying to defecate may be suffering from a dangerous blockage.","t":"兽医警告说，如果一只猫突然不再尝试**排便**，可能是患上了危险的肠梗阻。"},
"crust":{"e":"Molten rock rises from deep within the mantle and slowly cools to form new oceanic crust.","t":"熔融的岩石从地幔深处上升，缓慢冷却后形成新的海洋**地壳**。"},
"scholar":{"e":"A respected scholar of ancient Rome, she spent thirty years deciphering inscriptions that no one else could read.","t":"作为一位受人尊敬的古罗马**学者**，她花了三十年破译无人能懂的铭文。"},
"abort":{"e":"Mission control had to abort the launch just seconds before liftoff when a fuel sensor reported a leak.","t":"发射前几秒，燃料传感器报告泄漏，任务控制中心不得不**中止**发射。"},
"motive":{"e":"Detectives struggled to find a credible motive for the robbery, since nothing valuable had actually been taken.","t":"侦探们很难找到这起抢劫案可信的**动机**，因为实际上并没有丢失任何值钱的东西。"},
"credentialism":{"e":"Critics argue that rampant credentialism forces qualified workers to spend years chasing degrees no job actually requires.","t":"批评者认为，泛滥的**文凭主义**迫使本已合格的员工花费数年追逐工作根本用不上的学位。"},
"divine":{"e":"The ancient king claimed divine authority, insisting that his every command carried the weight of the gods.","t":"那位古代国王宣称自己拥有**神圣的**权威，坚称他的每一道命令都带有神明的分量。"},
"cohere":{"e":"The professor's argument failed to cohere, jumping between three unrelated theories without ever tying them together.","t":"教授的论证未能**连贯**一致，在三个不相关的理论间跳来跳去，始终没有串联起来。"},
"monogamy":{"e":"Swans are often cited as a symbol of monogamy, since a mated pair typically stays together for life.","t":"天鹅常被当作**一夫一妻制**的象征，因为配对的天鹅通常会相伴终生。"},
"tame":{"e":"Generations of careful breeding made the once-wild horses remarkably tame, willing to let children ride them.","t":"经过几代人精心培育，这些曾经野性十足的马变得异常**驯服**，甚至愿意让孩子骑乘。"},
"fragment":{"e":"Archaeologists pieced together the ancient vase from dozens of fragments scattered across the tomb's dusty floor.","t":"考古学家用散落在墓室尘土地面上的数十块**碎片**拼出了这只古代花瓶。"},
"stigma":{"e":"Mental illness still carries a stigma in many workplaces, making employees reluctant to ask for time off to heal.","t":"在许多职场中，精神疾病仍带有**耻辱**的色彩，让员工不愿请假去治疗。"},
"outlive":{"e":"Giant tortoises often outlive the very humans who raised them, sometimes surviving for more than a century.","t":"巨型陆龟常常**比饲养它们的人类活得更久**，有时能存活一个多世纪。"},
"resent":{"e":"Many employees resent being asked to work weekends without any extra pay or even a word of thanks.","t":"许多员工**憎恶**被要求在周末工作却拿不到额外报酬，甚至连一句感谢都没有。"},
"degenerative":{"e":"Her grandfather was diagnosed with a degenerative nerve disease that gradually robbed him of his ability to walk.","t":"她祖父被诊断出患有一种**退行性**神经疾病，逐渐夺走了他行走的能力。"},
"knit":{"e":"The fractured bone took nearly eight weeks to knit properly, even with the cast keeping it perfectly still.","t":"尽管石膏一直固定着骨折处，那根骨头还是花了将近八周才完全**愈合**。"},
"recount":{"e":"Survivors of the shipwreck were asked to recount every detail of that terrifying night for the official inquiry.","t":"海难幸存者被要求向官方调查**讲述**那个可怕夜晚的每一个细节。"},
"financial":{"e":"The startup's financial troubles worsened when its biggest investor suddenly withdrew support just before the product launch.","t":"这家初创公司的**财务**困境在最大投资方于产品发布前突然撤资后进一步恶化。"},
"crusade":{"e":"The senator launched a personal crusade against plastic packaging, pushing bill after bill through a skeptical congress.","t":"这位参议员发起了一场反对塑料包装的个人**运动**，一次次将法案推动通过持怀疑态度的国会。"},
"grasshopper":{"e":"A single grasshopper can eat its own body weight in leaves within just twenty-four hours of hatching.","t":"一只**蚂蚱**在孵化后短短二十四小时内，就能吃掉相当于自身体重的树叶。"},
"voltage":{"e":"Engineers had to reduce the voltage running through the circuit before the overheated wires could cause a fire.","t":"工程师必须降低流过电路的**电压**，否则过热的电线可能引发火灾。"},
"fundamental":{"e":"Trust remains fundamental to any lasting relationship, whether it involves business partners, friends, or married couples.","t":"信任对任何持久的关系都是**根本**的，无论是商业伙伴、朋友还是夫妻。"},
"documentary":{"e":"The documentary followed three families for over a decade, capturing how poverty shaped their children's daily choices.","t":"这部**纪录片**跟拍了三个家庭长达十多年，记录了贫困如何塑造孩子们的日常选择。"},
"merchant":{"e":"A wealthy merchant funded the expedition, hoping the spices brought back would make his investment many times over.","t":"一位富有的**商人**资助了这次远征，希望带回的香料能让他的投资翻上好几倍。"},
"reform":{"e":"The new education reform aims to shrink class sizes and give every teacher more time for individual students.","t":"这项新的教育**改革**旨在缩小班级规模，让每位教师有更多时间照顾学生个体。"},
"facade":{"e":"Behind a calm facade, the negotiator was quietly panicking about how little time remained before the deadline.","t":"在平静的**表面**之下，谈判代表其实正为所剩无几的时间暗自恐慌。"},
"channel":{"e":"Diplomats used a secret back channel to keep talks alive even after public negotiations had completely broken down.","t":"即便公开谈判已彻底破裂，外交官们仍通过一条秘密**渠道**维持着沟通。"},
"vibration":{"e":"A faint vibration in the floorboards was the only warning residents had before the earthquake struck in full force.","t":"地板传来的一丝细微**振动**，是居民在地震全面来袭前唯一得到的预警。"},
"perfect":{"e":"No one expected the young gymnast to land a perfect routine on her very first attempt at the Olympics.","t":"没人料到这位年轻体操运动员在奥运首次亮相就能完成一套**完美**的动作。"},
"soak":{"e":"Grandmother always let the beans soak overnight in cold water before cooking them slowly the next morning.","t":"祖母总是让豆子在冷水里**浸泡**一整夜，第二天早上再慢慢炖煮。"},
"resume":{"e":"Flights were grounded for six hours before air traffic control allowed departures to resume across the entire region.","t":"航班停飞六个小时后，空中交通管制才允许整个地区的航班**重新开始**起飞。"},
"hardy":{"e":"Only the hardiest seedlings survived the unexpected frost that swept through the orchard in early May.","t":"只有最**耐寒**的树苗挺过了五月初席卷果园的意外霜冻。"},
"acid":{"e":"Her acid remarks about his cooking left him too embarrassed to ever invite guests over again.","t":"她对他厨艺的**尖刻**评论，让他再也不好意思邀请客人来家里做客。"},
"hieratic":{"e":"Egyptian priests recorded temple accounts in a cursive hieratic script rather than the slower, more formal hieroglyphs.","t":"埃及祭司用书写更快的**僧侣体**草书记录神庙账目，而不是使用更正式却缓慢的象形文字。"},
"thorn":{"e":"A single thorn from the rosebush pierced her thumb deep enough to draw a surprising amount of blood.","t":"玫瑰丛上的一根**刺**扎进她的拇指，深得让人意外地流了不少血。"},
"lethal":{"e":"Even a small dose of the plant's sap can prove lethal to any animal unlucky enough to swallow it.","t":"哪怕只是这种植物汁液的一小剂量，对任何不慎吞下它的动物来说都可能是**致命的**。"},
"grab":{"e":"She had to grab the toddler's hand just before he wandered straight into the busy street.","t":"她赶紧**一把抓住**那个蹒跚学步的孩子的手，就在他径直走向繁忙街道之前。"},
"contrary":{"e":"Contrary to what most investors expected, the company's stock rose sharply right after the disappointing earnings report.","t":"与大多数投资者的预期**相反**，公司股价在令人失望的财报公布后反而大幅上涨。"},
"heritage":{"e":"The old stone bridge is protected as part of the town's cultural heritage, so no one may alter it.","t":"那座古老的石桥作为小镇文化**遗产**的一部分受到保护，任何人都不得擅自改动。"},
"cavity":{"e":"The dentist found a small cavity forming near the back molar and recommended filling it before it worsened.","t":"牙医发现靠近后槽牙处正在形成一个小**龋洞**，建议在恶化之前补上。"},
"astronomical":{"e":"Repairing the flood-damaged bridge will apparently cost an astronomical sum that the city budget simply cannot cover.","t":"修复被洪水损坏的桥梁显然需要一笔**庞大**的费用，市财政根本无力承担。"},
"likewise":{"e":"The eldest daughter chose to study medicine, and her younger brother likewise decided to pursue a career in surgery.","t":"大女儿选择学医，弟弟**也同样**决定投身外科事业。"},
"exterior":{"e":"The building's exterior walls were repainted a soft gray, though the interior still needed extensive renovation.","t":"这栋楼的**外部**墙面被重新粉刷成柔和的灰色，但内部仍需大规模翻修。"},
"waste":{"e":"Leaving every light on overnight is a waste of electricity that adds up to real money over a year.","t":"整夜开着所有的灯是一种电力**浪费**，一年下来会累积成一笔不小的钱。"},
"primate":{"e":"Chimpanzees, as our closest living primate relatives, share nearly ninety-nine percent of their DNA with humans.","t":"黑猩猩作为与我们血缘最近的**灵长类**近亲，与人类共享近百分之九十九的DNA。"},
"supply":{"e":"A sudden drought cut the region's water supply so severely that farmers had to abandon half their crops.","t":"一场突如其来的干旱严重削减了该地区的水**供应**，农民不得不放弃一半的作物。"},
"convey":{"e":"Her trembling voice conveyed more genuine fear than any of the words she actually managed to say.","t":"她颤抖的声音所**传达**的真实恐惧，远超她实际说出口的任何话语。"},
"garb":{"e":"Dressed in traditional garb for the festival, the dancers moved through the square in a blur of color.","t":"舞者们穿着节日的传统**服装**，在广场上舞动出一片斑斓的色彩。"},
"stem":{"e":"The government rushed new regulations into place to stem the spread of counterfeit medicine through online pharmacies.","t":"政府紧急出台新规，以**遏制**假药通过网络药房蔓延。"},
"naive":{"e":"It was naive of him to assume that everyone at the negotiating table shared his good intentions.","t":"他**天真**地以为谈判桌上的每个人都和他一样怀着善意。"},
"prepare":{"e":"Volunteers worked through the night to prepare enough hot meals for every family displaced by the flood.","t":"志愿者们通宵工作，为每个因洪水流离失所的家庭**准备**足够的热食。"},
"underground":{"e":"Engineers discovered an entire underground network of tunnels beneath the old city that no map had ever recorded.","t":"工程师们在古城地下发现了一整套从未被任何地图记录过的**地下**隧道网络。"},
"alert":{"e":"The night watchman stayed alert throughout his entire shift, scanning every shadow for signs of intruders.","t":"值夜的守卫整个班次都保持着**警觉**，仔细留意每一处阴影中是否有入侵者的迹象。"},
"genetics":{"e":"Modern genetics has helped reveal why certain diseases run so persistently through particular families across many generations.","t":"现代**遗传学**揭示了为何某些疾病会在特定家族中世代顽固地延续下去。"},
"girder":{"e":"Inspectors found a hairline crack running along the main girder supporting the entire weight of the overpass.","t":"检查人员发现支撑整座立交桥重量的主**大梁**上有一道细小的裂纹。"},
"allergic":{"e":"After breaking out in hives, she discovered she was severely allergic to the peanuts hidden in the sauce.","t":"起了荨麻疹后，她才发现自己对酱汁里的花生严重**过敏**。"},
"bold":{"e":"The young architect made a bold decision to scrap the original blueprint entirely and start over from scratch.","t":"这位年轻建筑师做出了一个**大胆**的决定，彻底放弃原设计图，从零开始。"},
"determine":{"e":"Investigators are still working to determine exactly what caused the chemical to ignite inside the warehouse.","t":"调查人员仍在努力**查明**究竟是什么原因导致化学品在仓库内起火。"},
"refreshing":{"e":"Her refreshing honesty about the company's repeated failures stood out sharply against the usual corporate spin and denial.","t":"她对公司失误坦诚得**令人耳目一新**，与惯常的公关话术形成鲜明对比。"},
"vapor":{"e":"Thin vapor rose from the hot spring, curling into the cold morning air before vanishing entirely.","t":"稀薄的**水蒸气**从温泉中升起，在寒冷的晨间空气中盘旋片刻后便完全消散。"},
"asymmetrical":{"e":"The building's asymmetrical design, with one wing much taller than the other, drew criticism from local residents.","t":"这栋建筑**不对称**的设计——一翼远高于另一翼——招致了当地居民的批评。"},
"epoch":{"e":"Historians consider the invention of the printing press the beginning of an entirely new epoch in human communication.","t":"历史学家认为印刷机的发明开启了人类传播史上一个全新的**时代**。"},
"collision":{"e":"A minor collision between two delivery trucks caused a traffic jam that stretched for nearly five miles.","t":"两辆送货卡车间的一次轻微**碰撞**造成了将近五英里长的交通拥堵。"},
"revival":{"e":"The city's downtown has seen a remarkable revival in recent years, with empty storefronts replaced by thriving cafes.","t":"近年来，这座城市的市中心经历了显著的**复兴**，空置的店铺被生意兴隆的咖啡馆取代。"},
"galaxy":{"e":"Astronomers estimate that our galaxy alone contains more than a hundred billion stars, many with their own planets.","t":"天文学家估计，仅我们所在的**星系**就包含一千多亿颗恒星，其中许多都拥有自己的行星。"},
"shovel":{"e":"He grabbed a rusty shovel and began digging through the snowdrift blocking the driveway before dawn broke.","t":"他抓起一把生锈的**铁铲**，赶在天亮前开始清理挡住车道的积雪。"},
"spectacular":{"e":"Fireworks lit up the harbor in a spectacular display that drew thousands of spectators to the waterfront.","t":"烟花照亮了海港，呈现出一场**壮观**的表演，吸引了数千名观众涌向海滨。"},
"rely":{"e":"Small island communities often rely heavily on fishing and tourism for nearly all of their annual income.","t":"小岛社区往往严重**依赖**捕鱼业和旅游业来获取几乎全部的年收入。"},
"caption":{"e":"Each photograph in the exhibit carried a brief caption explaining exactly where and when it had been taken.","t":"展览中的每张照片都配有一段简短的**说明文字**，解释拍摄的确切时间和地点。"},
"detract":{"e":"A single spelling error on the sign did little to detract from the overall charm of the little shop.","t":"招牌上的一个拼写错误几乎没有**减损**这家小店整体的魅力。"},
"scourge":{"e":"Malaria remained a deadly scourge across the region long after most other tropical diseases had been controlled.","t":"在该地区大多数其他热带疾病都已得到控制之后，疟疾仍长期是致命的**祸害**。"},
"aberrant":{"e":"The scientist flagged the aberrant data point, suspecting a faulty sensor rather than a genuine anomaly.","t":"这位科学家标记出这个**异常的**数据点，怀疑是传感器故障，而非真实的异常现象。"},
"compressible":{"e":"Unlike liquids, gases are highly compressible, which is why they can be stored under enormous pressure in small tanks.","t":"与液体不同，气体具有高度**可压缩性**，这就是为什么它们能以极高压力储存在小型容器中。"},
"ponder":{"e":"She sat by the window for an hour, quietly pondering whether to accept the job offer abroad.","t":"她在窗边坐了一个小时，静静地**思索**要不要接受那份海外工作邀约。"},
"suspense":{"e":"The novel's final chapter builds almost unbearable suspense, refusing to reveal the killer's identity until the last page.","t":"小说的最后一章营造出近乎难以忍受的**悬念**，直到最后一页才揭晓凶手身份。"},
"immigrate":{"e":"Her grandparents chose to immigrate to Canada in the 1960s, leaving behind everything familiar for an uncertain future.","t":"她的祖父母在20世纪60年代选择**移民**加拿大，抛下了所有熟悉的一切，奔赴不确定的未来。"},
"charismatic":{"e":"The charismatic young senator could sway skeptical voters with little more than a confident smile and a firm handshake.","t":"这位**极具魅力**的年轻参议员，仅凭自信的微笑和有力的握手就能打动怀疑的选民。"},
"smear":{"e":"Rival campaigns spent millions trying to smear the candidate with accusations that later proved completely false.","t":"竞争对手的阵营花费数百万试图**诋毁**这位候选人，而这些指控后来被证明完全是子虚乌有。"},
"wretch":{"e":"The old sailor was dismissed as a pitiful wretch, muttering about sea monsters no one else had ever seen.","t":"那位老水手被人当作一个可怜的**苦命人**，嘴里咕哝着谁也没见过的海怪。"},
"ruthless":{"e":"The company's ruthless cost-cutting measures left thousands of loyal employees without jobs just before the holidays began.","t":"公司**无情**的削减成本举措，让数千名忠诚的员工在节假日前夕失去了工作。"},
"cohabitation":{"e":"Many young couples now choose cohabitation before marriage, treating it as a practical trial run for shared life.","t":"如今许多年轻情侣会在婚前选择**同居**，把它当作共同生活的实际试验期。"},
"synonym":{"e":"Students often assume that every synonym listed in a thesaurus can replace a word without changing its tone.","t":"学生常常误以为词典里列出的每个**同义词**都能替换原词而不改变语气。"},
"proportion":{"e":"A surprisingly large proportion of the university's graduates go on to work in public health rather than private industry.","t":"这所大学的毕业生中，出人意料地有很大**比例**选择投身公共卫生而非私营行业。"},
"reddish":{"e":"The evening sky turned a soft reddish hue just before the sun disappeared completely behind the hills.","t":"傍晚的天空在太阳完全隐没于群山之后转变成一片柔和的**微红**色。"},
"construction":{"e":"Construction on the new bridge stalled for months after engineers discovered unstable soil beneath the riverbank.","t":"工程师发现河岸下方土质不稳后，新桥的**施工**停滞了数月。"},
"fellowship":{"e":"Winning the prestigious fellowship allowed her to spend a full year researching coral reefs without financial worry.","t":"荣获这项声望极高的**奖学金**，让她得以用一整年时间安心研究珊瑚礁，无需为经济发愁。"},
"architect":{"e":"The architect spent months studying the site's natural light before drawing a single line of the blueprint.","t":"这位**建筑师**在画出设计图的第一笔之前，花了数月研究场地的自然采光。"},
"band":{"e":"The local band rehearsed every night in a friend's garage, hoping someone at the festival would notice them.","t":"这支本地**乐队**每晚都在朋友家车库排练，希望音乐节上有人能注意到他们。"},
"gemstone":{"e":"Miners searched the riverbed for hours before finally uncovering a single flawless gemstone buried beneath the gravel.","t":"矿工们在河床里搜寻了数小时，终于在碎石下发现了一颗毫无瑕疵的**宝石**。"},
"flu":{"e":"The flu spread rapidly through the dormitory, forcing the university to cancel classes for nearly a week.","t":"**流感**在宿舍楼里迅速蔓延，迫使学校取消了将近一周的课程。"},
"thesis":{"e":"It took her nearly two years to gather enough data to support the central thesis of her dissertation.","t":"她花了将近两年时间收集数据，才足以支撑她论文的核心**论点**。"},
"clan":{"e":"Even after moving to different countries, members of the clan gathered every summer for a massive family reunion.","t":"即便分散移居到不同国家，这个**家族**的成员每年夏天仍会齐聚一堂举行盛大的家庭聚会。"},
"reflect":{"e":"Before answering, the interviewer asked her to reflect for a moment on her greatest professional failure.","t":"面试官在她回答之前，让她先**深思**片刻，想想自己职业生涯中最大的失败。"},
"deserted":{"e":"By midnight, the once-bustling market square stood completely deserted, its stalls shuttered and the cobblestones silent.","t":"到了午夜，曾经熙熙攘攘的集市广场变得完全**空无一人**，摊位紧闭，一片寂静。"},
"lobby":{"e":"Environmental groups continued to lobby lawmakers for stricter emissions standards despite fierce opposition from major manufacturers.","t":"尽管遭到各大制造商的强烈反对，环保组织仍持续**游说**立法者制定更严格的排放标准。"},
"probe":{"e":"Scientists sent a small robotic probe deep into the cave system to map passages too narrow for humans.","t":"科学家们派遣一个小型机器人**探测器**深入洞穴系统，绘制出人类无法通过的狭窄通道地图。"},
"thereby":{"e":"The merger eliminated duplicate management positions, thereby saving the combined company millions of dollars each year.","t":"此次合并消除了重复的管理职位，**从而**为合并后的公司每年节省数百万美元。"},
"toed":{"e":"Biologists classified the salamander as web-toed, noting thin membranes of skin stretched between each of its toes.","t":"生物学家将这种蝾螈归类为**有蹼趾的**，并指出其趾间有薄薄的皮膜相连。"},
"vigilance":{"e":"Airport security requires constant vigilance, since a single moment of carelessness could let a genuine threat slip through.","t":"机场安检需要持续保持**警惕**，因为哪怕一瞬间的疏忽都可能让真正的威胁蒙混过关。"},
"legislature":{"e":"The state legislature spent weeks debating the budget before finally passing a compromise version just before the deadline.","t":"州**立法机关**花了数周辩论预算案，终于在截止日期前通过了一个折中版本。"},
"gaseous":{"e":"Water can exist in solid, liquid, or gaseous form, depending entirely on its surrounding temperature and pressure.","t":"水可以以固态、液态或**气态**存在，这完全取决于周围的温度和压力。"},
"artificial":{"e":"The lake behind the dam is entirely artificial, created decades ago to supply the growing city with drinking water.","t":"大坝后面的这片湖泊完全是**人造**的，几十年前建成用以为不断扩张的城市供应饮用水。"},
"oxide":{"e":"Rust is simply a common iron oxide that forms when metal is exposed to moisture and oxygen over time.","t":"铁锈其实就是一种常见的铁**氧化物**，是金属长期暴露在潮气和氧气中形成的。"},
"debt":{"e":"The couple spent five grueling years paying off the debt they had accumulated during the recession.","t":"这对夫妇花了五年艰难岁月，才还清了他们在经济衰退期间积累的**债务**。"},
"glean":{"e":"Reporters could only glean a few scattered facts from witnesses who were too shaken to give a full account.","t":"记者们只能从惊魂未定、无法完整叙述的目击者那里**零星搜集**到几条信息。"},
"rural":{"e":"Broadband internet remains scarce in many rural communities, leaving farmers without reliable access to online markets.","t":"宽带网络在许多**乡村**社区依然稀缺，使农民无法可靠地接入网络市场。"},
"tally":{"e":"Election workers stayed up all night to tally the votes from every precinct before the morning deadline.","t":"选举工作人员彻夜未眠，在早晨截止时间前**清点**完每个投票站的选票。"},
"curl":{"e":"Smoke began to curl from the chimney the moment she lit the first log in the fireplace.","t":"她刚在壁炉里点燃第一根木柴，炊烟就开始从烟囱**袅袅盘旋**而上。"},
"snack":{"e":"Instead of a full lunch, she grabbed a quick snack from the vending machine between back-to-back meetings.","t":"她没有吃正餐，而是在两场连续的会议之间从自动售货机匆匆买了一份**小吃**。"},
"broadcast":{"e":"The station decided to broadcast the emergency alert nationwide the moment the storm turned toward the coast.","t":"电台在风暴转向海岸的那一刻，决定在全国范围内**广播**这条紧急警报。"},
"angiosperm":{"e":"Flowering plants, classified as angiosperms, make up the vast majority of plant life on Earth today.","t":"开花植物被归类为**被子植物**，构成了今天地球植物生命的绝大多数。"},
"cramped":{"e":"Six of us shared one cramped apartment that barely had room for a single bed, let alone a couch.","t":"我们六个人挤在一间**狭小**的公寓里，连放一张单人床都勉强，更别说沙发了。"},
"shellfish":{"e":"Chefs at the coastal restaurant pride themselves on serving shellfish caught fresh from the bay that same morning.","t":"这家海边餐厅的厨师们以供应当天早晨刚从海湾捕获的**贝类**海鲜为傲。"},
"postpone":{"e":"Organizers had no choice but to postpone the outdoor wedding when the forecast predicted heavy thunderstorms all weekend.","t":"天气预报显示整个周末都会有强雷暴，组织者别无选择，只能**推迟**这场户外婚礼。"},
"trace":{"e":"Genealogists were able to trace the family's roots back nearly four centuries to a small village in Wales.","t":"家谱学家得以将这个家族的根源**追溯**到近四百年前威尔士的一个小村庄。"},
"gnaw":{"e":"Mice had managed to gnaw through the wooden baseboard, leaving a ragged hole just large enough to squeeze through.","t":"老鼠已经**啃**穿了木制踢脚板，留下一个刚好能挤过去的参差不齐的洞。"},
"petition":{"e":"Neighbors circulated a petition demanding that the city install a traffic light at the dangerous intersection nearby.","t":"邻居们传阅了一份**请愿书**，要求市政府在这个危险的路口安装红绿灯。"},
"arrange":{"e":"She spent the entire afternoon trying to arrange the seating chart so that no two feuding relatives sat together.","t":"她花了一整个下午试图**安排**座位表，好让互有矛盾的亲戚们不必同桌而坐。"},
"tribal":{"e":"Tribal elders gathered around the fire each evening to pass down stories that had survived for generations.","t":"**部落**长老们每晚都会围坐在篝火旁，传承那些流传了好几代人的故事。"},
"destination":{"e":"After three connecting flights and a long layover, they finally reached their destination just before midnight.","t":"转乘三趟航班并经历一次长时间中转后，他们终于在午夜前抵达了**目的地**。"},
"reconstruction":{"e":"Reconstruction of the earthquake-damaged neighborhood took nearly a decade and required funding from several international agencies.","t":"这个地震受损街区的**重建**耗时近十年，需要多个国际机构提供资金支持。"},
"attach":{"e":"Please attach your official transcript and two signed letters of recommendation before submitting the completed online application.","t":"请在提交在线申请之前**附上**成绩单和两封推荐信。"},
"seismic":{"e":"The seismic activity recorded overnight suggested that a much larger earthquake might strike the fault line soon.","t":"夜间记录到的**地震**活动表明，这条断层可能很快会发生一场更大的地震。"},
"nonetheless":{"e":"The bridge was old and creaked with every gust of wind; nonetheless, engineers certified it as structurally sound.","t":"这座桥又老又旧，每次刮风都会发出吱呀声；**尽管如此**，工程师们仍认证它在结构上是安全的。"},
"abstract":{"e":"Explaining an abstract concept like justice to a five-year-old requires far simpler language than a courtroom would ever use.","t":"向一个五岁孩子解释正义这种**抽象**概念，需要比法庭用语简单得多的语言。"},
"barren":{"e":"Decades of drought turned the once-fertile valley into a barren stretch of cracked earth where nothing grew.","t":"数十年的干旱把这片曾经肥沃的山谷变成了寸草不生、土地龟裂的**贫瘠**地带。"},
"sore":{"e":"Her legs were sore for days after running the marathon without having trained nearly enough beforehand.","t":"在没有做好充分训练的情况下跑完马拉松后，她的双腿**疼痛**了好几天。"},
"familiarize":{"e":"New hires spend their first week shadowing veteran staff to familiarize themselves with the factory's safety procedures.","t":"新员工第一周会跟随资深员工，**熟悉**工厂的安全操作流程。"},
"dragonfly":{"e":"A bright blue dragonfly hovered motionless above the pond before darting suddenly toward a passing mosquito.","t":"一只鲜蓝色的**蜻蜓**静止悬停在池塘上方，随后突然朝一只飞过的蚊子冲去。"},
"setting":{"e":"The novel's setting, a remote fishing village battered by constant storms, mirrors the isolation its main character feels.","t":"小说的**背景**——一个常年遭受风暴侵袭的偏远渔村——映衬出主人公内心的孤独。"},
"multiply":{"e":"Bacteria in the petri dish can multiply exponentially, doubling in number every twenty minutes under ideal warm, moist conditions.","t":"在理想的温暖潮湿条件下，细菌能够**呈指数式繁殖**，每二十分钟数量就会翻一番。"},
"luxury":{"e":"Growing up on a farm with no running water, she never thought of a hot shower as a luxury.","t":"在没有自来水的农场长大，她从未把热水淋浴当作一种**奢侈**，直到离家后才意识到。"},
"bellows":{"e":"The blacksmith pumped the bellows steadily, feeding the forge fire until the iron glowed bright orange.","t":"铁匠持续地拉动**风箱**，给炉火供氧，直到铁块烧得发出明亮的橙色光芒。"},
"accomplish":{"e":"With limited funding and only three volunteers, the small charity managed to accomplish far more than anyone expected.","t":"尽管资金有限、只有三名志愿者，这家小慈善机构还是**完成**了远超所有人预期的成果。"},
"ripe":{"e":"The peaches hanging from the lowest branches were finally ripe enough to pick, their skin blushing a deep orange.","t":"挂在最低枝头的桃子终于**成熟**到可以采摘，果皮泛着深浓的橙色。"},
"detective":{"e":"The detective examined the muddy footprints outside the window, certain they belonged to someone far taller than the suspect.","t":"这位**侦探**仔细察看窗外的泥泞脚印，确信它们属于一个比嫌疑人高得多的人。"},
"survive":{"e":"Few of the original settlers managed to survive that first brutal winter without adequate food or shelter.","t":"最初的定居者中，很少有人能在缺乏充足食物和住所的情况下**幸存**过第一个残酷的冬天。"},
"merchandise":{"e":"The store's holiday merchandise sold out within hours, forcing managers to reorder stock twice in a single week.","t":"这家商店的节日**商品**几小时内就销售一空，迫使经理们一周内两次追加订货。"},
"temper":{"e":"His quick temper often got him into trouble, especially when referees made calls he disagreed with.","t":"他火爆的**脾气**常常给他惹麻烦，尤其是当裁判做出他不认同的判罚时。"},
"counterpart":{"e":"The American negotiator built a surprisingly warm rapport with her counterpart from the visiting Japanese delegation that week.","t":"这位美国谈判代表与日本代表团中和她**对应的人**建立了出人意料的融洽关系。"},
"seal":{"e":"Workers used molten wax to seal the ancient scroll inside a protective glass case before shipping it overseas.","t":"工作人员用熔化的蜡把这份古老的卷轴**密封**进保护性玻璃盒中，然后再运往海外。"},
"bounce":{"e":"The rubber ball hit the pavement hard and continued to bounce erratically down the steep hill.","t":"橡皮球重重砸在人行道上，随后不规则地**弹跳**着滚下陡坡。"},
"graphics":{"e":"The game's graphics improved dramatically after developers spent an extra year refining every texture and lighting effect.","t":"开发者多花了一年时间打磨每一处纹理和光影效果后，这款游戏的**画面**有了显著提升。"},
"pause":{"e":"She had to pause mid-sentence, overwhelmed by a wave of emotion she hadn't expected to feel.","t":"她不得不在话说到一半时**停顿**下来，被一阵意想不到的情绪浪潮所淹没。"},
"giraffe":{"e":"The giraffe stretched its long neck to reach the tender leaves at the very top of the acacia tree.","t":"**长颈鹿**伸长脖子去够金合欢树最顶端的嫩叶。"},
"limitation":{"e":"Every model has some limitation, and a good scientist always states clearly what the data cannot explain.","t":"每个模型都有其**局限性**，优秀的科学家总会清楚说明数据无法解释的部分。"},
"assortment":{"e":"The gift basket contained a colorful assortment of cheeses, crackers, and jams from several local farms nearby.","t":"这个礼品篮里装着来自本地农场的**各式各样**的奶酪、饼干和果酱。"},
"predominate":{"e":"Pine and spruce trees predominate throughout the northern forest, though a few stubborn oaks cling to the lower slopes.","t":"松树和云杉在北部森林中**占据主导**地位，尽管低坡上仍有几棵顽强的橡树存活。"},
"reproach":{"e":"Her father's silent reproach across the dinner table hurt far more than any shouted lecture ever could have.","t":"晚餐桌上父亲沉默的**责备**眼神，远比任何大声的训斥都更让她难受。"},
"pharaoh":{"e":"The young pharaoh ordered a magnificent temple built to honor the gods who had granted him the throne.","t":"这位年轻的**法老**下令建造一座宏伟的神庙，以敬奉赐予他王位的诸神。"},
"circulate":{"e":"Rumors began to circulate through the office long before management made any official announcement about the layoffs.","t":"早在管理层就裁员做出任何正式宣布之前，谣言就已经在办公室里**流传**开来。"},
"glorious":{"e":"The team's glorious victory in the final match was celebrated with a parade through the entire city.","t":"球队在决赛中取得的**辉煌**胜利，以一场贯穿全城的游行庆祝活动收尾。"},
"focal":{"e":"The fireplace serves as the focal point of the living room, drawing every eye the moment you walk in.","t":"壁炉是客厅的**焦点**，一走进房间视线就会立刻被它吸引。"},
"hearsay":{"e":"The judge dismissed the witness's claim as mere hearsay, since she had not seen the accident herself.","t":"法官驳回了这位证人的说法，认为那不过是**道听途说**，因为她本人并未目睹事故经过。"},
"lofty":{"e":"The charity's founder set lofty goals from the very beginning, vowing to end child hunger within a single decade.","t":"这家慈善机构的创始人从一开始就设立了**崇高**的目标，誓言在十年内消除儿童饥饿问题。"},
"nimble":{"e":"The nimble goalkeeper dove across the entire goal in a fraction of a second to block the shot.","t":"这位**敏捷**的守门员在电光石火间飞身扑向整个球门，挡下了那记射门。"},
"perpetual":{"e":"The old clock tower has run in perpetual motion since 1890, stopping only twice for essential repairs.","t":"这座古老的钟楼自1890年以来一直处于**永久**运转状态，只因必要维修停摆过两次。"},
"extinguish":{"e":"Firefighters worked for six straight hours to extinguish the blaze that had engulfed the entire warehouse.","t":"消防员连续奋战六个小时，才**扑灭**了吞噬整座仓库的大火。"},
"dote":{"e":"Grandparents tend to dote on their first grandchild, showering the baby with gifts far beyond what the parents allow.","t":"祖父母往往会**溺爱**他们的第一个孙辈，给孩子的礼物远超父母所允许的范围。"},
"consecutive":{"e":"The team won six consecutive championships before finally losing in the finals to a much younger squad.","t":"这支球队**连续**六年夺冠，最终才在决赛中输给了一支年轻得多的队伍。"},
"liberal":{"e":"Her liberal upbringing encouraged her to question authority and form her own opinions from an early age.","t":"她**开明**的成长环境鼓励她从小就质疑权威，形成自己的观点。"},
"rental":{"e":"They picked up a rental car at the airport and drove three hours to reach the coastal town.","t":"他们在机场取了一辆**租赁**汽车，开了三个小时才抵达那座海滨小镇。"},
"skeletal":{"e":"The museum proudly displayed the dinosaur's skeletal remains, reconstructed bone by bone over nearly two full years.","t":"博物馆展出了这只恐龙的**骨骼**遗骸，经过近两年时间一根骨头一根骨头地复原而成。"},
"tough":{"e":"Negotiating with the union proved tough, since neither side was willing to budge on wages or benefits.","t":"与工会的谈判**十分棘手**，因为双方都不愿在薪资或福利上让步。"},
"clump":{"e":"A clump of wildflowers grew stubbornly through a crack in the abandoned parking lot's cracked pavement.","t":"一**丛**野花顽强地从废弃停车场龟裂的路面缝隙中钻了出来。"},
"poetry":{"e":"She discovered a passion for poetry after a single high school teacher introduced her to Emily Dickinson.","t":"一位高中老师让她接触到艾米莉·狄金森的作品后，她发现了自己对**诗歌**的热情。"},
"repertoire":{"e":"The touring orchestra expanded its repertoire to include contemporary composers alongside the usual classical staples audiences expected.","t":"这支管弦乐团扩充了自己的**保留曲目**，在常规古典经典之外加入了当代作曲家的作品。"},
"imitate":{"e":"Young children instinctively imitate the facial expressions and subtle gestures of the adults surrounding them every day.","t":"幼儿会本能地**模仿**周围成年人的面部表情和手势。"},
"exploit":{"e":"The company was accused of trying to exploit a legal loophole to avoid paying millions in taxes.","t":"这家公司被指控试图**利用**一个法律漏洞来逃避数百万美元的税款。"},
"rally":{"e":"Down by twenty points at halftime, the team managed to rally and win the game in the final minute.","t":"中场时落后二十分，这支球队还是设法**重新振作**，在最后一分钟赢下了比赛。"},
"specify":{"e":"The contract failed to specify who would be responsible for repairs, leading to a bitter dispute later.","t":"合同未能**明确规定**由谁负责维修，后来因此引发了一场激烈的纠纷。"},
"genetic":{"e":"Researchers recently identified a rare genetic mutation that appears to protect certain individuals from the disease entirely.","t":"研究人员发现了一种**基因**突变，似乎能让某些人完全免受这种疾病的侵袭。"},
"scatter":{"e":"A sudden clap of thunder made the pigeons scatter in every direction across the crowded plaza below.","t":"一声突如其来的雷声让广场上的鸽子朝四面八方**四散**飞去。"},
"desperate":{"e":"With the last train leaving in two minutes, he made a desperate dash across the entire station.","t":"最后一班火车两分钟后就要开走，他**拼命**冲过了整个车站。"},
"proliferate":{"e":"Online scams began to proliferate as more elderly people gained access to smartphones and social media.","t":"随着越来越多老年人开始使用智能手机和社交媒体，网络诈骗开始**激增**。"},
"errand":{"e":"She ran a quick errand to the pharmacy before the storm made the roads impossible to drive on.","t":"趁着暴风雨还没把道路变得无法通行，她赶紧跑去药店办了个**差事**。"},
"horde":{"e":"A horde of eager shoppers pushed through the doors the instant the store opened for its Black Friday sale.","t":"商店黑色星期五促销一开门，**一大群**热切的顾客就涌了进去。"},
"literacy":{"e":"The charity's main mission is improving literacy among children in villages that still lack any formal school.","t":"这家慈善机构的主要使命是提高那些仍缺乏正规学校的村庄里儿童的**读写能力**。"},
"coverage":{"e":"Media coverage of the trial grew so intense that the judge eventually moved proceedings to a different city.","t":"有关这场审判的**新闻报道**愈演愈烈，以至于法官最终将诉讼程序转移到了另一座城市。"},
"subsidy":{"e":"The government offers a generous subsidy to farmers who switch from pesticides to organic growing methods.","t":"政府向从使用农药转向有机种植方法的农民提供丰厚的**补助金**。"},
"evidence":{"e":"Prosecutors presented DNA evidence directly linking the suspect to the scene of the crime that night.","t":"检方出示了DNA**证据**，直接将嫌疑人与当晚的犯罪现场联系起来。"},
"vivid":{"e":"Her vivid description of the shipwreck made listeners feel as though they were standing on the deck themselves.","t":"她对沉船事件**生动**的描述，让听众仿佛亲身站在了甲板上。"},
"suspension":{"e":"The truck's upgraded suspension absorbed most of the shock from the potholes on the unpaved mountain road.","t":"这辆卡车升级后的**悬架**系统吸收了未铺装山路上大部分坑洼带来的震动。"},
"cape":{"e":"Sailors long feared rounding the cape, where sudden violent storms had wrecked ships for centuries without warning.","t":"水手们长期以来都惧怕绕行这处**海角**，那里突如其来的猛烈风暴曾无数次让船只失事。"},
"sled":{"e":"Children pulled their wooden sled up the hill again and again, never tiring of the ride back down.","t":"孩子们一次又一次地把木**雪橇**拉上山坡，永远不会厌倦滑下来的乐趣。"},
"current":{"e":"A powerful current swept the swimmer far from shore before the lifeguard managed to reach him.","t":"在救生员赶到之前，一股强劲的**水流**已经把这名游泳者冲离岸边很远。"},
"vital":{"e":"Access to clean drinking water is vital to preventing the spread of disease throughout crowded refugee camps.","t":"获得清洁饮用水对于防止疾病在拥挤的难民营中蔓延**至关重要**。"},
"besiege":{"e":"Enemy forces continued to besiege the castle for nearly a year before its defenders finally surrendered.","t":"敌军**围困**这座城堡将近一年，守军才最终投降。"},
"media":{"e":"Social media has transformed how political campaigns reach young voters who rarely watch traditional television news.","t":"社交**媒体**已经改变了政治竞选团队接触年轻选民的方式，因为这些选民很少收看传统电视新闻。"},
"introduction":{"e":"The introduction of an invasive fish species devastated the lake's native trout population within just five years.","t":"一种入侵鱼类的**引进**，在短短五年内就摧毁了这片湖泊本土鳟鱼的种群。"},
"scout":{"e":"The coach sent an assistant to scout the rival team's next three games before the championship.","t":"教练派了一名助理教练去**侦察**对手球队接下来的三场比赛，为冠军赛做准备。"},
"herd":{"e":"A herd of wildebeest thundered across the plain, kicking up a massive cloud of dust visible for miles.","t":"一**群**角马在平原上疾驰而过，扬起的滚滚尘土数英里外都能看见。"},
"abrupt":{"e":"Her abrupt departure in the middle of the meeting left her colleagues confused and scrambling to explain her absence to the client.","t":"她**突然**在会议进行到一半时离开，让同事们困惑不已，还得手忙脚乱地向客户解释她的缺席。"},
"sew":{"e":"Grandmother would sew each torn hem by hand, refusing to let a sewing machine touch her grandchildren's clothes.","t":"祖母总是亲手**缝补**每一处裂开的衣边，绝不让缝纫机碰她孙辈的衣服。"},
"buck":{"e":"The startup chose to buck the trend by opening physical stores just as every competitor rushed online.","t":"这家初创公司**逆势而为**，在所有竞争对手都涌向线上时选择开设实体店。"},
"graph":{"e":"The scientist studied the graph carefully, noticing that the curve dipped sharply right before every recorded earthquake.","t":"科学家仔细研究这张**图表**，注意到曲线在每次记录到地震前都会急剧下降。"},
"shuttle":{"e":"A small van used to shuttle passengers between the remote parking lot and the terminal every ten minutes.","t":"一辆小型面包车每隔十分钟就在偏远停车场和航站楼之间**穿梭往返**，接送乘客。"},
"sake":{"e":"For the sake of her younger siblings, she postponed her own college plans and took a full-time job instead.","t":"**为了**弟弟妹妹着想，她推迟了自己的大学计划，转而找了一份全职工作。"},
"flap":{"e":"The startled goose began to flap its wings furiously, scattering feathers across the pond before it finally rose into the air.","t":"受惊的大鹅开始猛烈地**拍打**翅膀，羽毛散落一池塘，随后才终于飞起。"},
"horizon":{"e":"Living abroad for a year broadened her horizons far more than any textbook could, teaching her to question long-held assumptions.","t":"出国生活一年极大地拓宽了她的**眼界**，比任何教科书都更能教会她质疑那些根深蒂固的假设。"},
"sauce":{"e":"The chef simmered the tomato sauce for hours, letting the garlic and basil deepen into something worth savoring slowly.","t":"厨师将番茄**酱汁**小火慢炖了几个小时，让大蒜和罗勒的味道慢慢变得浓郁，值得细细品味。"},
"adjunct":{"e":"The new wing was built as an adjunct to the main hospital, handling overflow patients during flu season.","t":"这栋新楼是作为主医院的**附属设施**建造的，用于在流感季节收治超额病人。"},
"wasp":{"e":"A wasp had built its papery nest under the porch eaves, and nobody dared go near the steps.","t":"一只**黄蜂**在门廊屋檐下筑了个纸质的巢，没人敢靠近那几级台阶。"},
"stalk":{"e":"The lioness began to stalk the wounded gazelle, crouching low in the tall grass to stay hidden.","t":"母狮开始**悄悄跟踪**那只受伤的瞪羚，在高高的草丛中低伏着身子以隐藏自己。"},
"part-time":{"e":"She took a part-time job at the library to cover her tuition while finishing her degree at night.","t":"她在图书馆找了一份**兼职**工作来支付学费，同时晚上继续完成学位课程。"},
"harbor":{"e":"Despite her calm exterior, she continued to harbor deep resentment toward the colleague who had taken credit for her work.","t":"尽管表面平静，她心里始终**怀有**对那位窃取她工作成果的同事的深深怨恨。"},
"irrigate":{"e":"An elaborate network of ancient canals still irrigates these dry fields every spring, turning barren land into fertile cropland for miles around.","t":"一套古老精巧的运河网络至今仍在每年春天**灌溉**这些干旱的农田，将贫瘠的土地变成方圆数英里的肥沃耕地。"},
"communicate":{"e":"Deaf since birth, she learned to communicate fluently through sign language long before she ever spoke a word aloud.","t":"她生来失聪，早在开口说出第一个词之前，就已经学会用手语流利地**交流**。"},
"portion":{"e":"The restaurant serves such a generous portion that most customers end up taking half of it home in a box.","t":"这家餐厅提供的**分量**非常大，以至于大多数顾客最后都要打包一半带回家。"},
"authority":{"e":"After decades studying coral reefs, she became the leading authority that governments consulted whenever a new marine policy was drafted.","t":"经过数十年研究珊瑚礁，她成了各国政府起草新海洋政策时都要请教的**权威专家**。"},
"clinic":{"e":"The free clinic downtown treats hundreds of uninsured patients each week, often relying entirely on volunteer doctors and donated medicine.","t":"市中心的免费**诊所**每周要为数百名没有医保的病人看病，常常完全依靠志愿医生和捐赠药品维持运转。"},
"sanctuary":{"e":"The old monastery became a sanctuary for refugees fleeing the war, offering food and shelter to anyone who arrived.","t":"这座古老的修道院成了逃离战乱的难民的**庇护所**，为每一个到来的人提供食物和栖身之所。"},
"linguist":{"e":"As a linguist specializing in dying languages, she spends months in remote villages recording elders before their dialects disappear entirely.","t":"作为一名专攻濒危语言的**语言学家**，她常常在偏远村庄一待就是几个月，赶在方言彻底消失前记录下老人们的话语。"},
"closet":{"e":"The negotiators closeted themselves in a back room for six hours until they finally hammered out a compromise everyone could accept.","t":"谈判代表们把自己**关在**一间密室里长达六个小时，直到终于敲定了一个人人都能接受的折中方案。"},
"bookstore":{"e":"The independent bookstore on the corner survived only because loyal customers kept returning even after the chain store opened nearby.","t":"街角那家独立**书店**能存活下来，全靠忠实顾客不断光顾，即便附近开了连锁书店也是如此。"},
"remind":{"e":"The faded photograph on her desk continued to remind her of summers spent fishing with her father before he passed away.","t":"桌上那张褪色的照片总是**唤起**她对那些与父亲一起钓鱼的夏天的回忆，那时他还未离世。"},
"candidate":{"e":"Only one candidate bothered to answer every question honestly during the debate, even when the truth clearly hurt her chances.","t":"辩论中只有一位**候选人**愿意诚实回答每一个问题，即便真相显然会损害她胜选的机会。"},
"speculate":{"e":"Investigators refused to speculate about the cause of the fire until the forensic report was completely finished.","t":"调查人员拒绝在法医报告完全出炉之前就火灾原因进行**推测**。"},
"abiding":{"e":"Despite everything they went through, the two old friends maintained an abiding trust in each other that never once wavered.","t":"尽管经历了种种波折，这两位老朋友始终保持着对彼此**持久不变**的信任，从未动摇过。"},
"yield":{"e":"The new hybrid seeds yield nearly twice as much corn per acre as the varieties farmers planted a decade ago.","t":"这种新型杂交种子每英亩**产出**的玉米几乎是农民十年前种植品种的两倍。"},
"continuity":{"e":"The director insisted on watching every scene twice to check continuity, making sure props never mysteriously changed position between shots.","t":"导演坚持把每场戏都看两遍来检查**连贯性**，确保道具不会在镜头之间莫名其妙地换了位置。"},
"rodeo":{"e":"Every August, the small Texas town fills with visitors who come specifically to watch the rodeo and its daring bull riders.","t":"每年八月，这个德州小镇都会挤满专程前来观看**牛仔竞技表演**及其胆大骑手的游客。"},
"loan":{"e":"The young couple took out a loan from the credit union to cover the down payment on their first house.","t":"这对年轻夫妇向信用合作社申请了一笔**贷款**，用来支付他们第一套房子的首付。"},
"phase":{"e":"The company is entering a critical phase of development where every design decision could determine whether the product survives.","t":"公司正在进入一个关键的发展**阶段**，每一个设计决策都可能决定这款产品能否生存下来。"},
"specimen":{"e":"The biologist carefully preserved the specimen in a jar of formaldehyde, labeling it with the exact date and location found.","t":"生物学家小心翼翼地把这份**标本**保存在装有福尔马林的罐子里，并标注了发现的确切日期和地点。"},
"slide":{"e":"Children lined up eagerly to slide down the icy hill on flattened cardboard boxes all afternoon long.","t":"孩子们兴致勃勃地排着队，整个下午都坐在压扁的纸箱上从结冰的山坡上**滑下**。"},
"legible":{"e":"She rewrote her notes in large, legible print so her study group could actually read them before the final exam.","t":"她把笔记重新誊写成又大又**清晰易读**的字体，好让学习小组的同学们在期末考试前真能看得懂。"},
"complicated":{"e":"The tax form turned out to be far more complicated than she expected, with dozens of exceptions buried in the fine print.","t":"这份报税表比她预想的要**复杂**得多，细则里还藏着几十条例外情况。"},
"limb":{"e":"A heavy limb snapped off the old oak during the storm and crushed the fence along the back of the yard.","t":"暴风雨中，老橡树的一根粗大**枝干**折断，压塌了院子后面的围栏。"},
"subsequent":{"e":"The initial trial showed promise, but every subsequent experiment failed to reproduce the same encouraging results under laboratory conditions.","t":"最初的试验显示出前景，但**随后**的每一次实验都未能在实验室条件下重现同样令人鼓舞的结果。"},
"by-product":{"e":"Improved concentration turned out to be an unexpected by-product of her new meditation routine, not something she had originally sought.","t":"专注力提升竟成了她新养成的冥想习惯的意外**副产品**，而这并非她最初追求的目标。"},
"dorsal":{"e":"Marine biologists identify individual sharks by the distinctive scars and notches on each animal's dorsal fin.","t":"海洋生物学家通过每条鲨鱼**背部**鳍上独特的伤疤和缺口来辨认个体。"},
"zinc":{"e":"Manufacturers coat steel in a thin layer of zinc to keep the metal underneath from rusting in wet weather.","t":"制造商在钢材表面镀上一层薄薄的**锌**，以防止内部金属在潮湿天气中生锈。"},
"cable":{"e":"Workers spent all night burying the thick fiber-optic cable beneath the street so traffic could resume by morning.","t":"工人们彻夜不停地把粗大的光纤**电缆**埋到街道下面，好让交通能在早上恢复。"},
"politics":{"e":"She avoided discussing office politics altogether, believing that staying neutral was the safest way to keep everyone as an ally.","t":"她完全避免谈论办公室**政治**，认为保持中立是让所有人都愿意站在自己这边的最安全方式。"},
"bloom":{"e":"The cherry trees along the riverbank bloom for barely two weeks each spring before the delicate petals scatter in the wind.","t":"河岸边的樱花树每年春天只**开花**短短两周，之后娇嫩的花瓣便随风飘散。"},
"reputation":{"e":"The small bakery built its reputation on a single recipe passed down through three generations of the same family.","t":"这家小面包店的**名声**全靠一份在同一家族传承了三代的配方建立起来。"},
"overcharge":{"e":"The mechanic tried to overcharge her for a simple oil change, tacking on fees for services she never requested.","t":"修车工试图在一次简单的换油服务上向她**索价过高**，还额外加收了她根本没要求的项目费用。"},
"invade":{"e":"Colonies of fire ants have begun to invade the coastal wetlands, pushing out native species that once thrived there.","t":"火蚁群落已经开始**入侵**沿海湿地，把曾在那里繁盛生长的本地物种排挤出去。"},
"mansion":{"e":"The abandoned mansion at the edge of town had been empty for decades, its grand rooms slowly collapsing under years of neglect.","t":"镇边那座废弃的**府邸**已经空置了几十年，宏伟的房间在多年无人照管下渐渐坍塌。"},
"aquarium":{"e":"The children pressed their faces against the glass of the aquarium, mesmerized by a shark gliding silently just inches away.","t":"孩子们把脸贴在**水族馆**的玻璃上，被一条只在几英寸外无声滑过的鲨鱼深深吸引住了。"},
"wholesome":{"e":"The summer camp promised parents a wholesome environment where kids would spend their days hiking instead of staring at screens.","t":"这家夏令营向家长们承诺提供一个**有益身心**的环境，孩子们将整天徒步而不是盯着屏幕。"},
"haircut":{"e":"He got such a drastic haircut before the interview that his own mother failed to recognize him at first glance.","t":"面试前他剪了个变化极大的**发型**，以至于他母亲第一眼都没能认出他来。"},
"predator":{"e":"Without any natural predator on the island, the rabbit population exploded within just a few breeding seasons.","t":"由于岛上没有天然**捕食者**，兔子的数量在短短几个繁殖季内就急剧膨胀。"},
"awesome":{"e":"Standing at the rim of the canyon, tourists fell silent, humbled by the awesome scale of the landscape stretching before them.","t":"站在峡谷边缘，游客们都沉默了，被眼前这片**令人敬畏**的辽阔景观所震撼。"},
"lichen":{"e":"Patches of gray lichen had crept slowly across the tombstone over the centuries, nearly hiding the carved inscription beneath.","t":"几个世纪以来，一片片灰色的**地衣**慢慢爬满了墓碑，几乎遮住了下面雕刻的碑文。"},
"ongoing":{"e":"The investigation remains ongoing, and detectives have asked the public not to speculate about a suspect until charges are formally filed.","t":"调查仍在**进行中**，警探已要求公众在正式提出指控前不要对嫌疑人妄加揣测。"},
"gospel":{"e":"Younger employees no longer treat the founder's original marketing playbook as gospel, questioning strategies that once went unchallenged for decades.","t":"年轻员工不再把创始人最初的营销手册奉为**金科玉律**，开始质疑那些几十年来从未受到挑战的策略。"},
"reservation":{"e":"She called ahead to make a dinner reservation, knowing the popular restaurant would otherwise turn them away at the door.","t":"她提前打电话**预订**了晚餐座位，知道这家热门餐厅不然会把他们拒之门外。"},
"advertise":{"e":"Local shops began to advertise their weekend sales on social media instead of relying on the newspaper insert nobody read anymore.","t":"本地商店开始在社交媒体上**宣传**周末促销活动，不再依赖那份已经没人看的报纸夹页广告。"},
"mesmerize":{"e":"The street performer's juggling routine seemed to mesmerize the entire crowd, and no one moved until the final trick ended.","t":"街头艺人的杂耍表演似乎把整个人群都**迷住**了，直到最后一个把戏结束前没人挪动过脚步。"},
"groan":{"e":"The old wooden floorboards would groan under every footstep, making it impossible to sneak downstairs without waking the whole house.","t":"老旧的木地板每踩一步都会**吱吱作响**，让人根本没法偷偷下楼而不吵醒全家。"},
"modest":{"e":"Despite winning three gold medals, the swimmer remained remarkably modest, crediting her coaches and teammates in every single interview.","t":"尽管赢得了三枚金牌，这位游泳选手依然异常**谦虚**，在每一次采访中都把功劳归给教练和队友。"},
"magnificent":{"e":"Visitors gasped when they first entered the cathedral, awed by the magnificent stained-glass windows towering above the altar.","t":"游客们第一次走进大教堂时都倒吸一口气，被高耸在祭坛上方那**宏伟壮丽**的彩色玻璃窗震撼住了。"},
"hike":{"e":"Every autumn, the retired couple would hike the same mountain trail, marking the changing colors of the leaves along the way.","t":"每年秋天，这对退休夫妇都会去**徒步**走同一条山路，沿途记录树叶变色的情况。"},
"overall":{"e":"The overall quality of the harvest exceeded every forecast, even though individual farms reported mixed results depending on rainfall.","t":"今年收成的**总体**质量超出了所有预测，尽管各个农场因降雨量不同而结果参差不齐。"},
"scurry":{"e":"The moment the kitchen light flicked on, cockroaches would scurry into the cracks along the baseboard, vanishing almost instantly.","t":"厨房的灯一亮，蟑螂就会**急速逃窜**到踢脚板的缝隙里，几乎瞬间消失不见。"},
"indigestion":{"e":"He blamed the greasy street food for his indigestion, though he had eaten the same dish plenty of times before without any trouble.","t":"他把**消化不良**归咎于那份油腻的街头小吃，尽管之前他吃过很多次同样的菜都没出过问题。"},
"boom":{"e":"The coastal town began to boom after the new highway connected it to the capital, doubling its population within five years.","t":"新公路把这座沿海小镇与首都连通后，小镇开始**迅速发展**，五年内人口翻了一番。"},
"companion":{"e":"The old dog had been her constant companion since college, following her from one tiny apartment to the next without complaint.","t":"这只老狗自大学时代起就一直是她形影不离的**伙伴**，毫无怨言地跟着她搬过一个又一个小公寓。"},
"twine":{"e":"She wrapped the bundle of herbs tightly with garden twine before hanging it upside down to dry in the attic.","t":"她用园艺**细绳**把那捆香草牢牢扎紧，然后倒挂在阁楼里晾干。"},
"resident":{"e":"Every longtime resident of the block knew to avoid the pothole that the city had somehow never gotten around to fixing.","t":"这条街上每个住了很久的**居民**都知道要避开那个市政府一直没修的坑洞。"},
"float":{"e":"Autumn leaves would float lazily down the creek, catching briefly on rocks before drifting on toward the river.","t":"秋叶懒懒地**漂浮**顺溪而下，偶尔被岩石短暂拦住，随后又继续漂向河流。"},
"rod":{"e":"The old fisherman kept a single bamboo rod propped against the porch, refusing every modern replacement his grandsons offered him.","t":"老渔夫一直把一根竹**竿**靠在门廊边，拒绝了孙子们提供的所有现代化替代品。"},
"classical":{"e":"She grew up listening to classical music every evening, her father convinced it would somehow make her a better student.","t":"她从小每晚都听**古典**音乐长大，她父亲坚信这样能让她成为更优秀的学生。"},
"principle":{"e":"She refused to compromise on the principle that every employee, regardless of rank, deserved to be heard during safety reviews.","t":"她坚持不肯在这条**原则**上妥协：无论职位高低，每位员工在安全审查中都应该有发言权。"},
"outspoken":{"e":"The senator's outspoken criticism of the merger cost her several major donors but earned her the respect of ordinary voters.","t":"参议员**直言不讳**地批评这桩并购案，让她失去了几位重要的捐助人，却也赢得了普通选民的尊敬。"},
"factual":{"e":"The documentary aimed to stay strictly factual, avoiding dramatic reenactments that might distort what actually happened during the crisis.","t":"这部纪录片力求严格**忠于事实**，避免使用可能歪曲危机实际经过的戏剧化重现场景。"},
"prize":{"e":"Collectors prize this particular stamp above all others in the set, since only a handful were ever printed.","t":"收藏家们**珍视**这张邮票胜过整套里的其他所有邮票，因为当年只印制了寥寥几枚。"},
"obedience":{"e":"The drill sergeant demanded instant obedience from every recruit, tolerating no hesitation even during the most exhausting exercises.","t":"教官要求每个新兵都必须立即**服从**，即使在最累人的训练中也不容许丝毫犹豫。"},
"skeptical":{"e":"Investors remained skeptical of the startup's projections, having watched similar companies promise the same explosive growth and later collapse.","t":"投资者对这家初创公司的预测始终**持怀疑态度**，因为他们见过太多类似公司做出同样的爆炸性增长承诺后却轰然倒塌。"},
"invitation":{"e":"She hesitated before accepting the invitation, unsure whether attending her ex-boyfriend's wedding was really a wise idea.","t":"她在接受这份**邀请**前犹豫了一下，不确定参加前男友的婚礼是否真的明智。"},
"humble":{"e":"Despite becoming a bestselling author, he remained humble, still answering fan emails personally every single night before bed.","t":"尽管成了畅销书作家，他依然十分**谦逊**，每晚睡前仍会亲自回复粉丝的邮件。"},
"overflow":{"e":"Heavy rain caused the river to overflow its banks, flooding basements throughout the neighborhood within a matter of hours.","t":"暴雨导致河水**漫出**了河岸，短短几个小时内就淹没了整个社区的地下室。"},
"glimmer":{"e":"Even after the diagnosis, the doctors offered a glimmer of hope, pointing to a new treatment still in clinical trials.","t":"即使在确诊之后，医生们仍指出一线**希望的微光**，那是一种仍在临床试验中的新疗法。"},
"staunch":{"e":"Even when the party's popularity collapsed, she remained its most staunch defender, refusing to abandon the cause she believed in.","t":"即使该党的支持率暴跌，她依然是它最**坚定忠诚**的捍卫者，拒绝放弃自己所信仰的事业。"},
"traverse":{"e":"The expedition team needed nearly three weeks to traverse the glacier before reaching the base of the final peak.","t":"探险队花了近三周时间才**横穿**这片冰川，之后才抵达最后一座山峰的山脚。"},
"malice":{"e":"The critic insisted her harsh review came from honest judgment rather than any personal malice toward the young director.","t":"这位评论家坚称，她那篇尖锐的评论出于诚实的判断，而非对这位年轻导演怀有任何个人**恶意**。"},
"sneaky":{"e":"The cat gave a sneaky glance toward the counter before leaping up the instant its owner left the kitchen.","t":"那只猫**偷偷摸摸**地瞟了一眼台面，主人一离开厨房它就立刻跳了上去。"},
"uphold":{"e":"The appellate court chose to uphold the original verdict, finding no evidence that the trial had been conducted unfairly.","t":"上诉法院决定**维持**原判，认定没有证据表明庭审过程存在不公。"},
"vow":{"e":"Standing at her father's grave, she vowed to finish medical school no matter how many years it might take.","t":"站在父亲的墓前，她**发誓**无论要花多少年都一定要读完医学院。"},
"embargo":{"e":"The United Nations imposed a strict trade embargo on the regime, cutting off access to weapons and critical medical supplies.","t":"联合国对该政权实施了严格的贸易**禁运**，切断了其获取武器和关键医疗物资的渠道。"},
"ordeal":{"e":"Recovering from the surgery turned into a months-long ordeal, with complications forcing her back into the hospital twice.","t":"手术后的康复变成了一场长达数月的**煎熬**，各种并发症两度迫使她重新住院。"},
"venturesome":{"e":"Only the most venturesome hikers attempt the narrow ridge trail, where a single misstep could mean a fatal fall.","t":"只有最**敢于冒险**的徒步者才会尝试那条狭窄的山脊小径，一步踏错就可能坠落丧命。"},
"regiment":{"e":"The colonel had commanded the same regiment for over a decade, watching thousands of young soldiers pass through its ranks.","t":"这位上校已经统领同一个**团**超过十年，眼看着成千上万的年轻士兵在其中来来去去。"},
"smelting":{"e":"The ancient civilization mastered bronze smelting centuries before their neighbors ever learned to work with metal at all.","t":"这个古老文明掌握青铜**冶炼**技术的时间，比邻近部族学会使用任何金属都要早上好几个世纪。"},
"cartilage":{"e":"The flexible cartilage in your outer ear allows it to bend and spring back without ever actually breaking.","t":"外耳中富有弹性的**软骨**让它能够弯曲后又弹回原状，而不会真正断裂。"},
"fold":{"e":"She learned to fold the paper crane in under a minute, a skill her grandmother had taught her as a child.","t":"她学会了在一分钟内**折叠**出一只纸鹤，这是祖母小时候教她的手艺。"},
"courier":{"e":"A courier arrived at dawn carrying documents so sensitive that they could not be sent through ordinary mail.","t":"一名**信使**在黎明时分抵达，带来的文件极其机密，根本无法通过普通邮寄方式传送。"},
"sculpture":{"e":"The artist spent nearly two years carving the marble sculpture that now stands in the center of the plaza.","t":"这位艺术家花了近两年时间雕刻这座大理石**雕塑**，如今它矗立在广场中央。"},
"polygamy":{"e":"Anthropologists studying the isolated tribe found that polygamy remained common there long after neighboring communities had abandoned the practice.","t":"研究这个偏远部落的人类学家发现，**一夫多妻制**在那里依然普遍，远远晚于邻近社群放弃这一习俗的时间。"},
"trumpet":{"e":"The company loved to trumpet its charitable donations in press releases while quietly cutting corners on employee safety.","t":"这家公司喜欢在新闻稿中大肆**宣扬**自己的慈善捐款，却悄悄在员工安全上偷工减料。"},
"convene":{"e":"The board agreed to convene an emergency meeting the moment news of the data breach reached the executives.","t":"数据泄露的消息一传到高管耳中，董事会就立即同意**召开**一场紧急会议。"},
"babble":{"e":"The toddler would babble happily to herself for hours, stringing together sounds that resembled no actual language at all.","t":"那个学步的孩子常常自顾自地**咿呀学语**好几个小时，把一些完全不成语言的声音串在一起。"},
"canopy":{"e":"The dense forest canopy blocked out so much sunlight that almost nothing could grow on the ground below.","t":"茂密的森林**林冠**挡住了大量阳光，导致地面上几乎什么都长不出来。"},
"subjective":{"e":"Art critics admit that much of their praise is inherently subjective, shaped by personal taste rather than any fixed standard.","t":"艺术评论家承认，他们的许多赞誉本质上都是**主观**的，取决于个人品味而非任何固定标准。"},
"exclaim":{"e":"She could only exclaim in delight when she opened the box and saw the puppy hiding inside.","t":"打开箱子看到里面藏着的小狗时，她只能高兴地**惊呼**出声。"},
"contradictory":{"e":"The witness gave two completely contradictory accounts of the accident, which made the jury doubt her credibility entirely.","t":"目击者对事故给出了两份完全**相互矛盾**的陈述，这让陪审团彻底怀疑她的可信度。"},
"dissent":{"e":"One justice chose to dissent from the majority opinion, arguing that the ruling would set a dangerous precedent.","t":"一位大法官选择对多数意见**持异议**，认为该裁决将开创一个危险的先例。"},
"tender":{"e":"After the scandal broke, the minister immediately chose to tender his resignation rather than face a humiliating public inquiry.","t":"丑闻曝光后，这位部长立即选择**递交**辞呈，而不愿面对一场羞辱性的公开调查。"},
"bolt":{"e":"The moment the vet approached with the needle, the terrified cat tried to bolt straight through the open door.","t":"兽医一拿着针靠近，受惊的猫就试图**径直逃窜**穿过那扇开着的门。"},
"calamitous":{"e":"The engineers had warned for years that ignoring the cracks in the dam could lead to calamitous consequences downstream.","t":"工程师们多年来一直警告，忽视大坝裂缝可能会给下游带来**灾难性**的后果。"},
"affluent":{"e":"The charity focuses on neighborhoods overlooked by donors, rather than the affluent suburbs where most fundraising galas already take place.","t":"这家慈善机构专注于捐助者忽略的社区，而不是大多数筹款晚会已经扎堆举办的**富裕**郊区。"},
"superimpose":{"e":"The architect used software to superimpose the proposed building onto a photograph of the existing skyline for the city council.","t":"建筑师用软件把拟建的建筑**叠加**在现有天际线的照片上，展示给市议会看。"},
"congest":{"e":"Construction on the bridge continued to congest the highway every morning, turning a twenty-minute commute into nearly two hours.","t":"大桥的施工每天早上都在**堵塞**高速公路，把原本二十分钟的通勤变成了近两个小时。"},
"recollection":{"e":"Her recollection of the accident remained hazy for months, with entire minutes seemingly erased from her memory.","t":"她对那场事故的**记忆**在数月内一直模糊不清，整整几分钟仿佛从她的脑海中被抹去了。"},
"congratulation":{"e":"Messages of congratulation flooded her inbox within minutes of the announcement that she had won the fellowship.","t":"消息一宣布她赢得了这项奖学金，**祝贺**的信息就在几分钟内涌满了她的收件箱。"},
"ageism":{"e":"Older applicants often face subtle ageism during interviews, with hiring managers quietly assuming they lack energy or adaptability.","t":"年长的求职者在面试中常常遭遇隐性的**年龄歧视**，招聘经理会默默认定他们缺乏精力或适应能力。"},
"pilot":{"e":"The school decided to pilot the new reading program in just three classrooms before rolling it out district-wide.","t":"学校决定先在三个班级**试行**这套新的阅读方案，然后再推广到全学区。"},
"debut":{"e":"The young violinist's debut at Carnegie Hall drew a standing ovation that lasted nearly ten full minutes.","t":"这位年轻小提琴家在卡内基音乐厅的**首演**赢得了持续近十分钟的起立鼓掌。"},
"embarrass":{"e":"Her father loved to embarrass her in front of friends by pulling out old childhood photographs at every possible chance.","t":"她父亲总喜欢一逮到机会就翻出她小时候的照片，在朋友面前**让她难堪**。"},
"script":{"e":"The actors kept improvising new lines until the director finally forced everyone to stick to the original script.","t":"演员们一直即兴发挥新台词，直到导演终于强迫大家都严格按照原**剧本**来演。"},
"consent":{"e":"The surgeon could not proceed with the operation until the patient's family gave their formal consent in writing.","t":"外科医生在患者家属正式书面**同意**之前无法进行手术。"},
"directory":{"e":"She flipped through the old phone directory looking for a number that had probably been disconnected years ago.","t":"她翻着那本旧电话**号码簿**，寻找一个多半早已停用多年的号码。"},
"orchid":{"e":"The greenhouse specialized in rare orchid species, some of which took nearly a decade to finally produce a single bloom.","t":"这家温室专门培育稀有**兰花**品种，其中一些需要将近十年才能终于开出一朵花。"},
"convince":{"e":"It took the lawyer nearly three hours to convince the jury that the defendant had acted purely in self-defense.","t":"律师花了将近三个小时才**说服**陪审团相信被告的行为纯属正当防卫。"},
"ardent":{"e":"As an ardent supporter of the local theater, she donated both her time and her savings every single season.","t":"作为当地剧院的**热心**支持者，她每一季都会同时捐出自己的时间和积蓄。"},
"convection":{"e":"Warm air rising from the ocean surface drives the convection that eventually forms towering thunderstorm clouds overhead.","t":"从海面上升起的暖空气驱动着**对流**，最终在头顶形成高耸的雷暴云。"},
"hollow":{"e":"The old tree trunk had grown completely hollow inside, yet somehow it still managed to sprout green leaves every spring.","t":"那棵老树的树干内部已经完全**空心**，可它每年春天却依然设法长出绿叶。"},
"vague":{"e":"His explanation for missing the deadline remained frustratingly vague, offering no specific reason his supervisor could actually verify.","t":"他对错过截止日期的解释一直**含糊**得令人恼火，没提供任何主管能够核实的具体理由。"},
"antibiotic":{"e":"Doctors warned that overusing antibiotic treatments for minor colds was helping dangerous bacteria grow resistant faster than expected.","t":"医生警告说，滥用**抗生素**治疗普通感冒正在让危险细菌以比预期更快的速度产生耐药性。"},
"rinse":{"e":"She would always rinse the paintbrushes thoroughly in cold water the moment she finished each painting session.","t":"每次画完画，她总会立刻用冷水彻底**冲洗**画笔。"},
"nevertheless":{"e":"The bridge was old and creaked ominously with every gust; nevertheless, thousands of commuters crossed it without hesitation each day.","t":"这座桥又老又旧，每阵风吹来都会发出不祥的嘎吱声；**然而**，每天仍有成千上万的通勤者毫不犹豫地从桥上走过。"},
"insult":{"e":"He refused to apologize, insisting that his blunt comment was never meant to insult anyone at the table.","t":"他拒绝道歉，坚称自己那句直白的话从来无意**侮辱**餐桌上的任何人。"},
"cabin":{"e":"They spent their honeymoon in a tiny log cabin deep in the woods, miles from the nearest paved road.","t":"他们在森林深处一间小小的圆木**小屋**里度过了蜜月，那里离最近的柏油路有好几英里远。"},
"gourmet":{"e":"As a self-proclaimed gourmet, he refused to eat at any restaurant that hadn't earned at least one certified award.","t":"作为自封的**美食家**，他拒绝在任何一家没获得过认证奖项的餐厅用餐。"},
"insect":{"e":"The biology teacher asked each student to catch and identify at least ten different insect species over summer break.","t":"生物老师要求每个学生在暑假期间至少捕捉并识别十种不同的**昆虫**。"},
"productivity":{"e":"The factory's productivity nearly doubled after management replaced the outdated assembly line with automated robotic arms.","t":"工厂用自动化机械臂取代老旧的装配线后，**生产率**几乎翻了一番。"},
"surgeon":{"e":"The surgeon explained every risk of the procedure in careful detail before asking the family to sign the consent form.","t":"**外科医生**在请家属签署同意书之前，仔细详细地解释了这项手术的每一项风险。"},
"govern":{"e":"The council that governs this small island has resisted every attempt by outside investors to build a large resort.","t":"**治理**这座小岛的议会一直抵制外来投资者建造大型度假村的种种企图。"},
"strategy":{"e":"The coach devised a completely new defensive strategy overnight after watching game film of the opposing team's star player.","t":"教练在看完对方明星球员的比赛录像后，连夜设计出一套全新的防守**策略**。"},
"average":{"e":"Her test scores fell well above the average for students applying to the same competitive engineering program.","t":"她的考试成绩远高于申请同一竞争激烈的工程专业学生的**平均水平**。"},
"postcard":{"e":"Every city she visited, she mailed a postcard to her grandmother, who kept every single one pinned to her kitchen wall.","t":"她每到一座城市都会给祖母寄一张**明信片**，祖母把每一张都钉在了厨房的墙上。"},
"mount":{"e":"Pressure continued to mount on the CEO as shareholders demanded answers for the company's plummeting stock price.","t":"随着股东们要求就公司股价暴跌给出解释，首席执行官承受的压力持续**增大**。"},
"corporate":{"e":"She quit her corporate job to open a small bakery, trading a steady salary for the freedom to bake whatever she wanted.","t":"她辞去了**公司**的工作去开了家小面包店，用稳定的薪水换取想做什么就做什么的自由。"},
"distasteful":{"e":"He found the whole negotiation tactic distasteful, arguing that pressuring elderly clients into signing quickly was simply unethical.","t":"他觉得整套谈判手法都**令人反感**，认为逼迫年长客户匆忙签字根本不道德。"},
"medieval":{"e":"The walled city still preserves its medieval layout, with narrow cobblestone streets that no modern car could ever navigate.","t":"这座有城墙环绕的城市依然保留着**中世纪**的布局，狭窄的鹅卵石街道让任何现代汽车都无法通行。"},
"clamor":{"e":"The clamor from the protest outside grew so loud that the negotiators inside could barely hear each other speak.","t":"外面抗议活动的**喧闹声**变得如此响亮，以至于里面的谈判代表几乎听不清彼此说话。"},
"biochemical":{"e":"Researchers traced the disease to a subtle biochemical imbalance in the brain that standard blood tests routinely miss.","t":"研究人员将这种疾病追溯到大脑中一种细微的**生化**失衡，而标准的血液检测通常会漏掉它。"},
"second":{"e":"It took only a second for the entire glass shelf to shatter across the kitchen floor.","t":"只用了一**秒钟**，整块玻璃架就在厨房地板上摔得粉碎。"},
"assistance":{"e":"The nonprofit provides financial assistance to families struggling to cover medical bills after a sudden hospitalization.","t":"这家非营利组织为那些在突发住院后难以支付医疗账单的家庭提供经济**援助**。"},
"modeling":{"e":"Climate scientists rely on complex computer modeling to predict how rising temperatures will reshape coastlines over the next century.","t":"气候科学家依靠复杂的计算机**建模**来预测气温上升将在下个世纪如何重塑海岸线。"},
"laundry":{"e":"Mountains of dirty laundry piled up in the hallway all semester because none of the roommates wanted to do it first.","t":"整整一个学期，成堆的脏**衣物**都堆在走廊里，因为没有一个室友愿意先动手洗。"},
"spew":{"e":"The volcano began to spew molten ash high into the sky, forcing thousands of nearby residents to evacuate immediately.","t":"火山开始向高空**喷涌**熔岩灰烬，迫使附近数千名居民立即撤离。"},
"orbital":{"e":"Engineers carefully calculated the satellite's orbital path to avoid any collision with the debris already circling the planet.","t":"工程师们仔细计算了卫星的**轨道**路径，以避免与已经环绕地球的碎片发生碰撞。"},
"generalization":{"e":"Her professor warned against drawing a broad generalization from just three interviews conducted in a single small town.","t":"她的教授警告她不要仅凭在一个小镇上做的三次访谈就得出宽泛的**概括性结论**。"},
"inheritance":{"e":"She used her unexpected inheritance to pay off her student loans instead of buying the car she had always wanted.","t":"她用这笔意外得来的**遗产**还清了助学贷款，而不是去买一直想要的那辆车。"},
"detect":{"e":"The new sensor can detect even trace amounts of carbon monoxide long before the gas becomes dangerous to humans.","t":"这款新型传感器能够**探测**到微量的一氧化碳，远远早于这种气体对人体构成危险之前。"},
"preference":{"e":"The airline allows frequent flyers to indicate a seating preference, though window seats still sell out within minutes.","t":"这家航空公司允许常旅客表明座位**偏好**，尽管靠窗座位仍然会在几分钟内被订光。"},
"subliminal":{"e":"Advertisers once experimented with subliminal messages flashed too quickly for viewers to consciously notice on screen.","t":"广告商曾经试验过**潜意识**信息，这些信息在屏幕上一闪而过，快得让观众无法有意识地察觉。"},
"blame":{"e":"Rather than admit her own mistake, she chose to blame the intern for the error in the final report.","t":"她没有承认自己的失误，反而选择**责怪**实习生犯了最终报告里的错误。"},
"shape":{"e":"Her grandmother's stories about immigrating alone at seventeen would shape every major decision she made later in life.","t":"祖母讲述自己十七岁只身移民的故事，**塑造**了她后来人生中的每一个重大决定。"},
"hemisphere":{"e":"Winter in the southern hemisphere falls during June, July, and August, exactly opposite the seasons familiar to most Americans.","t":"南**半球**的冬天正好落在六月、七月和八月，与大多数美国人熟悉的季节完全相反。"},
"squirrel":{"e":"A squirrel darted across the yard and buried yet another acorn beneath the same maple tree it always chose.","t":"一只**松鼠**飞快跑过院子，又把一颗橡子埋在了它一贯选择的那棵枫树下。"},
"pollen":{"e":"Bees transfer pollen from flower to flower as they forage, unintentionally enabling plants across the meadow to reproduce.","t":"蜜蜂在采蜜过程中把**花粉**从一朵花带到另一朵花，无意间让整片草地上的植物得以繁殖。"},
"institute":{"e":"The university decided to institute a stricter attendance policy after noticing a sharp decline in classroom participation.","t":"大学在注意到课堂参与率大幅下降后，决定**设立**一项更严格的考勤制度。"},
"spark":{"e":"A single offhand comment during the meeting managed to spark an argument that lasted well into the evening.","t":"会议中一句随口的评论竟然**引发**了一场持续到深夜的争论。"},
"chain":{"e":"The coffee chain expanded so rapidly that it opened a new location almost every single week last year.","t":"这家咖啡**连锁店**扩张速度极快，去年几乎每周都会开一家新店。"},
"rattle":{"e":"The lawyer's aggressive cross-examination was clearly designed to rattle the witness into contradicting his earlier testimony.","t":"律师咄咄逼人的盘问显然是想**扰乱**证人的阵脚，让他推翻之前的证词。"},
"similar":{"e":"The twins' handwriting looked so similar that even their own mother sometimes confused whose homework belonged to whom.","t":"这对双胞胎的字迹**相似**到连他们的母亲有时都会搞混谁的作业是谁的。"},
"outfit":{"e":"She spent an entire paycheck on a single outfit for the interview, hoping it would make the right impression.","t":"她把一整份薪水都花在了面试穿的一身**行头**上，希望能给人留下恰当的印象。"},
"brand":{"e":"The startup spent months developing a brand that would feel trustworthy to parents shopping for children's products.","t":"这家初创公司花了几个月时间打造一个**品牌**，让为孩子购物的家长们感到值得信赖。"},
"distinguish":{"e":"Even experienced sommeliers sometimes struggle to distinguish between two wines made from grapes grown just a mile apart.","t":"即使是经验丰富的侍酒师，有时也很难**区分**两款用相隔仅一英里的葡萄园所产葡萄酿成的酒。"},
"artisan":{"e":"Each ceramic bowl in the shop was handmade by a local artisan who had trained under his father for twenty years.","t":"店里每一个陶碗都是由当地一位**手艺人**手工制作的，他跟着父亲学了二十年。"},
"mint":{"e":"The government decided to mint a limited commemorative coin to mark the fiftieth anniversary of the moon landing.","t":"政府决定**铸造**一枚限量纪念币，以纪念登月五十周年。"},
"vanish":{"e":"The hiking trail seemed to vanish entirely once the fog rolled in, leaving us to navigate purely by memory.","t":"大雾一起，那条徒步小径似乎彻底**消失**了，我们只能全凭记忆摸索前行。"},
"overwhelm":{"e":"Grief seemed to overwhelm her completely the moment she stepped back into her late husband's empty office.","t":"她一踏进已故丈夫空荡荡的办公室，悲伤似乎就将她彻底**淹没**。"},
"hypothesis":{"e":"The researcher designed three separate experiments simply to test her hypothesis that stress alters short-term memory formation.","t":"这位研究者设计了三组独立实验，专门用来检验她提出的压力会改变短期记忆形成的**假说**。"},
"sequoia":{"e":"Some sequoia trees in the park have stood for over two thousand years, surviving countless wildfires along the way.","t":"公园里的一些**红杉**已经屹立了两千多年，一路挺过了无数场野火。"},
"prairie":{"e":"Settlers crossing the open prairie in covered wagons often went weeks without spotting a single tree on the horizon.","t":"乘着篷车穿越广阔**大草原**的拓荒者常常一连几周都看不到地平线上有一棵树。"},
"canal":{"e":"Barges still transport heavy cargo along the old canal, moving far slower than trucks but at a fraction of the cost.","t":"驳船仍然沿着这条古老的**运河**运输重型货物，速度比卡车慢得多，但成本却只是其中一小部分。"},
"exact":{"e":"Nobody could give the detective an exact time when the argument in the parking lot had actually started.","t":"没有人能向侦探说出停车场里那场争执究竟是从**精确**的什么时间开始的。"},
"retail":{"e":"The boutique began to retail its handmade candles online after local demand quickly outgrew the small physical shop.","t":"由于本地需求迅速超出了小店的承受能力，这家精品店开始在网上**零售**其手工蜡烛。"},
"selection":{"e":"The bookstore's selection of rare first editions draws collectors from across the country to browse its dusty back shelves.","t":"这家书店**精选**的珍稀初版书吸引了全国各地的收藏家前来浏览它尘封的后架。"},
"tug":{"e":"The toddler kept trying to tug the tablecloth off the table, oblivious to the stack of dishes on top.","t":"那个学步的孩子一直试图**用力拽**掉桌布，完全没意识到上面摞着一叠盘子。"},
"overdue":{"e":"The library sent a final notice about the overdue novel, warning that fines would continue to accumulate daily.","t":"图书馆就这本**逾期未还**的小说发出了最后通知，警告滞纳金将每天继续累积。"},
"frustrate":{"e":"Constant power outages continued to frustrate the small factory's efforts to meet its export deadline this month.","t":"不断停电持续**挫败**着这家小工厂本月按时完成出口订单的努力。"},
"outline":{"e":"The professor asked every student to outline their thesis argument before writing a single paragraph of the actual paper.","t":"教授要求每个学生在动笔写论文正文之前，先**概述**一下论文的论点。"},
"species":{"e":"Marine biologists discovered an entirely new species of jellyfish drifting near the bottom of the trench.","t":"海洋生物学家在海沟底部附近发现了一个全新的水母**物种**。"},
"consequence":{"e":"Skipping the safety inspection turned out to have a consequence nobody at the plant had bothered to anticipate.","t":"跳过安全检查带来了一个工厂里没人愿意预先设想的**后果**。"},
"overcome":{"e":"She had to overcome a crippling fear of public speaking before she could even consider running for office.","t":"她必须先**克服**对公开演讲的极度恐惧，才能考虑参选公职。"},
"adjacent":{"e":"The fire spread quickly to the adjacent warehouse before firefighters could even finish unrolling their hoses.","t":"大火迅速蔓延到了**毗邻**的仓库，消防员甚至还没来得及展开水管。"},
"gradual":{"e":"The therapist recommended a gradual return to exercise, warning that pushing too hard too soon could reinjure the torn ligament.","t":"治疗师建议**循序渐进**地恢复运动，并警告操之过急可能会使撕裂的韧带再次受伤。"},
"puppet":{"e":"Critics dismissed the newly appointed president as a puppet controlled entirely by the military generals behind the scenes.","t":"批评者们认为这位新上任的总统不过是幕后军方将领完全操控的**傀儡**。"},
"accounting":{"e":"She switched her college major from art history to accounting after realizing how few jobs the former actually offered.","t":"她在意识到艺术史专业实际提供的工作机会少得可怜后，把大学专业换成了**会计学**。"},
"roll":{"e":"The barrel began to roll down the steep hill the moment the worker loosened the rope holding it in place.","t":"工人一松开固定绳索，那个木桶就立刻开始**滚动**下陡坡。"},
"parasite":{"e":"The tiny parasite lives inside the fish's gills, feeding off its blood without ever actually killing the host.","t":"这种微小的**寄生虫**生活在鱼鳃里，靠吸食鱼血为生，却从不会真正杀死宿主。"},
"clumsy":{"e":"His clumsy attempt at an apology only made the argument worse, since every sentence seemed to blame her instead.","t":"他**笨拙**的道歉尝试只让争吵变得更糟，因为几乎每句话听起来都是在怪她。"},
"recession":{"e":"The recession forced thousands of small businesses to close their doors permanently within just a single brutal year.","t":"这场**经济衰退**在短短残酷的一年内就迫使成千上万家小企业永久关门。"},
"deduct":{"e":"Her employer automatically deducts a portion of every paycheck to cover health insurance and retirement contributions.","t":"她的雇主会从每份薪水中自动**扣除**一部分，用于支付医疗保险和退休金。"},
"philosophy":{"e":"His entire philosophy toward business boiled down to one simple rule: always treat customers exactly like family.","t":"他整个经商**理念**可以归结为一条简单的原则：永远像对待家人一样对待顾客。"},
"reptile":{"e":"The zoo's new reptile exhibit features a rare albino python that visitors line up for hours to see.","t":"动物园新的**爬行动物**展区展出一条罕见的白化蟒蛇，游客们排队数小时只为一睹真容。"},
"admit":{"e":"Faced with irrefutable evidence, the defendant finally admitted his involvement in the scheme, ending months of denial and defensive testimony.","t":"面对确凿的证据，被告最终**承认**了自己参与了这一骗局，结束了数月的否认和辩解。"},
"swamp":{"e":"Emails from anxious parents swamped the school's front office within minutes of the storm warning being announced.","t":"暴风雨预警发布后几分钟内，焦虑家长的邮件就**淹没**了学校前台办公室。"},
"procedure":{"e":"Before the surgeons could begin, a nurse walked the anxious patient through the entire procedure, step by step.","t":"手术开始前，护士逐步向焦虑的病人讲解了整个**程序**。"},
"encase":{"e":"Thick layers of ice encased the fallen power lines, making repairs impossible until the temperature finally rose above freezing.","t":"厚厚的冰层把倒下的电线**包住**了，直到气温回升到冰点以上，抢修才成为可能。"},
"restoration":{"e":"The museum's decade-long restoration returned the crumbling fresco to something close to its original Renaissance brilliance.","t":"博物馆历时十年的**修复**工作，让这幅日渐斑驳的壁画重现了几分文艺复兴时期的辉煌。"},
"olfactory":{"e":"Bloodhounds rely on an extraordinarily keen olfactory sense to track a single scent across miles of confusing terrain.","t":"寻血猎犬依靠极其敏锐的**嗅觉**，能在数英里令人困惑的地形中追踪单一的气味。"},
"canvas":{"e":"The painter stretched a fresh canvas across the wooden frame, eager to begin the mural before daylight faded.","t":"画家把一块新**画布**绷在木框上，急着要在天黑之前开始画这幅壁画。"},
"pique":{"e":"A single cryptic sentence in the old letter piqued her curiosity enough that she spent the weekend researching its author.","t":"那封旧信里一句神秘的话**激起**了她的好奇心，让她花了整个周末去查这封信的作者。"},
"downside":{"e":"The apartment's only real downside was its distance from campus, which turned a simple errand into a lengthy commute.","t":"这间公寓唯一真正的**缺点**就是离校园太远，使得一次简单的外出办事变成了漫长的通勤。"},
"locate":{"e":"Search teams used thermal drones to locate the missing hikers before nightfall brought freezing temperatures to the ridge.","t":"搜救队使用热成像无人机在夜幕带来冰冷气温之前**定位**了失踪的徒步者。"},
"turbulent":{"e":"The pilot warned passengers to fasten their seatbelts as the plane entered a turbulent stretch of sky above the mountains.","t":"飞机进入山脉上空一段**动荡**的气流区时，飞行员提醒乘客系好安全带。"},
"sophisticated":{"e":"The lab's new imaging system was so sophisticated that technicians needed weeks of training just to operate it safely.","t":"实验室的新成像系统如此**精密**，技术人员需要数周培训才能安全操作它。"},
"tentacle":{"e":"The octopus wrapped a single tentacle around the shell, testing its weight before dragging the whole crab toward its den.","t":"章鱼用一根**触手**缠住贝壳，掂量了一下重量，然后把整只螃蟹拖向自己的巢穴。"},
"annotation":{"e":"The professor's handwritten annotation in the margin explained a proof more clearly than the entire printed textbook chapter.","t":"教授在页边手写的**注释**，比整章印刷的教材内容解释得还要清楚。"},
"rage":{"e":"Wildfires raged through the dry canyon for three days before exhausted crews finally contained the last stubborn flames.","t":"野火在干燥的峡谷中**肆虐**了三天，疲惫的救援队才终于扑灭了最后顽固的火苗。"},
"fiery":{"e":"Her fiery temper flared the moment anyone questioned her judgment in front of the rest of the team.","t":"只要有人当着全队的面质疑她的判断，她**暴躁**的脾气就会立刻发作。"},
"grouse":{"e":"Junior staff members grouse about the new scheduling software constantly, though none of them has proposed a workable alternative.","t":"初级员工经常**抱怨**新的排班软件，可他们中没有一个人提出过可行的替代方案。"},
"afloat":{"e":"Only a last-minute loan from her sister kept the small bookstore afloat through that brutal first winter.","t":"全靠姐姐在最后关头借的一笔钱，这家小书店才在那个残酷的第一个冬天**维持下去**。"},
"scruple":{"e":"The lawyer felt no scruple about exploiting the loophole, even though it left his opponent financially devastated.","t":"这位律师对利用这个法律漏洞毫无**顾忌**，尽管这让他的对手在经济上遭受重创。"},
"rob":{"e":"Two masked men robbed the corner pharmacy at closing time, fleeing moments before the police arrived.","t":"两名蒙面男子在打烊时**抢劫**了街角的药店，在警察到达前几分钟逃走了。"},
"dissimulate":{"e":"Diplomats often dissimulate their true frustration behind polite smiles, choosing careful language over any honest complaint.","t":"外交官常常用礼貌的微笑**掩饰**内心真实的沮丧，选择措辞谨慎而非直接抱怨。"},
"aboriginal":{"e":"Botanists catalogued dozens of aboriginal plant species on the island long before European ships ever reached its shores.","t":"早在欧洲船只抵达这座岛屿之前，植物学家就已经编目了数十种**土生土长**的植物物种。"},
"elapse":{"e":"Nearly a decade elapsed before the two estranged brothers finally spoke to each other again at their mother's funeral.","t":"将近十年**过去**，这对疏远的兄弟才终于在母亲的葬礼上重新开口交谈。"},
"plow":{"e":"Farmers plowed the frozen fields early that spring, determined to plant before the short growing season slipped away.","t":"那年春天，农民们早早地**耕犁**了冰冻的田地，决心要赶在短暂的生长季节结束前播种。"},
"despondent":{"e":"After failing the bar exam twice, he grew despondent and began to doubt whether he belonged in law at all.","t":"律师资格考试两次落榜后，他变得**沮丧**，开始怀疑自己究竟适不适合从事法律这一行。"},
"hind":{"e":"The injured deer dragged its hind leg across the frozen meadow, leaving a faint trail of blood in the snow.","t":"受伤的鹿拖着**后**腿穿过冰冻的草地，在雪地上留下一道淡淡的血迹。"},
"untapped":{"e":"Investors viewed the rural region's untapped mineral reserves as a fortune waiting for anyone bold enough to extract them.","t":"投资者认为这个农村地区**未开发**的矿产储备，是留给任何有胆量开采之人的一笔财富。"},
"ambush":{"e":"Rebel fighters ambushed the supply convoy at dawn, blocking the narrow mountain pass with fallen trees.","t":"反叛武装在黎明时分**伏击**了补给车队，用倒下的树木堵住了狭窄的山口。"},
"exponent":{"e":"As the movement's most persuasive exponent, she spent decades traveling the country to defend its core principles.","t":"作为这场运动最有说服力的**倡导者**，她花了数十年时间走遍全国，捍卫其核心原则。"},
"resist":{"e":"The old fortress walls were built thick enough to resist even sustained cannon fire during the siege.","t":"这座古老堡垒的城墙修建得极为坚厚，足以在围城期间**抵御**持续不断的炮火。"},
"moth":{"e":"A large moth kept circling the porch light, its pale wings flickering against the darkness of the yard.","t":"一只大**蛾**绕着门廊灯不停打转，苍白的翅膀在院子的黑暗中闪动。"},
"shame":{"e":"A deep sense of shame kept him from admitting that he had lost the family's entire savings on a single bet.","t":"深深的**羞愧**让他始终无法承认自己在一次赌博中输掉了全家的积蓄。"},
"disaster":{"e":"The flood was declared a national disaster after it destroyed thousands of homes along the swollen river.","t":"洪水摧毁了这条暴涨河流沿岸数千座房屋后，被宣布为一场全国性**灾难**。"},
"skull":{"e":"The archaeologist carefully brushed dirt away from the ancient skull before photographing it for the museum's records.","t":"考古学家小心翼翼地拂去古代**头骨**上的泥土，然后为博物馆的档案拍照存证。"},
"infant":{"e":"The exhausted new parents took turns rocking the crying infant back to sleep through most of the night.","t":"疲惫不堪的新手父母轮流哄着哭闹的**婴儿**，忙活了大半个晚上才让他重新入睡。"},
"commune":{"e":"Every summer he retreats alone to the cabin, wanting nothing more than to commune quietly with the surrounding forest.","t":"每年夏天他都会独自躲到小屋里，只想安静地与周围的森林**心灵相通**。"},
"recline":{"e":"She reclined against the porch cushions, watching the sunset stretch orange light across the quiet neighborhood.","t":"她**斜靠**在门廊的靠垫上，看着落日把橙色的光洒满这个安静的社区。"},
"available":{"e":"The new vaccine finally became available to the public after two years of rigorous clinical trials and review.","t":"经过两年严格的临床试验和审核，公众终于**能够获得**这款新疫苗。"},
"environmental":{"e":"The factory faced heavy fines after inspectors discovered it had ignored basic environmental regulations for nearly a decade.","t":"检查人员发现这家工厂近十年来一直无视基本的**环境**法规后，工厂被处以重罚。"},
"tableland":{"e":"Herds of wild horses roamed the vast tableland, grazing freely across miles of flat, wind-swept grassland.","t":"成群的野马在这片广袤的**高原**上漫游，在数英里平坦而多风的草地上自由觅食。"},
"erect":{"e":"Volunteers erected a temporary shelter within hours, giving the flood victims somewhere dry to sleep that night.","t":"志愿者们在几个小时内就**搭建**起一座临时避难所，让洪灾受害者当晚有干燥的地方可以睡觉。"},
"spheroid":{"e":"Because of its rotation, the Earth is technically not a perfect sphere but a slightly flattened spheroid.","t":"由于自转的缘故，地球严格来说并非完美的球体，而是一个略微扁平的**椭球体**。"},
"fatigue":{"e":"Extreme fatigue eventually forced the marathon runner to slow to a walk during the final grueling mile.","t":"极度的**疲劳**最终迫使这名马拉松选手在最后艰苦的一英里里放慢脚步、改为步行。"},
"climate":{"e":"Farmers in the region have had to adapt their crops repeatedly as the local climate grows hotter and drier each year.","t":"由于当地**气候**逐年变得更热更干，这个地区的农民不得不一再调整他们种植的作物。"},
"recall":{"e":"She could still vividly recall the smell of her grandmother's kitchen, even decades after the house had been sold.","t":"即使在房子卖掉几十年后，她依然能清晰地**回忆起**祖母厨房的味道。"},
"altitude":{"e":"The climbers stopped to acclimatize at a lower altitude before attempting the summit, where the air grows dangerously thin.","t":"登山者先在较低的**海拔**处适应，然后再尝试冲顶，那里的空气稀薄得十分危险。"},
"pursuit":{"e":"His relentless pursuit of perfection in every recording left the band exhausted but genuinely proud of the album.","t":"他对每一段录音精益求精的不懈**追求**，让乐队筋疲力尽，却也由衷地为这张专辑感到自豪。"},
"vertical":{"e":"The climbing wall's nearly vertical face tested even the most experienced athletes at the regional competition.","t":"这面攀岩墙几乎**垂直**的岩面，在这场地区比赛中考验了最有经验的运动员。"},
"flavor":{"e":"A pinch of smoked paprika gave the stew a deep, smoky flavor that the children instantly loved.","t":"一小撮烟熏红椒粉让这锅炖菜有了浓郁的烟熏**风味**，孩子们立刻就爱上了。"},
"priority":{"e":"After the diagnosis, spending time with his family became his only real priority, ahead of career or money.","t":"确诊之后，陪伴家人成了他唯一真正的**优先事项**，排在事业和金钱之前。"},
"radiate":{"e":"Even after sunset, the pavement continued to radiate heat that had been absorbed throughout the long summer afternoon.","t":"即使日落之后，人行道仍然持续**散发**出整个漫长夏日午后吸收的热量。"},
"glacier":{"e":"Scientists have watched the glacier retreat nearly a mile up the valley over the past three decades.","t":"科学家们观察到，在过去三十年里，这条**冰川**已沿山谷向后退缩了近一英里。"},
"position":{"e":"She turned down a prestigious position at the bank to teach chemistry at her old high school instead.","t":"她拒绝了银行一份令人艳羡的**职位**，转而回到自己的母校高中教化学。"},
"beach":{"e":"Local volunteers gathered at dawn to clear plastic debris from the beach before the tourist season began.","t":"当地志愿者在黎明时分聚集起来，赶在旅游旺季开始前清理**海滩**上的塑料垃圾。"},
"assistant":{"e":"The professor relied on her graduate assistant to grade papers and organize the lab's chaotic weekly schedule.","t":"教授依靠她的研究生**助教**批改论文，并安排实验室混乱的每周日程。"},
"comedy":{"e":"The director's latest comedy pokes gentle fun at office politics without ever feeling mean-spirited or cruel.","t":"这位导演最新的**喜剧**温和地调侃了办公室政治，却丝毫没有刻薄或残忍之感。"},
"overlap":{"e":"Her work schedule and her daughter's soccer practice overlap so often that her husband handles most pickups now.","t":"她的工作日程和女儿的足球训练常常**重叠**，所以现在大多数接送都是丈夫负责。"},
"militant":{"e":"A small group of militants seized the radio station, demanding the government release several imprisoned activists.","t":"一小群**激进分子**占领了电台，要求政府释放几名被监禁的活动人士。"},
"continuum":{"e":"Linguists now describe dialect boundaries not as sharp lines but as points along a gradual continuum of change.","t":"语言学家现在认为方言的界限并非清晰的分界线，而是一个渐变**连续体**上的点。"},
"virtuous":{"e":"The novel's supposedly virtuous hero turns out to have manipulated nearly everyone around him for personal gain.","t":"这部小说里那位据称**品行端正**的主人公，其实操纵了几乎所有身边的人来谋取私利。"},
"addictive":{"e":"Developers designed the game's reward system to be deliberately addictive, keeping players glued to their screens for hours.","t":"开发者故意把游戏的奖励系统设计得让人**上瘾**，使玩家一玩就是好几个小时。"},
"omit":{"e":"The editor omitted an entire paragraph from the final draft, worried it would distract readers from the main argument.","t":"编辑从终稿中**删去**了整整一段，担心它会分散读者对主要论点的注意力。"},
"illusion":{"e":"The narrow hallway's mirrors were carefully angled to create the illusion of a room twice its actual size.","t":"狭窄走廊里的镜子经过精心角度设计，营造出房间比实际大一倍的**错觉**。"},
"household":{"e":"After the film's surprise success, the young actress became a household name almost overnight across the country.","t":"这部电影意外走红后，这位年轻女演员几乎一夜之间就成了全国**家喻户晓**的人物。"},
"chronical":{"e":"Chronical back pain from decades of surgery finally forced her to retire years earlier than she had ever planned.","t":"数十年手术生涯带来的**慢性**背痛，最终迫使她比原计划提前多年退休。"},
"methane":{"e":"Decomposing waste in the landfill releases methane, a greenhouse gas far more potent than carbon dioxide.","t":"垃圾填埋场中腐烂的废物会释放**甲烷**，这是一种比二氧化碳强效得多的温室气体。"},
"compute":{"e":"Engineers carefully computed the bridge's exact load capacity before allowing the first heavy trucks to cross it.","t":"工程师们仔细**计算**了大桥的准确承重能力，才允许第一批重型卡车通过。"},
"preponderance":{"e":"A preponderance of evidence pointed to the defendant's guilt, even though no single witness had seen the crime.","t":"尽管没有一个目击者亲眼看到案发过程，但**占优势**的证据都指向被告有罪。"},
"reschedule":{"e":"The airline rescheduled the flight twice because of mechanical problems, leaving passengers stranded at the gate overnight.","t":"由于机械故障，航空公司两次**重新安排**了航班时间，导致乘客在登机口滞留了一整夜。"},
"genuine":{"e":"Her genuine concern for the new employees, rather than any company policy, was what made the office feel welcoming.","t":"让这间办公室显得温暖的，不是什么公司制度，而是她对新员工**真诚**的关心。"},
"leak":{"e":"Someone inside the campaign secretly leaked the confidential memo to reporters just days before the election.","t":"竞选团队内部有人在选举前几天把这份机密备忘录**泄露**给了记者。"},
"grazing":{"e":"Local ranchers rotate their cattle between fields to keep grazing sustainable and prevent the hillside from turning bare.","t":"当地牧场主轮换牧场放牛，以保持**放牧**的可持续性，防止山坡变得光秃秃。"},
"instance":{"e":"The professor cited a specific instance from last year's case study to illustrate how the theory actually works.","t":"教授引用了去年案例研究中的一个具体**例子**，来说明这个理论实际上是如何运作的。"},
"overtime":{"e":"Warehouse workers were asked to work overtime every night that week to clear the backlog before the holiday rush.","t":"那一周，仓库工人们被要求每晚都**加班**，以便在假日高峰之前清理积压的订单。"},
"physiology":{"e":"Understanding the physiology of high-altitude adaptation helped researchers explain why some climbers survive with so little oxygen.","t":"了解高海拔适应的**生理机能**，帮助研究人员解释了为何一些登山者能在如此稀薄的氧气中生存。"},
"lava":{"e":"Molten lava crept slowly down the volcano's slope, swallowing everything in its path including an entire coastal road.","t":"滚烫的**熔岩**缓缓沿火山坡流下，吞没了沿途的一切，包括一整条沿海公路。"},
"deserve":{"e":"After three years of unpaid overtime, she felt she deserved the promotion far more than anyone else on the team.","t":"三年无偿加班之后，她觉得自己比团队里任何人都更**应得**这次晋升。"},
"grocery":{"e":"On her way home, she stopped at the corner grocery to pick up milk and fresh bread for breakfast.","t":"在回家的路上，她在街角的**杂货店**停下来买了牛奶和新鲜面包当早餐。"},
"captivity":{"e":"The rescued eagle had spent so many years in captivity that keepers doubted it could ever survive in the wild.","t":"这只被救的鹰在**囚禁**中度过了太多年，饲养员都怀疑它是否还能在野外存活。"},
"pronounced":{"e":"Her accent became far more pronounced whenever she spoke to her grandmother on the phone in their native dialect.","t":"每当她用家乡方言跟祖母通电话时，她的口音就会变得**更加明显**。"},
"bouquet":{"e":"He arrived at the hospital clutching a bouquet of wildflowers he had picked along the roadside that morning.","t":"他抵达医院时，手里紧紧攥着一**束野花**，那是他那天早上沿路采摘的。"},
"endeavor":{"e":"The research team endeavored for years to isolate the gene responsible for the rare inherited disorder.","t":"研究团队多年来一直**努力**分离出导致这种罕见遗传性疾病的基因。"},
"submission":{"e":"The committee extended the deadline for grant submissions after several applicants complained about the short notice.","t":"几名申请人抱怨通知时间太短后，委员会延长了资助**申请提交**的截止日期。"},
"ware":{"e":"The market stall displayed handmade ware alongside carved wooden spoons and hand-woven baskets from nearby villages.","t":"集市摊位上陈列着手工制作的**陶器**，旁边还有雕花木勺和附近村庄手编的篮子。"},
"jaw":{"e":"The boxer's jaw absorbed the full force of the punch, sending him staggering back against the ropes.","t":"拳手的**下颌**承受了这一拳的全部力道，让他踉跄着后退撞上了绳索。"},
"retreat":{"e":"The exhausted army retreated across the frozen river, abandoning most of its heavy artillery along the way.","t":"疲惫不堪的军队**撤退**过结冰的河流，沿途丢弃了大部分重型火炮。"},
"squid":{"e":"Fishermen hauled in an enormous squid that night, far larger than anything the crew had ever seen.","t":"那天晚上渔民们捕获了一只巨大的**鱿鱼**，比船员们见过的任何一只都要大得多。"},
"adventure":{"e":"Their unplanned detour through the mountains turned into the kind of adventure they would recount for years.","t":"他们在山间意外的绕道，变成了一场日后多年都会反复提起的**冒险**。"},
"denote":{"e":"In this diagram, a dotted line denotes a boundary that is disputed rather than officially recognized.","t":"在这张图中，虚线**表示**的是一条存在争议、尚未获得正式承认的边界。"},
"stew":{"e":"She let the beef stew simmer on the stove for hours, filling the whole apartment with a rich aroma.","t":"她让牛肉**炖菜**在炉子上慢炖了几个小时，整间公寓都弥漫着浓郁的香气。"},
"incoming":{"e":"The incoming CEO promised to reorganize the entire supply chain within her first hundred days on the job.","t":"这位**新任**首席执行官承诺，要在上任的头一百天内重组整条供应链。"},
"rupture":{"e":"A ruptured water pipe beneath the busy street flooded the basements of three neighboring buildings overnight, causing significant damage.","t":"街道下方一根**破裂**的水管在夜间淹没了三栋相邻建筑的地下室，造成了严重损失。"},
"patriarchic":{"e":"The novel critiques the patriarchic customs that once denied village women any real say in property decisions.","t":"这部小说批判了曾经剥夺村里女性在财产问题上任何话语权的**家长制**习俗。"},
"depredation":{"e":"Decades of relentless depredation by poachers had left the once-thriving elephant population dangerously close to collapse.","t":"数十年来盗猎者无休止的**掠夺**，已使曾经繁盛的大象种群濒临崩溃的危险边缘。"},
"racing":{"e":"He spent every weekend at the racing track, convinced he would eventually pick the winning horse.","t":"他每个周末都泡在**赛马**场，坚信自己迟早能挑中获胜的那匹马。"},
"handle":{"e":"The new manager handled the layoffs with unusual compassion, meeting privately with every employee who lost a job.","t":"新任经理以罕见的同情心**处理**了这次裁员，私下与每一位失业员工进行了会面。"},
"operate":{"e":"Only certified technicians are allowed to operate the crane on this section of the construction site.","t":"在工地的这个区域，只有获得认证的技术人员才被允许**操作**这台起重机。"},
"hue":{"e":"The sunset painted the sky in shifting hues of orange and violet that lasted only a few minutes.","t":"落日把天空染成了变幻的橙紫**色调**，这景象只持续了短短几分钟。"},
"rhythm":{"e":"The drummer set a steady rhythm that the rest of the band gradually fell into without any rehearsal.","t":"鼓手定下了一个稳定的**节奏**，乐队其他成员在没有排练的情况下也逐渐跟上了。"},
"permission":{"e":"Students must obtain written permission from a parent before joining the overnight field trip to the mountains.","t":"学生必须获得家长的书面**许可**，才能参加这次去山区的过夜实地考察。"},
"catastrophe":{"e":"Engineers later admitted that a single overlooked valve had turned a minor leak into a full-blown catastrophe.","t":"工程师后来承认，一个被忽视的阀门竟把一次小小的泄漏变成了一场彻底的**灾难**。"},
"presidency":{"e":"Historians still debate whether his presidency achieved more good than harm for the country's fragile economy.","t":"历史学家至今仍在争论，他的**总统任期**对这个国家脆弱的经济究竟是利大于弊还是弊大于利。"},
"independent":{"e":"Raised by a single parent, she became fiercely independent long before most of her classmates left for college.","t":"由单亲抚养长大，她早在大多数同学离家上大学之前就已变得极其**独立**。"},
"handful":{"e":"Only a handful of students in the entire lecture hall had actually finished the assigned reading.","t":"整个阶梯教室里，实际读完指定阅读材料的学生只有**寥寥几个**。"},
"yelp":{"e":"The startled puppy yelped sharply when its paw got caught briefly under the sliding kitchen door.","t":"受惊的小狗爪子被厨房滑动门短暂夹住时，突然**尖叫**了一声。"},
"muse":{"e":"She mused quietly over her coffee, wondering whether she had made the right decision to leave her job.","t":"她端着咖啡静静地**沉思**，心里琢磨着辞职这个决定到底对不对。"},
"tickle":{"e":"The comedian's dry, understated jokes tickled the audience far more than the loud slapstick routines that followed.","t":"这位喜剧演员干涩、含蓄的笑话，比后面那些吵闹的滑稽表演更能**逗乐**观众。"},
"contemplate":{"e":"After the accident, she began to contemplate a career change entirely away from long-haul truck driving.","t":"事故发生后，她开始**考虑**彻底转行，不再从事长途卡车驾驶工作。"},
"mortify":{"e":"Her father's habit of singing loudly in public mortified her every single time they went out together.","t":"父亲喜欢在公共场合大声唱歌的习惯，每次和他一起出门都让她感到**难堪**。"},
"deviant":{"e":"Sociologists study deviant behavior not to condemn it but to understand what social pressures produce it.","t":"社会学家研究**越轨**行为，并非为了谴责它，而是为了理解是什么社会压力催生了它。"},
"patriarchy":{"e":"The anthropologist argued that patriarchy was not universal but had emerged only under specific historical conditions.","t":"这位人类学家指出，**父权制**并非普遍存在，而是只在特定的历史条件下才出现的。"},
"entreat":{"e":"The old fisherman entreated the young sailors not to venture out before the storm had fully passed.","t":"老渔夫**恳求**年轻的水手们，一定要等暴风雨完全过去之后再出海。"},
"loath":{"e":"He was loath to admit that his younger sister's business plan was actually far better than his own.","t":"他**不情愿**地承认，妹妹的商业计划其实比他自己的要好得多。"},
"derivation":{"e":"The professor traced the derivation of the word back through Latin and Greek to its ancient root.","t":"教授追溯了这个词的**词源**，从拉丁语、希腊语一路查到它古老的词根。"},
"gleam":{"e":"Moonlight gleamed off the wet cobblestones, making the empty alley look almost silver in the darkness.","t":"月光在湿漉漉的鹅卵石路面上**闪烁**，让这条空荡的小巷在黑暗中显得近乎银白。"},
"clench":{"e":"He clenched his fists under the table, determined not to let his frustration show during the meeting.","t":"他在桌子底下**攥紧**拳头，决心不让自己的沮丧在会议中流露出来。"},
"tempo":{"e":"The conductor slowed the tempo dramatically during the final movement, letting each note linger in the silence.","t":"指挥在终乐章大幅放慢了**速度**，让每一个音符都在寂静中久久回荡。"},
"brochure":{"e":"The travel agency's glossy brochure promised sunny beaches, but the resort turned out to be under construction.","t":"旅行社光鲜的**宣传册**承诺了阳光海滩，结果这家度假村其实还在施工中。"},
"conduct":{"e":"Researchers conducted the experiment three separate times before they trusted the surprising results enough to publish them.","t":"研究人员**进行**了三次独立的实验，才敢相信这个令人惊讶的结果并将其发表。"},
"faculty":{"e":"Even in her nineties, she retained the remarkable faculty of remembering every grandchild's birthday without a calendar.","t":"即使到了九十多岁，她依然保有过人的**记忆能力**，不用日历也能记住每个孙辈的生日。"},
"hint":{"e":"She dropped a subtle hint about wanting a puppy, hoping her parents would eventually take notice.","t":"她不经意地留下一个想要小狗的**暗示**，希望父母最终能注意到。"},
"chill":{"e":"A sudden chill swept through the valley overnight, coating every windshield in the parking lot with frost.","t":"一股突如其来的**寒意**一夜之间席卷山谷，给停车场里每辆车的挡风玻璃都结上了霜。"},
"sweeping":{"e":"The new legislation introduced sweeping changes to how hospitals across the state report medical errors to regulators.","t":"这项新法规对全州医院如何向监管机构报告医疗差错做出了**影响广泛**的改革。"},
"moist":{"e":"Bakers cover the dough with a damp cloth to keep it moist while it rises slowly overnight.","t":"面包师用一块湿布盖住面团，好让它在整夜发酵的过程中保持**湿润**。"},
"henceforth":{"e":"The board announced that, henceforth, all expense reports would require two signatures before reimbursement was approved.","t":"董事会宣布，**从此以后**，所有报销单都必须有两个人签字才能获批。"},
"advent":{"e":"The sudden advent of streaming services fundamentally changed how an entire generation discovered and shared new music.","t":"流媒体服务的突然**兴起**，从根本上改变了整整一代人发现和分享新音乐的方式。"},
"foreshorten":{"e":"The artist foreshortened the reclining figure's legs dramatically to create a convincing sense of depth on canvas.","t":"画家用透视法大幅**缩短**了斜倚人像的双腿，从而在画布上营造出令人信服的纵深感。"},
"internal":{"e":"An internal audit revealed that the company had been overcharging clients for nearly two years without anyone noticing.","t":"一次**内部**审计发现，这家公司在近两年里一直在多收客户的钱却无人察觉。"},
"yogurt":{"e":"She stirred fresh berries into her plain yogurt each morning instead of adding sugar or syrup.","t":"她每天早上都在原味**酸奶**里拌入新鲜浆果，而不是加糖或糖浆。"},
"remodel":{"e":"The couple spent an entire year remodeling the kitchen themselves to save money on contractor fees.","t":"这对夫妇花了整整一年自己动手**改造**厨房，以省下请承包商的费用。"},
"infrared":{"e":"The rescue team used an infrared camera to spot the trapped hikers' body heat through the dense fog.","t":"救援队使用**红外线**摄像机，在浓雾中探测到了被困徒步者身体散发的热量。"},
"spiny":{"e":"The spiny cactus offered little shade, but it was the only plant that survived the desert's brutal summers.","t":"这株**多刺**的仙人掌几乎遮不住阴凉，却是唯一能在沙漠酷暑中存活下来的植物。"},
"haul":{"e":"Volunteers hauled sandbags to the riverbank for hours, trying to hold back the rapidly rising floodwater.","t":"志愿者们花了几个小时**搬运**沙袋到河岸，试图挡住迅速上涨的洪水。"},
"noticeable":{"e":"There was a noticeable change in her mood after she switched to the new medication her doctor recommended.","t":"换用医生推荐的新药之后，她的情绪出现了**明显**的变化。"},
"decompose":{"e":"Fallen leaves decompose slowly on the forest floor each autumn, gradually enriching the soil with essential nutrients.","t":"每年秋天，落叶在林地上缓慢**分解**，逐渐用必需的养分滋养土壤。"},
"improve":{"e":"Regular practice gradually improved her pronunciation until native speakers stopped noticing any trace of an accent.","t":"持续的练习逐渐**改善**了她的发音，直到母语者再也听不出任何口音的痕迹。"},
"minute":{"e":"Under the microscope, researchers noticed minute cracks in the sample that were invisible to the naked eye.","t":"在显微镜下，研究人员注意到样本中一些肉眼看不见的**细微**裂纹。"},
"orchestra":{"e":"The community orchestra rehearsed every Tuesday evening in the church basement, preparing for its annual spring concert.","t":"这支社区**管弦乐队**每周二晚上都在教堂地下室排练，为一年一度的春季音乐会做准备。"},
"transaction":{"e":"Every transaction on the platform is recorded permanently, making fraudulent activity far easier for investigators to trace.","t":"平台上的每一笔**交易**都会被永久记录，这让调查人员追查欺诈活动变得容易得多。"},
"superintendent":{"e":"The new school superintendent immediately cut funding for standardized testing and redirected it toward music programs.","t":"新任学区**主管**立即削减了标准化考试的经费，转而将其投入音乐项目。"},
"brush":{"e":"She brushed the crumbs off the table before setting down the freshly baked pie for everyone to admire.","t":"她**拂**去桌上的碎屑，然后把刚烤好的派摆上桌，让大家都能好好欣赏一番。"},
"incredible":{"e":"The rescue dog's incredible sense of smell led searchers directly to the survivor buried under six feet of rubble.","t":"这只搜救犬**惊人**的嗅觉，直接把搜救人员带到了被埋在六英尺瓦砾下的幸存者身边。"},
"section":{"e":"The quiet section of the library near the windows became her favorite spot to study during finals week.","t":"图书馆靠窗那个安静的**区域**，成了她期末考试周最喜欢的学习地点。"},
"faucet":{"e":"A dripping faucet in the upstairs bathroom kept her awake for most of the night until she finally fixed it.","t":"楼上浴室一个滴水的**水龙头**，让她大半夜都睡不着，直到她终于把它修好。"},
"gradient":{"e":"Engineers had to reduce the road's gradient significantly so trucks wouldn't stall while climbing the steep mountain pass.","t":"工程师们不得不大幅降低这条道路的**坡度**，这样卡车爬这段陡峭山路时才不会熄火。"},
"absorption":{"e":"The plant's rapid absorption of nitrogen from the soil explained why it grew nearly twice as fast as its neighbors.","t":"这株植物从土壤中快速**吸收**氮元素，解释了它为何生长速度几乎是邻近植株的两倍。"},
"chimpanzee":{"e":"Researchers spent years observing how a wild chimpanzee troop used simple tools to extract termites from mounds.","t":"研究人员花了数年观察一群野生**黑猩猩**如何使用简单的工具从蚁丘中取出白蚁。"},
"temporary":{"e":"The bridge closure was meant to be temporary, but repairs dragged on for nearly two frustrating years.","t":"这座桥的封闭原本只是**临时**措施，但维修工程却拖了将近两年，令人沮丧。"},
"aggression":{"e":"The treaty was designed to prevent further aggression between the two neighboring countries after decades of border skirmishes.","t":"这项条约旨在防止两个邻国在经历数十年边境冲突后再度发生**侵略**行为。"},
"project":{"e":"Analysts project that the company's revenue will double within three years if the current growth trend continues.","t":"分析师**预测**，如果目前的增长趋势持续下去，这家公司的营收将在三年内翻倍。"},
"satire":{"e":"The novel is a biting satire of corporate culture, mocking empty jargon and pointless meetings alike.","t":"这部小说是一部辛辣的企业文化**讽刺作品**，把空洞的行话和无意义的会议都调侃了一番。"},
"batch":{"e":"The bakery sold out its entire first batch of cinnamon rolls within twenty minutes of opening.","t":"这家面包店开门仅二十分钟，第一**批**肉桂卷就全部售罄了。"},
"grovel":{"e":"He refused to grovel before the committee, even though a simple apology might have saved his position.","t":"他拒绝在委员会面前**卑躬屈膝**，尽管一句简单的道歉或许就能保住他的职位。"},
"ambient":{"e":"Soft ambient lighting throughout the restaurant made even the loudest tables feel strangely calm and intimate.","t":"整家餐厅柔和的**环境**灯光，让即便最吵闹的桌子也显得莫名平静而亲密。"},
"duplicate":{"e":"The locksmith duplicated her house key in under five minutes while she waited by the counter.","t":"锁匠在她于柜台旁等候的不到五分钟内，就把她家的钥匙**复制**好了。"},
"transcendent":{"e":"Critics called her final performance transcendent, unlike anything the orchestra had produced in its long history.","t":"评论家称她的最后一场演出**卓越非凡**，是这支乐团漫长历史上从未有过的水准。"},
"prostitution":{"e":"The city council debated new policies aimed at reducing street prostitution near the downtown transit station.","t":"市议会讨论了旨在减少市中心交通站附近街头**卖淫**现象的新政策。"},
"cluster":{"e":"A cluster of reporters gathered outside the courthouse, waiting for the jury to announce its verdict.","t":"一**群**记者聚集在法院外，等待陪审团宣布判决结果。"},
"verge":{"e":"By the fourth sleepless night, the new parents were verging on complete exhaustion and short tempers.","t":"到了第四个无眠之夜，这对新手父母已经**濒临**彻底崩溃和脾气暴躁的边缘。"},
"kinship":{"e":"Anthropologists carefully mapped the village's complex kinship system to understand how land was traditionally passed down.","t":"人类学家仔细梳理了这个村庄复杂的**亲属**体系，以理解土地历来是如何传承的。"},
"groove":{"e":"The needle settled gently into the old record's worn groove, filling the room with warm, crackling sound.","t":"唱针轻轻落入老唱片磨损的**纹路**，整个房间顿时充满了温暖而带着沙沙声的音乐。"},
"anomie":{"e":"The sociologist blamed the sudden anomie in the mining town on the abrupt collapse of its only industry.","t":"这位社会学家把矿业小镇突然出现的**社会失范**现象，归咎于其唯一产业的骤然崩溃。"},
"emigrate":{"e":"Her grandparents emigrated from a small coastal village long before she was born, carrying only a single suitcase.","t":"她的祖父母早在她出生之前就已经**移民**离开了那个小小的沿海村庄，只带着一只行李箱。"},
"slick":{"e":"Voters grew suspicious of the candidate's slick promises after none of his previous pledges had materialized.","t":"选民们对这位候选人**华而不实**的承诺越发怀疑，因为他之前的承诺没有一个兑现过。"},
"prelude":{"e":"The quiet border skirmishes turned out to be a prelude to a war that would last a decade.","t":"那些悄无声息的边境冲突，后来证明只是一场持续十年之久的战争的**序幕**。"},
"immerse":{"e":"She immersed herself completely in the language, refusing to speak English for the entire six-month exchange.","t":"她把自己完全**沉浸**在这门语言中，整整六个月的交流期间都拒绝说英语。"},
"barber":{"e":"The old barber had cut hair in the same tiny shop for over fifty years, refusing to retire.","t":"这位老**理发师**在同一家小店里理了五十多年的发，一直不肯退休。"},
"ruin":{"e":"A single careless mistake during the final inning ruined what had otherwise been a nearly perfect season.","t":"决赛局中一个粗心的失误，**毁掉**了原本几乎完美的整个赛季。"},
"auxiliary":{"e":"The hospital switched to its auxiliary generator the moment the main power grid failed during the storm.","t":"暴风雨中主电网一旦断电，医院就立刻切换到了**备用**发电机。"},
"distress":{"e":"The coast guard received a distress signal from a fishing boat taking on water miles offshore.","t":"海岸警卫队收到了一艘在数英里外海面进水的渔船发出的**遇难**信号。"},
"pole":{"e":"Workers raised the new flag to the top of the pole just as the ceremony began.","t":"就在仪式开始的那一刻，工作人员把新旗帜升到了旗**杆**顶端。"},
"vicinity":{"e":"Several small cafes opened in the vicinity of the new train station within just a few months.","t":"新火车站**附近**在短短几个月内就开了好几家小咖啡馆。"},
"metallic":{"e":"A sharp, metallic taste lingered in his mouth after he accidentally bit down on a piece of foil.","t":"他不小心咬到一片锡纸后，嘴里久久残留着一股刺鼻的**金属**味。"},
"term":{"e":"Neither company would agree to the contract's payment terms, so negotiations stalled for another three weeks.","t":"两家公司都不同意合同的付款**条款**，谈判因此又僵持了三个星期。"},
"chief":{"e":"The fire chief immediately ordered the entire block evacuated the moment flames reached the underground gas line.","t":"火势蔓延到地下燃气管道的那一刻，消防**队长**立即下令疏散整个街区。"},
"hinder":{"e":"Heavy fog hindered the search party's progress, forcing them to turn back before reaching the summit.","t":"浓雾**妨碍**了搜救队的进度，迫使他们在到达山顶之前折返。"},
"shatter":{"e":"One devastating injury shattered her Olympic dreams just months before the qualifying trials were set to begin.","t":"一次毁灭性的受伤，在资格赛即将开始前的几个月**击碎**了她的奥运梦想。"},
"instruction":{"e":"He skipped the printed assembly instructions entirely and still somehow managed to put the bookshelf together correctly.","t":"他完全跳过了印刷的组装**说明书**，却还是设法把书架正确地拼装了起来。"},
"prehistoric":{"e":"Fossilized footprints found deep inside the cave suggested that prehistoric humans once sheltered there during harsh winters.","t":"洞穴深处发现的化石足迹表明，**史前**人类曾在严酷的冬季躲藏于此。"},
"address":{"e":"The mayor promised to address the housing shortage directly in her speech to the city council.","t":"市长承诺将在她面向市议会的演讲中直接**处理**住房短缺问题。"},
"ripen":{"e":"The tomatoes ripened slowly on the windowsill, turning from pale green to deep red over two weeks.","t":"西红柿在窗台上慢慢**成熟**，两周内从淡绿色变成了深红色。"},
"infectious":{"e":"Her infectious enthusiasm for the project convinced even the most skeptical board members to approve the budget.","t":"她对这个项目**极具感染力**的热情，说服了董事会里最持怀疑态度的成员批准了预算。"},
"garbage":{"e":"Raccoons had torn through the garbage cans again, scattering trash across the entire driveway sometime overnight.","t":"浣熊又把**垃圾**桶翻了个底朝天，把垃圾撒得整条车道到处都是。"},
"bundle":{"e":"She tied the old newspapers into a tight bundle before carrying them out to the recycling bin.","t":"她把旧报纸捆成紧紧的一**捆**，然后拿到外面的回收箱里。"},
"provision":{"e":"A new provision in the lease requires tenants to give sixty days' notice before moving out.","t":"租约中新增的一项**条款**要求租户在搬出前提前六十天通知。"},
"meaningful":{"e":"Volunteering at the shelter gave her a far more meaningful sense of purpose than her old office job ever had.","t":"在收容所做志愿者，给了她比过去办公室工作更**有意义**的人生目标感。"},
"accompany":{"e":"A trusted family friend agreed to accompany the elderly widow to her medical appointments each week.","t":"一位值得信赖的家庭友人答应每周**陪同**这位年迈的寡妇去看病。"},
"linen":{"e":"The hotel changed the linen in every room daily, a small luxury that guests consistently praised.","t":"这家酒店每天都会更换每个房间的**亚麻织品**，这个小小的奢侈之处一直受到客人的称赞。"},
"quartz":{"e":"Thin veins of glittering quartz ran through the granite boulder, catching sunlight whenever hikers passed nearby.","t":"一缕缕闪闪发光的**石英**脉穿过这块花岗岩巨石，每当有徒步者经过便会反射阳光。"},
"uppermost":{"e":"Her children's safety remained uppermost in her mind throughout the entire chaotic evacuation from the burning building.","t":"在整个混乱的撤离过程中，孩子们的安全始终是她心中**最重要**的事。"},
"sacred":{"e":"The mountain is considered sacred by local tribes, who forbid any climbing above its lower slopes.","t":"这座山被当地部落视为**神圣**之地，他们禁止任何人攀登其低坡以上的区域。"},
"extent":{"e":"Doctors could not determine the full extent of the internal damage until they performed emergency surgery.","t":"医生们直到进行了紧急手术后，才能确定内部损伤的全部**程度**。"},
"classify":{"e":"Librarians carefully classify each new arrival by subject before shelving it in the appropriate section upstairs.","t":"图书管理员会先按主题**分类**每一本新到的书，再将它上架到相应的区域。"},
"sense":{"e":"The dog sensed the approaching earthquake minutes before the first tremor was even felt by humans.","t":"这只狗在人类感觉到第一次震动之前几分钟，就已经**察觉**到了即将来临的地震。"},
"obstacle":{"e":"Funding remained the biggest obstacle standing between the researchers and a viable vaccine for the disease.","t":"资金依然是横亘在研究人员与这种疾病可行疫苗之间最大的**障碍**。"},
"whereby":{"e":"The company introduced a new system whereby employees could report safety violations anonymously without fear of retaliation.","t":"公司推出了一套新制度，**借此**员工可以匿名举报安全违规行为，而不必担心遭到报复。"},
"enslave":{"e":"The documentary exposed how the factory had effectively enslaved migrant workers, confiscating their passports on arrival.","t":"这部纪录片揭露了这家工厂如何实际上**奴役**外来务工人员，一到岗就没收他们的护照。"},
"contender":{"e":"She emerged as the strongest contender for the championship after defeating last year's defending title-holder decisively.","t":"她击败了去年的卫冕冠军后，一跃成为本次锦标赛最强劲的**竞争者**。"},
"maze":{"e":"New employees often get lost in the maze of paperwork required before their first paycheck arrives.","t":"新员工常常会迷失在领到第一份薪水之前那**如迷宫般复杂**的文书流程之中。"},
"upsurge":{"e":"The city saw a dramatic upsurge in tourism after the historic bridge reopened to the public.","t":"这座历史悠久的大桥重新对外开放后，这座城市的旅游业出现了显著的**激增**。"},
"enunciate":{"e":"The debate coach insisted that every syllable be enunciated clearly, so judges in the back row could follow each argument without straining.","t":"辩论教练坚持要求每个音节都要**清晰地发音**，这样后排的评委才能毫不费力地听懂每一个论点。"},
"prejudice":{"e":"Years of exposure to biased news coverage had left him with a stubborn prejudice against anyone who disagreed with his political views.","t":"常年接触带有偏见的新闻报道，使他对任何政治观点与自己不同的人都怀有根深蒂固的**偏见**。"},
"ancestor":{"e":"Genealogists traced the family's ancestors back through seven generations of farmers before finally reaching a small village in Sicily.","t":"家谱研究者沿着七代农民往上追溯这个家族的**祖先**，最终找到了西西里岛的一个小村庄。"},
"shred":{"e":"Before recycling the old bank statements, she carefully shredded every page so that no one could recover her account numbers.","t":"在回收旧银行对账单之前，她把每一页都仔细**切碎**，这样谁也无法找回她的账号信息。"},
"chivalrous":{"e":"Even after losing the tournament, the young knight remained chivalrous, congratulating his opponent and helping him up from the muddy field.","t":"即使输掉了比武大会，这位年轻骑士依然**彬彬有礼**，向对手表示祝贺，还把他从泥泞的场地上扶了起来。"},
"heed":{"e":"The hikers ignored the ranger's warning, but those who heeded her advice about the storm avoided the dangerous flash flood entirely.","t":"徒步者们没有理会护林员的警告，但那些**留心**她关于风暴建议的人完全避开了危险的山洪。"},
"betray":{"e":"Desperate to save himself, the informant betrayed his closest friends to the police in exchange for a lighter sentence.","t":"为了自保，这名线人向警方**出卖**了自己最亲密的朋友，以换取较轻的刑罚。"},
"admire":{"e":"Colleagues admired her for staying calm under pressure, never raising her voice even when the project deadline seemed impossible to meet.","t":"同事们**钦佩**她在压力下始终保持冷静，即使项目截止日期看似遥不可及，她也从不提高嗓门。"},
"spearhead":{"e":"A determined group of scientists spearheaded the campaign to ban the pesticide after discovering its effects on local bird populations.","t":"一群意志坚定的科学家在发现这种农药对当地鸟类的影响后，**带头**发起了禁止使用该农药的运动。"},
"rainbow":{"e":"Sunlight scattering through the lingering raindrops arched a brilliant rainbow across the valley just as the storm clouds finally parted.","t":"阳光穿过还未散尽的雨滴，在山谷上空架起一道绚丽的**彩虹**，恰好这时暴风云也终于散开了。"},
"humanitarian":{"e":"The organization's humanitarian mission focused on delivering clean water and medical supplies to villages devastated by the earthquake.","t":"该组织的**人道主义**使命是向遭受地震重创的村庄提供干净水源和医疗物资。"},
"inactive":{"e":"Doctors warned that remaining inactive for months after the surgery would weaken his muscles far more than a gradual return to exercise.","t":"医生警告说，手术后如果一连几个月保持**不活动**状态，肌肉的萎缩程度会远超循序渐进恢复锻炼的情况。"},
"block":{"e":"A fallen tree blocked the only road into town, forcing emergency crews to reach the stranded residents by helicopter instead.","t":"一棵倒下的树**阻塞**了通往镇上的唯一道路，救援人员只好改乘直升机去营救被困的居民。"},
"recycle":{"e":"Instead of throwing away the shattered glass bottles, the factory recycles them into raw material for new construction tiles.","t":"这家工厂没有把破碎的玻璃瓶扔掉，而是把它们**回收利用**，制成新建筑瓷砖的原材料。"},
"adobe":{"e":"Generations of villagers had built their homes from sun-dried adobe, a material that kept interiors cool despite the desert heat.","t":"世世代代的村民都用晒干的**泥砖**建造房屋，这种材料即使在沙漠酷热中也能让室内保持凉爽。"},
"frost":{"e":"An unexpected frost blanketed the orchard overnight, killing the delicate blossoms before the peaches had any chance to form.","t":"一场突如其来的**霜冻**一夜之间笼罩了果园，娇嫩的花朵还没等桃子长成就被冻死了。"},
"longitude":{"e":"Sailors once relied on accurate clocks to calculate longitude, since even a small timing error could place a ship hundreds of miles off course.","t":"水手们曾经依靠精准的时钟来计算**经度**，因为哪怕很小的计时误差也可能使船只偏离航线几百英里。"},
"adequate":{"e":"The shelter had barely adequate space for the flood victims, with families sleeping in shifts because there were not enough cots.","t":"这个避难所的空间勉强**够用**，用来安置洪水灾民，家庭们只能轮流睡觉，因为行军床不够。"},
"kingdom":{"e":"The old king divided his kingdom among three sons, unaware that the decision would spark a war within a generation.","t":"老国王把自己的**王国**分给了三个儿子，却没料到这个决定会在一代人之内引发战争。"},
"intersection":{"e":"Traffic backed up for blocks after a delivery truck stalled right in the middle of the busiest intersection downtown.","t":"一辆送货卡车正好在市中心最繁忙的**十字路口**中央抛锚，导致交通堵塞了好几个街区。"},
"religion":{"e":"Despite growing up in the same household, the two brothers eventually chose completely different religions to guide their adult lives.","t":"尽管在同一个家庭长大，这两兄弟成年后却各自选择了完全不同的**宗教信仰**来指引自己的生活。"},
"surge":{"e":"Demand for face masks surged so quickly during the outbreak that most pharmacies sold out within a single afternoon.","t":"疫情爆发期间口罩需求**激增**得如此之快，以至于大多数药店一个下午就卖光了。"},
"method":{"e":"The chemistry teacher demonstrated a safer method for handling the volatile compound before letting students attempt the experiment themselves.","t":"化学老师先演示了一种更安全的处理这种易挥发化合物的**方法**，然后才让学生自己尝试这项实验。"},
"intent":{"e":"Investigators struggled to prove criminal intent, since the accused claimed he had simply forgotten to return the borrowed equipment.","t":"调查人员很难证明其犯罪**意图**，因为被告声称自己只是忘了归还借用的设备。"},
"maintain":{"e":"The old lighthouse keeper maintained the massive lens by hand, polishing every panel weekly so ships could still see the beam for miles.","t":"老灯塔看守人一直用手工**维护**那面巨大的透镜，每周都擦拭每一块镜片，好让船只在几英里外仍能看到灯光。"},
"vegetation":{"e":"Thick vegetation along the riverbank made it nearly impossible for the search team to spot the missing hikers from above.","t":"河岸边茂密的**植被**让搜救队几乎不可能从空中发现失踪的徒步者。"},
"possess":{"e":"Few musicians possess the rare combination of technical precision and raw emotion that made her performance so unforgettable.","t":"很少有音乐家**拥有**她那种精准技巧与原始情感兼具的稀有天赋，这也是她的演出如此难忘的原因。"},
"interplay":{"e":"The novel's tension comes from the constant interplay between the narrator's cold logic and his sister's impulsive, emotional decisions.","t":"这部小说的张力来自叙述者冷静的逻辑与他妹妹冲动、感性的决定之间不断的**相互作用**。"},
"recurring":{"e":"A recurring dream about falling from a great height kept waking her at exactly three in the morning, night after night.","t":"一个**反复出现**的从高处坠落的梦，每晚都在凌晨三点准时把她惊醒。"},
"cascade":{"e":"Meltwater cascaded down the mountainside in a series of glittering falls, feeding the river that irrigated the entire valley below.","t":"融化的雪水沿山坡层层**倾泻**而下，形成一连串闪耀的瀑布，为下方灌溉整个山谷的河流补充水源。"},
"assembly":{"e":"Workers on the assembly line repeated the same six steps hundreds of times each shift, tightening bolts on every passing chassis.","t":"**装配**线上的工人每班都要把同样的六个步骤重复几百次，给每一辆经过的底盘拧紧螺栓。"},
"investigate":{"e":"Detectives spent three weeks investigating the warehouse fire before concluding that faulty wiring, not arson, had caused the blaze.","t":"侦探们花了三周时间**调查**这场仓库大火，最终得出结论：起火原因是电线故障，而非纵火。"},
"mercantile":{"e":"The port city's wealth grew from its mercantile ties with distant colonies, which shipped spices, silk, and timber through its harbor.","t":"这座港口城市的财富源于它与遥远殖民地的**贸易**往来，香料、丝绸和木材都经这个港口运送。"},
"renovate":{"e":"The city council voted to renovate the crumbling opera house rather than demolish it, preserving its ornate ceiling for future generations.","t":"市议会投票决定**翻修**这座摇摇欲坠的歌剧院，而不是拆除它，把华丽的天花板留给后代。"},
"attractive":{"e":"The startup's flexible hours and generous vacation policy made it far more attractive to young engineers than the rigid corporate jobs nearby.","t":"这家初创公司灵活的工作时间和丰厚的假期政策，让它对年轻工程师来说远比附近死板的企业工作更具**吸引力**。"},
"postage":{"e":"Because the package weighed just over the limit, she had to pay extra postage before the clerk would accept it for shipping.","t":"因为包裹的重量刚好超过限制，她不得不多付**邮资**，柜员才肯受理这个包裹的寄送。"},
"coexist":{"e":"Conservationists argued that wolves and ranchers could coexist peacefully if the herds were better protected with sturdy fencing at night.","t":"环保主义者认为，只要夜间用坚固的围栏更好地保护畜群，狼群和牧场主就能和平**共存**。"},
"lasting":{"e":"The therapist explained that lasting change comes from small daily habits, not from one dramatic burst of willpower.","t":"治疗师解释说，**持久**的改变来自每天微小的习惯，而不是一时意志力的爆发。"},
"foster":{"e":"The community garden was designed to foster friendships among neighbors who had rarely spoken before sharing the same plot of soil.","t":"这个社区花园的初衷是**培养**邻里之间的友谊，此前这些邻居在共用同一块土地之前几乎从未交谈过。"},
"aloft":{"e":"The kestrel hung aloft above the meadow, wings barely moving, scanning the grass below for the slightest hint of movement.","t":"红隼**悬浮在高空**，停在草地上方，翅膀几乎不动，扫视着下方的草丛，寻找哪怕一丝动静。"},
"manifestation":{"e":"Her sudden generosity toward strangers was, according to her therapist, a manifestation of guilt she had never openly discussed.","t":"据她的治疗师说，她对陌生人突然表现出的慷慨，其实是她从未公开谈过的愧疚感的一种**表现**。"},
"date":{"e":"Archaeologists used carbon analysis to date the charred wooden beam to roughly three thousand years before the present era.","t":"考古学家用碳分析法**推断**这根烧焦木梁的年代，大约是在距今三千年前。"},
"surround":{"e":"Thick stone walls surrounded the ancient monastery, shielding the monks inside from raiders who occasionally passed through the valley.","t":"厚厚的石墙**环绕**着这座古老的修道院，保护院内的僧侣不受偶尔经过山谷的强盗侵扰。"},
"limestone":{"e":"The cathedral's walls were built entirely of limestone quarried from a nearby hillside, which gave the structure its pale golden hue.","t":"大教堂的墙壁完全用附近山坡开采的**石灰石**建成，这也让整座建筑呈现出淡淡的金色。"},
"exert":{"e":"The coach told the runners to exert steady pressure on the pace for the first five miles, saving their final push for the hill.","t":"教练告诉跑者在前五英里要**施加**稳定的配速压力，把最后的冲刺留给那段上坡路。"},
"converge":{"e":"Five hiking trails converge at the same mountain overlook, which is why the small clearing gets so crowded by midafternoon.","t":"五条徒步小径都在同一个山顶观景点**交汇**，这也是为什么这片小空地到了下午就变得拥挤不堪。"},
"prerequisite":{"e":"Fluency in organic chemistry is a prerequisite for the advanced biochemistry seminar, so most freshmen simply cannot enroll yet.","t":"精通有机化学是选修高级生物化学研讨课的**先决条件**，所以大多数大一新生根本还不能注册这门课。"},
"squeeze":{"e":"Somehow the moving crew managed to squeeze the enormous sofa through the narrow stairwell without scratching the freshly painted walls.","t":"搬家师傅们不知怎的就把那张巨大的沙发**挤**过了狭窄的楼梯间，还没刮花刚刷好的墙面。"},
"lengthen":{"e":"As autumn approached, the shadows lengthened noticeably each evening, and the farmers hurried to finish the harvest before the first frost.","t":"随着秋天临近，每天傍晚的阴影都明显**变长**，农民们赶紧在第一场霜冻来临前收完庄稼。"},
"atrophy":{"e":"Months in a cast left his calf muscle in a state of noticeable atrophy, thinner and weaker than the uninjured leg.","t":"打了几个月石膏后，他的小腿肌肉明显**萎缩**，比没受伤的那条腿更细更无力。"},
"employ":{"e":"The restaurant chose to employ only local farmers as suppliers, insisting that freshness mattered more than lower prices from distant wholesalers.","t":"这家餐厅坚持只**雇用**当地农民作为供应商，认为新鲜度比远方批发商的低价更重要。"},
"coil":{"e":"The electrician carefully coiled the excess cable around her forearm before tucking it neatly into the toolbox for the next job.","t":"电工小心地把多余的电缆**盘绕**在前臂上，然后整齐地收进工具箱，留给下一项工作用。"},
"applicant":{"e":"Out of nearly two hundred applicants, the hiring committee invited only six for a second round of interviews next week.","t":"在将近两百名**申请者**中，招聘委员会只邀请了六人参加下周的第二轮面试。"},
"gourd":{"e":"Farmers along the river dried hollowed-out gourds in the sun and used them as lightweight containers for carrying water.","t":"河边的农民把掏空的**葫芦**晒干，用它们做轻便的容器来盛水。"},
"concern":{"e":"The pediatrician's report concerned the parents deeply, since the test results suggested a condition none of the family had ever faced.","t":"儿科医生的报告让父母十分**担忧**，因为检测结果显示的这种病症，家里此前从未有人遇到过。"},
"mechanize":{"e":"Once the textile mill was mechanized, output tripled within a year, though hundreds of hand weavers lost their jobs.","t":"这家纺织厂**实现机械化**之后，产量在一年内翻了三倍，但数百名手工织工却因此失业。"},
"harmony":{"e":"The choir director spent an entire rehearsal fixing one chord, insisting the four voice parts had to blend in perfect harmony.","t":"合唱指挥花了整整一次排练来纠正一个和弦，坚持要求四个声部必须完美**和谐**地融合在一起。"},
"theoretical":{"e":"The professor's theoretical model predicted the bridge would hold twice its rated load, but engineers still insisted on physical testing.","t":"教授的**理论**模型预测这座桥能承受额定荷载的两倍，但工程师们仍坚持要进行实体测试。"},
"huddle":{"e":"Shivering penguins huddled together against the wind, each bird taking turns at the freezing outer edge of the group.","t":"瑟瑟发抖的企鹅们为抵御寒风而**挤作一团**，每只企鹅轮流站在寒冷的外围。"},
"overlook":{"e":"The terrace overlooked the entire bay, giving guests a sweeping view of the harbor lights as the sun went down.","t":"露台**俯瞰**整个海湾，让客人在日落时分能将港口的灯光尽收眼底。"},
"textile":{"e":"The museum's new wing displays centuries-old textiles, their dyes still vivid despite hundreds of years folded away in storage.","t":"博物馆新展厅展出了几百年历史的**纺织品**，尽管在库房里叠放了数百年，染色依然鲜艳。"},
"ratio":{"e":"The recipe calls for a precise ratio of flour to butter, and even a slight imbalance will ruin the pastry's texture.","t":"这份食谱要求面粉和黄油保持精确的**比例**，哪怕稍有失衡都会毁掉糕点的口感。"},
"idle":{"e":"The factory's machines sat idle for nearly a month while managers waited for a replacement part stuck in customs.","t":"工厂的机器**闲置**了将近一个月，因为管理层一直在等一个卡在海关的替换零件。"},
"execute":{"e":"The gymnast executed the entire routine without a single wobble, landing the final dismount as cleanly as she had in practice.","t":"这位体操运动员**完成**整套动作时没有一丝晃动，最后的落地动作也和训练时一样干净利落。"},
"shortage":{"e":"A severe shortage of nurses forced the hospital to cancel elective surgeries and reroute ambulances to facilities two counties away.","t":"护士的严重**短缺**迫使医院取消了择期手术，并把救护车改道送往两个县以外的医疗机构。"},
"existence":{"e":"The rebels lived a precarious existence deep in the mountains, moving camp every few weeks to avoid detection by patrols.","t":"叛军在深山中过着朝不保夕的**生存**状态，每隔几周就转移营地以躲避巡逻队的侦察。"},
"influential":{"e":"Her essay on climate policy became so influential that three senators cited it directly during the committee hearing.","t":"她那篇关于气候政策的文章**极具影响力**，以至于三位参议员在委员会听证会上直接引用了它。"},
"contemporary":{"e":"The gallery's newest exhibit pairs Renaissance portraits with contemporary paintings, inviting visitors to compare techniques separated by five centuries.","t":"画廊最新的展览把文艺复兴时期的肖像画与**当代**绘画并列展出，邀请观众比较相隔五个世纪的技法。"},
"wagon":{"e":"Pioneers packed their entire households onto a single wagon, hoping the wheels would survive the long journey west.","t":"拓荒者把全部家当都装上一辆**马车**，希望这些车轮能撑过这段漫长的西行旅程。"},
"profile":{"e":"The magazine ran a lengthy profile of the young violinist, tracing her journey from a small-town recital to international acclaim.","t":"这家杂志刊登了一篇关于这位年轻小提琴家的长篇**人物简介**，追溯她从小镇演奏会走向国际赞誉的历程。"},
"adjust":{"e":"The pilot had to adjust the flaps repeatedly as turbulence buffeted the small aircraft during its descent into the valley airport.","t":"飞机在下降进入山谷机场时不断遭遇气流颠簸，飞行员不得不反复**调整**襟翼。"},
"obituary":{"e":"The local newspaper's obituary praised the retired teacher for four decades of quietly mentoring students who struggled the most.","t":"当地报纸的**讣告**赞扬了这位退休教师默默辅导最困难学生长达四十年的贡献。"},
"bilateral":{"e":"The two nations signed a bilateral agreement to reduce tariffs on agricultural goods crossing their shared border each year.","t":"两国签署了一项**双边**协议，降低每年跨越共同边境的农产品关税。"},
"racism":{"e":"The documentary exposed the systemic racism embedded in housing policies that had denied loans to entire neighborhoods for decades.","t":"这部纪录片揭露了住房政策中根深蒂固的系统性**种族主义**，数十年来它一直拒绝向整片街区发放贷款。"},
"smirk":{"e":"He smirked as he revealed the winning card, clearly enjoying the shocked silence that fell over the poker table.","t":"他亮出获胜的那张牌时**得意地笑了**，显然很享受整张牌桌陷入震惊沉默的那一刻。"},
"trample":{"e":"The crowd surged forward so violently that several fans were trampled underfoot before security could pull them to safety.","t":"人群猛烈地向前涌动，好几名粉丝被**踩踏**在脚下，安保人员才把他们拉到安全地带。"},
"zigzag":{"e":"The rabbit zigzagged desperately across the field, narrowly dodging the fox's jaws with each sudden change of direction.","t":"兔子在田野上拼命**曲折奔跑**，每一次突然转向都堪堪躲开狐狸的利齿。"},
"deploy":{"e":"Commanders deployed an extra battalion along the eastern ridge overnight, anticipating an attack before sunrise the following morning.","t":"指挥官连夜在东侧山脊**部署**了一个增援营，预计第二天日出前会遭到攻击。"},
"memorize":{"e":"Before the recital, she memorized all forty pages of the concerto so thoroughly that she could play it without glancing at the sheet music.","t":"在演奏会之前，她把这首协奏曲整整四十页都**背熟**了，弹奏时完全不用看乐谱。"},
"stereotype":{"e":"The film deliberately subverted the stereotype of the clumsy sidekick, giving the character sharp wit and genuine emotional depth instead.","t":"这部电影刻意颠覆了\"笨拙配角\"的**刻板印象**，反而赋予这个角色犀利的机智和真挚的情感深度。"},
"invert":{"e":"The photographer inverted the negative by accident, printing an eerie image where every shadow appeared as pure white light.","t":"摄影师不小心把底片**颠倒**了，冲印出一张诡异的照片，每一处阴影都变成了纯白的光。"},
"obscene":{"e":"Critics called the executive's bonus obscene, noting that it exceeded the combined annual salaries of every factory worker he employed.","t":"批评者称这位高管的奖金**骇人听闻**，指出它超过了他手下所有工厂工人年薪的总和。"},
"wedge-shaped":{"e":"Engineers designed the building's wedge-shaped foundation to deflect the force of floodwater away from the vulnerable eastern wall.","t":"工程师把这栋建筑的地基设计成**楔形**，以便将洪水的冲击力从脆弱的东墙分流开。"},
"semantic":{"e":"The linguist argued that the dispute was purely semantic, since both sides actually agreed on the underlying policy itself.","t":"这位语言学家认为，这场争论纯粹是**语义**上的，因为双方实际上在政策本身上是一致的。"},
"preach":{"e":"The retired athlete now travels to schools, preaching the value of discipline to teenagers who idolize quick, easy success.","t":"这位退役运动员如今四处走访学校，向那些崇拜速成、轻易成功的青少年**宣讲**自律的价值。"},
"readability":{"e":"The editor rewrote every long, tangled sentence in the report, dramatically improving its readability for busy executives skimming on their phones.","t":"编辑重写了报告里每一个冗长纠结的句子，大幅提升了它的**可读性**，方便忙碌的高管用手机快速浏览。"},
"moderate":{"e":"The nutritionist recommended moderate portions of red meat each week rather than eliminating it entirely from his diet.","t":"营养师建议他每周吃**适量**的红肉，而不是从饮食中完全剔除。"},
"poverty":{"e":"Generations of poverty in the region left many families unable to afford even basic schoolbooks for their children.","t":"这个地区世代的**贫困**使许多家庭连基本的课本都买不起给孩子。"},
"sanitation":{"e":"Poor sanitation in the refugee camp led to a rapid spread of cholera before aid workers installed proper latrines.","t":"难民营**卫生设施**匮乏导致霍乱迅速蔓延，直到救援人员安装了合适的厕所才得以控制。"},
"tantalizing":{"e":"The bakery's window displayed a tantalizing row of pastries, and passersby kept stopping despite having no intention of buying anything.","t":"面包店的橱窗里摆着一排**诱人**的糕点，尽管根本没打算买，路人还是不断停下脚步。"},
"minor":{"e":"The contractor dismissed the crack in the foundation as a minor issue, though the inspector later deemed it structurally serious.","t":"承包商认为地基上的裂缝只是**次要**问题，但后来检查员却认定这在结构上很严重。"},
"coupon":{"e":"She clipped a stack of coupons from the Sunday paper, saving nearly thirty dollars on groceries at the checkout counter.","t":"她从周日的报纸上剪下一沓**优惠券**，结账时在杂货上省了将近三十美元。"},
"base":{"e":"The novelist based her latest thriller on a real unsolved kidnapping case from the nineteen seventies, changing only the victims' names.","t":"这位小说家把她最新的惊悚小说**基于**一桩上世纪七十年代真实的悬案绑架案，只改动了受害者的姓名。"},
"synchronize":{"e":"The dancers spent hours synchronizing their movements to the beat, until even the slightest hand gesture landed exactly together.","t":"舞者们花了几个小时让动作与节拍**同步**，直到连最细微的手势都能完全整齐划一。"},
"cafeteria":{"e":"Students crowded into the cafeteria at noon, balancing trays as they searched for an empty table near the windows.","t":"学生们中午挤进**自助食堂**，端着托盘四处寻找靠窗的空桌子。"},
"powder":{"e":"The chemist ground the crystals into a fine powder, then dissolved a small measured amount in distilled water for the experiment.","t":"化学家把这些晶体磨成了细**粉末**，然后取少量精确称量后溶解在蒸馏水中用于实验。"},
"devote":{"e":"She devoted every weekend for three years to restoring the abandoned chapel, sanding each pew by hand herself.","t":"她连续三年把每个周末都**投入**到修复这座废弃小教堂上，亲手打磨每一条长椅。"},
"monopoly":{"e":"The railroad company held a near-total monopoly on shipping in the region, allowing it to set prices however it wished.","t":"这家铁路公司在该地区几乎完全**垄断**了运输业务，因此可以随心所欲地定价。"},
"opponent":{"e":"The senator's fiercest opponent in the debate turned out to be a former ally who had grown disillusioned with the party.","t":"这场辩论中参议员最凶猛的**对手**，竟然是一位早已对本党心灰意冷的昔日盟友。"},
"idyllic":{"e":"Their honeymoon photos showed an idyllic cottage by the lake, with wildflowers spilling across the porch steps.","t":"他们的蜜月照片展示了一座湖边**田园诗般**的小屋，野花漫过门廊的台阶。"},
"constituent":{"e":"The congresswoman held a town hall every month so her constituents could raise concerns about roads, schools, and local taxes.","t":"这位女议员每月都召开一次市政厅会议，好让她的**选民**能就道路、学校和地方税收提出诉求。"},
"genesis":{"e":"Historians trace the genesis of the labor movement to a series of strikes in the textile mills of Lowell.","t":"历史学家把劳工运动的**起源**追溯到洛厄尔纺织厂的一系列罢工事件。"},
"convex":{"e":"The mirror's convex surface let the driver see traffic approaching from both directions of the otherwise blind intersection.","t":"这面镜子的**凸面**让司机能看到原本视线盲区的十字路口两个方向驶来的车辆。"},
"distinctive":{"e":"The chef's distinctive use of smoked paprika gave every dish a flavor customers could instantly recognize as hers alone.","t":"主厨对烟熏红椒粉**别具特色**的运用，让每道菜都带有顾客能立刻辨认出的独特风味。"},
"enlightenment":{"e":"Reading the philosopher's letters brought her a quiet sense of enlightenment about questions she had wrestled with for years.","t":"阅读这位哲学家的信件让她对多年来一直苦苦思索的问题获得了一种平静的**启迪**。"},
"facial":{"e":"The actor's facial expressions conveyed more grief in that silent close-up than any line of dialogue could have managed.","t":"在那个无声的特写镜头里，演员的**面部**表情所传达的悲伤，比任何台词都更有力。"},
"medium":{"e":"The artist chose watercolor as her primary medium, valuing the way the pigments bled unpredictably across the damp paper.","t":"这位艺术家选择水彩作为她主要的创作**媒介**，喜欢颜料在湿润纸面上难以预料地晕染开来的效果。"},
"drain":{"e":"Caring for three sick children single-handedly drained every ounce of energy she had left by the end of the week.","t":"独自照顾三个生病的孩子，到周末时已经**耗尽**了她所剩的每一分精力。"},
"require":{"e":"The visa application requires proof of employment, a bank statement, and a letter explaining the purpose of the trip.","t":"这份签证申请**需要**提供就业证明、银行对账单，以及一封说明出行目的的信。"},
"diplomatic":{"e":"Even when guests argued loudly at dinner, the hostess remained diplomatic, steering the conversation toward safer topics without anyone noticing.","t":"即使客人在晚宴上大声争论，女主人依然表现得十分**老练圆滑**，不动声色地把话题引向更安全的方向。"},
"oral":{"e":"Before the written exam, every candidate had to pass a grueling oral interview conducted entirely in the foreign language.","t":"在笔试之前，每位考生都必须通过一场完全用外语进行的艰苦**口头**面试。"},
"braid":{"e":"Her grandmother braided her hair every morning before school, weaving in a thin ribbon that matched her uniform.","t":"每天上学前，祖母都会给她**编**头发，还会编进一根与校服颜色相配的细丝带。"},
"daisy":{"e":"Wild daisies covered the meadow so thickly that from a distance the entire field looked dusted with fresh snow.","t":"野生**雏菊**密密麻麻地铺满了草地，从远处看整片田野就像撒了一层新雪。"},
"epic":{"e":"The team's comeback from a twenty-point deficit became an epic tale that fans would retell for decades afterward.","t":"这支球队从落后二十分中逆转取胜，成了一段球迷此后几十年都会反复讲述的**史诗般**的传奇。"},
"catalog":{"e":"She flipped through the seed catalog for hours, circling every variety of tomato she wanted to plant next spring.","t":"她翻阅种子**目录**好几个小时，圈出了每一个她想在明年春天种植的番茄品种。"},
"muscle":{"e":"Years of rowing had built dense muscle across his shoulders, visible even through the loose fabric of his jacket.","t":"多年划船练就了他肩部厚实的**肌肉**，即使隔着宽松的外套也能看得出来。"},
"ooze":{"e":"Thick sap oozed slowly from the cut in the pine bark, hardening into amber-colored beads by the following afternoon.","t":"浓稠的树脂从松树皮的切口缓缓**渗出**，到第二天下午已凝固成琥珀色的小珠。"},
"individual":{"e":"The therapist treated each patient as a unique individual, refusing to apply the same rigid treatment plan to everyone.","t":"治疗师把每位病人都当作独特的**个体**来对待，拒绝对所有人套用同一套僵化的治疗方案。"},
"chew":{"e":"The old dog chewed the leather bone slowly in the corner, seemingly content to make it last the entire afternoon.","t":"老狗在角落里慢慢**咀嚼**着那根皮骨头，似乎很满足能让它撑过整个下午。"},
"withstand":{"e":"The ancient sea wall had withstood centuries of pounding waves before a single unusually violent storm finally cracked it.","t":"这座古老的海堤**经受住**了几个世纪海浪的猛烈拍打，直到一场异常猛烈的风暴才最终使它开裂。"},
"apartment":{"e":"After months of searching, they finally found an apartment with enough natural light to keep their houseplants alive through winter.","t":"经过几个月的寻找，他们终于找到一间光照充足的**公寓**，足以让室内植物撑过整个冬天。"},
"porous":{"e":"The volcanic rock was so porous that rainwater seeped straight through it instead of pooling on the surface.","t":"这种火山岩**多孔**得连雨水都会直接渗透过去，而不会在表面积水。"},
"relevant":{"e":"The lawyer objected that the witness's childhood memories were not relevant to whether the contract had actually been signed.","t":"律师提出异议，认为证人的童年记忆与合同是否真的被签署并**无关**。"},
"through":{"e":"After the third rewrite, the editor was finally through with the manuscript and sent it straight to the printer.","t":"改了三遍之后，编辑终于**弄完**了这份稿子，直接把它送去了印刷厂。"},
"vacancy":{"e":"The motel's flickering sign advertised a vacancy, so the exhausted travelers pulled into the lot just before midnight.","t":"汽车旅馆闪烁的招牌上写着有**空房**，疲惫的旅客便在午夜前把车开进了停车场。"},
"dimensional":{"e":"The architect's new software rendered the blueprint as a fully dimensional model that clients could rotate and examine from any angle.","t":"建筑师的新软件把蓝图渲染成了一个完全立体**维度**化的模型，客户可以从任意角度旋转查看。"},
"crazy":{"e":"Friends thought it was crazy to quit a stable job for an unproven startup, but she never once regretted the leap.","t":"朋友们都觉得辞掉稳定工作去做一家前景未卜的初创公司很**疯狂**，但她从未后悔过这次跳跃。"},
"sidebar":{"e":"The newspaper ran a short sidebar next to the main article, listing five facts most readers had never heard about the disease.","t":"报纸在主文章旁边刊登了一则简短的**补充报道**，列出了大多数读者从未听说过的关于这种疾病的五个事实。"},
"drowsy":{"e":"The warm classroom and the professor's monotone voice made even the most attentive students feel drowsy by the second hour.","t":"温暖的教室加上教授单调的语调，让即使最专注的学生到第二个小时也感到**昏昏欲睡**。"},
"ridge":{"e":"The trail followed a narrow ridge for two miles, with steep drops falling away on both sides of the path.","t":"这条小径沿着一道狭窄的**山脊**延伸了两英里，路两侧都是陡峭的悬崖。"},
"bonanza":{"e":"The unexpected tourist boom turned out to be a bonanza for local restaurant owners who had struggled through years of slow business.","t":"这场意外的旅游热潮对当地苦苦挣扎多年的餐馆老板来说，成了一笔**意外之财**。"},
"alike":{"e":"The twins dressed alike well into their thirties, a habit their mother had started when they were toddlers.","t":"这对双胞胎直到三十多岁穿着依然**一模一样**，这个习惯是母亲从他们蹒跚学步时就养成的。"},
"pedagogy":{"e":"The new pedagogy emphasized hands-on projects over memorized facts, a shift that many veteran teachers initially resisted.","t":"这种新的**教学法**强调动手实践项目而非死记硬背，许多资深教师起初对此转变颇为抵触。"},
"material":{"e":"The sculptor searched junkyards for scrap metal, believing the most interesting material was whatever everyone else had already discarded.","t":"这位雕塑家在废品场里翻找废金属，相信最有趣的**材料**正是别人已经丢弃的东西。"},
"dot":{"e":"Small fishing boats dotted the harbor at dawn, their lanterns still glowing faintly against the gray morning light.","t":"黎明时分，小渔船**星罗棋布**地散布在港湾里，灯笼在灰蒙蒙的晨光中依然微微发亮。"},
"habitat":{"e":"Deforestation has shrunk the panda's natural habitat so severely that isolated populations can no longer find each other to breed.","t":"森林砍伐严重压缩了熊猫的自然**栖息地**，以至于被隔离的种群再也无法相遇繁殖。"},
"educated":{"e":"The scholarship program specifically targets first-generation students who would otherwise never become the first educated member of their family.","t":"这项奖学金计划专门面向家中第一代大学生，否则他们本不会成为家族中第一个**受过教育**的成员。"},
"accuse":{"e":"The union accused the factory of ignoring repeated safety complaints in the months leading up to the fatal accident.","t":"工会**指控**这家工厂在致命事故发生前的几个月里，一直无视多次提出的安全投诉。"},
"reckless":{"e":"The judge cited his reckless driving through three school zones as the reason for suspending his license immediately.","t":"法官以他**鲁莽**地驾车穿过三个校园区为由，立即吊销了他的驾照。"},
"rendition":{"e":"Her haunting rendition of the folk ballad silenced the entire coffeehouse, leaving even the baristas standing still to listen.","t":"她对那首民谣哀婉动人的**演唱**让整个咖啡馆都安静下来，连咖啡师都停下手来聆听。"},
"drift":{"e":"The empty canoe drifted slowly downstream, spinning gently in the current until it caught on a fallen branch.","t":"那艘空独木舟缓缓**漂流**而下，在水流中轻轻打转，直到被一根倒下的树枝挂住。"},
"haven":{"e":"For refugees fleeing the civil war, the small border town became an unlikely haven where aid workers offered food and shelter.","t":"对于逃离内战的难民来说，这座边境小镇意外地成了一个**避难所**，救援人员在那里提供食物和住所。"},
"slogan":{"e":"The campaign's slogan appeared on every bus stop in the city, repeated so often that even toddlers could recite it.","t":"这场竞选活动的**口号**出现在城里每一个公交站，反复出现到连幼儿都能背出来。"},
"affinity":{"e":"From an early age, she showed a natural affinity for numbers, solving puzzles that stumped children twice her age.","t":"她从小就对数字表现出天生的**喜爱**，能解开让年龄比她大一倍的孩子都束手无策的谜题。"},
"stun":{"e":"The verdict stunned the courtroom into silence, and even the defense attorney seemed unable to process what he had just heard.","t":"这个判决让整个法庭陷入**震惊**的沉默，连辩护律师似乎都无法消化自己刚刚听到的结果。"},
"comparative":{"e":"After years of famine, the village enjoyed a period of comparative prosperity once the new irrigation canal finally reached its fields.","t":"经历多年饥荒后，新灌溉渠终于引到田地，这个村庄迎来了一段**相对**繁荣的时期。"},
"fulfill":{"e":"Winning the scholarship finally allowed her to fulfill the dream of studying architecture that her parents once thought impossible.","t":"赢得这份奖学金终于让她**实现**了学习建筑学的梦想，而这在父母眼中曾经是不可能的事。"},
"paste":{"e":"The children pasted colorful scraps of tissue paper onto cardboard, creating a mosaic mural for the classroom wall.","t":"孩子们把彩色的薄纸碎片**粘贴**到硬纸板上，为教室墙壁制作了一幅马赛克壁画。"},
"scandal":{"e":"The corruption scandal forced three city officials to resign within a single week after journalists exposed the bribery scheme.","t":"这起腐败**丑闻**导致三名市政官员在记者揭露受贿方案后的一周内相继辞职。"},
"inactivate":{"e":"Heating the vaccine sample to a precise temperature inactivates the virus while leaving enough structure for the immune system to recognize.","t":"将疫苗样本加热到精确温度能**使病毒失去活性**，同时保留足够的结构供免疫系统识别。"},
"explode":{"e":"The city's population exploded after the tech company opened its headquarters there, doubling in size within just five years.","t":"这家科技公司在此设立总部后，这座城市的人口**激增**，短短五年内规模翻了一倍。"},
"utility":{"e":"Engineers questioned the utility of the added feature, since customer surveys showed almost no one ever used it.","t":"工程师们质疑这项新增功能的**实用性**，因为客户调查显示几乎没有人使用过它。"},
"filter":{"e":"The plant's roots filter heavy metals from the contaminated soil, slowly making the abandoned lot safe for future planting.","t":"这种植物的根系能**过滤**掉受污染土壤中的重金属，慢慢让这片废弃地重新变得适合种植。"},
"receptive":{"e":"Unlike her predecessor, the new manager proved remarkably receptive to feedback, adjusting the schedule the same week employees complained.","t":"与她的前任不同，这位新经理表现得异常**乐于接受**反馈，员工抱怨的当周就调整了排班。"},
"donate":{"e":"After the flood destroyed hundreds of homes, strangers across the country donated blankets, canned food, and bottled water within days.","t":"洪水摧毁了数百户人家之后，全国各地的陌生人在短短几天内就**捐赠**了毛毯、罐头食品和瓶装水。"},
"riddle":{"e":"The old man posed a riddle to every child who visited, promising a piece of candy to whoever solved it first.","t":"老人给每个来访的孩子出一个**谜语**，承诺谁先猜出来就给谁一块糖。"},
"schematic":{"e":"The engineer sketched a schematic diagram of the circuit on a napkin, labeling every resistor before the meeting even started.","t":"工程师在餐巾纸上画了一张电路的**图解**示意图，会议还没开始就已经标注好了每个电阻。"},
"pottery":{"e":"She spent every Saturday morning at the studio, shaping pottery on the wheel until her hands ached from the wet clay.","t":"她每周六早上都在工作室里度过，在轮盘上塑造**陶器**，直到双手因湿黏土而酸痛。"},
"acquit":{"e":"After deliberating for only two hours, the jury acquitted the defendant of all charges, citing a complete lack of physical evidence.","t":"陪审团只商议了两个小时，就以完全缺乏物证为由将被告**宣判无罪**。"},
"discount":{"e":"The store discounted all winter coats by forty percent the moment the first warm day of March arrived.","t":"三月第一个暖和的日子一到，这家商店就把所有冬季外套**打折**四成出售。"},
"semiotics":{"e":"Her thesis applied semiotics to advertising, examining how a single color could shift the meaning viewers assigned to a brand.","t":"她的论文将**符号学**应用于广告研究，探讨单单一种颜色如何改变观众赋予某个品牌的含义。"},
"subscribe":{"e":"Thousands of readers subscribed to the newsletter within its first week, drawn by the promise of unbiased local reporting.","t":"数千名读者在这份新闻通讯发布的第一周就**订阅**了它，被其承诺的公正本地报道所吸引。"},
"verbalize":{"e":"The counselor encouraged him to verbalize his frustration instead of letting it build silently until it exploded at home.","t":"辅导员鼓励他把心中的沮丧**用言语表达**出来，而不是让它默默积累直到在家里爆发。"},
"align":{"e":"The manager spent the retreat trying to align every department's goals with the company's new five-year strategic plan.","t":"经理在这次静修活动中努力把每个部门的目标与公司新的五年战略计划**保持一致**。"},
"purchase":{"e":"The museum purchased the rare manuscript at auction for nearly two million dollars, outbidding three private collectors.","t":"这家博物馆在拍卖会上以近两百万美元**购得**这份珍贵手稿，击败了三位私人收藏家。"},
"syntactic":{"e":"The linguistics paper analyzed the syntactic structure of the sentence, showing how word order alone changed its entire meaning.","t":"这篇语言学论文分析了这个句子的**句法**结构，展示了仅仅语序就能改变整个句意。"},
"verbiage":{"e":"The contract's dense verbiage buried a single crucial clause that most tenants never noticed until it was too late.","t":"这份合同冗长的**赘言**掩盖了一条关键条款，大多数租客直到为时已晚才注意到它。"},
"drag":{"e":"Exhausted after the storm, the sailors dragged the torn sail across the deck toward the repair station belowdecks.","t":"经历风暴后筋疲力尽的水手们把撕裂的帆**拖过**甲板，送往下层的维修站。"},
"rhyme":{"e":"The songwriter spent an entire afternoon searching for a word that would rhyme naturally with 'orange' and finally gave up.","t":"这位词曲作者花了整整一个下午寻找能与\"orange\"自然**押韵**的词，最终还是放弃了。"},
"given":{"e":"Within a given time frame, each team had to design, build, and test a working bridge made entirely of spaghetti.","t":"在**特定**的时间范围内，每个团队都必须设计、搭建并测试一座完全用意大利面做成的可用桥梁。"},
"periodical":{"e":"The library's rare periodical collection includes literary magazines that stopped printing more than a century ago.","t":"图书馆珍贵的**期刊**收藏中包括一些一个多世纪前就已停刊的文学杂志。"},
"endow":{"e":"Nature seemed to have endowed the young pianist with perfect pitch, a gift her teachers noticed the very first lesson.","t":"大自然似乎天生就**赋予**了这位年轻钢琴家完美音准，她的老师在第一堂课就注意到了这份天赋。"},
"offspring":{"e":"The female sea turtle returns to the same beach every few years, burying her offspring's eggs deep in the warm sand.","t":"这只雌海龟每隔几年就会回到同一片海滩，把**后代**的卵深深埋进温暖的沙子里。"},
"suburb":{"e":"Rising rents downtown pushed many young families out to the suburbs, where houses were larger and considerably cheaper.","t":"市中心不断上涨的房租把许多年轻家庭挤到了**郊区**，那里的房子更大，价格也便宜得多。"},
"evaporation":{"e":"The scientist measured the rate of evaporation from the shallow dish every hour to see how humidity affected the process.","t":"科学家每小时测量一次浅盘中水的**蒸发**速率，以观察湿度对这一过程的影响。"},
"bony":{"e":"The stray dog's bony frame and matted fur told the shelter workers he had been wandering the streets for weeks.","t":"这只流浪狗**瘦骨嶙峋**的身躯和打结的毛发，让收容所的工作人员看出它已经在街头游荡了好几周。"},
"polar":{"e":"Melting polar ice caps have raised sea levels enough to threaten coastal cities that sit only a few feet above the tide.","t":"**极地**冰盖的融化已经使海平面上升到足以威胁那些仅高出潮位几英尺的沿海城市。"},
"compose":{"e":"The composer composed the entire symphony in a single feverish month, rarely leaving his apartment except to buy more manuscript paper.","t":"这位作曲家在一个月的狂热创作中**谱写**完了整部交响曲，除了买更多的乐谱纸几乎足不出户。"},
"debate":{"e":"Historians still debate whether the treaty actually prevented war or merely postponed a conflict that had already become inevitable.","t":"历史学家至今仍在**争论**，这项条约究竟是真的避免了战争，还是只是推迟了一场早已不可避免的冲突。"},
"integrate":{"e":"The district worked for years to integrate students from the two rival schools smoothly after the controversial merger was announced.","t":"这项有争议的合并宣布之后，学区花了多年时间努力让两所对立学校的学生顺利**融合**在一起。"},
"simile":{"e":"The poet compared grief to a stone in the chest, a simile so simple that every reader instantly understood the weight she meant.","t":"诗人把悲伤比作胸口的一块石头，这个**明喻**如此简单，以至于每位读者都立刻理解了她所说的那种沉重。"},
"decent":{"e":"After years of temporary gigs, he finally landed a decent job with health insurance and a predictable paycheck every month.","t":"打了多年零工之后，他终于找到一份**体面**的工作，有医疗保险，每月还有稳定的薪水。"},
"rug":{"e":"A faded rug covered the worn floorboards in the center of the room, muffling footsteps whenever someone crossed the living room.","t":"一块褪色的**地毯**铺在房间中央磨损的地板上，每当有人穿过客厅，脚步声都会被它闷住。"},
"complacence":{"e":"The coach warned that early-season victories often breed a dangerous complacence that costs teams their focus later in the playoffs.","t":"教练警告说，赛季初的胜利常常滋生危险的**自满**情绪，导致球队在季后赛后期失去专注力。"},
"unbridgeable":{"e":"The two negotiating teams eventually admitted that their differences over territory were simply unbridgeable and ended the talks entirely.","t":"两个谈判团队最终承认，他们在领土问题上的分歧根本**无法逾越**，谈判也就此彻底终止。"},
"quote":{"e":"The professor loved to quote obscure poets mid-lecture, sending half the class scrambling to write down names they had never heard.","t":"这位教授喜欢在讲课中途**引用**一些冷门诗人的话，让半个班的学生手忙脚乱地记下从未听过的名字。"},
"immigrant":{"e":"Her grandparents arrived as immigrants with only a few coins in their pockets, unable to speak a word of the local language.","t":"她的祖父母作为**移民**抵达时口袋里只有几枚硬币，一句当地语言都不会说。"},
"asteroid":{"e":"Astronomers tracked the asteroid's trajectory for months, calculating that it would pass safely beyond the moon's orbit.","t":"天文学家追踪这颗**小行星**的轨迹长达数月，计算出它将安全地从月球轨道之外经过。"},
"haste":{"e":"In her haste to catch the departing train, she left her laptop charger plugged into the wall of the hotel room.","t":"由于**匆忙**赶那趟即将出发的火车，她把笔记本电脑充电器落在了酒店房间的墙插座上。"},
"suitcase":{"e":"He packed his suitcase the night before, folding each shirt carefully so nothing would wrinkle during the long flight abroad.","t":"他前一晚就收拾好了**手提箱**，小心翼翼地叠好每件衬衫，免得在漫长的国际航班上起皱。"},
"translation":{"e":"The new translation captured the novel's dark humor far better than the stiff, overly literal version published decades earlier.","t":"这个新**译本**对小说黑色幽默的捕捉，远胜于几十年前出版的那个生硬、过分直译的版本。"},
"meantime":{"e":"The repair crew ordered the replacement part from a distant supplier; in the meantime, residents had to boil their water before drinking it.","t":"维修队从一家远方供应商那里订购了替换零件；**与此同时**，居民们只能先把水煮沸才能饮用。"},
"senate":{"e":"The bill passed the House easily but stalled in the senate, where two committee chairs refused to schedule a vote.","t":"这项法案在众议院轻松通过，却在**参议院**卡住，因为两位委员会主席拒绝安排投票。"},
"chance":{"e":"The understudy finally got her chance to perform the lead role when the star actress came down with laryngitis backstage.","t":"当台上的明星女演员突然喉炎发作时，替补演员终于得到了她扮演主角的**机会**。"},
"overseas":{"e":"After graduation, she decided to study overseas for two years, choosing a small university in the Netherlands known for marine biology.","t":"毕业后，她决定去**海外**留学两年，选择了一所以海洋生物学闻名的荷兰小型大学。"},
"indispensable":{"e":"The old librarian had become so indispensable to the archive that no one could imagine the building running without her.","t":"这位老图书管理员对档案馆来说已经变得**必不可少**，没人能想象这栋楼离开她该如何运转。"},
"proceed":{"e":"Once the inspectors approved the blueprints, the construction crew was finally allowed to proceed with pouring the foundation.","t":"检查员批准蓝图之后，施工队终于获准**继续进行**地基的浇筑工作。"},
"alien":{"e":"The bureaucratic rules of the new country felt entirely alien to her, nothing like the informal system she had grown up with.","t":"这个新国家繁琐的官僚规则让她感到完全**陌生**，和她从小习惯的非正式体系毫无相似之处。"},
"proper":{"e":"Without the proper safety equipment, the technicians refused to enter the collapsed mine shaft, despite pressure from the company.","t":"没有**适当的**安全设备，技术人员拒绝进入那条已经坍塌的矿井，尽管公司施加了压力。"},
"sewage":{"e":"Untreated sewage flowing directly into the river forced the town to shut down its only public swimming beach for the summer.","t":"未经处理的**污水**直接流入河流，迫使该镇整个夏天都关闭了唯一的公共游泳海滩。"},
"residue":{"e":"After the wine evaporated from the pan, a sticky residue clung stubbornly to the bottom, resisting every attempt to scrub it away.","t":"酒液从锅中蒸发后，一层黏腻的**残留物**顽固地粘在锅底，怎么刷洗都去不掉。"},
"analysis":{"e":"Her careful analysis of the company's quarterly losses revealed a pattern of overspending that the executives had somehow overlooked for years.","t":"她对公司季度亏损所做的细致**分析**，揭示出高管们多年来一直忽视的过度支出模式。"},
"relative":{"e":"The relative calm of the small fishing village stood in sharp contrast to the chaos of the capital city we had just left.","t":"这座小渔村**相对的**宁静，与我们刚刚离开的首都的喧嚣混乱形成了鲜明对比。"},
"maximum":{"e":"The bridge's maximum load was clearly posted, yet the overloaded truck driver ignored the warning and crossed anyway.","t":"桥梁的**最大**承重量被清楚地标示出来，但那位超载的卡车司机无视警告，还是照样开了过去。"},
"poster":{"e":"A faded poster advertising last summer's music festival still hung crookedly on the brick wall behind the abandoned record shop.","t":"一张褪色的**海报**依然歪歪斜斜地挂在废弃唱片店后面的砖墙上，宣传着去年夏天的音乐节。"},
"fascinate":{"e":"The way octopuses can change color instantly to match their surroundings has fascinated marine biologists for generations.","t":"章鱼能够瞬间变色以融入周围环境的这种能力，让一代又一代的海洋生物学家为之**深深着迷**。"},
"stereo":{"e":"My uncle refused to throw out his ancient stereo, insisting that vinyl records sounded warmer through its huge wooden speakers.","t":"我叔叔拒绝扔掉他那台老旧的**立体声音响**，坚持认为黑胶唱片经过那对大木质音箱播放出来的声音更温暖。"},
"gin":{"e":"The bartender mixed the gin with a splash of tonic and a twist of lime before sliding the glass across the counter.","t":"调酒师把**杜松子酒**和一点汤力水、一片青柠皮混合调匀，然后把杯子推到吧台对面。"},
"confederacy":{"e":"Facing a common enemy, the scattered tribes formed a loose confederacy that allowed each village to keep its own chief.","t":"面对共同的敌人，分散的部落组成了一个松散的**联盟**，让每个村落都保留自己的首领。"},
"conservative":{"e":"Even after retiring, the old banker remained deeply conservative about money, refusing to invest in anything he didn't fully understand.","t":"即便退休之后，这位老银行家在金钱方面依然极为**保守**，拒绝投资任何他没有完全弄懂的东西。"},
"evoke":{"e":"The scent of cinnamon and pine instantly evoked memories of her grandmother's kitchen during the holidays.","t":"肉桂和松木的香气瞬间**唤起**了她对祖母节日厨房的种种回忆。"},
"receptor":{"e":"Certain nerve cells in the skin contain a receptor that responds only to sudden changes in temperature.","t":"皮肤中的某些神经细胞含有一种**受体**，只对温度的骤然变化做出反应。"},
"ability":{"e":"Despite his shyness, the young violinist possessed a remarkable ability to move an entire concert hall to tears.","t":"尽管性格腼腆，这位年轻的小提琴手却拥有让整个音乐厅观众落泪的非凡**才能**。"},
"brass":{"e":"During the parade's finale, the brass blared so loudly that the marching band drowned out the cheering crowd.","t":"在游行的最高潮，**铜管乐器**声浪震天，行进乐队的声音甚至盖过了欢呼的人群。"},
"gymnasium":{"e":"Every rainy afternoon, the students crowded into the gymnasium to practice basketball instead of running laps outside.","t":"每逢下雨的午后，学生们就挤进**体育馆**打篮球，而不是到室外跑圈。"},
"maize":{"e":"Generations of farmers in this valley have grown maize as their primary crop, rotating it with beans to keep the soil fertile.","t":"这个山谷里世世代代的农民都种植**玉米**作为主要作物，并与豆类轮作以保持土壤肥沃。"},
"magnesium":{"e":"Leafy green vegetables are rich in magnesium, a mineral the body needs to keep muscles and nerves functioning properly.","t":"绿叶蔬菜富含**镁**，这是身体维持肌肉与神经正常运作所必需的矿物质。"},
"disposal":{"e":"Proper disposal of the factory's chemical waste required special containers and a licensed crew trained to handle hazardous material.","t":"妥善**处理**这家工厂的化学废料，需要特殊容器和受过危险品处理培训的持证人员。"},
"annul":{"e":"The couple asked a judge to annul their marriage after discovering it had never been legally registered in the first place.","t":"这对夫妻请求法官**宣布他们的婚姻无效**，因为他们发现这段婚姻从一开始就没有合法登记过。"},
"mail":{"e":"Before leaving the post office, she double-checked the address and mailed the package to her brother stationed overseas.","t":"离开邮局前，她仔细核对了地址，把包裹**邮寄**给驻扎海外的弟弟。"},
"bill":{"e":"The senator spent months rallying support for the bill, which would finally guarantee paid leave to new parents nationwide.","t":"这位参议员花了数月时间争取支持这项**法案**，它将首次在全国范围内保障新生儿父母的带薪休假。"},
"enrich":{"e":"Spending a semester abroad enriched her understanding of cultures far beyond what any textbook could teach.","t":"出国交流一学期极大地**充实**了她对各种文化的理解，这是任何教科书都教不了的。"},
"march":{"e":"Thousands of workers joined the march downtown, demanding higher wages and safer conditions in the factories.","t":"数千名工人加入了市中心的**游行**，要求提高工资并改善工厂的安全条件。"},
"hormone":{"e":"A sudden drop in the hormone that regulates blood sugar can leave a person feeling shaky and disoriented within minutes.","t":"调节血糖的**激素**一旦骤然下降，会让人在几分钟内感到颤抖和神志不清。"},
"sapphire":{"e":"The museum's most prized exhibit was a flawless sapphire mined from a riverbed in Sri Lanka over a century ago.","t":"博物馆最珍贵的展品是一颗一个多世纪前从斯里兰卡河床开采出的完美无瑕的**蓝宝石**。"},
"hockey":{"e":"Growing up in Canada, she learned to skate almost before she could walk, and hockey quickly became her greatest passion.","t":"她在加拿大长大，几乎在会走路之前就学会了滑冰，**曲棍球**很快成了她最大的热爱。"},
"evaporate":{"e":"All his confidence evaporated the moment he stepped onto the stage and saw the size of the audience.","t":"他一踏上舞台看到观众规模的那一刻，全部的自信瞬间**消失**得无影无踪。"},
"linger":{"e":"The smell of burnt toast lingered in the kitchen for hours, no matter how many windows we opened.","t":"无论我们打开多少扇窗户，烤焦面包的气味都在厨房里**久久不散**。"},
"function":{"e":"Without regular maintenance, even the most advanced machinery will eventually stop functioning correctly under heavy daily use.","t":"若不定期维护，即便是最先进的机器，在高强度日常使用下也终将无法正常**运行**。"},
"troupe":{"e":"The traveling troupe performed Shakespeare in small towns across the countryside, setting up their makeshift stage in barns and village squares.","t":"这个巡回**剧团**在乡间的小镇上演莎士比亚戏剧，把临时舞台搭在谷仓和村庄广场里。"},
"enroll":{"e":"After months of saving, she finally enrolled in the culinary program she had dreamed about since high school.","t":"攒了几个月的钱之后，她终于**报名参加**了自己从高中起就梦寐以求的烹饪课程。"},
"confiscate":{"e":"Airport security confiscated the bottle of water at the checkpoint because it exceeded the permitted liquid limit.","t":"机场安检人员**没收**了那瓶水，因为它超出了允许携带的液体限量。"},
"concord":{"e":"After decades of border disputes, the two nations finally signed a treaty designed to restore lasting concord between their peoples.","t":"在经历了数十年的边境争端后，两国终于签署了一项条约，旨在恢复两国人民之间持久的**和睦**。"},
"brighten":{"e":"Her whole face brightened the instant she spotted her father waiting anxiously at the crowded airport arrival gate.","t":"她一看到父亲焦急地在拥挤的机场到达口等候，整张脸瞬间**明亮**了起来。"},
"vascular":{"e":"Years of untreated high blood pressure had left the patient with serious vascular damage throughout his legs and kidneys.","t":"多年未经治疗的高血压使这位病人的腿部和肾脏都出现了严重的**血管**损伤。"},
"aristocratic":{"e":"She carried herself with an aristocratic poise that made strangers assume she had grown up in a palace.","t":"她举止间透着一种**贵族**气派的沉稳，让陌生人都以为她是在宫殿里长大的。"},
"fracture":{"e":"The X-ray revealed a hairline fracture in her wrist, small enough that she had almost mistaken it for a bad sprain.","t":"X光片显示她的手腕上有一处细微的**骨折**，小到她差点把它误认为是严重扭伤。"},
"decree":{"e":"The king decreed that all taxes on bread be suspended during the famine that had gripped the countryside.","t":"国王**颁布法令**，在饥荒肆虐乡村期间暂停征收面包税。"},
"scarf":{"e":"She wrapped the wool scarf twice around her neck before stepping out into the biting winter wind.","t":"她把羊毛**围巾**在脖子上绕了两圈，才走进刺骨的冬风中。"},
"authoritative":{"e":"Critics regard her biography of the poet as the most authoritative account, drawing on letters no previous scholar had examined.","t":"评论家认为她为这位诗人写的传记是最具**权威性**的版本，因为她引用了此前任何学者都未曾查阅过的信件。"},
"autonomous":{"e":"The region was granted autonomous status, allowing local leaders to set their own tax policies without approval from the capital.","t":"该地区获得了**自治**地位，当地领导人无需首都批准即可自行制定税收政策。"},
"canvass":{"e":"Volunteers spent the weekend canvassing the neighborhood, knocking on every door to ask residents about the upcoming ballot measure.","t":"志愿者们花了整个周末在社区**挨家挨户拉票**，敲开每一户人家的门询问居民对即将到来的投票议案的看法。"},
"conspiracy":{"e":"Investigators uncovered a conspiracy among three executives to hide the company's mounting debts from its shareholders.","t":"调查人员揭露了三名高管合谋向股东隐瞒公司不断攀升的债务的**阴谋**。"},
"corrupt":{"e":"Absolute power gradually corrupted even the most idealistic members of the ruling council, until bribery became routine.","t":"绝对的权力逐渐**腐蚀**了议会中即便是最理想主义的成员，直到行贿受贿变得司空见惯。"},
"default":{"e":"If the homeowner defaults on the mortgage again, the bank will have the legal right to seize the property.","t":"如果房主再次在按揭贷款上**违约**，银行将拥有合法权利没收该房产。"},
"pivot":{"e":"The star quarterback quickly became the pivot around which the entire offensive strategy of the struggling team was rebuilt.","t":"这位明星四分卫很快成了整个球队进攻战术围绕旋转的**核心**，球队也因此重建了战术体系。"},
"seminar":{"e":"Graduate students are required to present original research at the weekly seminar before submitting their theses for review.","t":"研究生必须在提交论文接受评审之前，先在每周的**研讨会**上展示原创研究成果。"},
"depose":{"e":"The generals conspired to depose the aging monarch and install his more reform-minded son on the throne instead.","t":"将军们密谋**废黜**年迈的君主，改立他那位更倾向改革的儿子继位。"},
"identical":{"e":"The two vases looked identical at first glance, but only one carried the small maker's mark that proved its authenticity.","t":"这两只花瓶乍看之下**一模一样**，但只有一只带着能证明其真品身份的小小工匠印记。"},
"desegregate":{"e":"The federal court ordered the school district to desegregate its classrooms within the following academic year.","t":"联邦法院下令该学区必须在接下来的一学年内**废除教室里的种族隔离**。"},
"assassinate":{"e":"Bodyguards surrounded the president at every public event after intelligence agents uncovered a plot to assassinate him.","t":"情报人员发现了一起**暗杀**总统的阴谋后，保镖便在每一场公开活动中将他团团围住。"},
"superior":{"e":"Consumers consistently rated the handmade leather boots as superior to anything the mass-produced brands had to offer.","t":"消费者一致认为这款手工皮靴比任何批量生产品牌的产品都**更胜一筹**。"},
"photograph":{"e":"Tucked inside the old book, she found a faded photograph of her grandparents standing in front of their first house.","t":"她在那本旧书里发现了一张褪色的**照片**，照片上祖父母正站在他们的第一栋房子前。"},
"muscular":{"e":"Years of hauling fishing nets had given the old sailor a muscular build that men half his age envied.","t":"多年拉渔网的劳作让这位老水手练就了一身**肌肉发达**的体格，令年纪只有他一半的年轻人都羡慕不已。"},
"amino":{"e":"Proteins in the human body are built from chains of amino acids linked together in a specific sequence.","t":"人体内的蛋白质是由按特定顺序连接在一起的**氨基**酸链构成的。"},
"scarce":{"e":"Fresh water became so scarce during the drought that farmers had to ration it among their livestock and crops.","t":"干旱期间淡水变得极为**稀缺**，农民不得不在牲畜和农作物之间配给用水。"},
"incident":{"e":"A minor incident at the border checkpoint quickly escalated into a diplomatic crisis between the two neighboring countries.","t":"边境检查站发生的一起小**事件**迅速升级为两个邻国之间的外交危机。"},
"atmosphere":{"e":"Soft candlelight and quiet jazz gave the restaurant an intimate atmosphere that made every table feel private.","t":"柔和的烛光和轻柔的爵士乐为这家餐厅营造出一种亲密的**氛围**，让每张桌子都显得格外私密。"},
"instinct":{"e":"Even newborn sea turtles rely on instinct alone to find their way from the sand to the ocean waves.","t":"即便是刚孵化的小海龟，也仅凭**本能**就能从沙滩找到通往海浪的路。"},
"vacuum":{"e":"The sudden resignation of the CEO left a vacuum of leadership that the board struggled for months to fill.","t":"首席执行官突然辞职留下了一个领导层的**真空**，董事会花了数月时间都难以填补。"},
"antique":{"e":"Her grandmother's antique writing desk had been passed down through four generations without a single crack in its polished surface.","t":"祖母那张**古老的**写字台传了四代人，光洁的桌面上竟没有一丝裂痕。"},
"ideomotor":{"e":"Researchers explained the table's mysterious tilting as an ideomotor response, caused by the sitters' own unconscious muscle movements.","t":"研究人员将那张桌子神秘的倾斜解释为一种**观念运动**反应，是由参与者自己无意识的肌肉动作引起的。"},
"breathing":{"e":"The yoga instructor reminded the class to focus on slow, deep breathing whenever the poses became difficult.","t":"瑜伽教练提醒学员，每当体式变得困难时，都要专注于缓慢而深长的**呼吸**。"},
"dent":{"e":"A single hailstone left a small dent in the hood of the brand-new car parked outside.","t":"一颗冰雹就在停在外面的那辆崭新汽车的引擎盖上砸出了一个小小的**凹痕**。"},
"intrinsic":{"e":"Collectors argued that the painting's intrinsic value had little to do with the artist's fame or the price it might fetch at auction.","t":"收藏家们认为，这幅画作的**内在**价值与画家的名气或它在拍卖会上能卖出的价格没有多大关系。"},
"skeleton":{"e":"The museum's dinosaur skeleton towered over visitors, its enormous bones reassembled bone by bone over three painstaking years.","t":"博物馆里的恐龙**骨架**高耸在游客头顶，它庞大的骨骼是经过三年艰辛工作一块块重新拼装起来的。"},
"disease":{"e":"Poor sanitation in the crowded camp allowed the disease to spread rapidly among refugees before doctors could intervene.","t":"拥挤营地里恶劣的卫生条件让**疾病**在医生介入之前就已在难民中迅速传播开来。"},
"concentric":{"e":"The archer's target consisted of five concentric circles, each ring worth fewer points than the one closer to the center.","t":"弓箭手的靶子由五个**同心**圆组成，每一环的分值都比靠近圆心的那一环要低。"},
"racket":{"e":"The neighbors upstairs made such a racket at midnight that we finally called the building manager to complain.","t":"楼上的邻居半夜弄出这么大的**噪音**，我们最后只好打电话向物业管理员投诉。"},
"earnest":{"e":"His earnest apology, delivered without a hint of sarcasm, finally convinced her that he truly regretted the mistake.","t":"他那**真诚**的道歉，没有一丝讽刺的意味，终于让她相信他真心为这个错误感到后悔。"},
"instrument":{"e":"Surgeons rely on a delicate instrument no wider than a pencil to perform the most precise incisions.","t":"外科医生依靠一件不比铅笔宽多少的精细**器械**来完成最精准的切口。"},
"hibernation":{"e":"Black bears enter hibernation in late autumn, slowing their heart rate dramatically to survive the lean winter months.","t":"黑熊在深秋进入**冬眠**，大幅降低心率以熬过物资匮乏的冬季。"},
"fatal":{"e":"A single wrong turn on the icy mountain road proved fatal for the two hikers who never made it back.","t":"结冰山路上一个错误的转弯，最终对那两名再也没能回来的徒步者而言是**致命的**。"},
"nominate":{"e":"The committee voted unanimously to nominate her for the award, citing her decade of selfless volunteer work.","t":"委员会一致投票**提名**她获得这项奖项，理由是她十年来无私的志愿工作。"},
"cholesterol":{"e":"Doctors advised him to cut back on fried foods after tests showed his cholesterol had climbed to a dangerous level.","t":"检查显示他的**胆固醇**已升到危险水平后，医生建议他少吃油炸食品。"},
"souvenir":{"e":"She kept the chipped seashell as a souvenir of the summer she spent backpacking along the coast of Portugal.","t":"她把那只有缺口的贝壳留了下来，作为她那年夏天沿葡萄牙海岸背包旅行的**纪念品**。"},
"medication":{"e":"The nurse reminded him to take his medication with food to avoid the nausea it sometimes caused on an empty stomach.","t":"护士提醒他服用**药物**时要搭配食物，以免空腹服用引起恶心。"},
"electrode":{"e":"Technicians attached a small electrode to each temple to record the patient's brain activity during the seizure.","t":"技术人员在患者的两侧太阳穴各贴上一个小**电极**，以记录癫痫发作期间的脑部活动。"},
"thread":{"e":"Buried in the witness's rambling testimony was a single thread that finally connected the two unsolved robberies.","t":"在证人漫无边际的证词中，藏着一条最终将两起悬案联系起来的**线索**。"},
"sponge":{"e":"She wiped the counter clean with a damp sponge before setting out the plates for dinner.","t":"她用一块湿**海绵**把台面擦干净，然后才摆出晚餐用的盘子。"},
"automobile":{"e":"Henry Ford's assembly line made the automobile affordable for ordinary families who had once considered it a luxury.","t":"亨利·福特的流水线让曾经被视为奢侈品的**汽车**变得普通家庭也能负担得起。"},
"republic":{"e":"After the revolution, the newly formed republic held its first free elections in over four decades.","t":"革命之后，这个新成立的**共和国**举行了四十多年来的首次自由选举。"},
"ritual":{"e":"Every morning before dawn, the monks performed the same ancient ritual of lighting incense and chanting in unison.","t":"每天黎明前，僧侣们都会举行同样古老的**仪式**，点燃香烛并齐声诵经。"},
"periphery":{"e":"Small startups often thrive on the periphery of an industry, experimenting with ideas too risky for established giants.","t":"小型初创企业常常在行业的**边缘**地带蓬勃发展，尝试那些对成熟巨头来说太过冒险的想法。"},
"immediate":{"e":"The factory's collapse demanded an immediate response from emergency crews already stretched thin across the region.","t":"工厂倒塌事故需要应急队伍**立即**做出反应，而他们本已在整个地区分身乏术。"},
"delirium":{"e":"The fever climbed so high overnight that the child slipped into a delirium, muttering words that made no sense.","t":"高烧一夜之间飙升，孩子陷入了**精神错乱**的状态，嘴里嘟囔着毫无意义的话。"},
"botany":{"e":"Her fascination with wildflowers as a child eventually led her to pursue a career in botany at the state university.","t":"她儿时对野花的痴迷，最终引导她在州立大学投身**植物学**事业。"},
"quarterly":{"e":"The literary quarterly published only four issues a year, but each one featured meticulously selected new fiction.","t":"这份文学**季刊**一年只出版四期，但每一期都精心挑选了全新的小说作品。"},
"stage":{"e":"The drama club decided to stage an ambitious production of the musical despite having almost no budget for costumes.","t":"尽管服装预算几乎为零，话剧社还是决定**上演**一部雄心勃勃的音乐剧。"},
"legislative":{"e":"The proposal still needs legislative approval before construction on the new highway can officially begin next spring.","t":"这项提案仍需获得**立法**机构批准，新高速公路才能在明年春天正式动工。"},
"combination":{"e":"The chef's winning dish relied on an unexpected combination of dark chocolate and roasted chili peppers.","t":"这位厨师获奖的菜品，靠的是黑巧克力和烤辣椒这种出人意料的**组合**。"},
"inventory":{"e":"The warehouse manager discovered that half the inventory listed in the system no longer existed on the shelves.","t":"仓库经理发现系统里登记的**库存**有一半在货架上早已不存在了。"},
"endangered":{"e":"Conservationists built a protected reserve specifically to give the endangered rhinos a chance to breed safely.","t":"环保人士专门建立了一个受保护的保护区，让**濒危**犀牛有机会安全繁育。"},
"reservoir":{"e":"During the drought, the city drew drinking water from a reservoir that had dropped to a quarter of its normal level.","t":"干旱期间，这座城市从一座已降到正常水位四分之一的**水库**取用饮用水。"},
"squirt":{"e":"The toddler squeezed the bottle too hard and squirted ketchup all over his father's clean white shirt.","t":"小孩把瓶子捏得太用力，把番茄酱**喷**得他父亲干净的白衬衫上到处都是。"},
"resin":{"e":"Ancient insects trapped in amber were actually preserved in tree resin that hardened over millions of years.","t":"被困在琥珀中的远古昆虫，实际上是被历经数百万年硬化的树**脂**保存下来的。"},
"context":{"e":"Without knowing the historical context of the speech, students misunderstood the senator's sarcastic remark as a genuine compliment.","t":"由于不了解这篇演讲的历史**背景**，学生们把参议员那句讽刺的话误解成了真心的赞美。"},
"symptom":{"e":"A persistent dry cough that lasted for weeks was the first symptom that convinced her something was seriously wrong.","t":"持续数周不见好转的干咳，是让她确信自己出了严重问题的第一个**症状**。"},
"interrupt":{"e":"The teacher paused mid-sentence, visibly annoyed that a student kept interrupting her careful explanation with unrelated, rambling questions.","t":"老师说到一半停了下来，显然对一名学生不断用不相干的问题**打断**她细致的讲解感到恼火。"},
"velocity":{"e":"Engineers calculated the rocket's velocity at each stage of ascent to ensure it would safely reach orbit.","t":"工程师计算了火箭在上升各阶段的**速度**，以确保它能安全进入轨道。"},
"dormitory":{"e":"Freshmen are required to live in a dormitory on campus for their first full year at the university.","t":"大一新生第一年必须住在校园里的**宿舍**中。"},
"freight":{"e":"The company shifted most of its freight from trucks to trains after fuel prices climbed sharply.","t":"燃油价格大幅上涨后，这家公司把大部分**货运**从卡车转移到了火车上。"},
"tread":{"e":"She learned to tread carefully across the frozen pond, testing each step before trusting her full weight to the ice.","t":"她学会了小心翼翼地**踏**过结冰的池塘，每一步都先试探一下才敢把全部体重压上去。"},
"ascribe":{"e":"Historians ascribe the empire's sudden collapse to a combination of drought, plague, and endless costly wars.","t":"历史学家将这个帝国的突然崩溃**归因于**干旱、瘟疫和无休止的昂贵战争的共同作用。"},
"equation":{"e":"The physics teacher spent the entire class deriving the equation that describes how falling objects accelerate.","t":"物理老师花了一整堂课推导那条描述落体如何加速的**方程式**。"},
"copper":{"e":"Ancient tools unearthed at the site were fashioned almost entirely from copper, long before iron came into common use.","t":"在这个遗址出土的古老工具几乎全部由**铜**制成，那时铁器还远未普及。"},
"rear":{"e":"Both parents worked long hours, so it was their grandmother who mostly reared the three children.","t":"父母俩都要长时间工作，所以主要是祖母**抚养**了这三个孩子。"},
"accede":{"e":"After hours of tense negotiation, the union finally acceded to management's request for a shorter probationary period.","t":"经过数小时的紧张谈判，工会最终**同意**了管理层缩短试用期的请求。"},
"mosquito":{"e":"A single mosquito buzzing near her ear kept her awake for most of the humid summer night.","t":"一只在耳边嗡嗡作响的**蚊子**，让她在那个闷热的夏夜里几乎彻夜未眠。"},
"numerous":{"e":"The senator received numerous letters from constituents demanding stricter regulations on factory emissions near the river.","t":"这位参议员收到了**许多**选民来信，要求对河流附近工厂的排放实施更严格的监管。"},
"livestock":{"e":"Ranchers moved their livestock to higher pastures before the seasonal floods could reach the lowland fields.","t":"牧场主们在季节性洪水淹没低地牧场之前，就把**牲畜**转移到了地势较高的牧场。"},
"prescription":{"e":"The pharmacist double-checked the prescription with the doctor's office after noticing an unusually high dosage listed.","t":"药剂师发现**处方**上标注的剂量异常偏高，便向医生办公室再次核实。"},
"awkward":{"e":"An awkward silence fell over the dinner table after her sister brought up the inheritance dispute uninvited.","t":"她妹妹突然提起遗产纠纷之后，晚餐桌上陷入了一阵**尴尬**的沉默。"},
"collective":{"e":"The factory workers organized a collective demand for safer equipment after the second accident that month.","t":"这个月第二起事故发生后，工厂工人们组织了一次**集体**要求，希望获得更安全的设备。"},
"invertebrate":{"e":"Marine biologists classified the strange creature found on the seafloor as an invertebrate related to sea cucumbers.","t":"海洋生物学家将这种在海床上发现的奇特生物归类为与海参有亲缘关系的**无脊椎动物**。"},
"barge":{"e":"Without knocking, the manager barged into the meeting room and demanded to know why production had stopped.","t":"经理连门都没敲，就**闯**进会议室质问为什么生产停了下来。"},
"snap":{"e":"The old rope snapped under the weight of the climber, sending him tumbling several feet onto the padded mat below.","t":"那根旧绳子在攀岩者的重压下突然**断裂**，害他跌落好几英尺摔到下面的软垫上。"},
"feat":{"e":"Crossing the Atlantic alone in a rowboat was a feat that few sailors had ever dared attempt.","t":"独自划船横渡大西洋是一项极少有水手敢于尝试的**壮举**。"},
"conservation":{"e":"The nonprofit organization dedicated itself entirely to wetland conservation, restoring marshes that developers had drained decades earlier.","t":"这家非营利组织全身心投入湿地**保护**事业，修复了开发商数十年前排干的沼泽。"},
"smother":{"e":"She had to smother a laugh when the puppy tumbled clumsily off the couch during the solemn ceremony.","t":"那只小狗在庄严的仪式上笨拙地从沙发上摔下来时，她不得不**强忍**住笑声。"},
"blur":{"e":"Tears blurred her vision so badly that she could barely make out the words on the page.","t":"泪水把她的视线**模糊**得厉害，她几乎看不清页面上的字。"},
"mantle":{"e":"Molten rock rising from the Earth's mantle eventually breaks through the crust to form new volcanic islands.","t":"从地球**地幔**上升的熔岩最终会突破地壳，形成新的火山岛。"},
"demonstrate":{"e":"The scientist's experiment clearly demonstrated that the two chemicals reacted violently when combined at room temperature.","t":"这位科学家的实验清楚地**证明**了这两种化学物质在室温下混合会发生剧烈反应。"},
"additive":{"e":"Parents grew wary of the cereal after learning it contained an artificial additive linked to hyperactivity in children.","t":"家长们得知这款麦片含有一种与儿童多动症有关的人工**添加剂**后，便对它心生警惕。"},
"lithosphere":{"e":"Earthquakes occur when massive tectonic plates within the lithosphere grind slowly against each other along ancient fault lines.","t":"地震的发生，是因为**岩石圈**内巨大的构造板块沿着古老的断层线缓慢相互摩擦挤压。"},
"dam":{"e":"Engineers built a massive dam across the river valley to generate electricity for the entire region.","t":"工程师们在河谷上修建了一座巨大的**水坝**，为整个地区发电。"},
"steep":{"e":"The trail became so steep near the summit that hikers had to use both hands to climb.","t":"山路在接近峰顶时变得极为**陡峭**，徒步者不得不手脚并用才能爬上去。"},
"exhaust":{"e":"Three days of searching the wilderness exhausted the rescue team's supplies long before they found any trace of the missing hiker.","t":"在荒野中搜寻了三天，救援队的补给早在他们找到失踪徒步者的任何踪迹之前就已**耗尽**。"},
"cardiac":{"e":"The elderly patient was rushed to the emergency room after suffering a sudden cardiac arrest at home.","t":"这位老年病人在家中突发**心脏**骤停后被紧急送往急诊室。"},
"minimum":{"e":"The contract guarantees every worker a minimum of twelve paid vacation days each year, regardless of seniority.","t":"该合同保证每位员工每年至少享有十二天带薪假期，无论工龄长短，这是**最低**标准。"},
"raise":{"e":"The charity managed to raise enough money in a single weekend to rebuild the flood-damaged school.","t":"这家慈善机构仅用一个周末就**筹集**到了足够重建那所受洪灾损毁学校的资金。"},
"amateur":{"e":"Though he remained an amateur throughout his career, his paintings eventually sold for more than those of trained professionals.","t":"尽管他一辈子都只是个**业余爱好者**，他的画作最终卖出的价钱却超过了受过专业训练的画家。"},
"prior":{"e":"The nurse asked whether he had any prior history of allergic reactions before administering the new medication.","t":"护士在给他用新药之前，先询问他此**前**是否有过任何过敏反应史。"},
"sheer":{"e":"It was sheer luck that the climber grabbed the loose branch just before he would have fallen off the cliff.","t":"那位攀岩者在跌落悬崖之前一把抓住那根松动的树枝，纯粹是**运气**使然。"},
"measure":{"e":"The government introduced a new measure requiring all restaurants to display calorie counts clearly on their menus.","t":"政府出台了一项新**措施**，要求所有餐厅在菜单上清楚标示卡路里含量。"},
"engaging":{"e":"The new professor's engaging lectures drew students from other departments who weren't even enrolled in the class.","t":"这位新教授**引人入胜**的讲座吸引了许多甚至没有选这门课的其他院系学生前来旁听。"},
"convert":{"e":"The old factory was converted into loft apartments after the textile company moved its operations overseas.","t":"这家纺织公司把业务迁往海外后，那座旧工厂被**改建**成了阁楼公寓。"},
"tremendous":{"e":"The new vaccine had a tremendous impact on infant mortality rates within just a few years of its introduction.","t":"这种新疫苗问世仅仅几年，就对婴儿死亡率产生了**巨大**的影响。"},
"bunch":{"e":"She arranged a bunch of freshly picked wildflowers in a chipped ceramic vase on the sunny windowsill.","t":"她把一**束**刚采来的野花插进窗台上一只有缺口的陶瓷花瓶里。"},
"pictorial":{"e":"The magazine's pictorial history of the war conveyed more emotion through its photographs than any written account could.","t":"这本杂志**图文并茂**的战争史，透过照片所传达的情感胜过任何文字记述。"},
"enlist":{"e":"At eighteen, he decided to enlist in the navy rather than continue his studies at the local college.","t":"十八岁那年，他决定**参军**加入海军，而不是继续在当地大学读书。"},
"stuff":{"e":"The old barn was packed with stuff nobody had touched in decades, from broken tools to yellowed newspapers.","t":"这座旧谷仓里堆满了几十年没人碰过的各种**东西**，从破损的工具到发黄的报纸应有尽有。"},
"rumor":{"e":"A rumor about layoffs spread through the office within minutes, even though management had announced nothing official.","t":"一则关于裁员的**谣言**几分钟内就传遍了整个办公室，尽管管理层根本没有发布任何正式消息。"},
"agency":{"e":"The federal agency responsible for food safety launched an investigation after dozens of people fell ill from the same restaurant.","t":"负责食品安全的联邦**机构**在数十人因同一家餐厅而患病后展开了调查。"},
"packed":{"e":"The stadium was already packed long before kickoff, with thousands of fans lining up outside since early morning.","t":"距离开赛还有很久，体育场就已经**挤得水泄不通**，数千名球迷从清晨就开始在外面排队。"},
"resign":{"e":"After the scandal broke, the minister had no choice but to resign from his position within the cabinet.","t":"丑闻曝光后，这位部长别无选择，只能从内阁职位上**辞职**。"},
"guarantee":{"e":"No amount of careful preparation could truly guarantee that the delicate surgery would go exactly as the surgeons had planned.","t":"再周密的准备也无法真正**保证**这场精细的手术会完全按照医生们的计划进行。"},
"coordinate":{"e":"The relief agencies had to coordinate closely with local officials to distribute supplies efficiently after the earthquake.","t":"救援机构必须与地方官员密切**协调**，才能在地震后高效分发物资。"},
"terminology":{"e":"Medical terminology can overwhelm new patients, who often leave the doctor's office more confused than before.","t":"医学**术语**常常令初次就诊的病人不知所措，离开诊室时反而比之前更加困惑。"},
"inaugurate":{"e":"The scientist's discovery inaugurated a new era of research into how the brain repairs itself after injury.","t":"这位科学家的发现**开创**了研究大脑损伤后自我修复的新时代。"},
"composer":{"e":"The young composer spent three years writing a symphony that critics later called a masterpiece of modern orchestration.","t":"这位年轻**作曲家**花了三年时间创作了一部交响曲，评论家后来称之为现代管弦乐的杰作。"},
"trade":{"e":"Centuries of trade along the Silk Road brought spices, silk, and new ideas from Asia into European markets.","t":"丝绸之路沿线数百年的**贸易**，把香料、丝绸和新观念从亚洲带入了欧洲市场。"},
"empower":{"e":"The new law empowers local school boards to set their own curriculum standards without state interference.","t":"这项新法律**授权**地方学校董事会自行制定课程标准，不受州政府干预。"},
"injurious":{"e":"Doctors warned that the chemical fumes released during the fire could prove injurious to anyone with asthma.","t":"医生警告说，火灾期间释放的化学烟雾可能对任何哮喘患者都**有害**。"},
"faction":{"e":"A rebellious faction within the ruling party threatened to break away unless the prime minister resigned.","t":"执政党内一个反叛的**派系**威胁说，如果首相不辞职就要另立门户。"},
"lapse":{"e":"A momentary lapse in concentration caused the surgeon to nick a blood vessel during the routine procedure.","t":"一时的注意力**失误**，导致外科医生在这场常规手术中划破了一根血管。"},
"allay":{"e":"The mayor's calm press conference helped allay public fears about the safety of the city's drinking water.","t":"市长镇定自若的新闻发布会，有助于**减轻**公众对城市饮用水安全的担忧。"},
"fraud":{"e":"The investigation exposed a massive insurance fraud that had cost the company millions of dollars over a decade.","t":"这次调查揭露了一起让公司在十年间损失数百万美元的大规模保险**欺诈**案。"},
"imperial":{"e":"For more than two centuries, imperial armies expanded the empire's borders relentlessly before its sudden and final collapse.","t":"两个多世纪以来，**帝国**军队不断扩张疆域，直到最终突然崩溃。"},
"empress":{"e":"The empress ruled the vast territory for nearly four decades, outlasting three different emperors of neighboring kingdoms.","t":"这位**女皇**统治这片广袤领土近四十年，在位时间超过了邻国三位不同的皇帝。"},
"dramatic":{"e":"Sales figures showed a dramatic increase after the company redesigned its packaging to appeal to younger shoppers.","t":"这家公司重新设计包装以吸引年轻消费者后，销售数据出现了**大幅**增长。"},
"apply":{"e":"She decided to apply for the scholarship even though the deadline was only two days away.","t":"尽管离截止日期只剩两天，她还是决定**申请**这份奖学金。"},
"interrogate":{"e":"Detectives interrogated the suspect for nearly six hours before he finally admitted where he had hidden the stolen goods.","t":"警探们**审讯**了嫌疑人近六个小时，他才终于交代了赃物藏在哪里。"},
"juridical":{"e":"The dispute raised complex juridical questions about which country's courts actually had jurisdiction over the case.","t":"这场纠纷引发了复杂的**司法**问题，即究竟哪个国家的法院对此案拥有管辖权。"},
"lawsuit":{"e":"The former employee filed a lawsuit against the company, claiming she had been fired for reporting safety violations.","t":"这名前员工向公司提起**诉讼**，声称自己是因举报安全违规行为而被解雇的。"},
"farce":{"e":"The trial quickly turned into a farce when the star witness admitted he had never actually seen the crime take place.","t":"当明星证人承认自己其实从未目睹犯罪过程时，这场审判很快就沦为了一场**闹剧**。"},
"lubricant":{"e":"Mechanics apply a thin lubricant to the gears every few months to prevent the metal from grinding and wearing down.","t":"技工们每隔几个月就给齿轮涂上一层薄薄的**润滑剂**，以防止金属磨损。"},
"dairy":{"e":"The farmer's dairy supplied fresh milk and cheese to nearly every restaurant in the small mountain town.","t":"这位农场主的**奶场**向这座山间小镇几乎每一家餐厅供应新鲜牛奶和奶酪。"},
"microwave":{"e":"He reheated last night's leftovers in the microwave while scrolling through the morning news on his phone.","t":"他一边用**微波炉**加热昨晚剩下的饭菜，一边刷着手机上的早间新闻。"},
"legislate":{"e":"Parliament refused to legislate on the controversial issue, leaving individual states to set their own rules instead.","t":"议会拒绝就这一有争议的问题**立法**，转而让各州自行制定规则。"},
"indict":{"e":"A grand jury voted to indict the former treasurer on multiple charges of embezzling public funds.","t":"大陪审团投票决定以多项侵吞公款的罪名**起诉**这位前财务主管。"},
"tube":{"e":"The plumber replaced the corroded tube beneath the sink before it could burst and flood the kitchen.","t":"水管工在那根腐蚀的**管子**爆裂淹没厨房之前，及时更换了水槽下方的管道。"},
"cancel":{"e":"Heavy snowfall forced the airline to cancel dozens of flights that had been scheduled to depart that evening.","t":"大雪迫使这家航空公司**取消**了数十趟原定当晚起飞的航班。"},
"industry":{"e":"The rapid rise of streaming services transformed the entire music industry within less than a single decade.","t":"流媒体服务的迅速崛起，在不到十年的时间里就改变了整个音乐**行业**。"},
"dispute":{"e":"A property line dispute between the two neighbors dragged on in court for nearly three years.","t":"这两户邻居之间的地界**纠纷**在法庭上拖了将近三年。"},
"essay":{"e":"Her essay on climate migration impressed the judges so much that it won first place in the national contest.","t":"她那篇关于气候移民的**文章**令评委印象深刻，最终在全国比赛中夺得第一名。"},
"sieve":{"e":"She pressed the boiled berries through a fine sieve to separate the smooth juice from the seeds and skins.","t":"她把煮过的浆果压过细**筛**，把顺滑的果汁与籽和皮分离开来。"},
"commit":{"e":"Investigators still don't know why the otherwise law-abiding accountant chose to commit such a brazen fraud.","t":"调查人员至今仍不明白，这位一向遵纪守法的会计师为何会去**犯下**如此明目张胆的欺诈罪行。"},
"auditorium":{"e":"Every student in the school gathered in the auditorium for the annual assembly celebrating the graduating seniors.","t":"全校学生齐聚**礼堂**，参加庆祝毕业班学生的年度集会。"},
"transportation":{"e":"The city invested heavily in public transportation, adding new bus routes to connect neighborhoods that had long been isolated.","t":"这座城市大力投资公共**交通**，新增公交线路连接了长期以来相对孤立的社区。"},
"dilute":{"e":"The chemist had to dilute the acid with water before it was safe to handle in the classroom.","t":"化学老师必须先用水**稀释**这种酸，才能让它在教室里安全使用。"},
"plastic":{"e":"Warm clay remains plastic enough to shape by hand for only a short window before it stiffens.","t":"温热的陶土只有很短的时间保持足够的**可塑性**供人用手塑形，随后就会变硬。"},
"stack":{"e":"Librarians stacked the returned books neatly on the cart before wheeling them back to their shelves.","t":"图书管理员把归还的书整齐地**堆放**在推车上，然后推回书架。"},
"oval":{"e":"The dining table was oval rather than round, allowing more guests to fit comfortably around its edges.","t":"餐桌是**椭圆形**的，而不是圆形，这样能让更多客人舒适地围坐在桌边。"},
"fabric":{"e":"The tailor examined the fabric closely, running her fingers over the fine silk to check for any flaws.","t":"裁缝仔细检查这块**布料**，用手指抚过精细的丝绸以查看有无瑕疵。"},
"capacity":{"e":"The new stadium's seating capacity nearly doubled that of the old, cramped arena it eventually replaced.","t":"这座新体育场的座位**容量**几乎是它最终取代的那座老旧拥挤球场的两倍。"},
"blast":{"e":"The blast from the explosion shattered every window within three blocks of the abandoned old warehouse.","t":"那场爆炸的**冲击波**震碎了那座废弃旧仓库周围三个街区内的每一扇窗户。"},
"partnership":{"e":"The two chefs formed a partnership to open a restaurant that combined both of their culinary traditions.","t":"两位厨师建立了**合作伙伴关系**，共同开了一家融合他们各自烹饪传统的餐厅。"},
"relic":{"e":"Archaeologists carefully brushed away the sand to reveal a relic believed to date back three thousand years.","t":"考古学家小心翼翼地拂去沙土，露出一件据信可追溯到三千年前的**遗物**。"},
"meteorology":{"e":"She switched her major to meteorology after a single semester of tracking hurricanes fascinated her completely.","t":"仅仅一个学期的飓风追踪课程就让她彻底着迷，于是她把专业改成了**气象学**。"},
"circumference":{"e":"Engineers measured the circumference of the ancient tower to determine how much the stone base had shifted over centuries.","t":"工程师测量了这座古塔的**周长**，以确定石质地基在数百年间发生了多大的位移。"},
"device":{"e":"Engineers designed a small device that warns drivers the moment tire pressure drops below a safe threshold.","t":"工程师设计了一款小巧的**装置**，能在胎压降到安全阈值以下时立刻警示司机。"},
"beak":{"e":"The heron speared the fish with its long, sharp beak before swallowing it whole in a single gulp.","t":"苍鹭用它又长又尖的**喙**叉住鱼，然后一口把整条鱼吞了下去。"},
"premier":{"e":"The city's premier concert hall attracts world-renowned orchestras from every continent throughout the entire performance season.","t":"这座城市**首屈一指**的音乐厅，整个演出季都吸引着来自各大洲的世界知名交响乐团。"},
"codify":{"e":"Legal scholars worked for years to codify the scattered customary rules into a single, coherent body of law.","t":"法律学者花了多年时间，把散乱的习惯法规**编纂**成一部统一连贯的法典。"},
"dismal":{"e":"Rain fell steadily under a dismal gray sky, matching the mood of everyone stuck waiting at the station.","t":"雨在**阴沉**灰暗的天空下不停地下着，仿佛映衬着每一个困在车站等待的人的心情。"},
"harsh":{"e":"Only the hardiest plants can survive the harsh winters of the Siberian tundra, where temperatures plunge for months.","t":"只有最顽强的植物才能在西伯利亚冻原**严酷**的冬天里存活下来，那里的气温会持续数月骤降。"},
"volunteer":{"e":"She volunteered to stay late every Friday, tutoring students who struggled with algebra after the regular class ended.","t":"她**主动**每周五留到很晚，在正课结束后为那些代数有困难的学生补习。"},
"chubby":{"e":"The chubby toddler giggled uncontrollably every time his older sister blew a raspberry on his round belly.","t":"每次姐姐在他圆滚滚的肚子上吹气发出怪声，这个**圆嘟嘟**的小孩都会忍不住咯咯大笑。"},
"intimate":{"e":"Decades of shared struggle had forged an intimate bond between the two old friends that nothing could break.","t":"数十年共同经历的磨难，让这两位老朋友之间形成了任何事都无法打破的**亲密**纽带。"},
"transcend":{"e":"Great art can transcend the specific era that produced it, speaking directly to audiences who live centuries later.","t":"伟大的艺术能够**超越**孕育它的特定时代，直接与几个世纪后的观众对话。"},
"hurry":{"e":"She had to hurry through breakfast because the school bus never waited more than two minutes at her stop.","t":"她不得不**匆匆**吃完早饭，因为校车在她那一站从不会多等两分钟。"},
"venom":{"e":"The cobra injected enough venom in that single bite to kill an adult within a few hours.","t":"那条眼镜蛇一口咬下注入的**毒液**足以在几个小时内致一个成年人死亡。"},
"monarchy":{"e":"After centuries of monarchy, the small kingdom finally adopted a constitution that transferred real power to an elected parliament.","t":"经历了几个世纪的**君主制**之后，这个小王国终于通过了一部宪法，把实权移交给民选议会。"},
"paraphrase":{"e":"Rather than quote the dense legal passage directly, the teacher chose to paraphrase it in simple, everyday language.","t":"老师没有直接引用那段晦涩的法律条文，而是选择用简单日常的语言把它**改写**一遍。"},
"worth":{"e":"Renovating the old farmhouse took two exhausting years, but the finished result proved worth every sleepless night.","t":"翻修这栋老农舍花了两年精疲力竭的时间，但最终的成果证明**值得**每一个不眠之夜。"},
"loyal":{"e":"Even after the company nearly collapsed, most of its longtime employees remained loyal and refused better offers elsewhere.","t":"即使公司几乎倒闭，大多数老员工依然**忠诚**，拒绝了别处更好的机会。"},
"dinosaur":{"e":"Paleontologists unearthed a nearly complete dinosaur skeleton from the cliffside, its massive ribs still curved around ancient sediment.","t":"古生物学家从悬崖边挖出了一具几乎完整的**恐龙**骨架，巨大的肋骨仍蜷曲环绕着远古的沉积物。"},
"hazard":{"e":"Loose wiring in the basement posed a serious fire hazard that the inspector flagged immediately during his visit.","t":"地下室里松动的电线构成了严重的火灾**隐患**，检查员当场就指了出来。"},
"recreation":{"e":"After grueling exams, students flocked to the lake for recreation, swimming and canoeing until the sun went down.","t":"熬过艰苦的考试后，学生们涌向湖边**消遣**娱乐，游泳划船直到日落。"},
"swindle":{"e":"The con artist tried to swindle elderly homeowners out of their savings by posing as a roofing contractor.","t":"那个骗子冒充屋顶承包商，企图**骗取**老年房主们的积蓄。"},
"collide":{"e":"Two freight trains collided head-on in the fog, derailing dozens of cars and spilling cargo across the tracks.","t":"两列货运列车在浓雾中迎面**相撞**，数十节车厢脱轨，货物散落一地。"},
"oxygen":{"e":"Climbers above eight thousand meters carry bottled oxygen because the air there is too thin to sustain consciousness.","t":"在八千米以上攀登的登山者要携带瓶装**氧气**，因为那里的空气稀薄得无法维持意识清醒。"},
"gem":{"e":"Tucked away in a quiet alley, the tiny bakery turned out to be a real gem few tourists ever find.","t":"这家小面包店藏在僻静的小巷里，是难得被游客发现的一块**瑰宝**。"},
"lower":{"e":"The central bank decided to lower interest rates sharply in hopes of reviving consumer spending before winter.","t":"央行决定大幅**降低**利率，希望在冬季来临前刺激消费支出回升。"},
"avalanche":{"e":"The avalanche swept down the mountainside without warning, burying the ski lodge under twelve feet of snow.","t":"**雪崩**毫无预警地从山坡上倾泻而下，将滑雪小屋埋在十二英尺深的积雪之下。"},
"fierce":{"e":"The two companies waged a fierce battle for market share, slashing prices until neither could turn a profit.","t":"两家公司为争夺市场份额展开**激烈**的争斗，不断压低价格，直到谁都无法盈利。"},
"sponsor":{"e":"A local bank agreed to sponsor the youth soccer league, covering uniforms, equipment, and travel costs for every team.","t":"一家本地银行同意**赞助**这个青少年足球联赛，承担所有球队的球衣、装备和差旅费用。"},
"cuneiform":{"e":"Archaeologists carefully deciphered the cuneiform tablets to reveal detailed records of grain trade across ancient Mesopotamia's busy river ports.","t":"考古学家仔细解读了这些**楔形文字**泥板，揭示出古代美索不达米亚繁忙河港谷物贸易的详细记录。"},
"manifesto":{"e":"The young artists published a manifesto declaring that painting must abandon realism and embrace pure abstraction instead.","t":"这群年轻艺术家发表了一份**宣言**，宣称绘画必须抛弃写实主义，转而拥抱纯粹的抽象。"},
"outlaw":{"e":"Several countries have moved to outlaw single-use plastic bags entirely, forcing retailers to offer paper or cloth alternatives.","t":"一些国家已开始全面**禁止**一次性塑料袋，迫使零售商改用纸袋或布袋。"},
"pact":{"e":"The two rival gangs signed an uneasy pact promising to stay out of each other's territory after the shooting.","t":"枪击事件后，两个敌对帮派签署了一份脆弱的**协议**，承诺不再侵犯对方的地盘。"},
"reign":{"e":"During her reign, the queen expanded trade routes across three continents and reformed the kingdom's outdated legal system.","t":"在她的**统治**期间，女王将贸易路线扩展到三大洲，并改革了王国陈旧的法律体系。"},
"summon":{"e":"The judge summoned both attorneys to her chambers to settle the dispute before the jury returned.","t":"法官把双方律师**传召**到她的办公室，要求在陪审团归来前解决争端。"},
"wield":{"e":"As the newly appointed CEO, she began to wield considerable influence over decisions the board once made alone.","t":"作为新任首席执行官，她开始**行使**对那些原本只由董事会决定事务的重大影响力。"},
"verdict":{"e":"After deliberating for nine hours, the jury finally reached a verdict that stunned everyone in the courtroom.","t":"经过九个小时的商议，陪审团终于做出了一个让庭上所有人震惊的**裁定**。"},
"hurl":{"e":"Furious protesters began to hurl rocks at the barricade, forcing police to retreat behind their riot shields.","t":"愤怒的抗议者开始向路障**猛掷**石块，迫使警察退到防暴盾牌后面。"},
"prosecute":{"e":"Prosecutors decided to prosecute the factory owner for knowingly dumping toxic waste into the town's only river.","t":"检方决定**起诉**这名工厂主，指控他明知故犯地向镇上唯一的河流排放有毒废物。"},
"blade":{"e":"The chef sharpened the knife's blade until it could slice a tomato paper-thin without tearing the skin.","t":"厨师把刀**刃**磨得锋利无比，切番茄时薄如纸片却不会撕破表皮。"},
"verifiable":{"e":"Scientific claims must be verifiable through repeated experiments before the wider research community will accept them as fact.","t":"科学论断必须能通过反复实验**得到证实**，更广泛的研究界才会将其视为事实。"},
"suborn":{"e":"The defense lawyer was disbarred after evidence showed he had tried to suborn a witness into lying under oath.","t":"那名辩护律师因被证实曾**收买**一名证人让其在宣誓后作伪证而被吊销执照。"},
"notion":{"e":"The professor challenged the popular notion that intelligence is fixed at birth and cannot be meaningfully developed.","t":"教授对智力天生固定、无法有效发展这一流行**观念**提出了质疑。"},
"migrate":{"e":"Every autumn, millions of monarch butterflies migrate thousands of miles south to spend the winter in Mexico.","t":"每年秋天，数百万只帝王蝶会**迁徙**数千英里南下，在墨西哥过冬。"},
"preside":{"e":"The retired general was asked to preside over the peace talks because both sides trusted his neutrality.","t":"这位退役将军被邀请**主持**和平谈判，因为双方都信任他的中立立场。"},
"slander":{"e":"The actress sued the tabloid for slander after it falsely claimed she had abandoned her own children.","t":"那家小报谎称她抛弃了自己的孩子，这位女演员因此以**诽谤**罪起诉了对方。"},
"scheme":{"e":"The two disgruntled employees hatched a scheme to funnel company funds into a fake consulting account.","t":"两名心怀不满的员工策划了一个**阴谋**，把公司资金转入一个虚假的咨询账户。"},
"consult":{"e":"Before signing the contract, she decided to consult a lawyer who specialized in international trade disputes.","t":"在签合同之前，她决定**请教**一位专攻国际贸易纠纷的律师。"},
"dispose":{"e":"Years of financial hardship disposed him to distrust anyone who offered help without expecting something in return.","t":"多年的经济困境使他**倾向于**不信任任何提供帮助却不图回报的人。"},
"pulse":{"e":"The paramedic pressed two fingers against the victim's wrist and felt for a pulse before starting compressions.","t":"急救人员把两根手指按在伤者的手腕上，先感受**脉搏**，然后才开始按压。"},
"furnace":{"e":"The blacksmith fed more coal into the furnace until the metal inside glowed a bright, malleable orange.","t":"铁匠往**熔炉**里添了更多煤炭，直到里面的金属发出明亮、易于锻打的橙色光芒。"},
"dilemma":{"e":"Faced with a painful dilemma, she had to choose between accepting the promotion and staying near her aging parents.","t":"面对痛苦的**困境**，她必须在接受晋升和留在年迈父母身边之间做出选择。"},
"peculiar":{"e":"A peculiar smell drifted from the basement for weeks before anyone thought to check behind the water heater.","t":"地下室里飘出一股**古怪**的气味好几周，才有人想到去热水器后面查看。"},
"morale":{"e":"After three straight losses, the coach organized a team dinner specifically to boost morale before the playoffs began.","t":"连续输掉三场比赛后，教练特意组织了一场团队聚餐，为季后赛开始前提振**士气**。"},
"screen":{"e":"The hiring committee had to screen over three hundred applications before selecting a shortlist of ten candidates.","t":"招聘委员会必须从三百多份申请中**筛选**，才能选出十人的候选名单。"},
"valid":{"e":"Her passport had expired the month before, so it was no longer valid for international travel.","t":"她的护照上个月就已过期，因此已不再**有效**，无法用于出国旅行。"},
"eject":{"e":"When the engine caught fire mid-flight, the pilot had no choice but to eject before the plane went down.","t":"发动机在飞行中着火时，飞行员别无选择，只能在飞机坠毁前**弹射**逃生。"},
"skip":{"e":"Feeling confident about the material, she decided to skip the review chapter and jump straight into the exercises.","t":"她对这些内容很有信心，于是决定**跳过**复习章节，直接进入练习题。"},
"bump":{"e":"In the crowded hallway, she accidentally bumped into her old roommate for the first time in years.","t":"在拥挤的走廊里，她无意中**撞见**了多年未见的老室友。"},
"submarine":{"e":"The submarine descended silently beneath the ice sheet, its sonar the only way to detect nearby vessels.","t":"**潜水艇**悄然下潜到冰层之下，声呐是探测附近船只的唯一手段。"},
"promising":{"e":"The scholarship committee singled out her research proposal as the most promising submission among two hundred applicants.","t":"奖学金评审委员会认为她的研究计划是两百名申请者中最**有前途**的一份。"},
"domesticate":{"e":"Early farmers began to domesticate wild wolves, gradually breeding them into the loyal dogs we know today.","t":"早期的农民开始**驯化**野狼，逐渐把它们培育成我们今天熟知的忠诚犬类。"},
"staff":{"e":"The hospital struggled to staff its emergency room properly after half the night-shift nurses resigned in protest.","t":"夜班护士有一半因抗议辞职后，医院很难为急诊室**配备**足够的人手。"},
"motion":{"e":"The dancer's every motion seemed effortless, though years of grueling practice lay behind each graceful gesture.","t":"这位舞者的每一个**动作**看似毫不费力，但每个优美姿态的背后都是多年的刻苦练习。"},
"pathology":{"e":"The medical student spent her final year studying pathology, examining tissue samples to diagnose the underlying disease.","t":"这名医学生最后一年专攻**病理学**，通过检验组织样本来诊断潜在的疾病。"},
"torrent":{"e":"A sudden torrent of rain flooded the narrow streets within minutes, sweeping parked cars against the curb.","t":"一场突如其来的**倾盆**大雨几分钟内就淹没了狭窄的街道，把停放的车辆冲向路边。"},
"pocketbook":{"e":"Voters ultimately care less about abstract ideology than about how a policy affects their own pocketbook.","t":"选民最终在意的不是抽象的意识形态，而是某项政策如何影响自己的**钱包**。"},
"kerosene":{"e":"Before electricity reached the village, families relied on kerosene lamps to light their homes after dark.","t":"在电力尚未通到村庄之前，家家户户都依靠**煤油**灯在天黑后照明。"},
"smoothly":{"e":"Despite months of preparation delays, the product launch went smoothly, and sales exceeded every early projection.","t":"尽管筹备阶段一再延误，产品发布还是**顺利**进行，销量超出了所有早期预期。"},
"bulb":{"e":"The reading lamp flickered twice and went dark, so she climbed on a chair to replace the bulb.","t":"台灯闪了两下就熄灭了，于是她爬上椅子去换那个**灯泡**。"},
"reasonable":{"e":"Given the extensive damage from the storm, the contractor's repair estimate seemed entirely reasonable to the homeowners.","t":"考虑到风暴造成的重大损失，承包商的维修报价在房主们看来完全**合理**。"},
"captive":{"e":"The rebels held the young captive for three tense weeks before negotiators finally secured his safe release.","t":"叛军扣押这名**俘虏**长达三周，谈判人员最终才成功让他安全获释。"},
"attract":{"e":"The museum's new exhibit on ancient shipwrecks managed to attract record crowds during its very first weekend open.","t":"博物馆关于古代沉船的新展览在开放的第一个周末就**吸引**了创纪录的人群。"},
"pipe":{"e":"Engineers designed a system to pipe fresh water directly from the mountain spring into every household in the valley.","t":"工程师设计了一套系统，把山泉水直接**用管道输送**到山谷里每一户人家。"},
"crumple":{"e":"She read the rejection letter once, then let her hand crumple the paper into a tight little ball.","t":"她把那封拒信读了一遍，然后任由自己的手把这张纸**揉皱**成一个紧实的小球。"},
"reliance":{"e":"The startup's heavy reliance on a single supplier proved disastrous when that factory shut down overnight.","t":"这家创业公司过度**依赖**单一供应商，当那家工厂一夜之间停产时，后果十分惨重。"},
"bald":{"e":"By his early thirties, he had already gone completely bald and stopped fighting it with expensive treatments.","t":"他三十出头就已经完全**秃顶**了，也不再用昂贵的疗法去对抗这件事。"},
"extraordinary":{"e":"The young violinist displayed extraordinary talent, performing concertos that usually take seasoned professionals decades to fully master.","t":"这位年轻的小提琴家展现出**非凡**的天赋，演奏的协奏曲通常需要资深演奏家花上数十年才能真正掌握。"},
"checked":{"e":"He wore a checked flannel shirt to the interview, hoping it looked casual but still professionally put together.","t":"他穿了一件**格子**法兰绒衬衫去面试，希望看起来既随意又不失专业。"},
"jeans":{"e":"After years of formal office attire, she finally felt comfortable wearing jeans and sneakers to work every day.","t":"多年穿着正式的办公室装束后，她终于可以自在地每天穿**牛仔裤**和运动鞋上班了。"},
"insurance":{"e":"After the flood destroyed their basement, the family was relieved their insurance covered nearly all the repair costs.","t":"洪水毁掉了他们的地下室后，这家人庆幸自己的**保险**几乎覆盖了全部维修费用。"},
"maritime":{"e":"The small nation's economy has always depended heavily on maritime trade routes connecting it to distant markets.","t":"这个小国的经济一直严重依赖连接远方市场的**海上**贸易路线。"},
"continent":{"e":"Geologists believe this single continent once split apart slowly, drifting into the separate landmasses we recognize today.","t":"地质学家认为这块单一的**大陆**曾经缓慢分裂，逐渐漂移成我们今天所知的几块独立陆地。"},
"fungi":{"e":"Certain fungi break down dead wood so efficiently that entire fallen trees can vanish within a few short years.","t":"某些**真菌**分解枯木的效率极高，倒下的整棵树可能在短短几年内就消失不见。"},
"documentation":{"e":"Before approving the loan, the bank required extensive documentation proving the applicant's income and employment history.","t":"在批准贷款之前，银行要求提供大量**文件**来证明申请人的收入和工作经历。"},
"gender":{"e":"The survey asked respondents to indicate their gender but also included an option to leave the question blank.","t":"问卷要求受访者填写自己的**性别**，但也提供了一个可以不作答的选项。"},
"clue":{"e":"The detective found a single muddy footprint that became the only clue linking the suspect to the crime scene.","t":"侦探发现了一个泥泞的脚印，这成了将嫌疑人与犯罪现场联系起来的唯一**线索**。"},
"plague":{"e":"Persistent rumors continued to plague the mayor's campaign, no matter how many times his staff denied them.","t":"无论幕僚多少次辟谣，挥之不去的谣言依然**困扰**着这位市长的竞选活动。"},
"aggravate":{"e":"Scratching the mosquito bite will only aggravate the itching and increase the risk of infection later on.","t":"抓挠蚊子叮咬的地方只会**加重**瘙痒，还会增加日后感染的风险。"},
"surpass":{"e":"This year's harvest is expected to surpass last year's total by nearly twenty percent, according to agricultural officials.","t":"据农业官员预测，今年的收成有望**超过**去年总量近百分之二十。"},
"previous":{"e":"Her previous employer had promised a promotion that never materialized, so she began quietly searching elsewhere.","t":"她**之前**的雇主曾承诺给她升职，但始终没有兑现，于是她开始悄悄另谋出路。"},
"hereditary":{"e":"Doctors warned that the disease was hereditary, urging her siblings to get tested even though they felt fine.","t":"医生警告说这种疾病是**遗传性**的，敦促她的兄弟姐妹即便自我感觉良好也要去做检测。"},
"bosom":{"e":"He carried the guilt of that decision deep within his bosom for the rest of his life.","t":"那个决定带来的愧疚，他一生都深藏在**内心**深处。"},
"calculus":{"e":"Most engineering programs require students to master calculus before they can enroll in advanced physics courses.","t":"大多数工程专业都要求学生先掌握**微积分**，才能选修高等物理课程。"},
"invalid":{"e":"Because the contract lacked both signatures, the lawyer declared it invalid and refused to proceed with the sale.","t":"由于合同缺少双方签字，律师宣布该合同**无效**，拒绝继续推进这笔交易。"},
"dosage":{"e":"The pharmacist warned that doubling the dosage would not speed recovery but could seriously damage her liver instead.","t":"药剂师提醒说，把**剂量**加倍并不会加快康复，反而可能严重损害她的肝脏。"},
"balm":{"e":"Her grandmother's soft voice on the phone was a balm after such a stressful, exhausting week at work.","t":"经过如此紧张疲惫的一周工作后，电话里祖母温柔的声音成了一剂**慰藉**。"},
"infirm":{"e":"The once-vigorous farmer grew infirm in his final years, relying on a cane just to cross the yard.","t":"这位曾经精力充沛的农夫晚年变得**虚弱**，仅仅穿过院子都要靠拐杖支撑。"},
"patient":{"e":"The nurse checked on every patient in the ward twice an hour throughout that especially chaotic night shift.","t":"在那个格外混乱的夜班里，护士每隔半小时就要查看病房里的每一位**病人**。"},
"optic":{"e":"Damage to the optic nerve can cause partial or total blindness, depending on how many fibers are affected.","t":"**视**神经受损可能导致部分或完全失明，具体取决于受影响的神经纤维数量。"},
"pathological":{"e":"His pathological fear of germs made even a simple, friendly handshake feel completely unbearable to him.","t":"他对细菌有一种**病态**的恐惧，以至于连简单友好的握手都让他难以忍受。"},
"capillary":{"e":"Blood flows so slowly through each capillary that oxygen has time to diffuse directly into surrounding tissue.","t":"血液流经每一根**毛细血管**的速度极其缓慢，使氧气有足够时间直接扩散到周围组织中。"},
"trench":{"e":"Soldiers spent months huddled in a muddy trench, enduring freezing rain while waiting for orders to advance.","t":"士兵们在泥泞的**战壕**里挤了几个月，冒着刺骨的寒雨等待前进的命令。"},
"costume":{"e":"For the school play, she sewed an elaborate costume covered in sequins to look like a peacock.","t":"为了学校的话剧演出，她缝制了一套缀满亮片的华丽**戏服**，看起来像一只孔雀。"},
"rampant":{"e":"Corruption had grown so rampant within the agency that even routine permits required an unofficial payment.","t":"该机构内部的腐败已变得如此**猖獗**，甚至连普通的许可证都需要私下付钱。"},
"generate":{"e":"Solar panels installed on the roof now generate enough electricity to power the entire household during summer months.","t":"安装在屋顶上的太阳能板如今**产生**的电量足以在夏季供应整户人家。"},
"cassette":{"e":"He found a dusty cassette in the attic labeled with his mother's handwriting from decades before he was born.","t":"他在阁楼里发现了一盘积满灰尘的**磁带**，上面是母亲几十年前、他出生之前留下的字迹。"},
"Neolithic":{"e":"Archaeologists uncovered Neolithic tools near the riverbank, suggesting farming communities settled there thousands of years ago.","t":"考古学家在河岸附近发现了**新石器时代**的工具，说明农耕社群在几千年前就已定居于此。"},
"fumigate":{"e":"The exterminator had to fumigate the entire warehouse for three days to eliminate the stubborn termite infestation.","t":"灭虫人员不得不对整个仓库**熏蒸**消毒三天，才彻底清除了顽固的白蚁。"},
"counter":{"e":"The spokesperson moved quickly to counter the rumor, releasing internal documents that disproved every claim in it.","t":"发言人迅速采取行动**反驳**这一谣言，公布了内部文件，推翻了其中的每一项说法。"},
"flag":{"e":"The editor decided to flag every paragraph that seemed to contain unverified statistics before sending it to print.","t":"编辑决定把每一段似乎含有未经核实数据的内容都**标记**出来，然后才送去印刷。"},
"pliable":{"e":"The potter kept the clay moist so it would stay pliable enough to shape into delicate curves.","t":"陶艺家让粘土保持湿润，好让它足够**柔韧**，可以塑成精致的曲线形状。"},
"recipe":{"e":"Grandmother refused to write down her dumpling recipe, insisting the proportions had to be felt, not measured.","t":"奶奶拒绝把她的饺子**食谱**写下来，坚持认为用量必须靠感觉，而不是靠量具。"},
"precautionary":{"e":"The airline canceled all flights as a precautionary measure once the volcanic ash cloud began drifting toward the coast.","t":"一旦火山灰云开始飘向海岸，航空公司便取消了所有航班，作为**预防性**措施。"},
"compact":{"e":"The engineers redesigned the engine to be far more compact, freeing up space for a larger fuel tank.","t":"工程师把发动机重新设计得更加**紧凑**，从而腾出空间安装更大的油箱。"},
"sap":{"e":"Months of chronic insomnia began to sap her energy, leaving her too exhausted to concentrate at work.","t":"长期失眠开始**耗尽**她的精力，让她疲惫得无法在工作中集中注意力。"},
"auditory":{"e":"The therapist designed an auditory exercise that trained patients to distinguish similar consonant sounds more accurately.","t":"治疗师设计了一项**听觉**训练，帮助患者更准确地区分相近的辅音。"},
"explicit":{"e":"The contract left nothing to interpretation, spelling out explicit deadlines and penalties for every possible delay.","t":"这份合同不留任何解释空间，对每一种可能的延误都写明了**明确**的截止日期和处罚条款。"},
"lens":{"e":"The photographer switched to a wide-angle lens to fit the entire canyon into a single dramatic frame.","t":"摄影师换上广角**镜头**，好把整个峡谷都纳入一张震撼的画面之中。"},
"volatile":{"e":"Currency traders avoided the region entirely because its politics had grown too volatile to predict with confidence.","t":"货币交易员完全回避这个地区，因为那里的政局已**动荡不安**到难以预测的地步。"},
"celestial":{"e":"Ancient sailors relied on celestial navigation, charting their course by tracking the position of familiar stars.","t":"古代水手依靠**天体**导航，通过追踪熟悉星辰的位置来确定航向。"},
"utilize":{"e":"The architect decided to utilize reclaimed timber from the old barn instead of ordering new lumber.","t":"建筑师决定**利用**旧谷仓回收的木材，而不是订购新的木料。"},
"behaviorism":{"e":"Behaviorism dominated psychology for decades, insisting researchers study only observable actions rather than internal mental states.","t":"**行为主义**在心理学界主导了数十年，坚持认为研究者只应研究可观察的行为，而非内在心理状态。"},
"semester":{"e":"She transferred schools midway through the semester, which made it hard to catch up on missed material.","t":"她在**学期**进行到一半时转学，这让她很难补上落下的课程内容。"},
"equator":{"e":"Countries near the equator generally experience little seasonal variation, with warm temperatures persisting throughout the entire year.","t":"靠近**赤道**的国家通常季节变化不大，全年气温都保持温暖。"},
"productive":{"e":"Working from home in the early morning turned out to be far more productive than her usual office routine.","t":"清晨在家办公被证明比她平时的办公室工作方式要**高效**得多。"},
"elicit":{"e":"The interviewer's gentle, open-ended questions managed to elicit surprisingly candid answers from the usually guarded manager.","t":"面试官温和而开放式的提问，竟然从这位平时防备心很重的经理那里**引出**了出乎意料的坦诚回答。"},
"newsletter":{"e":"Every Friday, the nonprofit sends out a newsletter summarizing its latest projects to hundreds of loyal donors.","t":"这家非营利组织每周五都会向数百名忠实捐赠者发送一份**通讯简报**，总结最新的项目进展。"},
"salon":{"e":"Every Thursday evening, the countess hosted a literary salon where poets and philosophers debated late into the night.","t":"每周四晚上，伯爵夫人都会举办一场文学**沙龙**，诗人和哲学家们会争论到深夜。"},
"afford":{"e":"Even with both parents working full-time, the family still could not afford a house in that neighborhood.","t":"即使父母双方都全职工作，这家人依然**负担不起**那个街区的一套房子。"},
"magma":{"e":"Deep beneath the volcano, magma slowly accumulates in a chamber until pressure finally forces it toward the surface.","t":"在火山深处，**岩浆**缓慢地在岩浆房中聚集，直到压力最终将它推向地表。"},
"hieroglyph":{"e":"Each hieroglyph carved into the tomb's wall told part of the pharaoh's journey into the afterlife.","t":"墓室墙壁上雕刻的每一个**象形文字**都讲述着法老通往来世旅程的一部分。"},
"Jupiter":{"e":"Jupiter is so massive that its gravity alone shields the inner planets from many wandering comets.","t":"**木星**质量极大，仅凭它的引力就能为内侧行星挡住许多游荡的彗星。"},
"qualify":{"e":"She had to pass three separate exams before she could qualify to practice law in that state.","t":"她必须通过三场不同的考试，才能**取得资格**在该州执业律师。"},
"parameter":{"e":"Before running the simulation, the engineer adjusted several parameters to reflect the bridge's actual wind load.","t":"在运行模拟之前，工程师调整了几个**参数**，以反映大桥实际承受的风荷载。"},
"contradict":{"e":"The witness's second statement seemed to flatly contradict everything she had told police just hours earlier that morning.","t":"这位证人的第二次陈述似乎与她几个小时前告诉警方的一切完全**矛盾**。"},
"thaw":{"e":"She took the frozen chicken out early so it would have plenty of time to thaw before dinner.","t":"她早早把冷冻鸡肉拿出来，好让它有足够时间在晚饭前**解冻**。"},
"walnut":{"e":"The carpenter chose a rich, dark walnut for the dining table because it would age beautifully over decades.","t":"木匠为餐桌选用了色泽深厚的**胡桃木**，因为它会随着岁月流逝而愈发美观。"},
"square":{"e":"Thousands of demonstrators gathered in the central square, chanting slogans that echoed off the surrounding government buildings.","t":"数千名示威者聚集在中央**广场**，高喊的口号在周围的政府大楼间回荡。"},
"policy":{"e":"The new immigration policy sparked heated debate in Congress, with lawmakers deeply divided along party lines.","t":"新的移民**政策**在国会引发了激烈的辩论，议员们在党派立场上严重分歧。"},
"obstruct":{"e":"A fallen tree continued to obstruct the mountain road for days before crews finally cleared it away.","t":"一棵倒下的树持续**阻塞**这条山路好几天，工作人员才终于将它清理干净。"},
"loathsome":{"e":"The critic described the film's villain as a loathsome character whose every line made audiences squirm in disgust.","t":"影评人把这部电影的反派描述成一个**令人厌恶**的角色，他的每一句台词都让观众感到不适。"},
"swing":{"e":"The old rope bridge would swing dangerously with every gust, forcing hikers to grip the rails tightly.","t":"这座老旧的绳索桥每次刮风都会危险地**摇摆**，逼得徒步者紧紧抓住护栏。"},
"molecule":{"e":"A single water molecule consists of two hydrogen atoms bonded tightly to just one central oxygen atom.","t":"一个水**分子**由两个氢原子紧密结合到一个中心氧原子上构成。"},
"navigate":{"e":"The captain had to navigate the narrow strait carefully, since hidden reefs had wrecked several ships before.","t":"船长必须小心翼翼地**驾驶穿越**这条狭窄的海峡，因为隐藏的暗礁曾使几艘船只失事。"},
"tangle":{"e":"The kitten managed to tangle the entire ball of yarn around the legs of the dining chairs.","t":"小猫把整团毛线都**缠绕**到了餐椅的椅腿上。"},
"opposite":{"e":"Her brother took the opposite approach entirely, saving every dollar instead of spending freely like she did.","t":"她哥哥采取了完全**相反**的做法，把每一块钱都存起来，而不是像她那样随意花销。"},
"far-fetched":{"e":"His explanation for the missing funds sounded so far-fetched that even his closest friends refused to believe it.","t":"他对资金失踪的解释听起来如此**牵强**，就连他最亲密的朋友都不愿相信。"},
"senator":{"e":"The senator introduced a bill that would provide free school lunches to every child in the state.","t":"这位**参议员**提出了一项法案，将为全州每个孩子提供免费校餐。"},
"contributor":{"e":"She became a regular contributor to the magazine, publishing essays on rural life almost every other month.","t":"她成了这本杂志的固定**撰稿人**，几乎每隔一个月就发表一篇关于乡村生活的随笔。"},
"nitrogen":{"e":"Farmers add nitrogen to depleted soil because crops need it to build proteins and grow strong leaves.","t":"农民会给贫瘠的土壤添加**氮**肥，因为农作物需要它来合成蛋白质、长出茁壮的叶片。"},
"terminus":{"e":"The old railway terminus still stands downtown, though trains stopped arriving there over fifty years ago.","t":"这座老旧的铁路**终点站**至今仍矗立在市中心，尽管火车已有五十多年不再抵达那里。"},
"eligible":{"e":"Only students with a minimum grade average were eligible to apply for the university's most competitive scholarship.","t":"只有平均成绩达到最低要求的学生才**有资格**申请这所大学竞争最激烈的奖学金。"},
"specialize":{"e":"After years of general practice, the doctor decided to specialize in treating rare childhood genetic disorders.","t":"在多年从事全科诊疗之后，这位医生决定**专攻**罕见的儿童遗传疾病治疗。"},
"accelerate":{"e":"The driver had to accelerate quickly to merge safely onto the highway before the gap in traffic closed.","t":"司机必须迅速**加速**，才能在车流缺口闭合前安全并入高速公路。"},
"ductile":{"e":"Gold is remarkably ductile, which is why artisans can hammer a single ounce into sheets many meters wide.","t":"黄金具有极强的**延展性**，这就是为什么工匠能把一盎司黄金锤打成好几米宽的薄片。"},
"comparison":{"e":"Any comparison between the two candidates' records quickly reveals how differently they voted on key issues.","t":"只要对这两位候选人的从政记录稍作**比较**，就能看出他们在关键议题上的投票有多么不同。"},
"symphony":{"e":"The orchestra spent months rehearsing the symphony before finally performing it for a sold-out concert hall.","t":"乐团花了数月排练这部**交响曲**，才终于在座无虚席的音乐厅里进行了演出。"},
"plaster":{"e":"Workers had to plaster the cracked walls before the painters could even begin applying the first coat.","t":"工人必须先用灰泥**抹平**开裂的墙壁，油漆工才能开始刷第一层漆。"},
"dazzling":{"e":"Fireworks burst over the harbor in a dazzling display that left the entire crowd gasping in wonder.","t":"烟花在港口上空绽放出一场**令人目眩神迷**的表演，让全场观众都惊叹不已。"},
"compare":{"e":"Critics often compare her early novels to the work of Victorian writers, though her themes are strikingly modern.","t":"评论家常把她的早期小说与维多利亚时代作家的作品相**比较**，尽管她的主题其实非常现代。"},
"radiation":{"e":"Workers at the nuclear plant wear special suits to limit their exposure to harmful radiation during repairs.","t":"核电站的工人在检修时会穿特殊防护服，以减少接触有害**辐射**的风险。"},
"evaluate":{"e":"The committee will evaluate each proposal on originality, feasibility, and potential impact before awarding the grant.","t":"委员会将从原创性、可行性和潜在影响三方面**评估**每份提案，然后再决定拨款。"},
"electrolysis":{"e":"Through electrolysis, scientists can split ordinary water into its component hydrogen and oxygen gases using electric current.","t":"通过**电解**作用，科学家可以利用电流把普通水分解成氢气和氧气两种成分气体。"},
"literary":{"e":"Her literary ambitions began early, filling notebook after notebook with poems long before she turned twelve.","t":"她的**文学**抱负很早就显露出来，早在十二岁之前就写满了一本又一本诗歌笔记。"},
"subconscious":{"e":"Freud believed that many of our everyday decisions are quietly shaped by the subconscious rather than by reason.","t":"弗洛伊德认为，我们日常的许多决定其实是悄悄被**潜意识**塑造的，而非出于理性。"},
"needy":{"e":"Every winter, volunteers distribute warm coats and blankets to needy families living in the shelter downtown.","t":"每年冬天，志愿者都会向住在市中心收容所的**贫困**家庭分发保暖大衣和毛毯。"},
"trauma":{"e":"Years of therapy helped her slowly process the trauma from the car accident that took her brother's life.","t":"多年的心理治疗帮助她慢慢疗愈那场夺走弟弟生命的车祸留下的**精神创伤**。"},
"cortex":{"e":"Neuroscientists discovered that the visual cortex remains active even when a person's eyes are completely closed.","t":"神经科学家发现，即使一个人双眼完全闭上，视觉**皮层**仍然保持活跃。"},
"syndrome":{"e":"Doctors identified a rare syndrome causing her joints to weaken gradually despite her otherwise excellent health.","t":"医生诊断出一种罕见的**综合征**，导致她的关节逐渐衰弱，尽管她其他方面的健康状况都很好。"},
"wrench":{"e":"He tried to wrench the stuck door open, but the rusted hinges refused to budge at all.","t":"他试图**用力拉**开卡住的门，但锈蚀的合页纹丝不动。"},
"amphibious":{"e":"The military deployed amphibious vehicles that could roll straight from the beach into open water without pausing.","t":"军方部署了**水陆两栖**车辆，能够毫不停顿地直接从海滩驶入开阔水域。"},
"carbohydrate":{"e":"Endurance athletes often load up on carbohydrate the night before a marathon to maximize their glycogen stores.","t":"耐力运动员常常在马拉松前一晚大量摄入**碳水化合物**，以最大限度储存糖原。"},
"executive":{"e":"The newly promoted executive spent her first month simply listening to every department before proposing any changes.","t":"这位新晋升的**高管**上任第一个月只是倾听每个部门的意见，尚未提出任何改动。"},
"trance":{"e":"The repetitive drumming gradually put several dancers into a trance, their movements becoming slow and dreamlike.","t":"反复的鼓点逐渐让几位舞者陷入一种**恍惚**状态，动作变得缓慢而如梦似幻。"},
"disturbance":{"e":"Police were called to break up a loud disturbance outside the bar shortly after closing time.","t":"打烊后不久，酒吧外发生了一场吵闹的**骚动**，警察被叫去平息。"},
"plankton":{"e":"Tiny plankton drifting near the ocean surface form the foundation of nearly every marine food chain.","t":"漂浮在海洋表层附近的微小**浮游生物**构成了几乎每一条海洋食物链的基础。"},
"lack":{"e":"The proposal ultimately failed because it seemed to lack any realistic plan for securing long-term funding.","t":"这份提案最终失败了，因为它似乎**缺乏**任何切实可行的长期筹资计划。"},
"slice":{"e":"She watched her father slice the roast into thin, even pieces before arranging them neatly on the platter.","t":"她看着父亲把烤肉**切成**薄而均匀的片，然后整齐地摆在大盘子上。"},
"replenish":{"e":"The hikers stopped at the mountain spring to replenish their water bottles before tackling the final steep climb.","t":"徒步者在山泉旁停下，**补充**水壶里的水，然后再挑战最后一段陡峭的攀爬。"},
"optimal":{"e":"Nutritionists recommend eating a small meal every three hours to maintain optimal energy levels throughout the day.","t":"营养师建议每三小时进食一次小份餐点，以便全天维持**最佳**的精力水平。"},
"fibrous":{"e":"The old celery stalk had grown tough and fibrous, making it nearly impossible to chew comfortably.","t":"这根老芹菜茎变得又老又**多纤维**，几乎让人没法舒服地嚼动。"},
"buffalo":{"e":"Herds of buffalo once roamed the Great Plains by the millions before hunters nearly wiped them out.","t":"曾经有数百万头**野牛**成群漫游在大平原上，直到猎人几乎将它们赶尽杀绝。"},
"willow":{"e":"A single weeping willow drooped gracefully over the pond, its branches trailing in the still water.","t":"一棵垂**柳**优雅地垂在池塘上方，枝条拖曳在平静的水面上。"},
"induce":{"e":"Doctors will sometimes induce labor artificially when a pregnancy continues well past its expected due date.","t":"当孕期明显超过预产期时，医生有时会人工**引产**。"},
"rayon":{"e":"Manufacturers began using rayon during the war years because silk had grown scarce and prohibitively expensive.","t":"战争年代，制造商开始使用**人造丝**，因为真丝变得稀缺且价格高得离谱。"},
"scale":{"e":"The small factory expanded its production scale dramatically after finally securing a contract with a major retailer.","t":"这家小工厂在终于拿下一家大型零售商的合同后，大幅扩大了生产**规模**。"},
"recital":{"e":"After years of lessons, she finally performed her first piano recital in front of a full auditorium.","t":"经过多年的课程学习，她终于在座无虚席的礼堂里举办了自己的第一场钢琴**演奏会**。"},
"silt":{"e":"Decades of silt had built up along the riverbed, forcing engineers to dredge the channel before ships could pass.","t":"数十年积累的**淤泥**在河床上不断堆积，工程师们不得不疏浚河道，船只才能通行。"},
"ample":{"e":"The new apartment offered ample storage space, with closets in every room and a spacious basement besides.","t":"这套新公寓提供了**充足**的储物空间，每个房间都有衣柜，另外还有宽敞的地下室。"},
"converse":{"e":"The two scientists could converse fluently in French, even though neither had studied the language formally.","t":"这两位科学家能用法语流利地**交谈**，尽管他们都没有正式学过这门语言。"},
"patriot":{"e":"During the revolution, ordinary shopkeepers and farmers became devoted patriots willing to risk everything for independence.","t":"革命期间，普通的店主和农民都成为了愿意为独立牺牲一切的忠诚**爱国者**。"},
"oak":{"e":"The ancient oak at the center of town had stood for over three hundred years, surviving countless storms.","t":"镇中心那棵古老的**橡树**已经矗立了三百多年，经受住了无数场风暴。"},
"emanate":{"e":"A faint smell of cinnamon seemed to emanate from the kitchen long before the pie was actually ready.","t":"早在派做好之前，厨房里似乎就已经**散发**出一股淡淡的肉桂香味。"},
"encrust":{"e":"Years of mineral-rich water had left the old pipes badly encrusted with a thick, chalky buildup.","t":"多年富含矿物质的水流让这些旧管道**结满硬壳**，覆盖着一层厚厚的白垢。"},
"herbivore":{"e":"Unlike its sharp-toothed relatives, this ancient creature was a gentle herbivore that grazed on ferns and low branches.","t":"与它那些牙齿锋利的近亲不同，这种远古生物是温和的**食草动物**，以蕨类和低矮的树枝为食。"},
"floral":{"e":"She chose a floral wallpaper for the nursery, covered in tiny pink blossoms and pale green vines.","t":"她给婴儿房选了一款**花卉**图案的壁纸，上面缀满粉色小花和浅绿色藤蔓。"},
"track":{"e":"Wildlife biologists attached a radio collar to track the wolf's movements across the entire national park.","t":"野生动物学家给这只狼戴上无线电项圈，以便**追踪**它在整个国家公园内的活动。"},
"sprain":{"e":"She had to sit out the entire season after she managed to sprain her ankle during warmup drills.","t":"她在热身训练中不慎**扭伤**了脚踝，不得不缺席整个赛季。"},
"constant":{"e":"The constant dripping from that leaky bathroom faucet kept her wide awake for most of the night.","t":"浴室水龙头**持续不断**的滴水声让她大半个晚上都无法入睡。"},
"hoof":{"e":"The blacksmith trimmed each hoof carefully before fitting the horse with a fresh set of iron shoes.","t":"铁匠仔细修剪了马的每一个**蹄子**，然后才为它钉上一副新的铁蹄铁。"},
"adopt":{"e":"The school board voted to adopt a new curriculum that emphasizes hands-on science experiments over textbook memorization.","t":"校董事会投票决定**采用**一套新课程，更注重动手科学实验，而非死记硬背课本。"},
"sustainable":{"e":"The farm switched to sustainable practices, rotating crops instead of relying on chemical fertilizers every season.","t":"这家农场转向**可持续**耕作，通过轮作而不是每季依赖化肥来维持地力。"},
"bound":{"e":"As the eldest son, he felt bound to take over the family business no matter his own ambitions.","t":"作为长子，他觉得自己有**义务**接管家族企业，无论自己有什么抱负。"},
"molecular":{"e":"Recent advances in molecular biology have allowed researchers to edit specific genes with astonishing new precision.","t":"**分子**生物学的最新进展使研究人员能够以惊人的新精度编辑特定基因。"},
"diameter":{"e":"The old well's opening measured barely a meter in diameter, just wide enough for a bucket to pass.","t":"这口老井的井口**直径**仅有一米左右，刚好能让水桶通过。"},
"linguistic":{"e":"Her linguistic training helped her notice subtle grammatical patterns that most casual readers would never catch.","t":"她所受的**语言学**训练让她能注意到大多数普通读者根本不会察觉的细微语法规律。"},
"rancher":{"e":"The rancher spent every morning on horseback, checking fences across thousands of acres of open grassland.","t":"这位**牧场主**每天清晨都骑马巡视，检查横跨数千英亩开阔草场的围栏。"},
"heyday":{"e":"During its heyday, the coastal town welcomed thousands of tourists every single weekend throughout the summer season.","t":"在**全盛时期**，这座海滨小镇整个夏季每个周末都会迎来数千名游客。"},
"bleach":{"e":"Years of relentless sunlight had begun to bleach the fabric awning until it looked almost white.","t":"多年无情的日晒已经开始把这块布篷**漂白**，让它看起来几乎是白色的。"},
"nap":{"e":"After lunch, the toddler always took a short nap that left him cheerful and energetic for the rest of the afternoon.","t":"午饭后，这个小男孩总要**小睡**一会儿，之后整个下午都会精神饱满、心情愉快。"},
"clog":{"e":"Grease and hair had clogged the kitchen sink so completely that water pooled and refused to drain for hours.","t":"油脂和头发把厨房水槽**堵塞**得严严实实，水在里面积了好几个小时都排不出去。"},
"sulfur":{"e":"A sharp odor of sulfur drifted from the hot spring, warning hikers that the water below was scalding and mineral-rich.","t":"一股刺鼻的**硫磺**气味从温泉中飘出，提醒徒步者下面的水滚烫且富含矿物质。"},
"apprenticeship":{"e":"Rather than attend college, she completed a five-year apprenticeship under a master carpenter, learning joinery through daily hands-on practice.","t":"她没有上大学，而是跟着一位木匠师傅完成了为期五年的**学徒生涯**，通过每日动手实践学习细木工艺。"},
"prevailing":{"e":"The prevailing opinion among economists was that inflation would ease by spring, though a few analysts remained openly skeptical.","t":"经济学家中**普遍**的看法是通胀将在春季缓解，尽管少数分析师仍公开表示怀疑。"},
"hop":{"e":"Missing the bus by seconds, he decided to hop on his neighbor's motorcycle instead of waiting another twenty minutes.","t":"因为差几秒就错过了公交车，他决定**跳上**邻居的摩托车，而不是再等二十分钟。"},
"grind":{"e":"Every morning before dawn, the baker would grind whole wheat kernels into flour using an old stone mill.","t":"每天黎明前，面包师都会用一台老石磨把全麦麦粒**磨碎**成面粉。"},
"objective":{"e":"This quarter, the team's primary objective is to reduce shipping delays, even if that means renegotiating supplier contracts.","t":"这个季度，团队的首要**目标**是减少发货延误，哪怕这意味着要重新谈判供应商合同。"},
"flourish":{"e":"Despite the drought elsewhere in the valley, the orchard continued to flourish because an underground spring kept its roots moist.","t":"尽管山谷其他地方遭遇干旱，这片果园却因为地下泉水滋润根系而持续**繁茂生长**。"},
"bulletin":{"e":"Anticipating the incoming storm, the school posted an emergency bulletin on its website announcing that all classes were canceled.","t":"预见到即将到来的暴风雨，学校在网站上发布了一则紧急**公告**，宣布所有课程停课。"},
"stock":{"e":"Before the hurricane hit, residents rushed to stock their pantries with canned goods, bottled water, and flashlight batteries.","t":"飓风来袭前，居民们纷纷抢购罐头食品、瓶装水和手电筒电池，**储备**家中食品柜。"},
"crow":{"e":"After his rival dropped out of the race, the candidate could not resist crowing about his certain victory to reporters.","t":"在对手退出竞选后，这位候选人忍不住向记者们**得意洋洋地夸耀**自己稳操胜券。"},
"hawk":{"e":"Vendors would hawk roasted chestnuts on every street corner as soon as the first winter chill arrived.","t":"一到初冬的寒意来临，小贩们就会在每个街角**叫卖**烤栗子。"},
"response":{"e":"Her immediate response to the criticism was to apologize sincerely rather than defend her original decision.","t":"面对批评，她当即的**反应**是真诚道歉，而不是为自己最初的决定辩护。"},
"haunt":{"e":"Decades after the argument had ended, the memory of his father's disappointed silence still continued to haunt him.","t":"在那场争吵结束几十年后，父亲那沉默的失望神情依然**萦绕**在他心头。"},
"traditional":{"e":"Many rural households still swear by traditional methods of curing meat, smoking it slowly over a wood fire for days.","t":"许多乡村家庭仍然遵循**传统**的腌肉方法，将肉用柴火慢慢熏制数日。"},
"protein":{"e":"Nutritionists recommend that athletes consume enough protein after exercise to help torn muscle fibers repair themselves.","t":"营养学家建议运动员在锻炼后摄入足够的**蛋白质**，以帮助撕裂的肌肉纤维自我修复。"},
"sprout":{"e":"Within a week of heavy rain, tiny green shoots had begun to sprout across the previously barren field.","t":"一场大雨过后仅一周，先前贫瘠的田野上就开始**发芽**冒出嫩绿的新苗。"},
"compass":{"e":"Economic and environmental factors, not just battles, now fall within the compass of the history course after a curriculum overhaul.","t":"经过课程改革，经济和环境因素如今也被纳入了这门历史课的**范围**，而不仅仅是战争。"},
"theory":{"e":"Her theory about ocean currents shifting global weather patterns gained wide acceptance only after decades of satellite data confirmed it.","t":"她关于洋流改变全球天气模式的**理论**，直到数十年的卫星数据证实之后才被广泛接受。"},
"atom":{"e":"Splitting a single atom of uranium releases an astonishing amount of energy, a fact that transformed both physics and warfare.","t":"分裂一个铀**原子**会释放出惊人的能量，这一事实改变了物理学和战争的面貌。"},
"luster":{"e":"Years of gentle polishing had given the antique silver teapot a warm luster that mass-produced pieces rarely achieve.","t":"多年精心的抛光让这把古董银茶壶拥有了一种温润的**光泽**，这是批量生产的器皿很少能达到的。"},
"review":{"e":"Before the final exam, she spent three nights reviewing every chapter of her chemistry notes line by line.","t":"期末考试前，她花了三个晚上逐行**复习**化学笔记的每一章。"},
"correspond":{"e":"For years before finally meeting in person at a conference in Geneva, the two scientists had corresponded only by letter.","t":"在日内瓦的一次会议上终于见面之前，这两位科学家多年来一直只靠书信**往来**。"},
"hydrothermal":{"e":"Deep-sea explorers found strange tube worms clustered around hydrothermal vents, where mineral-rich water bursts scalding from the ocean floor.","t":"深海探险者发现奇特的管虫聚集在**热液**喷口附近，那里富含矿物质的滚烫海水从洋底喷涌而出。"},
"perceive":{"e":"Through years of training, the sommelier learned to perceive subtle differences in flavor that most people never notice.","t":"经过多年训练，这位侍酒师学会了**察觉**大多数人从未注意到的细微风味差异。"},
"strand":{"e":"A sudden blizzard stranded hundreds of travelers at the airport overnight, forcing many to sleep on the terminal floor.","t":"一场突如其来的暴风雪让数百名旅客一夜之间**滞留**在机场，许多人被迫睡在航站楼地板上。"},
"alternative":{"e":"When the bridge closed for repairs, commuters had to find an alternative that added nearly an hour to their drive.","t":"大桥因维修封闭后，通勤者不得不寻找**替代方案**，这使他们的车程多了将近一个小时。"},
"erupt":{"e":"Tension between the rival fan groups finally erupted into a shoving match minutes after the referee's controversial call.","t":"裁判做出有争议的判罚后几分钟，对立球迷群体之间的紧张情绪终于**爆发**成一场推搡冲突。"},
"chlorine":{"e":"After testing revealed the pool no longer met safety standards, the lifeguard added extra chlorine right before reopening it.","t":"在检测显示泳池不再符合安全标准后，救生员在重新开放前加入了额外的**氯**。"},
"scrape":{"e":"He had to scrape a thick layer of frost off the windshield before he could safely drive to work.","t":"他不得不先把挡风玻璃上厚厚的一层霜**刮掉**，才能安全开车去上班。"},
"conceive":{"e":"The architect first conceived the museum's spiraling design while idly sketching seashells during a lazy beach vacation years earlier.","t":"这位建筑师最初**构思**出博物馆螺旋形设计的灵感，是多年前在一次悠闲的海滩度假中随手描画贝壳时产生的。"},
"process":{"e":"Within a single eight-hour shift, the factory can process nearly two tons of raw sugarcane into refined sugar.","t":"在一个八小时的班次内，这家工厂就能把近两吨甘蔗原料**加工**成精制糖。"},
"corps":{"e":"The visiting president was trailed everywhere by a corps of photographers eager to capture even the smallest misstep.","t":"到访的总统身边总跟着一**队**摄影记者，他们急于捕捉哪怕最微小的失误。"},
"isolate":{"e":"Doctors decided to isolate the patient in a separate ward to prevent the rare infection from spreading further.","t":"医生决定把病人**隔离**在单独的病房，以防止这种罕见感染进一步传播。"},
"emit":{"e":"Old diesel trucks emit far more soot and toxic gases than the newer electric models replacing them citywide.","t":"老旧柴油卡车**排放**的烟尘和有毒气体，远比正在全市替代它们的新型电动车型多得多。"},
"capability":{"e":"Camera capability on the new smartphone impressed critics so much that several called it the best on the market.","t":"这款新智能手机的相机**性能**给评论家们留下了深刻印象，以至于有几位称它是市面上最好的。"},
"opaque":{"e":"The bathroom window was made of opaque glass, letting in daylight while still keeping the room private.","t":"浴室的窗户用的是**不透明**玻璃，既能让日光透进来，又能保持房间的私密性。"},
"tow":{"e":"After the engine stalled on the highway shoulder, a repair crew had to tow the disabled car nearly ten miles to the nearest garage.","t":"引擎在高速公路路肩熄火后，维修人员不得不把这辆抛锚的车**拖**到将近十英里外的最近修理厂。"},
"imply":{"e":"Her hesitation before answering the question seemed to imply that she was hiding something from the committee.","t":"她回答问题前的犹豫似乎在**暗示**她对委员会隐瞒了什么。"},
"glaze":{"e":"Before firing each bowl in the kiln overnight, the potter would glaze it with a pale blue finish.","t":"在把每个碗放进窑里烧一整夜之前，陶艺师会先给它**上釉**，刷上淡蓝色的釉料。"},
"organic":{"e":"The restaurant sources only organic vegetables from nearby farms that avoid synthetic pesticides and chemical fertilizers entirely.","t":"这家餐厅只采购附近农场的**有机**蔬菜，这些农场完全不使用合成农药和化学肥料。"},
"ailment":{"e":"A persistent cough turned out to be a minor ailment easily cured with rest and plenty of warm tea.","t":"那阵持续的咳嗽结果只是个小**毛病**，靠休息和多喝热茶就轻松治好了。"},
"curve":{"e":"Along the cliffside, the road took a sharp curve that forced drivers to slow down or risk skidding off.","t":"沿着悬崖边，这条路有一个急**弯**，迫使司机减速慢行，否则就有打滑冲出路面的风险。"},
"twinkling":{"e":"The twinkling of an eye was all it took for the magician's assistant to vanish from the locked cabinet on stage.","t":"只需**一眨眼**的工夫，魔术师的助手就从舞台上锁着的柜子里消失了。"},
"hominid":{"e":"Fossil hunters unearthed a hominid skull in the riverbed, sparking fresh debate about when our ancestors first walked upright.","t":"化石猎人在河床中发掘出一个**原始人类**的头骨，引发了关于我们的祖先何时开始直立行走的新一轮争论。"},
});
